#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SENSITIVITY 40.0  // mV/A
#define ZERO_CURRENT_OFFSET 2048.0 // ADC value at 0A
#define VREF 4.096 // V

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_ads1115();
int16_t read_ads1115();
float convert_to_current(int16_t adc_value);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the ADS1115
int init_ads1115() {
    // Configuration register value:
    // OS = 0 (Start single conversion)
    // MUX = 010 (AIN0 single-ended)
    // PGA = 011 (PGA ±4.096V)
    // MODE = 1 (Single-shot mode)
    // DR = 110 (128 SPS)
    // COMP_MODE = 0 (Traditional comparator)
    // COMP_POL = 0 (Active low)
    // COMP_LAT = 0 (Non-latching comparator)
    // COMP_QUE = 111 (Disable comparator)
    uint16_t config = 0x4083; //0b0100000010000011

    // Write the configuration to the ADS1115
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, buf + 1, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads the ADS1115 and returns the 16-bit ADC value
int16_t read_ads1115() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1; // Indicate an error
    }

    // Combine the two bytes into a 16-bit value
    int16_t adc_value = (buf[0] << 8) | buf[1];
    return adc_value;
}

// Converts the ADC value to a current in Amperes
float convert_to_current(int16_t adc_value) {
    float voltage = (float)adc_value * VREF / 32768.0; // 32768 = 2^15
    float current = (voltage - (ZERO_CURRENT_OFFSET * VREF / 32768.0)) / (SENSITIVITY / 1000.0); // Convert mV to V and divide by sensitivity
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_ads1115();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(adc_value);

        // Print current value
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

