#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4" // Try gpiochip4, fallback to gpiochip0
#define GPIO_PIN 18
#define DEFAULT_SENSITIVITY 100.0f // mV/A
#define DEFAULT_THRESHOLD 5.0f    // A
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static float sensitivity = DEFAULT_SENSITIVITY;
static float threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int speed_hz);
int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len);
int read_adc(int fd, int channel);
float voltage_to_current(int adc_value, float sensitivity);
int gpio_init(const char *chip_name, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
int log_data(float current);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int speed_hz) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = 0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int fd, int channel) {
    uint8_t tx[3];
    uint8_t rx[3];

    // Construct SPI command
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx, rx, 3) != 0) {
        fprintf(stderr, "Error during ADC read\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Convert ADC voltage to current
float voltage_to_current(int adc_value, float sensitivity) {
    // Assuming VREF = 3.3 V
    float voltage = (float)adc_value / 1023.0f * 3.3f;
    return voltage / (sensitivity / 1000.0f); // Convert mV/A to V/A and then A
}

// GPIO initialization function
int gpio_init(const char *chip_name, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "current_sensor", 0) != 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Set GPIO value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) != 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, 1000000); // 1 MHz
    if (spi_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Current sensor monitoring started. Sensitivity: %.2f mV/A, Threshold: %.2f A\n", sensitivity, threshold);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        float current = voltage_to_current(adc_value, sensitivity);

        // Log data
        log_data(current);

        // Control fan based on current threshold
        if (current > threshold) {
            if (gpio_set_value(gpio_line, 1) != 0) {
                fprintf(stderr, "Error setting GPIO HIGH\n");
            }
        } else {
            if (gpio_set_value(gpio_line, 0) != 0) {
                fprintf(stderr, "Error setting GPIO LOW\n");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Current sensor monitoring stopped.\n");
    return 0;
}

