// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int co_raw;
    int no2_raw;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int channel);
float convert_to_ppm(int raw_value);
int log_data(float co_ppm);
void signal_handler(int signal);
