    if (raw_value < 0) raw_value = 0;
    if (raw_value > (int)(MAX_EXPECTED_RESISTANCE * 1000)) raw_value = (int)(MAX_EXPECTED_RESISTANCE * 1000);

    // Apply the calibration curve
    float resistance = (float)raw_value / 1000.0; // Convert to ohms
    float ppm = slope * resistance + intercept;

    return ppm;
}

