        }

        // Convert to PPM
        float co_ppm = convert_to_ppm(co_raw);

        // Log the data
        if (log_data(co_ppm) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("CO: %.2f PPM\n", co_ppm);

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

