// Constants
#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define CSV_FILENAME "flame_data.csv"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
int log_data(int flame_presence, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Reads the flame sensor's digital output
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Reads the MCP3008 ADC value from the specified channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Perform SPI transaction
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Calculates the temperature based on the ADC value
float calculate_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate an error
    }

    // Linear scaling: 10-bit ADC (0-1023) maps to 10.0-40.0°C
    return 10.0 + (float)adc_value / 102.3 * 30.0;
}

// Logs the data to a CSV file
int log_data(int flame_presence, float temperature) {
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open file %s for writing\n", CSV_FILENAME);
        return -1; // Indicate an error
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to file
    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_presence, temperature);

    // Close file
    fclose(fp);

    return 0;
}

