    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure flame sensor GPIO as input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read flame sensor
        int flame_presence = read_flame_sensor();

        // Read MCP3008 ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate temperature
        float temperature = calculate_temperature(adc_value);
        if (temperature < 0) {
            fprintf(stderr, "Error: Failed to calculate temperature\n");
            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(flame_presence, temperature) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

