#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define WINDOW_SIZE_MS 100
#define NUM_SAMPLES (WINDOW_SIZE_MS / (SAMPLE_INTERVAL_US / 1000))
#define RMS_THRESHOLD 0.7
#define LED_GPIO 27
#define CSV_FILE "audio_events.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(int on);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mic1_channel;
    int mic2_channel;
    int sample_interval_us;
    int window_size_ms;
    double rms_threshold;
    int led_gpio;
    char *csv_file;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_BAUD,
    MIC1_CHANNEL,
    MIC2_CHANNEL,
    SAMPLE_INTERVAL_US,
    WINDOW_SIZE_MS,
    RMS_THRESHOLD,
    LED_GPIO,
    CSV_FILE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.csv_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
    int sample_index = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (!terminate) {
        // Read ADC values
        int mic1_value = read_mcp3008(config.mic1_channel);
        int mic2_value = read_mcp3008(config.mic2_channel);

        // Store samples
        mic1_samples[sample_index] = mic1_value;
        mic2_samples[sample_index] = mic2_value;

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Check threshold and control LED
        if (mic1_rms > config.rms_threshold || mic2_rms > config.rms_threshold) {
            control_led(1); // Turn on LED
            gpioDelay(500);  // Wait 500 ms
            control_led(0); // Turn off LED
        }

        // Update sample index and check if window is complete
        sample_index++;
        if (sample_index >= NUM_SAMPLES) {
            sample_index = 0;
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval_us);

        // Check if the window is complete
        clock_gettime(CLOCK_REALTIME, &current_time);
        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;
        if (elapsed_ms >= config.window_size_ms) {
            break; // Exit the loop after the window is complete
        }
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += pow(samples[i], 2);
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Log data to CSV file
void log_data(double mic1_rms, double mic2_rms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s.%09ld,%.6f,%.6f\n", timestamp, ts.tv_nsec, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED
void control_led(int on) {
    gpioWrite(config.led_gpio, on);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

