#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define I2C_ADDR 0x48
#define LED_GPIO 17
#define CURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE 10 // Hz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(float current);
float calculate_average_current();
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char read_data[2];

    // Configuration register: Single-ended A0, +/-4.096V, 128 SPS, Disable comparator
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-ended A0, +/-4.096V, 128 SPS)
    config[2] = 0x83; // LSB: 10000011 (Disable comparator)

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 128 SPS)
    gpioDelay(125000); // 125 ms

    // Read conversion register
    config[0] = 0x00; // Conversion register address
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "I2C write (read address) failed\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_data, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    *raw_value = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Function to convert raw value to current
float convert_to_current(int16_t raw_value) {
    // Assuming 5V supply
    float voltage = (raw_value * 5.0) / 32767.0; // 32767 is the max value for 16-bit signed integer
    float current = (voltage - 0.5) * 100.0; // 0.5V is 0A, 4.5V is 100A
    return current;
}

// Function to add current to the circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average current
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed. Exiting...\n");
}

// Cleanup function
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
