// Constants
#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define TCS34725_ID_REG 0x12
#define TCS34725_ATIME_REG 0x01
#define TCS34725_CONTROL_REG 0x0F
#define TCS34725_ENABLE_REG 0x00
#define TCS34725_CDATA_REG 0x14
#define TCS34725_RDATA_REG 0x16
#define TCS34725_GDATA_REG 0x18
#define TCS34725_BDATA_REG 0x1A

#define CSV_FILE "color_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int verify_sensor_id(int handle);
int configure_sensor(int handle);
int read_sensor_data(int handle, unsigned short *clear, unsigned short *red, unsigned short *green, unsigned short *blue);
int write_data_to_csv(const char *filename, unsigned short clear, unsigned short red, unsigned short green, unsigned short blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Verify sensor ID
int verify_sensor_id(int handle) {
    int id = i2cReadByteData(handle, TCS34725_ID_REG);
    if (id < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }

    if ((id & 0x0F) != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

// Configure sensor
int configure_sensor(int handle) {
    // Set integration time (ATIME) to 2.4ms
    if (i2cWriteByteData(handle, TCS34725_ATIME_REG, 0xFF) < 0) {
        fprintf(stderr, "Failed to write ATIME register\n");
        return -1;
    }

    // Set gain (CONTROL) to 4x
    if (i2cWriteByteData(handle, TCS34725_CONTROL_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to write CONTROL register\n");
        return -1;
    }

    // Power on and enable ADC
    if (i2cWriteByteData(handle, TCS34725_ENABLE_REG, 0x03) < 0) {
        fprintf(stderr, "Failed to write ENABLE register\n");
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int handle, unsigned short *clear, unsigned short *red, unsigned short *green, unsigned short *blue) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(handle, TCS34725_CDATA_REG);
        if (result >= 0) {
            *clear = (unsigned short)result;
            break;
        } else {
            fprintf(stderr, "Failed to read clear data, retrying...\n");
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        result = i2cReadWordData(handle, TCS34725_RDATA_REG);
        if (result >= 0) {
            *red = (unsigned short)result;
            break;
        } else {
            fprintf(stderr, "Failed to read red data, retrying...\n");
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        result = i2cReadWordData(handle, TCS34725_GDATA_REG);
        if (result >= 0) {
            *green = (unsigned short)result;
            break;
        } else {
            fprintf(stderr, "Failed to read green data, retrying...\n");
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == 0) return -1;

    retries = 3;
    while (retries > 0) {
        result = i2cReadWordData(handle, TCS34725_BDATA_REG);
        if (result >= 0) {
            *blue = (unsigned short)result;
            break;
        } else {
            fprintf(stderr, "Failed to read blue data, retrying...\n");
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries == 0) return -1;

    return 0;
}

// Write data to CSV file
int write_data_to_csv(const char *filename, unsigned short clear, unsigned short red, unsigned short green, unsigned short blue) {
    FILE *fp = fopen(filename, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");
    }
    fseek(fp, 0, SEEK_END);

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to CSV file
    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, TCS34725_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    unsigned short clear, red, green, blue;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            // Write data to CSV file
            if (write_data_to_csv(CSV_FILE, clear, red, green, blue) != 0) {
