#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MOTOR_SHUTDOWN_GPIO 17
#define OVERCURRENT_THRESHOLD 10.0 // Amperes
#define SENSITIVITY 0.1 // V/A
#define OFFSET 0.05 // V
#define LOG_FILE "current_log.csv"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *motor_shutdown_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
int gpio_init(void);
int motor_shutdown(int state);
int log_data(float current);
void signal_handler(int sig);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to voltage conversion function
float adc_to_voltage(int adc_value) {
    return (float)adc_value * (3.3 / 1023.0);
}

// Voltage to current conversion function
float voltage_to_current(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    motor_shutdown_line = gpiod_chip_get_line(gpio_chip, MOTOR_SHUTDOWN_GPIO);
    if (!motor_shutdown_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(motor_shutdown_line, "motor_shutdown", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Motor shutdown function
int motor_shutdown(int state) {
    if (gpiod_line_set_value(motor_shutdown_line, state) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }

        // Check if the file is empty, if so, write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Current (A)\n");
        }
        fseek(log_file, 0, SEEK_END); // Reset file pointer to the end
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to current
        float current = voltage_to_current(voltage);

        // Log the data
        if (log_data(current) < 0) {
            fprintf(stderr, "Logging failed.\n");
        }

        printf("Current: %.2f A\n", current);

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Disabling motor.\n");
            if (motor_shutdown(0) < 0) {
                fprintf(stderr, "Motor shutdown failed.\n");
            }
            log_data(-1.0); // Log the overcurrent event
            sleep(1); // Wait for 1 second
            if (motor_shutdown(1) < 0) {
                fprintf(stderr, "Motor re-enable failed.\n");
            }
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Disable motor
    motor_shutdown(1);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close GPIO line
    if (motor_shutdown_line) {
        gpiod_line_release(motor_shutdown_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

