#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define PRESSURE_REG 0x00
#define LOG_FILE "pressure_log.csv"

int i2c_handle;
FILE *log_file;

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read the pressure value from the sensor
int read_pressure(int i2c_handle) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data from register 0x%02X: %d\n", PRESSURE_REG, result);
        return -1; // Indicate an error
    }

    return (buf[0] << 8) | buf[1]; // Combine the two bytes into a 16-bit value
}

// Function to convert the raw pressure value to kPa
float convert_to_kPa(int raw_value) {
    return ((float)raw_value / 65535.0) * 500.0;
}

// Function to log the pressure reading to a file
int log_pressure(const char *timestamp, float pressure_kPa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int raw_pressure;
    float pressure_kPa;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the pressure value
        raw_pressure = read_pressure(i2c_handle);
        if (raw_pressure < 0) {
            fprintf(stderr, "Error reading pressure, skipping logging.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert the pressure to kPa
        pressure_kPa = convert_to_kPa(raw_pressure);

        // Get the current timestamp
        timestamp = get_timestamp();

        // Log the pressure reading
