// Constants
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int handle, int channel);
float convert_to_pressure(int adc_value);
float convert_to_temperature(int adc_value);
void control_led(int pressure);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read from ADS1115
int read_ads1115(int handle, int channel) {
    unsigned char config[3];
    int16_t adc_value;
    int retries = 3;

    // Configure the ADS1115 for single-ended read on the specified channel
    config[0] = CONFIG_REG; // Configuration register address
    config[1] = 0xC2;       // Single-ended AIN0, FSR = +/-6.144V, 128 SPS
    config[2] = 0x83;       // Start single conversion

    if (i2cWriteDevice(handle, (char *)config, 3) != 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    char read_buffer[2];
    if (i2cReadDevice(handle, read_buffer, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    adc_value = (read_buffer[0] << 8) | read_buffer[1];

    return adc_value;
}

// Function to convert ADC value to pressure (kPa)
float convert_to_pressure(int adc_value) {
    // Assuming 0V = 0 kPa, 5V = 400 kPa
    return (float)adc_value * (400.0 / 65535.0);
}

// Function to convert ADC value to temperature (°C)
float convert_to_temperature(int adc_value) {
    // Simplified NTC approximation (1V = 0°C, 2V = 100°C)
    float voltage = (float)adc_value * (5.0 / 65535.0);
    return (voltage - 1.0) * 100.0;
}

// Function to control the LED
void control_led(int pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("MLX90834 Pressure and Temperature Sensor\n");

    while (!terminate) {
        int pressure_adc, temperature_adc;
        float pressure, temperature;

        // Read pressure and temperature from ADS1115
        pressure_adc = read_ads1115(i2c_handle, 0); // AIN0
        temperature_adc = read_ads1115(i2c_handle, 1); // AIN1

        if (pressure_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Error reading from ADS1115, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert ADC values to pressure and temperature
        pressure = convert_to_pressure(pressure_adc);
        temperature = convert_to_temperature(temperature_adc);

        // Control the LED
        control_led((int)pressure);

        // Print the pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

