#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // 4.096V reference voltage
#define SENSITIVITY 0.1   // 0.1V/kPa
#define OFFSET 0.5        // 0.5V offset
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc(int *raw_value);
double convert_to_voltage(int raw_value);
double convert_to_pressure(double voltage);
int log_pressure(double pressure);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    double ref_voltage;
    double sensitivity;
    double offset;
    double min_pressure;
    double max_pressure;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value
int read_adc(int *raw_value) {
    char config[3];
    char read_data[2];

    // Configure ADS1115 for single-ended AIN0, 4.096V, 128 SPS, continuous conversion
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // 0b11000011
    config[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for reading\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *raw_value = (read_data[0] << 8) | read_data[1];
    *raw_value = *raw_value >> 4; // 12-bit value

    return 0;
}

// Convert raw ADC value to voltage
double convert_to_voltage(int raw_value) {
    return ((double)raw_value / 32768.0) * REF_VOLTAGE;
}

// Convert voltage to pressure in kPa
double convert_to_pressure(double voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Log pressure reading to file
int log_pressure(double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int raw_value;
    double voltage, pressure;

    printf("Starting pressure monitoring...\n");

    while (!terminate) {
        // Read ADC value
        if (read_adc(&raw_value) == 0) {
            // Convert to voltage
            voltage = convert_to_voltage(raw_value);

            // Convert to pressure
            pressure = convert_to_pressure(voltage);

            // Validate pressure range
            if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
                // Log pressure
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(1000000); // 1Hz
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Pressure monitoring stopped.\n");

    return 0;
}

