#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0
#define CS_PIN 8
#define ADC_CHANNELS 3
#define ADC_RESOLUTION 1024 // 2^10
#define VREF 3.3
#define SENSITIVITY 300.0 // mV/g
#define ZERO_G_VOLTAGE 1.65
#define IMPACT_THRESHOLD 2.0 // g
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_g(float voltage);
void log_data(float x, float y, float z, float magnitude);
void check_impact(float magnitude);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // De-assert CS

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value >= ADC_RESOLUTION) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }
    return ((float)adc_value / ADC_RESOLUTION) * VREF;
}

// Function to convert voltage to acceleration in g
float voltage_to_g(float voltage) {
    return (voltage - ZERO_G_VOLTAGE) * (VREF / SENSITIVITY);
}

// Function to log data to file
void log_data(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check for impact
void check_impact(float magnitude) {
    if (magnitude > IMPACT_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // De-assert CS initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        int adc_values[ADC_CHANNELS];
        float voltages[ADC_CHANNELS];
        float g_values[ADC_CHANNELS];

        // Read ADC values from each channel
        for (int i = 0; i < ADC_CHANNELS; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] == -1) {
                fprintf(stderr, "Error: Failed to read ADC channel %d\n", i);
                continue; // Skip to the next channel
            }

            voltages[i] = adc_to_voltage(adc_values[i]);
            if (voltages[i] == -1.0) {
                fprintf(stderr, "Error: Failed to convert ADC value to voltage for channel %d\n", i);
                continue; // Skip to the next channel
            }

            g_values[i] = voltage_to_g(voltages[i]);
        }

        // Calculate acceleration magnitude
        float magnitude = sqrt(g_values[0] * g_values[0] + g_values[1] * g_values[1] + g_values[2] * g_values[2]);

        // Log data
        log_data(g_values[0], g_values[1], g_values[2], magnitude);

        // Check for impact
        check_impact(magnitude);

        // Delay for the sample period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    printf("Closing resources...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

