#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel(int channel, int baud);
int read_mcp3008(int channel);
float convert_to_flow_rate(int adc_value);
char* get_timestamp();
int log_data(char *timestamp, float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float vref;
    float flow_rate_min;
    float flow_rate_max;
    char *log_file;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_BAUD,
    MCP3008_CHANNEL,
    VREF,
    FLOW_RATE_MIN,
    FLOW_RATE_MAX,
    LOG_FILE
};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = open_spi_channel(config.spi_channel, config.spi_baud);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Continuing.\n");
            gpioDelay(1000000); // Wait 1 second
            continue;
        }

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);

        // Validate flow rate
        if (flow_rate < config.flow_rate_min || flow_rate > config.flow_rate_max) {
            fprintf(stderr, "Error: Flow rate out of range: %.2f L/min\n", flow_rate);
        }

        // Get timestamp
        char *timestamp = get_timestamp();

        // Log data
        if (log_data(timestamp, flow_rate) != 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        free(timestamp); // Free the allocated timestamp memory

        // Wait 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // SPI mode 0
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to flow rate
float convert_to_flow_rate(int adc_value) {
    return ((float)adc_value / 1023.0) * config.vref * 5.0;
}

// Get timestamp in YYYY-MM-DD HH:MM:SS.uuuuuu format
char* get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    time_t rawtime = ts.tv_sec;
    struct tm *timeinfo = localtime(&rawtime);

    char *timestamp = malloc(30 * sizeof(char)); // Allocate memory for timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + 19, 11, ".%06ld", ts.tv_nsec / 1000); // Append microseconds

    return timestamp;
}

// Log data to file
int log_data(char *timestamp, float flow_rate) {
    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

