#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASURE_COMMAND 0x6845
#define DATA_LENGTH 6
#define CSV_FILE "environmental_data.csv"
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Calibration coefficients (replace with actual values from datasheet)
float c0, c1, c00, c10, c01, c11, c20, c21, c30;

// Function prototypes
int i2c_open(int bus, int address);
int i2c_write(int fd, uint8_t *data, int length);
int i2c_read(int fd, uint8_t *data, int length);
int i2c_close(int fd);
int read_sensor_data(int fd, uint8_t *data);
int process_sensor_data(uint8_t *data, float *temperature, float *pressure);
int log_data(float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);
int init_i2c(int bus, int address);

// I2C open function with retry
int i2c_open(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function with retry
int i2c_write(int fd, uint8_t *data, int length) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(fd, data, length) == length) {
            return 0; // Success
        }
        perror("Error writing to I2C device");
        retries++;
        sleep(1); // Wait before retrying
    }
    fprintf(stderr, "Failed to write to I2C device after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C read function with retry
int i2c_read(int fd, uint8_t *data, int length) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(fd, data, length) == length) {
            return 0; // Success
        }
        perror("Error reading from I2C device");
        retries++;
        sleep(1); // Wait before retrying
    }
    fprintf(stderr, "Failed to read from I2C device after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) == 0) {
        return 0;
    } else {
        perror("Error closing I2C device");
        return -1;
    }
}

