int read_sensor_data(int fd, uint8_t *data) {
    uint8_t command = MEASURE_COMMAND;
    if (i2c_write(fd, &command, 1) != 0) {
        fprintf(stderr, "Failed to send measurement command.\n");
        return -1;
    }

    // Wait for conversion (adjust delay as needed)
    usleep(10000); // 10ms

    if (i2c_read(fd, data, DATA_LENGTH) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }

    return 0;
}

// Process sensor data function
int process_sensor_data(uint8_t *data, float *temperature, float *pressure) {
    // Extract raw values
    int32_t raw_pressure = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | (uint32_t)data[2];
    int32_t raw_temperature = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | (uint32_t)data[5];

    // Apply calibration formulas (replace with actual formulas from datasheet)
    *temperature = c0 + c1 * raw_temperature;
    *pressure = c00 + c10 * raw_temperature + c01 * raw_pressure + c11 * raw_temperature * raw_pressure;

    return 0;
}

// Log data function
int log_data(float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        return -1;
    }

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fclose(csv_file);

    return 0;
}

// Display data function
void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int address) {
    i2c_fd = i2c_open(bus, address);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c(I2C_BUS, I2C_ADDRESS) != 0) {
        return 1;
    }

    // Main loop
    uint8_t data[DATA_LENGTH];
    float temperature, pressure;

    while (program_running) {
        if (read_sensor_data(i2c_fd, data) == 0) {
            if (process_sensor_data(data, &temperature, &pressure) == 0) {
                log_data(temperature, pressure);
                display_data(temperature, pressure);
            } else {
                fprintf(stderr, "Failed to process sensor data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(5); // Sample every 5 seconds
    }

    // Cleanup
    i2c_close(i2c_fd);

    return 0;
}

