#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1

// Define noise cancellation parameters
#define NOISE_CANCELLATION_FACTOR 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t left;
    int16_t right;
} AudioData;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to perform noise cancellation
AudioData noise_cancellation(int left_channel, int right_channel) {
    AudioData result;
    result.left = (int16_t)((float)left_channel - (float)right_channel * NOISE_CANCELLATION_FACTOR);
    result.right = (int16_t)((float)right_channel - (float)left_channel * NOISE_CANCELLATION_FACTOR);
    return result;
}

int main(int argc, char *argv[]) {
    float gain = 1.0; // Default gain

    // Parse command-line arguments
    if (argc > 1) {
        gain = atof(argv[1]);
        printf("Using gain: %f\n", gain);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read audio data from microphones
        int left_channel_value = read_mcp3008(MCP3008_CHANNEL_0);
        int right_channel_value = read_mcp3008(MCP3008_CHANNEL_1);

        if (left_channel_value == -1 || right_channel_value == -1) {
            fprintf(stderr, "Error reading audio data. Retrying...\n");
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Apply gain
        left_channel_value = (int)((float)left_channel_value * gain);
        right_channel_value = (int)((float)right_channel_value * gain);

        // Perform noise cancellation
        AudioData audio_data = noise_cancellation(left_channel_value, right_channel_value);

        // Print CSV data
        printf("%d,%d\n", audio_data.left, audio_data.right);

        // Delay
        gpioDelay(1000); // 1ms delay
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

