#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define RETRY_COUNT 3
#define VOLTAGE_THRESHOLD 1.0
#define SAMPLE_INTERVAL_MS 500

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int channel);
float read_temperature(void);
float voltage_compensation(int adc_value, float temperature);
void log_data(int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected);
void control_buzzer(int flame_detected);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading from MCP3008\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Read temperature from file
float read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return 25.0; // Default temperature
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return 25.0; // Default temperature
    }

    fclose(fp);
    return temperature;
}

// Voltage compensation function
float voltage_compensation(int adc_value, float temperature) {
    float voltage = (float)adc_value * (3.3 / 1024.0);
    return voltage + (temperature - 25.0) * 0.001;
}

// Log data to file
void log_data(int adc_value, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, adc_value, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control buzzer function
void control_buzzer(int flame_detected) {
    int ret;
    if (flame_detected) {
        ret = gpiod_line_set_value(buzzer_line, 1); // Turn buzzer ON
        if (ret < 0) {
            fprintf(stderr, "Error setting buzzer value: %s\n", strerror(-ret));
        }
    } else {
        ret = gpiod_line_set_value(buzzer_line, 0); // Turn buzzer OFF
        if (ret < 0) {
            fprintf(stderr, "Error setting buzzer value: %s\n", strerror(-ret));
        }
    }
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO line
    if (buzzer_line != NULL) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value;
        float temperature;
        float compensated_voltage;
        int flame_detected = 0;

        // Retry loop for ADC reading
        for (int i = 0; i < RETRY_COUNT; i++) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "ADC read failed, retrying (%d/%d)\n", i + 1, RETRY_COUNT);
                usleep(10000); // Wait 10ms before retrying
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed after multiple retries\n");
            log_data(-1, -1.0, -1.0, -1.0, 0); // Log error
            control_buzzer(0); // Turn off buzzer
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before next sample
            continue; // Skip to the next iteration
        }

        // Read temperature
        temperature = read_temperature();

        // Voltage compensation
        compensated_voltage = voltage_compensation(adc_value, temperature);

        // Flame detection
        if (compensated_voltage > VOLTAGE_THRESHOLD) {
            flame_detected = 1;
        }

        // Log data
        log_data(adc_value, (float)adc_value * (3.3 / 1024.0), compensated_voltage, temperature, flame_detected);

        // Control buzzer
        control_buzzer(flame_detected);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

