#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Default values
#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30.0
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_PATH "/path/to/msmtp.conf"

// Global variables
int spi_handle;
int spi_channel = DEFAULT_SPI_CHANNEL;
int adc_channel = DEFAULT_ADC_CHANNEL;
int min_raw = DEFAULT_MIN_RAW;
int max_raw = DEFAULT_MAX_RAW;
double moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
char recipient_email[256] = DEFAULT_RECIPIENT_EMAIL;
char msmtp_config_path[256] = DEFAULT_MSMTP_CONFIG_PATH;

volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
double calibrate_moisture(int raw_value, int min_raw, int max_raw);
int log_data(double moisture_percentage);
int send_email(double moisture_percentage);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calibrate raw ADC value to moisture percentage
double calibrate_moisture(int raw_value, int min_raw, int max_raw) {
    double moisture_percentage = 100.0 - ((double)(raw_value - min_raw) / (double)(max_raw - min_raw)) * 100.0;
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    }
    if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }
    return moisture_percentage;
}

// Function to log data to file
int log_data(double moisture_percentage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open plant_data.txt for writing\n");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);

    return 0;
}

// Function to send email alert
int send_email(double moisture_percentage) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    char command[512];
    snprintf(command, sizeof(command), "echo \"Subject: Soil Moisture Alert\n\nTimestamp: %s\nMoisture: %.2f%%\" | msmtp -t -C %s %s", timestamp, moisture_percentage, msmtp_config_path, recipient_email);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
        return -1;
    }

    int status = pclose(fp);
    if (status != 0) {
