// GPIO cleanup function
void gpio_cleanup(void) {
    if (ce0_line) {
        gpiod_line_set_value(ce0_line, 0);
        gpiod_line_release(ce0_line);
    }
    if (ce1_line) {
        gpiod_line_set_value(ce1_line, 0);
        gpiod_line_release(ce1_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

