#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_SENSORS 4
#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8
#define CS_GPIO_PIN 100 // Dummy pin number
#define CS_GPIO_VALUE 0 // Dummy pin value
#define CS_GPIO_POLARITY 0 // Dummy pin polarity
#define CS_GPIO_DIRECTION "out" // Dummy pin direction
#define CS_GPIO_EDGE "none" // Dummy pin edge
#define CS_GPIO_BUS_REQUEST "spi0.0" // Dummy bus request
#define CS_GPIO_BUS_RELEASE "spi0.0" // Dummy bus release
#define CS_GPIO_REQUEST_FLAGS 0 // Dummy request flags
#define CS_GPIO_RELEASE_FLAGS 0 // Dummy release flags

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
float read_sensor(int channel);
int log_data(float sensor0, float sensor1, float sensor2, float sensor3);
void signal_handler(int sig);
int gpio_init(void);
int gpio_set_value(int value);
int gpio_cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read sensor data function
float read_sensor(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) & 0xFF; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    // Assert chip select
    if (gpio_set_value(1) != 0) {
        fprintf(stderr, "Error asserting chip select\n");
        return -1.0;
    }

    // Perform SPI transfer
    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        // De-assert chip select
        if (gpio_set_value(0) != 0) {
            fprintf(stderr, "Error de-asserting chip select\n");
        }
        return -1.0;
    }

    // De-assert chip select
    if (gpio_set_value(0) != 0) {
        fprintf(stderr, "Error de-asserting chip select\n");
        return -1.0;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Convert to voltage
    float voltage = (adc_value / 1023.0) * VREF;

    return voltage;
}

// Log data function
int log_data(float sensor0, float sensor1, float sensor2, float sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, sensor0, sensor1, sensor2, sensor3);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// GPIO initialization function (using libgpiod)
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, CS_GPIO_LINE);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "environmental_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = CS_GPIO_REQUEST_FLAGS;

    if (gpiod_line_request(gpio_line, &config, CS_GPIO_VALUE) != 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

// GPIO set value function (using libgpiod)
int gpio_set_value(int value) {
    if (!gpio_line) {
        fprintf(stderr, "GPIO line not initialized\n");
        return -1;
    }

    if (gpiod_line_set_value(gpio_line, value) != 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    return 0;
}

// GPIO cleanup function (using libgpiod)
int gpio_cleanup(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpio_cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        float sensor0 = read_sensor(0);
        float sensor1 = read_sensor(1);
        float sensor2 = read_sensor(2);
        float sensor3 = read_sensor(3);

        // Log data
        if (sensor0 >= 0 && sensor1 >= 0 && sensor2 >= 0 && sensor3 >= 0) {
            log_data(sensor0, sensor1, sensor2, sensor3);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(spi_fd);
    fclose(log_file);
    gpio_cleanup();

    fprintf(stderr, "Exiting cleanly\n");
    return 0;
}

