#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL 5 // seconds

// Data structure for the circular buffer
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

// Global variables
int spi_handle;
volatile int pump_state = 0; // 0 = off, 1 = on
LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_data(int moisture_level, int pump_state);
void print_log_buffer();
void timer_callback();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", PUMP_GPIO);
    }
}

// Function to log data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to print the contents of the circular buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer[index].timestamp));
        printf("[%s] Moisture: %d, Pump: %s\n", timestamp_str, log_buffer[index].moisture_level, log_buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("-------------------\n");
}

// Timer callback function
void timer_callback() {
    int moisture_level = read_mcp3008(0);
    if (moisture_level == -1) {
        fprintf(stderr, "Error: Failed to read moisture level\n");
        return;
    }

    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        control_pump(1); // Turn pump ON
        pump_state = 1;
        log_data(moisture_level, pump_state);
        printf("Moisture level: %d, Pump: ON\n", moisture_level);
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        control_pump(0); // Turn pump OFF
        pump_state = 0;
        log_data(moisture_level, pump_state);
        printf("Moisture level: %d, Pump: OFF\n", moisture_level);
    } else {
        log_data(moisture_level, pump_state);
        printf("Moisture level: %d, Pump: %s\n", moisture_level, pump_state ? "ON" : "OFF");
    }

    print_log_buffer();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop the timer
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer 0

    // Turn pump OFF
    control_pump(0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL * 1000, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Infinite loop
    while (1) {
        gpioDelay(1000); // Sleep for 1 second
    }

    return 0;
}

