// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define VREF 3.3
#define CSV_FILE "analog_log.csv"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value);
int log_data(int channel, float voltage);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Reads the ADC value from the specified channel of the MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI command
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Calculates the voltage from the ADC value
float calculate_voltage(int adc_value) {
    return (adc_value / 1023.0) * VREF;
}

// Logs the channel number and voltage to a CSV file
int log_data(int channel, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Could not open CSV file %s\n", CSV_FILE);
        return -1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long fsize = ftell(csv_file);
    if (fsize == 0) {
        fprintf(csv_file, "Timestamp,Channel,Voltage\n");
    }

    fprintf(csv_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fclose(csv_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data logging... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel <= 2; channel++) {
            int adc_value = read_mcp3008(channel);
            if (adc_value >= 0) {
                float voltage = calculate_voltage(adc_value);
                if (log_data(channel, voltage) != 0) {
                    fprintf(stderr, "Error: Failed to log data for channel %d\n", channel);
                }
            } else {
                fprintf(stderr, "Error: Failed to read ADC value from channel %d\n", channel);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 500ms
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

