#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define RELAY_GPIO 17
#define DOOR_SENSOR_GPIO 27
#define NUM_SAMPLES 10
#define SAMPLE_INTERVAL_MS 50
#define POLL_INTERVAL_MS 200
#define RELAY_DURATION_S 3
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *door_sensor_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_adc(int channel);
float calculate_distance(int adc_value);
int calibrate_threshold(int *samples, int num_samples);
int read_door_sensor();
void activate_relay();
void deactivate_relay();
void log_event(const char *event);
void signal_handler(int sig);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO lines
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    door_sensor_line = gpiod_chip_get_line(gpio_chip, DOOR_SENSOR_GPIO);
    if (!door_sensor_line) {
        perror("Error getting door sensor GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("Error requesting relay GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_input(door_sensor_line, "door_sensor") < 0) {
        perror("Error requesting door sensor GPIO line as input");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to read ADC value from ADS1115
int read_adc(int channel) {
    unsigned char config[3];
    short adc_value;

    // Configure ADS1115 for single-ended read on specified channel
    config[0] = CONFIG_REG;
    config[1] = 0x40 | (channel << 1) | 0x03; // Single-ended, 128 SPS, +/-4.096V
    config[2] = 0x83; // Disable comparator, start single conversion

    if (write(i2c_fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion register
    unsigned char data[2];
    config[0] = CONVERSION_REG;
    if (write(i2c_fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];

    return adc_value;
}

// Function to calculate distance from ADC value (using GP2Y0A21YK0F datasheet)
float calculate_distance(int adc_value) {
    // Linear approximation: distance (cm) = 29.14 / (adc_value - 2.7)
    // This is a rough approximation and may need calibration.
    if (adc_value > 0) {
        return 29.14 / (adc_value - 2.7);
    } else {
        return 100.0; // Return a large value if ADC reading is invalid
    }
}

// Function to calibrate the threshold
int calibrate_threshold(int *samples, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    return (int)(sum / num_samples * 0.8);
}

// Function to read the door sensor
int read_door_sensor() {
    int value = gpiod_line_get_value(door_sensor_line);
    if (value < 0) {
        perror("Error reading door sensor value");
        return -1;
    }
    return value;
}

// Function to activate the relay
void activate_relay() {
    if (gpiod_line_set_value(relay_line, 1) < 0) {
        perror("Error activating relay");
    }
    log_event("Relay activated");
}

// Function to deactivate the relay
void deactivate_relay() {
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        perror("Error deactivating relay");
    }
    log_event("Relay deactivated");
}

// Function to log events to a file
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Calibrate threshold
    int adc_samples[NUM_SAMPLES];
    for (int i = 0; i < NUM_SAMPLES; i++) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC during calibration. Exiting.\n");
            deactivate_relay();
            gpiod_chip_close(gpio_chip);
            close(i2c_fd);
            return 1;
        }
        adc_samples[i] = adc_value;
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }
    int threshold = calibrate_threshold(adc_samples, NUM_SAMPLES);
    printf("Threshold: %d\n", threshold);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0);
