#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_PIN_0 8
#define CS_GPIO_PIN_1 7
#define CS_GPIO_PIN_2 25
#define LOG_FILE "soil_moisture_log.csv"
#define LOG_INTERVAL 5 // seconds

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line_0 = NULL;
static struct gpiod_line *cs_line_1 = NULL;
static struct gpiod_line *cs_line_2 = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int read_mcp3008(int chip_select_pin, int channel);
int log_data(int sensor1, int sensor2, int sensor3);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed (1 MHz)
    int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line_0 = gpiod_chip_get_line(gpio_chip, CS_GPIO_PIN_0);
    cs_line_1 = gpiod_chip_get_line(gpio_chip, CS_GPIO_PIN_1);
    cs_line_2 = gpiod_chip_get_line(gpio_chip, CS_GPIO_PIN_2);

    if (!cs_line_0 || !cs_line_1 || !cs_line_2) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line_0, "soil_moisture", 0) < 0 ||
        gpiod_line_request_output(cs_line_1, "soil_moisture", 0) < 0 ||
        gpiod_line_request_output(cs_line_2, "soil_moisture", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// MCP3008 read function
int read_mcp3008(int chip_select_pin, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    // Configure SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    // Chip select
    if (gpiod_line_set_value(cs_line_0, 0) < 0 ||
        gpiod_line_set_value(cs_line_1, 0) < 0 ||
        gpiod_line_set_value(cs_line_2, 0) < 0) {
        perror("Error setting CS line low");
        return -1;
    }

    // Transfer data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        // Deselect chip after error
        if (gpiod_line_set_value(cs_line_0, 1) < 0 ||
            gpiod_line_set_value(cs_line_1, 1) < 0 ||
            gpiod_line_set_value(cs_line_2, 1) < 0) {
            perror("Error setting CS line high after error");
        }
        return -1;
    }

    // Deselect chip
    if (gpiod_line_set_value(cs_line_0, 1) < 0 ||
        gpiod_line_set_value(cs_line_1, 1) < 0 ||
        gpiod_line_set_value(cs_line_2, 1) < 0) {
        perror("Error setting CS line high");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Data logging function
int log_data(int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file is newly created
    if (access(LOG_FILE, F_OK) == -1) {
        // File doesn't exist, write the header
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            perror("Error opening log file for writing");
            return -1;
        }
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    } else {
        // File exists, open in append mode
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("Error opening log file for appending");
            return -1;
        }
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fclose(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    fprintf(stderr, "Cleaning up resources...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO lines
    if (cs_line_0) {
        gpiod_line_release(cs_line_0);
    }
    if (cs_line_1) {
        gpiod_line_release(cs_line_1);
    }
    if (cs_line_2) {
        gpiod_line_release(cs_line_2);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    fprintf(stderr, "Cleanup complete.\n");
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Initialization complete. Logging data every %d seconds.\n", LOG_INTERVAL);

    // Main loop
    while (!terminate) {
        int sensor1 = read_mcp3008(CS_GPIO_PIN_0, 0);
        int sensor2 = read_mcp3008(CS_GPIO_PIN_1, 0);
        int sensor3 = read_mcp3008(CS_GPIO_PIN_2, 0);

        if (sensor1 == -1 || sensor2 == -1 || sensor3 == -1) {
            fprintf(stderr, "Error reading sensor data. Logging -1 for all sensors.\n");
            log_data(-1, -1, -1);
        } else {
            if (log_data(sensor1, sensor2, sensor3) < 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        sleep(LOG_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

