    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                moisture_threshold = atof(optarg);
                break;
            case 'd':
                pump_duration = atof(optarg);
                break;
            case 's':
                sleep_interval = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Irrigation system started");

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture = adc_to_moisture(adc_value);
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
            log_message(log_buffer);

            if (moisture < moisture_threshold) {
                control_pump(1); // Activate pump
                gpioDelay(pump_duration * 1000000); // Delay for pump duration (microseconds)
                control_pump(0); // Deactivate pump
            }
        } else {
            log_message("Error: Failed to read moisture sensor");
        }

        gpioDelay(sleep_interval * 1000000); // Delay for sleep interval (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

