#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define SAMPLE_INTERVAL_MS 100

int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a byte from the I2C device
int read_i2c_byte(int fd, uint8_t *data) {
    ssize_t bytes_read = read(fd, data, 1);
    if (bytes_read != 1) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a byte to the I2C device
int write_i2c_byte(int fd, uint8_t data) {
    ssize_t bytes_written = write(fd, &data, 1);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t control_byte = 0x40; // Single-ended mode, AIN0, analog output disabled
    uint8_t dummy_data;

    // Dummy read to clear the previous conversion
    if (read_i2c_byte(i2c_fd, &dummy_data) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print the ADC value
    while (1) {
        // Write the control byte to initiate the conversion
        if (write_i2c_byte(i2c_fd, control_byte) != 0) {
            close(i2c_fd);
            return 1;
        }

        // Read the ADC value from the I2C device
        uint8_t adc_value;
        if (read_i2c_byte(i2c_fd, &adc_value) != 0) {
            close(i2c_fd);
            return 1;
        }

        // Print the ADC value
        printf("ADC Value: %d\n", adc_value);

        // Wait for the specified interval
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup for completeness.
    close(i2c_fd);
    return 0;
}

