#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_MOTOR_SHUTDOWN 27
#define MAGNETIC_FIELD_THRESHOLD 500.0 // Gauss
#define BUFFER_SIZE 10
#define NUM_SENSORS 3

// Sensor Calibration Data
typedef struct {
    int sensor_id;
    float zero_field_voltage;
    float sensitivity;
} sensor_calibration_t;

sensor_calibration_t sensor_calibrations[NUM_SENSORS] = {
    {0, 2.5, 1.4}, // Sensor 0
    {1, 2.5, 1.4}, // Sensor 1
    {2, 2.5, 1.4}  // Sensor 2
};

// Global Variables
int i2c_handles[NUM_SENSORS];
float magnetic_field_readings[NUM_SENSORS][BUFFER_SIZE];
int buffer_index = 0;
bool motor_shutdown_active = false;

// Function Prototypes
int initialize_i2c(int sensor_id);
int read_adc(int i2c_handle);
float convert_to_voltage(int raw_value);
float convert_to_gauss(int raw_value, int sensor_id);
void update_circular_buffer(float gauss_value, int sensor_id);
float calculate_rolling_average(int sensor_id);
void control_motor_shutdown(float average_gauss);
void log_data(int sensor_id, float voltage, float gauss, float rolling_average);
void log_threshold_event(int sensor_id, float rolling_average);
void signal_handler(int signal);

// Function Implementations

int initialize_i2c(int sensor_id) {
    int handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (handle < 0) {
        syslog(LOG_ERR, "Sensor %d: Failed to open I2C device: %d", sensor_id, handle);
        return -1;
    }

    // Configure ADS1115 for single-ended channel AIN0, 4.096V range, 128 SPS
    unsigned char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0x43; // 0b01000011
    config[2] = 0x83; // 0b10000011

    int result = i2cWriteDevice(handle, config, 3);
    if (result != 0) {
        syslog(LOG_ERR, "Sensor %d: Failed to write to I2C device: %d", sensor_id, result);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

int read_adc(int i2c_handle) {
    unsigned char buffer[2];
    int raw_value;

    // Read the conversion register
    int result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        syslog(LOG_ERR, "Failed to read ADC value: %d", result);
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

float convert_to_voltage(int raw_value) {
    return (float)raw_value * 4.096 / 32768.0;
}

float convert_to_gauss(int raw_value, int sensor_id) {
    float voltage = convert_to_voltage(raw_value);
    if (voltage < 0 || voltage > 3.3) {
        syslog(LOG_ERR, "Sensor %d: Invalid voltage reading: %f", sensor_id, voltage);
        return -1.0;
    }

    float gauss = (voltage - sensor_calibrations[sensor_id].zero_field_voltage) / (sensor_calibrations[sensor_id].sensitivity / 1000.0);
    return gauss;
}

void update_circular_buffer(float gauss_value, int sensor_id) {
    magnetic_field_readings[sensor_id][buffer_index] = gauss_value;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

float calculate_rolling_average(int sensor_id) {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += magnetic_field_readings[sensor_id][i];
    }
    return sum / BUFFER_SIZE;
}

void control_motor_shutdown(float average_gauss) {
    if (average_gauss > MAGNETIC_FIELD_THRESHOLD && !motor_shutdown_active) {
        gpioWrite(GPIO_MOTOR_SHUTDOWN, 1); // HIGH
        motor_shutdown_active = true;
        syslog(LOG_INFO, "Motor shutdown activated!");
    } else if (average_gauss <= MAGNETIC_FIELD_THRESHOLD && motor_shutdown_active) {
        gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // LOW
        motor_shutdown_active = false;
        syslog(LOG_INFO, "Motor shutdown deactivated!");
    }
}

void log_data(int sensor_id, float voltage, float gauss, float rolling_average) {
    syslog(LOG_INFO, "Sensor %d: Voltage = %.3f V, Gauss = %.3f, Rolling Average = %.3f", sensor_id, voltage, gauss, rolling_average);
}

void log_threshold_event(int sensor_id, float rolling_average) {
    syslog(LOG_WARNING, "Sensor %d: Rolling average exceeded threshold (%.3f Gauss)", sensor_id, rolling_average);
}

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("magnetic_field_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_MOTOR_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Initialize to LOW

    // Initialize I2C for each sensor
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = initialize_i2c(i);
        if (i2c_handles[i] < 0) {
            // Handle initialization failure, but continue with other sensors
            syslog(LOG_ERR, "Failed to initialize sensor %d, continuing...", i);
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                int raw_value = read_adc(i2c_handles[i]);
                if (raw_value >= 0) {
                    float voltage = convert_to_voltage(raw_value);
                    float gauss = convert_to_gauss(raw_value, i);

                    if (gauss >= 0) {
                        update_circular_buffer(gauss, i);
                        float rolling_average = calculate_rolling_average(i);
                        control_motor_shutdown(rolling_average);
                        log_data(i, voltage, gauss, rolling_average);

                        if (rolling_average > MAGNETIC_FIELD_THRESHOLD) {
                            log_threshold_event(i, rolling_average);
                        }
                    }
                }
            }
        }
        gpioDelay(100000); // 1 Hz sampling rate (100 ms delay)
    }

    return 0;
}

