#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define READ_INTERVAL 60      // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int is_moisture_low(int adc_value, int threshold);
void control_pump(int gpio_pin, int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);

    if (spi_result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", spi_result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to check if moisture level is low
int is_moisture_low(int adc_value, int threshold) {
    return adc_value < threshold;
}

// Function to control the water pump
void control_pump(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI_MODE_0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Watering system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read moisture level
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            log_event("Error: Failed to read ADC value");
            gpioDelay(READ_INTERVAL * 1000); // Wait before retrying
            continue;
        }

        // Check moisture level
        if (is_moisture_low(adc_value, MOISTURE_THRESHOLD)) {
            fprintf(stderr, "Moisture level low (ADC: %d). Activating pump.\n", adc_value);
            log_event("Moisture level low. Activating pump.");

            // Activate pump
            control_pump(PUMP_GPIO, 1);
            gpioDelay(WATERING_DURATION * 1000); // Wait for watering duration

            // Deactivate pump
            control_pump(PUMP_GPIO, 0);
            fprintf(stderr, "Pump deactivated.\n");
            log_event("Pump deactivated.");
        } else {
            fprintf(stderr, "Moisture level OK (ADC: %d).\n", adc_value);
            log_event("Moisture level OK.");
        }

        // Wait before next reading
        gpioDelay(READ_INTERVAL * 1000);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    control_pump(PUMP_GPIO, 0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

