        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Watering system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read moisture level
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            log_event("Error: Failed to read ADC value");
            gpioDelay(READ_INTERVAL * 1000); // Wait before retrying
            continue;
