            // Deactivate pump
            control_pump(PUMP_GPIO, 0);
            fprintf(stderr, "Pump deactivated.\n");
            log_event("Pump deactivated.");
        } else {
            fprintf(stderr, "Moisture level OK (ADC: %d).\n", adc_value);
            log_event("Moisture level OK.");
        }

        // Wait before next reading
        gpioDelay(READ_INTERVAL * 1000);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    control_pump(PUMP_GPIO, 0); // Ensure pump is off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

