#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1.0 // seconds
#define BLINK_ON_TIME 0.05 // seconds
#define BLINK_OFF_TIME 0.05 // seconds

// Global variables
static int i2c_handle;
static double threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
double convert_to_gauss(int16_t adc_value);
void control_led(int state);
void blink_led();
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    double threshold;
    int led_gpio;
} Config;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended input on AIN0, PGA=4.096V
    uint8_t config[3];
    config[0] = CONFIG_REG; // Configuration register address
    config[1] = 0xC2;       // Single-ended AIN0, PGA=4.096V, 128 SPS
    config[2] = 0x83;       // Enable, start single conversion

    int result = i2cWriteDevice(i2c_handle, (char *)config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read ADC value
int16_t read_adc() {
    uint8_t read_config[3];
    read_config[0] = CONVERSION_REG; // Conversion register address
    read_config[1] = 0x00;           // Dummy byte
    read_config[2] = 0x00;           // Dummy byte

    int result = i2cWriteDevice(i2c_handle, (char *)read_config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C for read: %d\n", result);
        return -1;
    }

    char buffer[2];
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    return (int16_t)((buffer[0] << 8) | buffer[1]);
}

// Function to convert ADC value to Gauss
double convert_to_gauss(int16_t adc_value) {
    // Assuming 3.3V reference and 4.096V PGA
    double voltage = (adc_value * 3.3) / 65535.0;
    return voltage / 0.001; // 1.0 mV/Gauss = 0.001 V/Gauss
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Function to blink the LED
void blink_led() {
    control_led(1); // Turn on LED
    gpioDelay(BLINK_ON_TIME * 1000000); // Delay in microseconds
    control_led(0); // Turn off LED
    gpioDelay(BLINK_OFF_TIME * 1000000); // Delay in microseconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        double gauss = convert_to_gauss(adc_value);
        printf("Magnetic Field Strength: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            blink_led();
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

