#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <stdbool.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define MQTT_HOST "localhost" // Change to your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_PUBLISH_TOPIC "soil_moisture"
#define MQTT_SUBSCRIBE_TOPIC "pump_control"
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MOISTURE_READ_INTERVAL 60 // seconds

// Global variables
static int spi_handle;
static struct mosquitto *mqtt_client = NULL;
static volatile sig_atomic_t terminate = 0;
static bool pump_state = false; // false = off, true = on

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(bool on);
void publish_moisture(float moisture);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int sig);
int mqtt_connect_and_subscribe();
void mqtt_disconnect();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0) {
        syslog(LOG_ERR, "Invalid ADC value: %d", adc_value);
        return -1.0;
    }

    // Assuming ADC range is 0-1023 (10-bit ADC)
    // Map ADC value to moisture percentage (0-100%)
    // This is a linear mapping; adjust as needed for your sensor
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;

    // Clamp moisture to 0-100%
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;

    return moisture;
}

// Function to control the relay
void control_relay(bool on) {
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", RELAY_GPIO);
    }
    pump_state = on;
    syslog(LOG_INFO, "Relay %s", on ? "ON" : "OFF");
}

// Function to publish moisture reading to MQTT
void publish_moisture(float moisture) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int ret = mosquitto_publish(mqtt_client, NULL, MQTT_PUBLISH_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(ret));
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_SUBSCRIBE_TOPIC) == 0) {
            if (strcmp(message->payload, "pump_on") == 0) {
                control_relay(true);
            } else if (strcmp(message->payload, "pump_off") == 0) {
                control_relay(false);
            } else {
                syslog(LOG_WARNING, "Unknown MQTT message: %s", (char *)message->payload);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to connect to MQTT broker and subscribe to topic
int mqtt_connect_and_subscribe() {
    int ret;

    mosquitto_lib_init();

    mqtt_client = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        return -1;
    }

    mosquitto_connect_callback_set(mqtt_client, NULL);
    mosquitto_message_callback_set(mqtt_client, message_callback);

    ret = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_subscribe(mqtt_client, NULL, MQTT_SUBSCRIBE_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(ret));
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        return -1;
    }

    syslog(LOG_INFO, "Connected to MQTT broker and subscribed to topic");
    return 0;
}

// Function to disconnect from MQTT broker
void mqtt_disconnect() {
    if (mqtt_client) {
        mosquitto_disconnect(mqtt_client);
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        syslog(LOG_INFO, "Disconnected from MQTT broker");
    }
}

int main() {
    openlog("soil_moisture_sensor", LOG_PID, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(false); // Ensure relay is off on startup

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (mqtt_connect_and_subscribe() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value);
        if (moisture < 0.0) {
            syslog(LOG_ERR, "Failed to calculate moisture");
            continue; // Skip to the next iteration
        }

        // Control relay based on moisture level
        if (moisture < MOISTURE_THRESHOLD_LOW && !pump_state) {
            control_relay(true);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state) {
            control_relay(false);
        }

        // Publish moisture reading
        publish_moisture(moisture);

        // MQTT loop
        mosquitto_loop(mqtt_client, 0, 1); // Non-blocking loop

        // Wait for the next reading
        sleep(MOISTURE_READ_INTERVAL);
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    control_relay(false); // Ensure relay is off
    spiClose(spi_handle);
    mqtt_disconnect();
    gpioTerminate();
    closelog();

    return 0;
}

