#include <unistd.h>

// Define GPIO pins for vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADC channel for noise level
#define NOISE_LEVEL_CHANNEL 0

// Define noise level threshold
#define NOISE_THRESHOLD 500

// Define PWM frequency
#define PWM_FREQUENCY 100 // Hz

// Define log file name
#define LOG_FILE "vibration_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
int map_adc_to_pwm(int adc_value);
void set_motor_pwm(int gpio, int pwm_value);
void log_event(int adc_value, int pwm_value);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map ADC value to PWM duty cycle
int map_adc_to_pwm(int adc_value) {
    // Linearly map ADC value (0-1023) to PWM duty cycle (0-1000000)
    return (int)(((float)adc_value / 1023.0) * 1000000.0);
}

// Function to set PWM duty cycle for a motor
void set_motor_pwm(int gpio, int pwm_value) {
    gpioPWM(gpio, pwm_value);
}

// Function to log event to file
void log_event(int adc_value, int pwm_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - ADC: %d, PWM: %d\n", timestamp, adc_value, pwm_value);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-1000000)
    gpioSetPWMrange(MOTOR1_GPIO, 1000000);
    gpioSetPWMrange(MOTOR2_GPIO, 1000000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read noise level from ADC
        int adc_value = read_adc(NOISE_LEVEL_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Map ADC value to PWM duty cycle
        int pwm_value = map_adc_to_pwm(adc_value);

        // Control motors based on noise level
        if (adc_value > NOISE_THRESHOLD) {
            set_motor_pwm(MOTOR1_GPIO, pwm_value);
            set_motor_pwm(MOTOR2_GPIO, pwm_value);
            log_event(adc_value, pwm_value);
        } else {
            set_motor_pwm(MOTOR1_GPIO, 0);
            set_motor_pwm(MOTOR2_GPIO, 0);
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // pigpio's delay function
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_motor_pwm(MOTOR1_GPIO, 0);
    set_motor_pwm(MOTOR2_GPIO, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

