float calculate_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value from response
            result = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return result;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d), retrying...\n", retries + 1);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    // Assuming 0 ADC value corresponds to 0% moisture and 1023 corresponds to 100%
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
}

// Function to log data with timestamp
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture_percentage);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(60000); // Wait 60 seconds before retrying
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Control the pump based on moisture level
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            control_pump(1); // Turn on pump
        } else {
            control_pump(0); // Turn off pump
        }

        // Log the data
        log_data(moisture_percentage);

        // Wait 60 seconds
        gpioDelay(60000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

