#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_sensor_values(int sensor_values[], int num_sensors);
int map_to_valve_position(float average_value);
void set_valve_position(int position);
void log_data(int sensor_values[], float average_value, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message for MCP3008
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to average sensor values
float average_sensor_values(int sensor_values[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensor_values[i] >= 0) { // Only include valid readings
            sum += sensor_values[i];
            valid_count++;
        }
    }

    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return -1.0; // Indicate no valid readings
    }
}

// Function to map average ADC value to valve position
int map_to_valve_position(float average_value) {
    if (average_value < 0) return 0; // Handle invalid average
    return (int)(100.0 - (average_value / 1023.0) * 100.0); // Inverse mapping
}

// Function to set valve position using PWM
void set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > 100) position = 100;

    gpioPWM(VALVE_GPIO, position);
}

// Function to log data to file
void log_data(int sensor_values[], float average_value, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Sensor0: %d, Sensor1: %d, Sensor2: %d, Average: %.2f, Valve: %d\n",
            timestamp, sensor_values[0], sensor_values[1], sensor_values[2], average_value, valve_position);
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor_values[NUM_SENSORS];
        float average_value;
        int valve_position;

        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d\n", i);
                sensor_values[i] = -1; // Mark as invalid
            }
        }

        // Calculate average sensor value
        average_value = average_sensor_values(sensor_values, NUM_SENSORS);
        if (average_value < 0) {
            fprintf(stderr, "Error: No valid sensor readings, skipping valve control\n");
            set_valve_position(0); // Close valve
            log_data(sensor_values, -1.0, 0); // Log with invalid average
        } else {
            // Map average value to valve position
            valve_position = map_to_valve_position(average_value);

            // Set valve position
            set_valve_position(valve_position);

            // Log data
            log_data(sensor_values, average_value, valve_position);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_valve_position(0); // Close valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

