int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value = -1; // Initialize to an error value
    int retries = 0;

    // Construct SPI command (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
