    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            float moisture_percentage = convert_to_moisture(adc_value);
            if (moisture_percentage != -1.0) {
                log_data(moisture_percentage);
                printf("Moisture: %.2f%%\n", moisture_percentage);
            } else {
                fprintf(stderr, "Error converting ADC value to moisture percentage.\n");
            }
        } else {
            fprintf(stderr, "Error reading from MCP3008.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

