#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_SENSORS 3
#define CALIBRATION_FILE "theremin_config.txt"
#define LOG_FILE "theremin_log.txt"

// Default calibration values
float default_calibration[NUM_SENSORS] = {1.0, 1.0, 1.0};

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int trig_pin;
    int echo_pin;
    float calibration_factor;
} sensor_t;

// Function prototypes
float read_distance(int trig_pin, int echo_pin);
int read_ldr(int spi_handle);
float map_distance_to_frequency(float distance, float min_distance, float max_distance, float min_frequency, float max_frequency);
int map_ldr_to_volume(int ldr_value, int min_ldr, int max_ldr, int min_volume, int max_volume);
void save_calibration(float calibration[], int num_sensors, const char *filename);
void load_calibration(float calibration[], int num_sensors, const char *filename);
void signal_handler(int signal);

// Function to read distance from HC-SR04 sensor
float read_distance(int trig_pin, int echo_pin) {
    gpioWrite(trig_pin, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(trig_pin, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(echo_pin) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    if (count >= 10000) {
        fprintf(stderr, "Error: Echo start timeout on pin %d\n", echo_pin);
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(echo_pin) == 1 && count < 10000) {
        count++;
        gpioDelay(1);
    }
    if (count >= 10000) {
        fprintf(stderr, "Error: Echo end timeout on pin %d\n", echo_pin);
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = time_taken * 34300.0 / 2.0; // Distance in cm

    return distance;
}

// Function to read LDR value from MCP3008 ADC
int read_ldr(int spi_handle) {
    char tx_buf[3];
    char rx_buf[3];

    // MCP3008 configuration: single-ended channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance, float min_distance, float max_distance, float min_frequency, float max_frequency) {
    if (distance <= min_distance) {
        return min_frequency;
    } else if (distance >= max_distance) {
        return max_frequency;
    } else {
        return min_frequency + (distance - min_distance) * (max_frequency - min_frequency) / (max_distance - min_distance);
    }
}

// Function to map LDR value to volume
int map_ldr_to_volume(int ldr_value, int min_ldr, int max_ldr, int min_volume, int max_volume) {
    if (ldr_value <= min_ldr) {
        return min_volume;
    } else if (ldr_value >= max_ldr) {
        return max_volume;
    } else {
        return min_volume + (ldr_value - min_ldr) * (max_volume - min_volume) / (max_ldr - min_ldr);
    }
}

// Function to save calibration data to file
void save_calibration(float calibration[], int num_sensors, const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing\n");
        return;
    }

    for (int i = 0; i < num_sensors; i++) {
        fprintf(fp, "sensor%d_calibration: %f\n", i, calibration[i]);
    }

    fclose(fp);
}

// Function to load calibration data from file
void load_calibration(float calibration[], int num_sensors, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file, using default values\n");
        for (int i = 0; i < num_sensors; i++) {
            calibration[i] = default_calibration[i];
        }
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        char *key = strtok(line, ":");
        char *value_str = strtok(NULL, "\n");

        if (key != NULL && value_str != NULL) {
            if (strncmp(key, "sensor0_calibration", 18) == 0) {
                calibration[0] = atof(value_str);
            } else if (strncmp(key, "sensor1_calibration", 18) == 0) {
                calibration[1] = atof(value_str);
            } else if (strncmp(key, "sensor2_calibration", 18) == 0) {
                calibration[2] = atof(value_str);
            }
        }
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Initialize PWM
    gpioSetPWMfrequency(PWM_PIN, 440); // Initial frequency (will be overridden later)
    gpioSetPWMrange(PWM_PIN, 1000); // PWM range

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Load calibration data
    float sensor_calibration[NUM_SENSORS];
    load_calibration(sensor_calibration, NUM_SENSORS, CALIBRATION_FILE);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float distances[NUM_SENSORS];
        int ldr_values[NUM_SENSORS];
        float frequency[NUM_SENSORS];
        int volume[NUM_SENSORS];

        // Read sensor data
        for (int i = 0; i < NUM_SENSORS; i++) {
            distances[i] = read_distance(TRIG_PIN, ECHO_PIN);
            if (distances[i] < 0) {
                distances[i] = 100.0; // Use a default value in case of error
            }
            ldr_values[i] = read_ldr(spi_handle);
            if (ldr_values[i] < 0) {
                ldr_values[i] = 512; // Use a default value in case of error
            }
        }

        // Map sensor data to audio parameters
        for (int i = 0; i < NUM_SENSORS; i++) {
            frequency[i] = map_distance_to_frequency(distances[i], 10.0, 100.0, 220.0, 880.0);
            volume[i] = map_ldr_to_volume(ldr_values[i], 0, 1023, 0, 1000);
        }

        // Calculate average frequency and volume
        float avg_frequency = 0.0;
        int avg_volume = 0;
        int valid_sensor_count = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (distances[i] > 0) { // Check for valid distance reading
                avg_frequency += frequency[i] * sensor_calibration[i];
                avg_volume += volume[i];
                valid_sensor_count++;
            }
        }

        if (valid_sensor_count > 0) {
            avg_frequency /= valid_sensor_count;
            avg_volume /= valid_sensor_count;
        } else {
            avg_frequency = 440.0; // Default frequency
            avg_volume = 500; // Default volume
        }

        // Set PWM frequency and duty cycle
        gpioSetPWMfrequency(PWM_PIN, (int)avg_frequency);
        gpioPWM(PWM_PIN, avg_volume);

        // Log data
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %.2f, Volume: %d\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
                    avg_frequency, avg_volume);
            fclose(log_file);
        } else {
            fprintf(stderr, "Error: Could not open log file\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup
    gpioPWM(PWM_PIN, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

