#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int convert_to_aqi(int adc_value);
void control_fan(int aqi);
void log_data(int aqi);
