// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1;
    int retries = 0;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode + channel
    tx_buffer[2] = 0x00; // Dummy byte

    while (retries < RETRY_COUNT) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d). Retrying...\n", retries + 1);
            gpioDelay(RETRY_DELAY * 1000000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "SPI read failed after %d retries. Exiting.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to convert ADC value to AQI
int convert_to_aqi(int adc_value) {
    // Linear mapping: 0-500 AQI for 0-1023 ADC value
    return (int)(((float)adc_value / 1023.0) * 500.0);
}

