void control_fan(int aqi) {
    if (aqi > 100) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON (AQI: %d)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF (AQI: %d)\n", aqi);
    }
}

