        return -1;
    }

    // Set max speed
    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(const char *chip, int pin) {
    struct gpiod_chip *chip_ = gpiod_chip_open_by_name(chip);
    if (!chip_) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_ = gpiod_chip_get_line(chip_, pin);
    if (!line_) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_);
        return -1;
    }

    int ret = gpiod_line_request_output(line_, "alcohol_sensor", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_);
        gpiod_line_release(line_);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO Get Value
int gpio_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Read MCP3008
int read_mcp3008(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value = -1;

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (channel << 4) | 0x80; // Single-ended + channel
    tx[2] = 0x00; // Dummy byte

    for (int i = 0; i < MAX_RETRIES; ++i) {
        if (spi_transfer(spi_fd, tx, rx, 3) == 0) {
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "SPI transfer failed, retrying (%d/%d)...\n", i + 1, MAX_RETRIES);
            usleep(100000); // 100 ms delay
        }
    }

    if (adc_value == -1) {
        fprintf(stderr, "Failed to read MCP3008 after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return adc_value;
}

// Convert to PPM
float convert_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Classify Reading
const char *classify_reading(float ppm) {
    if (ppm > 50.0) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < 20.0) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

// Log Reading
int log_reading(const char *timestamp, int adc_value, float ppm, const char *classification) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, ADC: %d, PPM: %.2f, Classification: %s\n", timestamp, adc_value, ppm, classification);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Convert to PPM
        float ppm = convert_to_ppm(adc_value);

        // Classify reading
        const char *classification = classify_reading(ppm);

        // Get timestamp
        time_t now = time(NULL);
        struct tm *tstruct = gmtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

        // Log reading
        if (log_reading(timestamp, adc_value, ppm, classification) != 0) {
            fprintf(stderr, "Failed to log reading.\n");
        }

        // Sleep for the specified interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Exiting.\n");
    return 0;
}

