#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// MCP3008
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Speed factor mapping
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion profile parameters
#define ACCELERATION_TIME 2 // seconds
#define DECELERATION_TIME 2 // seconds
#define PAUSE_TIME 5 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float map_potentiometer_to_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void motion_profile(int motor1_speed, int motor2_speed);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor
float map_potentiometer_to_speed(int pot_value) {
    // Logarithmic mapping
    float speed_factor = (float)(pot_value) / 1023.0;
    speed_factor = MIN_SPEED + (MAX_SPEED - MIN_SPEED) * (1.0 - exp(-speed_factor * 10.0));
    return speed_factor;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    int gpio_pin;
    if (motor == 1) {
        gpio_pin = MOTOR1_ENABLE;
    } else {
        gpio_pin = MOTOR2_ENABLE;
    }
    gpioPWM(gpio_pin, speed);
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    int gpio_pin;
    if (motor == 1) {
        gpio_pin = MOTOR1_DIRECTION;
    } else {
        gpio_pin = MOTOR2_DIRECTION;
    }
    gpioWrite(gpio_pin, direction);
}

// Function to implement motion profile
void motion_profile(int motor1_speed, int motor2_speed) {
    int current_speed = MIN_SPEED;
    int target_speed = MAX_SPEED;
    int direction = 1; // 1 for forward, 0 for backward

    // Acceleration
    for (int i = 0; i < ACCELERATION_TIME * 100; i++) {
        current_speed = MIN_SPEED + (int)((float)i / (ACCELERATION_TIME * 100.0) * (target_speed - MIN_SPEED));
        set_motor_speed(1, current_speed);
        set_motor_speed(2, current_speed);
        delay(10);
    }

    // Hold at max speed
    set_motor_speed(1, target_speed);
    set_motor_speed(2, target_speed);
    delay(2000);

    // Deceleration
    for (int i = 0; i < DECELERATION_TIME * 100; i++) {
        current_speed = target_speed - (int)((float)i / (DECELERATION_TIME * 100.0) * (target_speed - MIN_SPEED));
        set_motor_speed(1, current_speed);
        set_motor_speed(2, current_speed);
        delay(10);
    }

    // Reverse directions
    direction = !direction;
    set_motor_direction(1, direction);
    set_motor_direction(2, direction);
    delay(PAUSE_TIME * 1000);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;

    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize wiringPi SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPi SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set initial motor directions (forward)
    set_motor_direction(1, 1);
    set_motor_direction(2, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        // Map potentiometer values to speed factors
        float motor1_speed_factor = map_potentiometer_to_speed(pot1_value);
        float motor2_speed_factor = map_potentiometer_to_speed(pot2_value);

        // Apply motion profile
        motion_profile((int)motor1_speed_factor, (int)motor2_speed_factor);
    }

    return 0;
}

