// Define GPIO pins
#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define constants
#define NUM_SAMPLES 100
#define CALIBRATION_TIME 5 // seconds
#define THRESHOLD_PERCENTAGE 10
#define DEBOUNCE_DELAY 10 // milliseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_average_ambient_level(int num_samples);
int is_noise_detected(double ambient_level, double current_level, double threshold_percentage);
void control_led(int state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate average ambient level
double calculate_average_ambient_level(int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value in calibration.\n");
            return -1.0; // Indicate error
        }
        sum += adc_value;
        gpioDelay(1000); // 1 ms delay
    }
    return sum / num_samples;
}

// Function to check if noise is detected
int is_noise_detected(double ambient_level, double current_level, double threshold_percentage) {
    double threshold = ambient_level * (1.0 + threshold_percentage / 100.0);
    return (current_level > threshold);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
}

