    printf("Calibrating for %d seconds...\n", CALIBRATION_TIME);
    double ambient_level = calculate_average_ambient_level(NUM_SAMPLES * CALIBRATION_TIME);
    if (ambient_level == -1.0) {
        fprintf(stderr, "Error: Calibration failed.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    printf("Average ambient level: %.2f\n", ambient_level);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    printf("Monitoring sound levels...\n");
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
            continue; // Skip to the next iteration
        }

        if (is_noise_detected(ambient_level, adc_value, THRESHOLD_PERCENTAGE)) {
            printf("Noise detected! Current level: %d, Threshold: %.2f\n", adc_value, ambient_level * (1.0 + THRESHOLD_PERCENTAGE / 100.0));
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

