#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <sys/time.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define SAMPLE_RATE_HZ 1000
#define LOG_FILE "audio_log.txt"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8 // GPIO8 (CE0, physical pin 24)

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int read_adc(int channel);
int log_data(uint32_t timestamp_ns, uint16_t adc_value);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "audio_logger", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_MAX_SPEED_HZ;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Assert CS
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting GPIO line value (CS low)");
        return -1;
    }

    // Transfer data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        // De-assert CS before returning
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting GPIO line value (CS high)");
        }
        return -1;
    }

    // De-assert CS
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting GPIO line value (CS high)");
        return -1;
    }

    // Parse ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Log data to file
int log_data(uint32_t timestamp_ns, uint16_t adc_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%u|%u\n", timestamp_ns, adc_value);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    fprintf(stderr, "Cleaning up...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    fprintf(stderr, "Cleanup complete.\n");
}

int main(void) {
    struct timespec sleep_time;
    struct timespec remaining_time;
    struct timeval tv;
    uint32_t timestamp_ns;
    int adc_value;

