#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define MCP3008_CS 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define ADXL335 sensitivity and zero-g bias
#define ADXL335_SENSITIVITY 300.0 // mV/g
#define ADXL335_BIAS 1.5         // V
#define VREF 3.3                  // Reference voltage

// Define Kalman filter parameters
#define Q 0.001
#define R 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
double x_state = 0.0;
double y_state = 0.0;
double z_state = 0.0;
double x_covariance = 1.0;
double y_covariance = 1.0;
double z_covariance = 1.0;

// Function prototypes
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_acceleration(double voltage);
void kalman_filter(double x, double y, double z, double *x_filtered, double *y_filtered, double *z_filtered);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    if (spi_result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", spi_result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC reading to voltage
double adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    return ((double)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to acceleration
double voltage_to_acceleration(double voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Error: Invalid voltage: %f\n", voltage);
        return -1.0;
    }

    return (voltage - ADXL335_BIAS) * 1000.0 / ADXL335_SENSITIVITY; // Convert mV to g
}

// Kalman filter implementation
void kalman_filter(double x, double y, double z, double *x_filtered, double *y_filtered, double *z_filtered) {
    // Prediction step
    double x_pred = x_state;
    double y_pred = y_state;
    double z_pred = z_state;

    double x_covariance_pred = x_covariance + Q;
    double y_covariance_pred = y_covariance + Q;
    double z_covariance_pred = z_covariance + Q;

    // Update step
    double Kx = x_covariance_pred / (x_covariance_pred + R);
    double Ky = y_covariance_pred / (y_covariance_pred + R);
    double Kz = z_covariance_pred / (z_covariance_pred + R);

    *x_filtered = x_pred + Kx * (x - x_pred);
    *y_filtered = y_pred + Ky * (y - y_pred);
    *z_filtered = z_pred + Kz * (z - z_pred);

    // Post-update covariance
    x_covariance = (1 - Kx) * x_covariance_pred;
    y_covariance = (1 - Ky) * y_covariance_pred;
    z_covariance = (1 - Kz) * z_covariance_pred;

    // Update state
    x_state = *x_filtered;
    y_state = *y_filtered;
    z_state = *z_filtered;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int adc_x = read_mcp3008(0);
        int adc_y = read_mcp3008(1);
        int adc_z = read_mcp3008(2);

        if (adc_x == -1 || adc_y == -1 || adc_z == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        double voltage_x = adc_to_voltage(adc_x);
        double voltage_y = adc_to_voltage(adc_y);
        double voltage_z = adc_to_voltage(adc_z);

        if (voltage_x == -1.0 || voltage_y == -1.0 || voltage_z == -1.0) {
            fprintf(stderr, "Error: Failed to convert ADC values to voltages\n");
            continue; // Skip to the next iteration
        }

        // Convert voltages to acceleration values
        double acceleration_x = voltage_to_acceleration(voltage_x);
        double acceleration_y = voltage_to_acceleration(voltage_y);
        double acceleration_z = voltage_to_acceleration(voltage_z);

        if (acceleration_x == -1.0 || acceleration_y == -1.0 || acceleration_z == -1.0) {
            fprintf(stderr, "Error: Failed to convert voltages to acceleration values\n");
            continue; // Skip to the next iteration
        }

        // Apply Kalman filter
        double acceleration_x_filtered, acceleration_y_filtered, acceleration_z_filtered;
        kalman_filter(acceleration_x, acceleration_y, acceleration_z, &acceleration_x_filtered, &acceleration_y_filtered, &acceleration_z_filtered);

        // Print filtered acceleration values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", acceleration_x_filtered, acceleration_y_filtered, acceleration_z_filtered);

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

