#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define constants
#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define MIN_B 0.0
#define MAX_B 100.0

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2, *line3;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
float calculate_magnetic_field(int sensor_value);
void log_data(float sensor1_b, float sensor2_b, float sensor3_b);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read sensor value from a GPIO line
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to calculate magnetic field strength
float calculate_magnetic_field(int sensor_value) {
    float v_out = (sensor_value == 1) ? VCC : 0.0;
    float b = (v_out - V_QUIESCENT) / SENSITIVITY;
    return b;
}

// Function to log data to a file
void log_data(float sensor1_b, float sensor2_b, float sensor3_b) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, sensor1_b, sensor2_b, sensor3_b);
    fflush(log_file);

    // Check for out-of-range values
    if (sensor1_b < MIN_B || sensor1_b > MAX_B) {
        fprintf(stderr, "Warning: Sensor 1 magnetic field out of range: %.3f mT\n", sensor1_b);
    }
    if (sensor2_b < MIN_B || sensor2_b > MAX_B) {
        fprintf(stderr, "Warning: Sensor 2 magnetic field out of range: %.3f mT\n", sensor2_b);
    }
    if (sensor3_b < MIN_B || sensor3_b > MAX_B) {
        fprintf(stderr, "Warning: Sensor 3 magnetic field out of range: %.3f mT\n", sensor3_b);
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    line3 = gpiod_chip_get_line(chip, SENSOR3_GPIO);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as inputs
    if (gpiod_line_request_input(line1, "sensor1") < 0 ||
        gpiod_line_request_input(line2, "sensor2") < 0 ||
        gpiod_line_request_input(line3, "sensor3") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int sensor1_value = read_sensor(line1);
        int sensor2_value = read_sensor(line2);
        int sensor3_value = read_sensor(line3);

        if (sensor1_value >= 0 && sensor2_value >= 0 && sensor3_value >= 0) {
            float sensor1_b = calculate_magnetic_field(sensor1_value);
            float sensor2_b = calculate_magnetic_field(sensor2_value);
            float sensor3_b = calculate_magnetic_field(sensor3_value);

            log_data(sensor1_b, sensor2_b, sensor3_b);
        } else {
            fprintf(stderr, "Skipping logging due to sensor read error.\n");
        }

        usleep(100000); // 100 milliseconds
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    // Close log file
    fclose(log_file);

    return 0;
}

