#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(float moisture_percentage);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "SPI transfer error: %d", result);
        log_event(error_message);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(float moisture_percentage) {
    if (moisture_percentage < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        log_event("Pump turned ON.");
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        log_event("Pump turned OFF.");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("Program started.");

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "SPI open failed: %d", spi_handle);
        log_event(error_message);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC value, retrying...");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Control the pump
        control_pump(moisture_percentage);

        // Log the data
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Moisture: %.2f%%, ADC: %d", moisture_percentage, adc_value);
        log_event(log_message);

        // Wait 60 seconds
        gpioDelay(60000); // pigpio's delay function uses milliseconds
    }

    // Cleanup
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off on exit
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    log_event("Program terminated.");

    return 0;
}

