        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("Program started.");

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "SPI open failed: %d", spi_handle);
        log_event(error_message);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC value, retrying...");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Control the pump
        control_pump(moisture_percentage);

        // Log the data
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Moisture: %.2f%%, ADC: %d", moisture_percentage, adc_value);
        log_event(log_message);

        // Wait 60 seconds
        gpioDelay(60000); // pigpio's delay function uses milliseconds
    }

    // Cleanup
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off on exit
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    log_event("Program terminated.");

    return 0;
}

