    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%d\n", timestamp, channel, adc_value);
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(spi_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel,ADC Value\n");
    }

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_adc_channel(i);
            if (adc_value >= 0) {
                log_data(i, adc_value);
            } else {
                fprintf(stderr, "Error reading ADC channel %d\n", i);
            }
        }
        sleep(1);
    }

    // Close SPI device and CSV file
    close(spi_fd);
    fclose(csv_file);

    return 0;
}

