#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log errors with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

// Function to handle MQTT disconnection
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_error("MQTT disconnected unexpectedly");
    }
}

// Function to handle MQTT messages
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        cJSON *json = cJSON_Parse((char *)message->payload);
        if (json) {
            cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
            if (cJSON_IsBool(led_state_json)) {
                int led_state = cJSON_IsTrue(led_state_json) ? 1 : 0;
                gpioWrite(GPIO_PIN, led_state);
                printf("Received LED state: %s\n", led_state ? "ON" : "OFF");
            } else {
                log_error("Invalid JSON: 'led_state' is not a boolean");
            }
            cJSON_Delete(json);
        } else {
            log_error("Invalid JSON payload");
        }
    } else {
        log_error("Empty MQTT message received");
    }
}

// Function to connect to the MQTT broker with exponential backoff
int mqtt_connect_with_retry(struct mosquitto *mosq, const char *client_id, const char *host, int port) {
    int rc = 0;
    int delay = 1;
    while (running && (rc = mosquitto_connect(mosq, host, port, 60)) != MOSQ_ERR_SUCCESS) {
        log_error("MQTT connection failed, retrying...");
        sleep(delay);
        delay *= 2;
        if (delay > 60) {
            delay = 60;
        }
    }
    return rc;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    log_error("Signal received, exiting...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Turn off the LED
    gpioWrite(GPIO_PIN, 0);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client instance");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set callbacks
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker
    if (mqtt_connect_with_retry(mosq, MQTT_CLIENT_ID, MQTT_BROKER, MQTT_PORT) != MOSQ_ERR_SUCCESS) {
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Subscribe to the MQTT topic
    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
        log_error("Failed to subscribe to MQTT topic");
        running = 0;
    }

    // Start the MQTT loop
    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

