#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sound_sensor_line;
struct gpiod_line *alarm_led_line;

// Signal handler function
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int sound_level;
    int ret;
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 100000000; // 100 milliseconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get sound sensor line
    sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Error getting sound sensor line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get alarm LED line
    alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Error getting alarm LED line");
        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        return 1;
    }

    // Request sound sensor line as input
    ret = gpiod_line_request_input(sound_sensor_line, "sound_sensor");
    if (ret < 0) {
        perror("Error requesting sound sensor line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        return 1;
    }

    // Request alarm LED line as output
    ret = gpiod_line_request_output(alarm_led_line, "alarm_led", 0); // Initially off
    if (ret < 0) {
        perror("Error requesting alarm LED line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sound sensor value
        sound_level = gpiod_line_get_value(sound_sensor_line);
        if (sound_level < 0) {
            perror("Error reading sound sensor value");
            break;
        }

        // Print sound level
        printf("Sound level: %d\n", sound_level);

        // Check for sound detection
        if (sound_level == 0) {
            printf("Sound detected!\n");

            // Blink alarm LED
            for (int i = 0; i < 5; i++) {
                // Turn LED on
                ret = gpiod_line_set_value(alarm_led_line, 1);
                if (ret < 0) {
                    perror("Error setting alarm LED value (on)");
                    break;
                }
                nanosleep(&(struct timespec){.tv_sec = 1, .tv_nsec = 0}, NULL);

                // Turn LED off
                ret = gpiod_line_set_value(alarm_led_line, 0);
                if (ret < 0) {
                    perror("Error setting alarm LED value (off)");
                    break;
                }
                nanosleep(&(struct timespec){.tv_sec = 1, .tv_nsec = 0}, NULL);
            }
        }

        // Delay
        nanosleep(&delay, NULL);
    }

    // Cleanup (in case the loop breaks)
    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    gpiod_chip_close(chip);

    return 0;
}

