#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define CONSUMER "vibration-monitor"
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct timespec ts;
    FILE *log_file;
    char timestamp[30];
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = CONSUMER;
    config.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(stdout, "Vibration monitor started. Logging to %s\n", LOG_FILE);

    while (!terminate) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        ret = gpiod_line_event_read(line, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%s Vibration detected!\n", timestamp);
        fflush(log_file);

        fprintf(stdout, "%s Vibration detected!\n", timestamp);

        system("sudo shutdown -h now");
    }

    fprintf(stdout, "Cleaning up...\n");

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    fprintf(stdout, "Exiting.\n");
    return 0;
}

