#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdint.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LM35_SCALE 10.0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
void add_to_buffer(float temperature);
void write_buffer_to_file();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | (channel << 4)); // Single-ended mode + channel number
    tx[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to convert ADC value to temperature
float convert_to_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = voltage * (LM35_SCALE / 10.0);
    return temperature;
}

// Function to add temperature to the circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to write the circular buffer to a file
void write_buffer_to_file() {
    if (log_file != NULL) {
        fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, log_file);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

