    // Main loop
    while (1) {
        // Read temperature from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(5);
            continue;
        }

        // Convert ADC value to temperature
        float temperature = convert_to_temperature(adc_value);

        // Add temperature to circular buffer
        add_to_buffer(temperature);

        // Print temperature to console
        printf("Temperature: %.2f °C\n", temperature);

        // Write buffer to file
        if (log_file != NULL) {
            write_buffer_to_file();
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

