#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750();
int read_mcp3008(int channel);
char* get_timestamp();
int log_data(char *timestamp, int light_level, int sound_level);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode (CPHA = 0, CPOL = 0)
    unsigned char mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure SPI bits per word
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure SPI max speed (1 MHz)
    unsigned int speed = 1000000; // Hz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750() {
    unsigned char data[2];
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C not initialized\n");
        return -1;
    }

    // Send start measurement command (High Resolution Mode)
    unsigned char cmd = 0x10; // 0x10 for continuous high resolution mode
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement to complete (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine the bytes to get the lux value
    int lux = (data[0] << 8) | data[1];
    return lux;
}

// Read sound level from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    if (spi_fd < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return -1;
    }

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(char *timestamp, int light_level, int sound_level) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light_level, sound_level);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
    }

    // Initialize SPI
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Starting data logging...\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int light_level = -1;
        if (i2c_fd != -1) {
            light_level = read_bh1750();
            if (light_level < 0) {
                fprintf(stderr, "Error reading BH1750 sensor\n");
            }
        }

        int sound_level = -1;
        if (spi_fd != -1) {
            sound_level = read_mcp3008(MCP3008_CHANNEL);
            if (sound_level < 0) {
                fprintf(stderr, "Error reading MCP3008 sensor\n");
            }
        }

        // Get timestamp
        char *timestamp = get_timestamp();

        // Log data
        if (timestamp != NULL) {
            if (log_data(timestamp, light_level, sound_level) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
            free(timestamp);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    printf("Exiting...\n");
    cleanup();
    return 0;
}

