#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x62
#define VREF 3.3
#define MAX_RETRIES 3

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int set_dac_voltage(float voltage);
int log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    fprintf(stderr, "Error: Max retries reached for SPI transfer.\n");
    return -1; // Indicate failure
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 1024.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to set DAC voltage
int set_dac_voltage(float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Error: Invalid DAC voltage: %.2f\n", voltage);
        return -1;
    }

    unsigned int dac_value = (unsigned int)((voltage / VREF) * 4095.0);
    char i2c_tx_buf[3];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        i2c_tx_buf[0] = 0x40; // Write DAC command
        i2c_tx_buf[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
        i2c_tx_buf[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

        result = i2cWriteDevice(i2c_handle, i2c_tx_buf, 3);
        if (result == 3) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C write failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    fprintf(stderr, "Error: Max retries reached for I2C write.\n");
    return -1; // Indicate failure
}

// Function to log data to file
int log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Map temperature to voltage
        float voltage = (temperature / 50.0) * 3.3;

        // Set DAC voltage
        if (set_dac_voltage(voltage) != 0) {
            fprintf(stderr, "Error: Failed to set DAC voltage\n");
        }

        // Log data
        log_data(adc_value, temperature, voltage);

        // Wait for 0.5 seconds
        gpioDelay(500000); // 0.5 seconds = 500000 microseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

