#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define LED_GPIO 16
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY_MS 100
#define LED_ON_TIME_MS 500
#define ADC_CHANNEL 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void log_event(const char *timestamp);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate an error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (spi_result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", spi_result);
        return -1; // Indicate an error
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log an event to a file
void log_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sound_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Optionally add retry logic here
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay before next attempt
            continue;
        }

        // Check if sound level exceeds threshold
        if (adc_value > SOUND_THRESHOLD) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event
            log_event(timestamp);

            // Turn on LED
            gpioWrite(LED_GPIO, 1);

            // Wait for 500ms
            gpioDelay(LED_ON_TIME_MS * 1000);

            // Turn off LED
            gpioWrite(LED_GPIO, 0);
        }

        // Debounce delay
        gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

