#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain level threshold
#define RAIN_THRESHOLD 5

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_SPEED 150

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor(int channel);
int convert_to_rain_level(int adc_value);
void control_motor(int direction, int speed);
void log_rain_data(int rain_level);
void signal_handler(int signal);

// Function to read rain sensor data from MCP3008
int read_rain_sensor(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
