    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR_ENA, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read rain sensor data
        int adc_value = read_rain_sensor(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor data\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to rain level
        int rain_level = convert_to_rain_level(adc_value);

        // Log rain data
        log_rain_data(rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            control_motor(MOTOR_FORWARD, MOTOR_SPEED);
            gpioDelay(3000); // 3 seconds
            control_motor(MOTOR_REVERSE, MOTOR_SPEED);
            gpioDelay(3000); // 3 seconds
        } else {
            control_motor(MOTOR_REVERSE, MOTOR_SPEED);
        }

        gpioDelay(1000); // Poll every 1 second
    }

    // Cleanup
    control_motor(MOTOR_REVERSE, MOTOR_SPEED); // Stop the motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

