#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define MIC_DATA_PIN 26
#define LED_PIN 16

// Define clap threshold
#define CLAP_THRESHOLD 700

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile unsigned long last_clap_time = 0;

// Function prototypes
int initialize_gpio();
int read_microphone_data();
void control_led(int state);
void print_timestamped_message(const char *message);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int mic_data_pin;
    int led_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(MIC_DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting MIC_DATA_PIN to input mode.\n");
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED_PIN to output mode.\n");
        return -1;
    }
    return 0;
}

// Read microphone data using bit-banged ADC
int read_microphone_data() {
    int data = 0;
    for (int i = 0; i < 10; i++) {
        gpioWrite(MIC_DATA_PIN, 1); // Drive pin high
        gpioDelay(1); // Short delay
        data = data << 1; // Shift previous data
        if (gpioRead(MIC_DATA_PIN) == 1) {
            data++;
        }
        gpioWrite(MIC_DATA_PIN, 0); // Drive pin low
        gpioDelay(1); // Short delay
    }
    return data;
}

// Control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Print a timestamped message to the console
void print_timestamped_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Clap detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = read_microphone_data();

        if (adc_value > CLAP_THRESHOLD) {
            unsigned long current_time = gpioTick();
            if ((current_time - last_clap_time) > (DEBOUNCE_TIME * 1000)) { // Convert ms to us
                print_timestamped_message("Clap detected!");
                control_led(1); // Turn on LED
                gpioDelay(500); // Wait for 500 ms
                control_led(0); // Turn off LED
                last_clap_time = current_time;
            }
        }
        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    gpioTerminate();
    return 0;
}

