#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio17"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIRECTION_PATH GPIO_PATH "/direction"
#define GPIO_VALUE_PATH GPIO_PATH "/value"

#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO configuration
typedef struct {
    int pin;
    char export_path[50];
    char unexport_path[50];
    char direction_path[100];
    char value_path[100];
} gpio_config_t;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
float voltage_to_distance(float voltage);
void log_distance(float distance);
void check_proximity(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Caught signal %d, exiting gracefully.\n", signal);
        program_running = 0;
    }
}

// Exports the specified GPIO pin
int gpio_export(int pin) {
    FILE *fp = fopen(GPIO_EXPORT_PATH, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_EXPORT_PATH, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    FILE *fp = fopen(GPIO_UNEXPORT_PATH, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Sets the direction of the specified GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char direction_path[100];
    snprintf(direction_path, sizeof(direction_path), GPIO_PATH "/direction");
    FILE *fp = fopen(direction_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", direction_path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s", direction);
    fclose(fp);
    return 0;
}

// Reads the value of the specified GPIO pin
int gpio_read(int pin) {
    char value_path[100];
    snprintf(value_path, sizeof(value_path), GPIO_PATH "/value");
    FILE *fp = fopen(value_path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", value_path, strerror(errno));
        return -1;
    }
    int value;
    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Error reading value from %s\n", value_path);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return value;
}

// Converts the voltage to distance using the formula A / voltage + B
float voltage_to_distance(float voltage) {
    float A = 26.0;
    float B = -6.0;
    return A / voltage + B;
}

// Logs the distance to a file with a timestamp
void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f mm\n", timestamp, distance);
    fclose(fp);
}

// Checks if the distance is below 200 mm and prints a message
void check_proximity(float distance) {
    if (distance < 200.0) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Proximity sensor program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO value
        int gpio_value = gpio_read(GPIO_PIN);
        if (gpio_value == -1) {
            fprintf(stderr, "Failed to read GPIO %d value\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        // Convert GPIO value to voltage
        float voltage = (float)gpio_value * 3.3;

        // Convert voltage to distance
        float distance = voltage_to_distance(voltage);

        // Log the distance
        log_distance(distance);

        // Check proximity
        check_proximity(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport GPIO pin on exit
    if (gpio_unexport(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_PIN);
    }

    printf("Proximity sensor program exited.\n");

    return 0;
}

