    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    FILE *fp = fopen(GPIO_UNEXPORT_PATH, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Sets the direction of the specified GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char direction_path[100];
    snprintf(direction_path, sizeof(direction_path), GPIO_PATH "/direction");
    FILE *fp = fopen(direction_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", direction_path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s", direction);
    fclose(fp);
    return 0;
}

// Reads the value of the specified GPIO pin
int gpio_read(int pin) {
    char value_path[100];
    snprintf(value_path, sizeof(value_path), GPIO_PATH "/value");
    FILE *fp = fopen(value_path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", value_path, strerror(errno));
        return -1;
    }
    int value;
    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Error reading value from %s\n", value_path);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return value;
}

// Converts the voltage to distance using the formula A / voltage + B
float voltage_to_distance(float voltage) {
    float A = 26.0;
    float B = -6.0;
    return A / voltage + B;
}

