// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 500

// DRV5055-A1 parameters
#define VREF 3.3
#define SENSITIVITY 100.0 // mV/mT
#define QUIESCENT_OUTPUT 1650.0 // mV

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_init(void);
int read_mcp3008(int channel);
