#define SENSITIVITY 100.0 // mV/mT
#define QUIESCENT_OUTPUT 1650.0 // mV

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_init(void);
int read_mcp3008(int channel);
float calculate_magnetic_field(int adc_value);
int log_data(time_t timestamp, float magnetic_field);
void signal_handler(int sig);
