// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

