#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 21
#define FIELD_THRESHOLD 10.0 // mT
#define VCC 3.3 // Supply voltage
#define SENSITIVITY_mV_per_mT 1.65 // mV/mT
#define QUIESCENT_OUTPUT VCC/2 // V

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
float convert_to_field_strength(float voltage);
void log_data(float field_strength);
void control_led(float field_strength);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int led_gpio;
    float field_threshold;
    float vcc;
    float sensitivity_mv_per_mt;
    float quiescent_output;
} Config;

Config config = {SPI_CHANNEL, SPI_BAUD, LED_GPIO, FIELD_THRESHOLD, VCC, SENSITIVITY_mV_per_mT, QUIESCENT_OUTPUT};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float voltage = convert_to_voltage(adc_value);
        float field_strength = convert_to_field_strength(voltage);

        log_data(field_strength);
        control_led(field_strength);

        gpioDelay(100); // 100 ms delay
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // SPI_MODE0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(config.led_gpio, PI_OUTPUT);

    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float convert_to_voltage(int adc_value) {
    return (float)adc_value * config.vcc / 1023.0;
}

float convert_to_field_strength(float voltage) {
    return (voltage - config.quiescent_output) * 1000.0 / config.sensitivity_mv_per_mt;
}

void log_data(float field_strength) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f mT\n", timestamp, field_strength);
    fflush(log_file); // Ensure data is written to file immediately
}

void control_led(float field_strength) {
    if (field_strength > config.field_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn LED on
    } else {
        gpioWrite(config.led_gpio, 0); // Turn LED off
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(config.led_gpio, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

