#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 5.0          // Reference voltage (V)
#define MAX_CURRENT 50.0   // Maximum current (A)
#define ZERO_CURRENT_VOLTAGE 2.5 // Voltage at 0A (V)
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_current(float voltage);
void log_current(float current);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Warning: Voltage out of range (0-%fV): %fV\n", VREF, voltage);
        return -1.0; // Indicate error
    }
    return (voltage - ZERO_CURRENT_VOLTAGE) * (MAX_CURRENT / (VREF - ZERO_CURRENT_VOLTAGE));
}

// Function to log current data to file
void log_current(float current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Append timestamp and current to file
    fprintf(fp, "%s %.2f A\n", timestamp, current);

    // Flush the buffer to ensure data is written to disk
    fflush(fp);

    fclose(fp);
}

