    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample.\n");
            gpioDelay(100000); // Wait 100ms
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value / 1023.0 * VREF;

        // Convert voltage to current
        float current = voltage_to_current(voltage);
        if (current < 0.0) {
            fprintf(stderr, "Error converting voltage to current, skipping sample.\n");
            gpioDelay(100000); // Wait 100ms
            continue;
        }

        // Log the current value
        log_current(current);

        // Wait 100ms
        gpioDelay(100000);
    }

    // Close SPI and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Current monitoring stopped.\n");
    return 0;
}

