#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
volatile sig_atomic_t terminate_flag = 0;
int spi_handle;

// Structure for SPI configuration
typedef struct {
    int channel;
    int baud;
} spi_config_t;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int adc_value = -1; // Initialize to an error value
    int retries = 3;

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended + channel select
    tx_buf[2] = 0x00; // Dummy byte

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 0) {
            adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed. Retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI transfer failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to calculate moisture level
double calculate_moisture_level(int adc_value) {
    double moisture_level = 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_level < 0.0) {
        moisture_level = 0.0;
    } else if (moisture_level > 100.0) {
        moisture_level = 100.0;
    }
    return moisture_level;
}

// Function to log data to file
void log_data(double moisture_level) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
        terminate_flag = 1;
    }
}

// Function to setup SPI
int spi_setup(spi_config_t config) {
    int handle = spiOpen(config.channel, config.baud, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, handle);
        return -1;
    }
    return handle;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};
    spi_handle = spi_setup(spi_config);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            log_data(moisture_level);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        gpioDelay(READ_DELAY * 1000000); // Delay for 60 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

