#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>

#define GPIO_PIN 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define ISO_8601_TIMESTAMP_LENGTH 21
#define IMAGE_DIR "/home/pi/security_cam/"
#define DEBOUNCE_DELAY_MS 200
#define POLLING_INTERVAL_MS 50

volatile sig_atomic_t terminate = 0;

// Function to generate ISO 8601 timestamp
int generate_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);

    if (strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        syslog(LOG_ERR, "Error formatting timestamp");
        return -1;
    }
    return 0;
}

// Function to construct the image filename
int construct_image_filename(char *filename_buffer, size_t buffer_size, const char *timestamp) {
    if (snprintf(filename_buffer, buffer_size, "%s%s.jpg", IMAGE_DIR, timestamp) >= buffer_size) {
        syslog(LOG_ERR, "Filename buffer overflow");
        return -1;
    }
    return 0;
}

// Function to check if the target directory exists
int check_image_directory() {
    if (access(IMAGE_DIR, F_OK) == -1) {
        syslog(LOG_ERR, "Image directory does not exist: %s", IMAGE_DIR);
        return -1;
    }
    return 0;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    pid_t pid;
    int status;

    pid = fork();
    if (pid == -1) {
        syslog(LOG_ERR, "Fork failed: %s", strerror(errno));
        return -1;
    } else if (pid == 0) {
        // Child process
        char command[256];
        snprintf(command, sizeof(command), "libcamera-still -n -o %s --width %d --height %d --iso 800", filename, IMAGE_WIDTH, IMAGE_HEIGHT);
        char *args[] = {NULL};
        char *envp[] = {NULL};
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        syslog(LOG_ERR, "execl failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
            return -1;
        }
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    int gpio_state = 0;
    int last_gpio_state = 0;
    char timestamp[ISO_8601_TIMESTAMP_LENGTH];
    char filename[256];

    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Configure GPIO17 as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    syslog(LOG_INFO, "Security camera started");

    // Main loop
    while (!terminate) {
        gpio_state = gpioRead(GPIO_PIN);

        if (gpio_state != last_gpio_state) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read GPIO state after debounce
            int debounced_state = gpioRead(GPIO_PIN);

            if (debounced_state != gpio_state) {
                // State has changed during debounce
                continue;
            }

            if (debounced_state == 1) {
                // Motion detected
                syslog(LOG_INFO, "Motion detected");

                // Generate timestamp
                if (generate_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
                    syslog(LOG_ERR, "Failed to generate timestamp");
                    continue;
                }

                // Construct filename
                if (construct_image_filename(filename, sizeof(filename), timestamp) != 0) {
                    syslog(LOG_ERR, "Failed to construct filename");
                    continue;
                }

                // Check image directory
                if (check_image_directory() != 0) {
                    syslog(LOG_ERR, "Failed to check image directory");
                    continue;
                }

                // Capture image
                if (capture_image(filename) != 0) {
                    syslog(LOG_ERR, "Failed to capture image");
                } else {
                    syslog(LOG_INFO, "Image captured: %s", filename);
                }
            }

            last_gpio_state = gpio_state;
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    gpioTerminate();
    syslog(LOG_INFO, "Security camera stopped");
    closelog();

    return 0;
}

