#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>
#include <stdbool.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_GREY
#define NUM_BUFFERS 4

// Structure to hold camera information
typedef struct {
    int fd;
    struct v4l2_buffer buffers[NUM_BUFFERS];
    void *buffer_ptrs[NUM_BUFFERS];
    struct v4l2_format format;
    unsigned int frame_count;
    bool streaming;
} camera_t;

// Global camera instance
camera_t camera;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping...\n", signal);
    camera.streaming = false;
}

// Function to initialize the camera device
int init_camera(camera_t *cam) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    // Open the device
    cam->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (cam->fd < 0) {
        perror("Error opening device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(cam->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(cam->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(cam->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(cam->fd);
        return -1;
    }

    // Set the format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(cam->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(cam->fd);
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(cam->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(cam->fd);
        return -1;
    }

    // Map the buffers
    for (i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(cam->fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(cam->fd);
            return -1;
        }

        cam->buffers[i] = buf;

        cam->buffer_ptrs[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, cam->fd, buf.m.offset);
        if (cam->buffer_ptrs[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(cam->fd);
            return -1;
        }
    }

    // Queue the buffers
    for (i = 0; i < NUM_BUFFERS; i++) {
        if (ioctl(cam->fd, VIDIOC_QBUF, &cam->buffers[i]) < 0) {
            perror("Error queuing buffer");
            close(cam->fd);
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(cam->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(cam->fd);
        return -1;
    }

    cam->streaming = true;
    cam->frame_count = 0;

    return 0;
}

// Function to capture a frame
int capture_frame(camera_t *cam) {
    fd_set fds;
    struct timeval tv;
    unsigned int i;

    FD_ZERO(&fds);
    FD_SET(cam->fd, &fds);

    tv.tv_sec = 2; // 2 seconds timeout
    tv.tv_usec = 0;

    int r = select(cam->fd + 1, &fds, NULL, NULL, &tv);

    if (r < 0) {
        perror("Error in select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(cam->fd, VIDIOC_DQBUF, &cam->buffers[0]) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Save the frame as a PGM file
    char filename[50];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", cam->frame_count + 1);
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    fwrite(cam->buffer_ptrs[0], 1, IMAGE_WIDTH * IMAGE_HEIGHT, fp);

    fclose(fp);
    cam->frame_count++;

    if (ioctl(cam->fd, VIDIOC_QBUF, &cam->buffers[0]) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to clean up resources
void cleanup(camera_t *cam) {
    unsigned int i;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (cam->streaming) {
        if (ioctl(cam->fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("Error stopping stream");
        }
    }

    for (i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(cam->buffer_ptrs[i], cam->buffers[i].length) < 0) {
            perror("Error unmapping buffer");
        }
    }

    close(cam->fd);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera(&camera) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    printf("Camera initialized successfully. Capturing frames...\n");

    // Capture frames continuously until a signal is received
    while (camera.streaming) {
        if (capture_frame(&camera) < 0) {
            fprintf(stderr, "Frame capture failed\n");
            break;
        }
    }

    // Clean up resources
    cleanup(&camera);

    printf("Exiting.\n");
    return 0;
}

