#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define LOG_FILE "frame_log.txt"

// Structure to hold video device information
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void **buffers;
    unsigned int n_buffers;
} video_device_t;

// Global variables
video_device_t device;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int open_device(const char *device_name);
int init_device(video_device_t *device);
int start_capturing(video_device_t *device);
int stop_capturing(video_device_t *device);
int uninit_device(video_device_t *device);
int close_device(video_device_t *device);
int read_frame(video_device_t *device);
int log_timestamp(FILE *fp);
void signal_handler(int sig);

// Error handling macro
#define CHECK_ERROR(ret, msg) \
    if (ret < 0) { \
        fprintf(stderr, "%s: %s\n", msg, strerror(errno)); \
        return -1; \
    }

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to initialize the video device
int init_device(video_device_t *device) {
    int ret;

    // Query capabilities
    ret = ioctl(device->fd, VIDIOC_QUERYCAP, &device->cap);
    CHECK_ERROR(ret, "VIDIOC_QUERYCAP");

    if (!(device->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(device->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    // Set format
    device->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    device->fmt.fmt.pix.width = 640;
    device->fmt.fmt.pix.height = 480;
    device->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    device->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = ioctl(device->fd, VIDIOC_S_FMT, &device->fmt);
    CHECK_ERROR(ret, "VIDIOC_S_FMT");

    // Request buffers
    device->req.count = 4; // Number of buffers
    device->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    device->req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(device->fd, VIDIOC_REQBUFS, &device->req);
    CHECK_ERROR(ret, "VIDIOC_REQBUFS");

    if (device->req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    device->buffers = calloc(device->req.count, sizeof(void *));
    if (!device->buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    device->n_buffers = device->req.count;

    // Map buffers
    for (unsigned int i = 0; i < device->n_buffers; ++i) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        ret = ioctl(device->fd, VIDIOC_QUERYBUF, &buf);
        CHECK_ERROR(ret, "VIDIOC_QUERYBUF");

        device->buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, device->fd, buf.m.offset);
        if (device->buffers[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        ret = ioctl(device->fd, VIDIOC_QBUF, &buf);
        CHECK_ERROR(ret, "VIDIOC_QBUF");
    }

    return 0;
}

// Function to start capturing frames
int start_capturing(video_device_t *device) {
    int ret;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    ret = ioctl(device->fd, VIDIOC_STREAMON, &type);
    CHECK_ERROR(ret, "VIDIOC_STREAMON");

    return 0;
}

// Function to stop capturing frames
int stop_capturing(video_device_t *device) {
    int ret;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    ret = ioctl(device->fd, VIDIOC_STREAMOFF, &type);
    CHECK_ERROR(ret, "VIDIOC_STREAMOFF");

    return 0;
}

// Function to uninitialize the video device
int uninit_device(video_device_t *device) {
    int ret;

    // Unmap buffers
    for (unsigned int i = 0; i < device->n_buffers; ++i) {
        if (device->buffers[i] != NULL && device->buffers[i] != MAP_FAILED) {
            ret = munmap(device->buffers[i], device->fmt.fmt.pix.sizeimage);
            if (ret < 0) {
                fprintf(stderr, "Error unmapping buffer %d: %s\n", i, strerror(errno));
                return -1;
            }
        }
    }

    free(device->buffers);

    return 0;
}

// Function to close the video device
int close_device(video_device_t *device) {
    if (device->fd != -1) {
        close(device->fd);
        device->fd = -1;
    }
    return 0;
}

// Function to read a single frame
int read_frame(video_device_t *device) {
    fd_set fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&fds);
    FD_SET(device->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    ret = select(device->fd + 1, &fds, NULL, NULL, &tv);
    if (ret == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    ret = ioctl(device->fd, VIDIOC_DQBUF, &device->buf);
    CHECK_ERROR(ret, "VIDIOC_DQBUF");

    ret = ioctl(device->fd, VIDIOC_QBUF, &device->buf);
    CHECK_ERROR(ret, "VIDIOC_QBUF");

    return 0;
}

// Function to log the timestamp to a file
int log_timestamp(FILE *fp) {
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int ret;

    // Initialize video device structure
    memset(&device, 0, sizeof(device));
    device.fd = -1;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the video device
    device.fd = open_device(DEVICE_NAME);
    if (device.fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize the video device
    if (init_device(&device) < 0) {
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Start capturing frames
    if (start_capturing(&device) < 0) {
        uninit_device(&device);
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        stop_capturing(&device);
        uninit_device(&device);
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        if (read_frame(&device) == 0) {
            if (log_timestamp(log_file) != 0) {
                fprintf(stderr, "Error logging timestamp\n");
            }
        }
    }

    // Cleanup
    stop_capturing(&device);
    uninit_device(&device);
    close_device(&device);

    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

