int close_device(video_device_t *device) {
    if (device->fd != -1) {
        close(device->fd);
        device->fd = -1;
    }
    return 0;
}

// Function to read a single frame
int read_frame(video_device_t *device) {
    fd_set fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&fds);
    FD_SET(device->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    ret = select(device->fd + 1, &fds, NULL, NULL, &tv);
    if (ret == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    ret = ioctl(device->fd, VIDIOC_DQBUF, &device->buf);
    CHECK_ERROR(ret, "VIDIOC_DQBUF");

    ret = ioctl(device->fd, VIDIOC_QBUF, &device->buf);
    CHECK_ERROR(ret, "VIDIOC_QBUF");

    return 0;
}

// Function to log the timestamp to a file
int log_timestamp(FILE *fp) {
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int ret;

    // Initialize video device structure
    memset(&device, 0, sizeof(device));
    device.fd = -1;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open the video device
    device.fd = open_device(DEVICE_NAME);
    if (device.fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize the video device
    if (init_device(&device) < 0) {
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Start capturing frames
    if (start_capturing(&device) < 0) {
        uninit_device(&device);
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        stop_capturing(&device);
        uninit_device(&device);
        close_device(&device);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        if (read_frame(&device) == 0) {
            if (log_timestamp(log_file) != 0) {
                fprintf(stderr, "Error logging timestamp\n");
            }
        }
    }

    // Cleanup
    stop_capturing(&device);
    uninit_device(&device);
    close_device(&device);

    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

