        for (int i = 0; i < n_buffers; i++) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(video_fd, VIDIOC_QBUF, &buf) == -1) {
                perror("Error queuing buffer");
                running = 0;
                break;
            }
        }

        if (!running) break;

        fd_set fds;
        struct timeval tv;
        FD_ZERO(&fds);
        FD_SET(video_fd, &fds);
        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        int r = select(video_fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            perror("Error in select");
            running = 0;
            break;
        } else if (r == 0) {
            fprintf(stderr, "Timeout waiting for buffer\n");
            continue;
        }

        if (ioctl(video_fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("Error dequeuing buffer");
            running = 0;
            break;
        }

        // Fragment the frame into UDP packets
        for (int j = 0; j < MAX_FRAGMENTS; j++) {
            FrameFragment fragment;
            fragment.frame_index = frame_index;
            fragment.fragment_index = j;
            fragment.total_fragments = MAX_FRAGMENTS;
            fragment.payload_size = (j == MAX_FRAGMENTS - 1) ? IMAGE_SIZE % FRAGMENT_SIZE : FRAGMENT_SIZE;
            fragment.data = buffers[buf.index] + (j * FRAGMENT_SIZE);

            enqueue_fragment(&fragment_buffer, fragment);
        }

        frame_index++;
    }
    pthread_exit(NULL);
}

// Function to send frames
void *send_frames(void *arg) {
