    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

// Function to start capturing video
int start_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }
    return 0;
}

// Function to stop capturing video
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to uninitialize the video device
int uninit_device(int fd) {
    return 0;
}

// Function to close the video device
int close_device(int fd) {
    if (close(fd) == -1) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

// Function to initialize memory mapping
int init_mmap(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    for (int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to initialize the UDP socket
int init_socket(const char *server_ip, int server_port) {
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        sockfd = -1;
        return -1;
    }
    return 0;
}

// Function to create a UDP socket
int create_socket(const char *server_ip, int server_port) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_address.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return -1;
    }

    return sock;
}

// Function to send a UDP packet
int send_udp_packet(int sockfd, struct sockaddr_in *server_addr, FrameFragment fragment) {
    unsigned char *data = malloc(FRAGMENT_SIZE);
    if (!data) {
        perror("Error allocating memory for packet data");
        return -1;
    }

    // Create header
    int header[4] = {fragment.frame_index, fragment.fragment_index, fragment.total_fragments, fragment.payload_size};
    memcpy(data, header, sizeof(header));

    // Copy payload
    memcpy(data + sizeof(header), fragment.data, fragment.payload_size);

    ssize_t bytes_sent = sendto(sockfd, data, FRAGMENT_SIZE, 0, (struct sockaddr *)server_addr, sizeof(*server_addr));
    if (bytes_sent < 0) {
        perror("Error sending packet");
        free(data);
        return -1;
    }

    free(data);
    return 0;
}

// Function to capture frames
void *capture_frames(void *arg) {
    while (running) {
        for (int i = 0; i < n_buffers; i++) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;

            if (ioctl(video_fd, VIDIOC_QBUF, &buf) == -1) {
                perror("Error queuing buffer");
                running = 0;
                break;
            }
        }

        if (!running) break;

        fd_set fds;
        struct timeval tv;
        FD_ZERO(&fds);
        FD_SET(video_fd, &fds);
        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        int r = select(video_fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            perror("Error in select");
            running = 0;
            break;
        } else if (r == 0) {
            fprintf(stderr, "Timeout waiting for buffer\n");
            continue;
        }

        if (ioctl(video_fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("Error dequeuing buffer");
            running = 0;
            break;
        }

        // Fragment the frame into UDP packets
        for (int j = 0; j < MAX_FRAGMENTS; j++) {
            FrameFragment fragment;
            fragment.frame_index = frame_index;
            fragment.fragment_index = j;
            fragment.total_fragments = MAX_FRAGMENTS;
            fragment.payload_size = (j == MAX_FRAGMENTS - 1) ? IMAGE_SIZE % FRAGMENT_SIZE : FRAGMENT_SIZE;
            fragment.data = buffers[buf.index] + (j * FRAGMENT_SIZE);

            enqueue_fragment(&fragment_buffer, fragment);
        }

        frame_index++;
    }
    pthread_exit(NULL);
}

// Function to send frames
void *send_frames(void *arg) {
    while (running) {
        FrameFragment fragment = dequeue_fragment(&fragment_buffer);
        if (fragment.data != NULL) {
            if (send_udp_packet(sockfd, &server_addr, fragment) != 0) {
                running = 0;
                break;
            }
        } else {
            // Buffer is empty, sleep for a short time to avoid busy-waiting
            struct timespec sleep_time;
            sleep_time.tv_sec = 0;
            sleep_time.tv_nsec = 10000000; // 10ms
            nanosleep(&sleep_time, NULL);
        }
    }
    pthread_exit(NULL);
}

// Function to enqueue a frame fragment into the circular buffer
void enqueue_fragment(CircularBuffer *cb, FrameFragment fragment) {
    if (cb->count == cb->capacity) {
        fprintf(stderr, "Fragment buffer is full!\n");
        return;
    }

    cb->buffer[cb->head] = fragment;
    cb->head = (cb->head + 1) % cb->capacity;
    cb->count++;
}

// Function to dequeue a frame fragment from the circular buffer
FrameFragment dequeue_fragment(CircularBuffer *cb) {
    FrameFragment fragment;
    fragment.data = NULL;

    if (cb->count == 0) {
        return fragment; // Return an empty fragment
    }

    fragment = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % cb->capacity;
    cb->count--;

    return fragment;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Signal received, stopping...\n");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop threads
    pthread_cancel(capture_thread);
    pthread_cancel(send_thread);
    pthread_join(capture_thread, NULL);
    pthread_join(send_thread, NULL);

    // Free fragment buffer
    if (fragment_buffer.buffer != NULL) {
        free(fragment_buffer.buffer);
    }

    // Uninitialize device
    if (video_fd != -1) {
        uninit_device(video_fd);
    }

    // Close device
    if (video_fd != -1) {
        close_device(video_fd);
    }

    // Unmap buffers
    for (int i = 0; i < n_buffers; i++) {
        if (buffers[i] != NULL && buffers[i] != MAP_FAILED) {
            munmap(buffers[i], buf.length);
        }
    }

    // Close socket
    if (sockfd != -1) {
        close(sockfd);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize circular buffer
    fragment_buffer.capacity = 100; // Adjust capacity as needed
    fragment_buffer.buffer = (FrameFragment *)malloc(fragment_buffer.capacity * sizeof(FrameFragment));
    if (fragment_buffer.buffer == NULL) {
        perror("Error allocating fragment buffer");
        return 1;
    }
    fragment_buffer.head = 0;
    fragment_buffer.tail = 0;
    fragment_buffer.count = 0;

    // Open video device
    video_fd = open_device(VIDEO_DEVICE);
    if (video_fd == -1) {
        cleanup();
        return 1;
    }

    // Initialize device
    if (init_device(video_fd) == -1) {
        cleanup();
        return 1;
    }

    // Initialize memory mapping
    if (init_mmap(video_fd) == -1) {
        cleanup();
        return 1;
    }

    // Initialize socket
    if (init_socket(server_ip, server_port) == -1) {
        cleanup();
        return 1;
    }

    // Create capture thread
    if (pthread_create(&capture_thread, NULL, capture_frames, NULL) != 0) {
        perror("Error creating capture thread");
        cleanup();
        return 1;
    }

    // Create send thread
    if (pthread_create(&send_thread, NULL, send_frames, NULL) != 0) {
        perror("Error creating send thread");
        cleanup();
        return 1;
    }

    // Start capturing
    if (start_capturing(video_fd) == -1) {
        cleanup();
        return 1;
    }

    // Wait for threads to finish (or signal to stop)
    pthread_join(capture_thread, NULL);
    pthread_join(send_thread, NULL);

    // Stop capturing
    if (stop_capturing(video_fd) == -1) {
        cleanup();
        return 1;
    }

    // Cleanup resources
    cleanup();

    printf("Exiting.\n");
    return 0;
}

