#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <stdbool.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define IMAGE_FORMAT V4L2_PIX_FMT_MJPEG
#define NUM_BUFFERS 4
#define IMAGE_FILENAME "image.jpg"

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int                 fd         = -1;
static buffer              *buffers    = NULL;
static unsigned int        n_buffers  = 0;
static volatile sig_atomic_t keep_running = 1;

// Signal handler
static void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        fprintf(stderr, "Received signal %d, stopping...\n", signo);
        keep_running = 0;
    }
}

// Function to check V4L2 capabilities
static int check_capability(int fd, unsigned int capability) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & capability)) {
        fprintf(stderr, "Device does not support capability 0x%08x\n", capability);
        return -1;
    }

    return 0;
}

// Function to enumerate supported formats
static int enumerate_formats(int fd) {
    struct v4l2_fmtdesc fmtdesc;
    memset(&fmtdesc, 0, sizeof(fmtdesc));
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    printf("Supported formats:\n");
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        printf("  %s\n", fmtdesc.description);
        fmtdesc.index++;
    }
    return 0;
}

// Function to set format
static int set_format(int fd) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    printf("Format set to %dx%d, format %d\n", fmt.fmt.pix.width, fmt.fmt.pix.height, fmt.fmt.pix.pixelformat);
    return 0;
}

// Function to request buffers
static int request_buffers(int fd, unsigned int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < num_buffers) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        return -1;
    }

    return 0;
}

// Function to mmap buffers
static int mmap_buffers(int fd, unsigned int num_buffers, buffer *buffers) {
    for (unsigned int i = 0; i < num_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }
    return 0;
}

// Function to queue buffer
static int queue_buffer(int fd, unsigned int index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

// Function to start streaming
static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

// Function to dequeue buffer
static int dequeue_buffer(int fd) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    return buf.index;
}

// Function to save image to file
static int save_image(const char *filename, const buffer *buf, size_t length) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t bytes_written = fwrite(buf->start, 1, length, fp);
    if (bytes_written != length) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, length);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

// Function to stop streaming
static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

// Function to unmap buffers
static int unmap_buffers(buffer *buffers, unsigned int num_buffers) {
    for (unsigned int i = 0; i < num_buffers; i++) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("munmap");
            return -1;
        }
    }
    return 0;
}

// Function to close device
static int close_device(int fd) {
    if (close(fd) < 0) {
        perror("close");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Check capabilities
    if (check_capability(fd, V4L2_CAP_VIDEO_CAPTURE) < 0 ||
        check_capability(fd, V4L2_CAP_STREAMING) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Enumerate formats
    if (enumerate_formats(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Set format
    if (set_format(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    buffers = calloc(NUM_BUFFERS, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (request_buffers(fd, NUM_BUFFERS) < 0) {
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    n_buffers = NUM_BUFFERS;

    // Mmap buffers
    if (mmap_buffers(fd, n_buffers, buffers) < 0) {
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Queue buffers
    for (unsigned int i = 0; i < n_buffers; i++) {
        if (queue_buffer(fd, i) < 0) {
            unmap_buffers(buffers, n_buffers);
            free(buffers);
            close_device(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    if (start_streaming(fd) < 0) {
        unmap_buffers(buffers, n_buffers);
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Dequeue and save image
    int dequeued_index = dequeue_buffer(fd);
    if (dequeued_index < 0) {
        stop_streaming(fd);
        unmap_buffers(buffers, n_buffers);
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (save_image(IMAGE_FILENAME, &buffers[dequeued_index], buffers[dequeued_index].length) < 0) {
        stop_streaming(fd);
        unmap_buffers(buffers, n_buffers);
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (stop_streaming(fd) < 0) {
        unmap_buffers(buffers, n_buffers);
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Unmap buffers
    if (unmap_buffers(buffers, n_buffers) < 0) {
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Free buffers
    free(buffers);

    // Close device
    if (close_device(fd) < 0) {
        return EXIT_FAILURE;
    }

    printf("Image saved to %s\n", IMAGE_FILENAME);
    return EXIT_SUCCESS;
}

