#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

// Define PWM parameters
#define PWM_PERIOD_NS 20000000 // 20 ms
#define MIN_PULSE_WIDTH_NS 1000000 // 1 ms
#define MAX_PULSE_WIDTH_NS 2000000 // 2 ms
#define DUTY_CYCLE_RANGE 1000

// Define servo limits
#define MIN_POSITION 25
#define MAX_POSITION 125

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pan_servo_line, *tilt_servo_line;
static struct gpiod_line *tilt_up_line, *tilt_down_line, *pan_left_line, *pan_right_line;
static int pan_position = 75;
static int tilt_position = 75;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_button(struct gpiod_line *line);
void set_servo_position(struct gpiod_line *line, int position);
void cleanup_gpio();
void signal_handler(int sig);

// Function to initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    pan_servo_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_servo_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    tilt_up_line = gpiod_chip_get_line(chip, TILT_UP_PIN);
    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    pan_left_line = gpiod_chip_get_line(chip, PAN_LEFT_PIN);
    pan_right_line = gpiod_chip_get_line(chip, PAN_RIGHT_PIN);

    if (!pan_servo_line || !tilt_servo_line || !tilt_up_line || !tilt_down_line || !pan_left_line || !pan_right_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Set GPIO lines as output
    if (gpiod_line_request_output(tilt_servo_line, "tilt_servo", 0) < 0) {
        perror("Error requesting tilt servo line as output");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_output(pan_servo_line, "pan_servo", 0) < 0) {
        perror("Error requesting pan servo line as output");
        cleanup_gpio();
        return -1;
    }

    // Set GPIO lines as input with pull-up resistors
    if (gpiod_line_request_input(tilt_up_line, "tilt_up") < 0) {
        perror("Error requesting tilt up line as input");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_input(tilt_down_line, "tilt_down") < 0) {
        perror("Error requesting tilt down line as input");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_input(pan_left_line, "pan_left") < 0) {
        perror("Error requesting pan left line as input");
        cleanup_gpio();
        return -1;
    }
    if (gpiod_line_request_input(pan_right_line, "pan_right") < 0) {
        perror("Error requesting pan right line as input");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to read a button state
int read_button(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading button value");
        return -1; // Indicate error
    }
    return value;
}

// Function to set servo position using PWM
void set_servo_position(struct gpiod_line *line, int position) {
    if (position < MIN_POSITION) position = MIN_POSITION;
    if (position > MAX_POSITION) position = MAX_POSITION;

    // Calculate pulse width in nanoseconds
    long pulse_width_ns = MIN_PULSE_WIDTH_NS + (long)((float)(position - MIN_POSITION) / (MAX_POSITION - MIN_POSITION) * (MAX_PULSE_WIDTH_NS - MIN_PULSE_WIDTH_NS));

    // Calculate duty cycle
    int duty_cycle = (int)((float)pulse_width_ns / PWM_PERIOD_NS * DUTY_CYCLE_RANGE);

    // Set the servo position by toggling the GPIO line
    for (int i = 0; i < duty_cycle; ++i) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting servo line high");
            return;
        }
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting servo line low");
            return;
        }
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (tilt_servo_line) {
        gpiod_line_release(tilt_servo_line);
    }
    if (pan_servo_line) {
        gpiod_line_release(pan_servo_line);
    }
    if (tilt_up_line) {
        gpiod_line_release(tilt_up_line);
    }
    if (tilt_down_line) {
        gpiod_line_release(tilt_down_line);
    }
    if (pan_left_line) {
        gpiod_line_release(pan_left_line);
    }
    if (pan_right_line) {
        gpiod_line_release(pan_right_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Pan-Tilt System Control Program\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read button states
        int tilt_up = read_button(tilt_up_line);
        int tilt_down = read_button(tilt_down_line);
        int pan_left = read_button(pan_left_line);
        int pan_right = read_button(pan_right_line);

        if (tilt_up < 0 || tilt_down < 0 || pan_left < 0 || pan_right < 0) {
            fprintf(stderr, "Error reading button states. Continuing.\n");
        } else {
            // Update servo positions based on button presses
            if (tilt_up == 0) {
                tilt_position += 5;
                if (tilt_position > MAX_POSITION) tilt_position = MAX_POSITION;
            } else if (tilt_down == 0) {
                tilt_position -= 5;
                if (tilt_position < MIN_POSITION) tilt_position = MIN_POSITION;
            }

            if (pan_left == 0) {
                pan_position -= 5;
                if (pan_position < MIN_POSITION) pan_position = MIN_POSITION;
            } else if (pan_right == 0) {
                pan_position += 5;
                if (pan_position > MAX_POSITION) pan_position = MAX_POSITION;
            }

            // Set servo positions
            set_servo_position(tilt_servo_line, tilt_position);
            set_servo_position(pan_servo_line, pan_position);
        }

        // Delay for 50 ms
        usleep(50000);
    }

    return 0;
}

