#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <stdint.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define JPEG_QUALITY 75
#define NUM_BUFFERS 4

// Structure to hold camera information
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    unsigned int n_buffers;
} camera_t;

// Global camera instance
camera_t camera;

// Function prototypes
int init_camera(camera_t *cam);
int start_capturing(camera_t *cam);
int read_frame(camera_t *cam, unsigned char **frame_data);
int stop_capturing(camera_t *cam);
int uninit_camera(camera_t *cam);
int box_blur(unsigned char *src, unsigned char *dst, int width, int height);
int save_jpeg(unsigned char *image, int width, int height, int quality, const char *filename);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        stop_capturing(&camera);
        uninit_camera(&camera);
        exit(0);
    }
}

// Initialize the camera
int init_camera(camera_t *cam) {
    cam->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (cam->fd < 0) {
        fprintf(stderr, "Error opening device: %s\n", strerror(errno));
        return -1;
    }

    // Check device capabilities
    if (ioctl(cam->fd, VIDIOC_QUERYCAP, &cam->cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(cam->fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(cam->fd);
        return -1;
    }

    if (!(cam->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(cam->fd);
        return -1;
    }

    // Set video format
    cam->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
