#define DEVICE_NAME "/dev/video0"

// Structure to hold camera capabilities
typedef struct {
    struct v4l2_capability cap;
    struct v4l2_cropcap cropcap;
    struct v4l2_format fmt;
    unsigned int min_width;
    unsigned int min_height;
    unsigned int max_width;
    unsigned int max_height;
    unsigned int step_width;
    unsigned int step_height;
    struct v4l2_fract min_fps;
    struct v4l2_fract max_fps;
    struct v4l2_fract step_fps;
    int autofocus_supported;
} camera_capabilities_t;

// Function to initialize camera capabilities
void init_camera_capabilities(camera_capabilities_t *cap) {
    memset(cap, 0, sizeof(camera_capabilities_t));
    cap->min_width = 0;
    cap->min_height = 0;
    cap->max_width = 0;
    cap->max_height = 0;
    cap->step_width = 0;
    cap->step_height = 0;
    cap->min_fps.numerator = 0;
    cap->min_fps.denominator = 0;
    cap->max_fps.numerator = 0;
    cap->max_fps.denominator = 0;
    cap->step_fps.numerator = 0;
    cap->step_fps.denominator = 0;
    cap->autofocus_supported = 0;
}

// Function to query camera capabilities
int query_capabilities(int fd, camera_capabilities_t *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap->cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

