#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo center position (microseconds)
#define SERVO_CENTER 1500

// Define servo limits (microseconds)
#define SERVO_MIN 1000
#define SERVO_MAX 2000

// Define increment/decrement step (microseconds)
#define SERVO_STEP 10

// Global variables for servo positions
int pan_position = SERVO_CENTER;
int tilt_position = SERVO_CENTER;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void update_servos();
void increment_pan();
void decrement_pan();
void increment_tilt();
void decrement_tilt();
void button_pressed(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Print startup message
    printf("Pan-Tilt System Control\n");
    printf("Pan Servo: GPIO%d, Tilt Servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Pan: %d us, Tilt: %d us\n", pan_position, tilt_position);

    // Main loop
    while (1) {
        update_servos();
        gpioDelay(50); // 50 ms delay
    }

    return 0;
}

// Initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set initial servo positions
    gpioServo(PAN_SERVO_PIN, SERVO_CENTER);
    gpioServo(TILT_SERVO_PIN, SERVO_CENTER);

    // Set up interrupt handlers for button presses
    gpioSetAlertFuncEx(UP_BUTTON_PIN, button_pressed, NULL);
    gpioSetAlertFuncEx(DOWN_BUTTON_PIN, button_pressed, NULL);
    gpioSetAlertFuncEx(LEFT_BUTTON_PIN, button_pressed, NULL);
    gpioSetAlertFuncEx(RIGHT_BUTTON_PIN, button_pressed, NULL);

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio()
{
    // Stop servos
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();
}

// Update servos with current positions
void update_servos()
{
    gpioServo(PAN_SERVO_PIN, pan_position);
    gpioServo(TILT_SERVO_PIN, tilt_position);
}

// Increment pan servo position
void increment_pan()
{
    pan_position += SERVO_STEP;
    if (pan_position > SERVO_MAX) {
        pan_position = SERVO_MAX;
    }
}

// Decrement pan servo position
void decrement_pan()
{
    pan_position -= SERVO_STEP;
    if (pan_position < SERVO_MIN) {
        pan_position = SERVO_MIN;
    }
}

// Increment tilt servo position
void increment_tilt()
{
    tilt_position += SERVO_STEP;
    if (tilt_position > SERVO_MAX) {
        tilt_position = SERVO_MAX;
    }
}

// Decrement tilt servo position
void decrement_tilt()
{
    tilt_position -= SERVO_STEP;
    if (tilt_position < SERVO_MIN) {
        tilt_position = SERVO_MIN;
    }
}

// Button press handler
void button_pressed(int gpio, int level, uint32_t tick)
{
    if (level == 0) { // Button is pressed (active low)
        switch (gpio) {
            case UP_BUTTON_PIN:
                increment_tilt();
                break;
            case DOWN_BUTTON_PIN:
                decrement_tilt();
                break;
            case LEFT_BUTTON_PIN:
                decrement_pan();
                break;
            case RIGHT_BUTTON_PIN:
                increment_pan();
                break;
        }
    }
}

