#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <curl/curl.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 2000
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_JSON_LEN 512

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to get current timestamp with microseconds
char* get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    static char timestamp[80];
    snprintf(timestamp, sizeof(timestamp), "%s.%06ld", buf, ts.tv_nsec / 1000);
    return timestamp;
}

// Function to capture a JPEG image using libcamera-still
int capture_image(const char* filename) {
    char command[MAX_FILENAME_LEN * 2];
    snprintf(command, sizeof(command), "libcamera-still -n -o %s --width %d --height %d --quality %d", filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("execl failed");
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        perror("fork failed");
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            fprintf(stderr, "libcamera-still command failed with status %d\n", WEXITSTATUS(status));
            return -1;
        }
    }
    return 0;
}

// Function to create JSON payload
char* create_json_payload(const char* filename, const char* timestamp, int motion_detected, int gpio_pin) {
    char* json_payload = (char*)malloc(MAX_JSON_LEN);
    if (json_payload == NULL) {
        perror("malloc failed");
        return NULL;
    }
    snprintf(json_payload, MAX_JSON_LEN, "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_detected\": %d, \"gpio_pin\": %d}", filename, timestamp, motion_detected, gpio_pin);
    return json_payload;
}

// Function to send HTTP POST request using libcurl
int send_http_request(const char* server_ip, int server_port, const char* json_payload) {
    CURL *curl;
    CURLcode res;
    char url[MAX_FILENAME_LEN];

    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char* server_ip = argv[1];
    int server_port = atoi(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = 0; // 0: no motion, 1: motion
    time_t last_motion_time = 0;

    while (!terminate) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            if (current_state == 1) {
                // Motion detected
                time_t now = time(NULL);
                if (now - last_motion_time > DEBOUNCE_DELAY_MS / 1000.0) {
                    char* timestamp = get_timestamp();
                    char filename[MAX_FILENAME_LEN];
                    snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);

                    // Create capture directory if it doesn't exist
                    struct stat st = {0};
                    if (stat(CAPTURE_DIR, &st) == -1) {
                        if (mkdir(CAPTURE_DIR, 0777) == -1) {
                            if (errno == EEXIST) {
                                fprintf(stderr, "Directory %s already exists\n", CAPTURE_DIR);
                            } else {
                                perror("mkdir failed");
                                continue;
                            }
                        }
                    }

                    if (capture_image(filename) == 0) {
                        char* json_payload = create_json_payload(filename, timestamp, 1, GPIO_PIN);
                        if (json_payload != NULL) {
                            if (send_http_request(server_ip, server_port, json_payload) != 0) {
                                fprintf(stderr, "Failed to send HTTP request\n");
                            }
                            free(json_payload);
                        }
                    } else {
                        fprintf(stderr, "Failed to capture image\n");
                    }

                    last_motion_time = now;
                }
            }
            last_state = current_state;
        }

        gpioDelay(100); // Check every 100 ms
    }

    gpioTerminate();
    return 0;
}

