#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get the current timestamp in YYYYMMDD_HHMMSS_mmm format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y%m%d_%H%M%S", timeinfo);
    return timestamp;
}

// Function to generate the filename based on the timestamp
char* generate_filename(const char* timestamp) {
    char *filename = (char*)malloc(50 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }
    snprintf(filename, 50, "%s/%s_motion.jpg", IMAGE_DIR, timestamp);
    return filename;
}

// Function to capture an image using libcamera-still
int capture_image(const char* filename) {
    char command[200];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute libcamera-still");
        return -1;
    }
    return WEXITSTATUS(status); // Return the exit status of the command
}

// Function to log an event to the log file
void log_event(const char* message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_fp, "%s: %s\n", timestamp, message);
    fflush(log_fp); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Open the log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    log_event("Starting motion detection...");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        log_event("Failed to open GPIO chip");
        fclose(log_fp);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_fp);
        return 1;
    }

    // Request the GPIO line as input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_detector";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;

    // Set debounce time (50ms)
    config.consumer_fd = -1; // Not used, but must be set to -1
    config.debounce_period_us = 50000; // 50ms

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Failed to request GPIO line as input");
        log_event("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        fclose(log_fp);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Wait for a falling edge with a timeout
        int ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            log_event("Failed to wait for GPIO event");
            break;
        } else if (ret == 0) {
            // Timeout occurred
            continue;
        }

        // Generate timestamp
        char* timestamp = get_timestamp();
        if (timestamp == NULL) {
            log_event("Failed to generate timestamp");
            break;
        }

        // Generate filename
        char* filename = generate_filename(timestamp);
        if (filename == NULL) {
            log_event("Failed to generate filename");
            free(timestamp);
            break;
        }

        // Capture image
        int capture_status = capture_image(filename);
        if (capture_status != 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "libcamera-still failed with status %d", capture_status);
            log_event(error_message);
        } else {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Motion detected, image saved: %s", filename);
            log_event(log_message);
        }

        // Clean up
        free(timestamp);
        free(filename);
    }

    // Release resources
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }

    log_event("Exiting...");

    return 0;
}

