#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define neutral position (90 degrees)
#define NEUTRAL_PULSE_WIDTH 1500 // microseconds

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Setting servos to neutral position and exiting.\n");
        program_running = 0;
    }
}

// Function to set the pan servo angle
int set_pan_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Pan angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate failure
    }

    // Calculate pulse width based on angle (0-180 degrees -> 500-2500 microseconds)
    int pulse_width = NEUTRAL_PULSE_WIDTH + (int)((float)(angle - 90) / 90.0 * (2500 - 500));

    // Set the pan servo pulse width
    gpioPWM(PAN_GPIO, pulse_width);

    return 0; // Indicate success
}

// Function to set the tilt servo angle
int set_tilt_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Tilt angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1; // Indicate failure
    }

    // Calculate pulse width based on angle (0-180 degrees -> 500-2500 microseconds)
    int pulse_width = NEUTRAL_PULSE_WIDTH + (int)((float)(angle - 90) / 90.0 * (2500 - 500));

    // Set the tilt servo pulse width
    gpioPWM(TILT_GPIO, pulse_width);

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with error code
    }

    // Set GPIO pins to output mode
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set initial servo positions to neutral
    set_pan_angle(90);
    set_tilt_angle(90);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pan-Tilt Control\n");
    printf("Use arrow keys (or 'q' to quit) to control the camera.\n");

    int pan_angle = 90;
    int tilt_angle = 90;

    while (program_running) {
        int input = getchar();

        switch (input) {
            case 'w': // Up arrow
            case 'W':
                pan_angle += 5;
                if (pan_angle > MAX_ANGLE) {
                    pan_angle = MAX_ANGLE;
                }
                break;
            case 's': // Down arrow
            case 'S':
                pan_angle -= 5;
                if (pan_angle < MIN_ANGLE) {
                    pan_angle = MIN_ANGLE;
                }
                break;
            case 'a': // Left arrow
            case 'A':
                tilt_angle -= 5;
                if (tilt_angle < MIN_ANGLE) {
                    tilt_angle = MIN_ANGLE;
                }
                break;
            case 'd': // Right arrow
            case 'D':
                tilt_angle += 5;
                if (tilt_angle > MAX_ANGLE) {
                    tilt_angle = MAX_ANGLE;
                }
                break;
            case 'q': // Quit
            case 'Q':
                program_running = 0;
                break;
            default:
                // Ignore other input
                continue;
        }

        // Set servo angles
        if (set_pan_angle(pan_angle) != 0) {
            fprintf(stderr, "Error setting pan angle.\n");
        }
        if (set_tilt_angle(tilt_angle) != 0) {
            fprintf(stderr, "Error setting tilt angle.\n");
        }

        // Delay to prevent excessive CPU usage
        usleep(100000); // 100 ms
    }

    // Set servos to neutral position before exiting
    set_pan_angle(90);
    set_tilt_angle(90);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

