};

// Function prototypes
int read_cpu_temp();
int read_cpu_usage();
void oled_init();
void oled_clear();
void oled_set_cursor(int x, int y);
void oled_write_char(char c);
void oled_write_string(const char *str);
void oled_update_display();
void signal_handler(int signal);

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open CPU temperature file.\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Could not read CPU temperature from file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to read CPU usage from /proc/stat
int read_cpu_usage() {
    FILE *fp;
    unsigned long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long prev_total = 0, prev_idle_total = 0;
    unsigned long total, idle_total;
    int usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open /proc/stat file.\n");
        return -1;
    }

    if (fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error: Could not read CPU statistics from file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    idle_total = idle + iowait;

    if (prev_total != 0 && prev_idle_total != 0) {
        unsigned long diff_total = total - prev_total;
        unsigned long diff_idle = idle_total - prev_idle_total;
        usage = (int)(((diff_total - diff_idle) * 100.0) / diff_total);
    } else {
        usage = 0; // Initialization
    }

    prev_total = total;
    prev_idle_total = idle_total;

    return usage;
}

// Function to initialize the OLED display
void oled_init() {
    // Initialization sequence (SSD1306 datasheet)
    unsigned char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Multiplex ratio
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode (horizontal)
        0xA1,       // Segment remap
        0xC8,       // COM output scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Precharge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Normal/Inverse display
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteByteData(i2c_handle, 0x00, init_commands[i]) != 0) {
            fprintf(stderr, "Error: I2C write failed during OLED initialization.\n");
            gpioTerminate();
            exit(1);
        }
    }
}

// Function to clear the OLED display
void oled_clear() {
    for (int i = 0; i < OLED_WIDTH * (OLED_HEIGHT / 8); i++) {
        if (i2cWriteByteData(i2c_handle, 0x40, 0x00) != 0) {
            fprintf(stderr, "Error: I2C write failed during OLED clear.\n");
            gpioTerminate();
            exit(1);
        }
    }
}

// Function to set the cursor position
void oled_set_cursor(int x, int y) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) {
        fprintf(stderr, "Error: Invalid cursor position.\n");
        return;
    }

    if (i2cWriteByteData(i2c_handle, 0x00, 0xB0 + y / 8) != 0) {
        fprintf(stderr, "Error: I2C write failed during OLED set cursor (page).\n");
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00 + (x & 0x0F)) != 0) {
        fprintf(stderr, "Error: I2C write failed during OLED set cursor (low nibble).\n");
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10 + ((x >> 4) & 0x0F)) != 0) {
        fprintf(stderr, "Error: I2C write failed during OLED set cursor (high nibble).\n");
        gpioTerminate();
        exit(1);
    }
}

// Function to write a character to the OLED display
void oled_write_char(char c) {
    if (c < 32 || c > 126) {
        c = 0; // Use space for invalid characters
    }

    for (int i = 0; i < 5; i++) {
        unsigned char data = font[c - 32][i];
        if (i2cWriteByteData(i2c_handle, 0x40, data) != 0) {
            fprintf(stderr, "Error: I2C write failed during OLED write char.\n");
            gpioTerminate();
            exit(1);
        }
    }
    if (i2cWriteByteData(i2c_handle, 0x40, 0x00) != 0) {
        fprintf(stderr, "Error: I2C write failed during OLED write char (space).\n");
        gpioTerminate();
        exit(1);
    }
}

// Function to write a string to the OLED display
void oled_write_string(const char *str) {
    int x = 0;
    int y = 0;
    oled_set_cursor(x, y);
    for (int i = 0; str[i] != '\0'; i++) {
        oled_write_char(str[i]);
        x += 6; // Character width + 1 pixel spacing
        if (x >= OLED_WIDTH) {
            x = 0;
            y += 8; // Character height
            if (y >= OLED_HEIGHT) {
                oled_clear();
                y = 0;
            }
            oled_set_cursor(x, y);
        }
    }
}

// Function to update the OLED display
void oled_update_display() {
    // No specific command needed for partial update in this driver.
    // The data is directly written to the display memory.
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    oled_init();
    oled_clear();

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        int temp = read_cpu_temp();
        char temp_str[20];
        if (temp == -1) {
            snprintf(temp_str, sizeof(temp_str), "Temp Error");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", (float)temp / 1000.0);
        }

        // Read CPU usage
        int usage = read_cpu_usage();
        char usage_str[20];
        if (usage == -1) {
            snprintf(usage_str, sizeof(usage_str), "Usage Error");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", usage);
        }

        // Clear the display
        oled_clear();

        // Write temperature and usage to the display
        oled_write_string(temp_str);
        oled_set_cursor(0, 8); // Move to the next line
        oled_write_string(usage_str);

        // Update the display
        oled_update_display();

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    oled_clear();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

