#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>
#include <wiringPi.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_fd;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
void update_display();
void signal_handler(int signal);
void lcd_init();
void lcd_string(const char *s);
void lcd_clear();
void lcd_command(int cmd);
void lcd_data(int data);

// LCD functions (using wiringPiI2C)
void lcd_init() {
    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C communication.\n");
        exit(1);
    }

    // Initialize LCD (4-bit mode)
    delay(50); // Wait for LCD to power up
    lcd_command(0x33); // Initialize
    lcd_command(0x32); // Initialize
    lcd_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_command(0x0C); // Display on, cursor off, blink off
    lcd_command(0x06); // Increment cursor, no shift
    lcd_command(0x01); // Clear display
    delay(2);          // Delay for clear display
}

void lcd_string(const char *s) {
    while (*s) {
        lcd_data(*s++);
    }
}

void lcd_clear() {
    lcd_command(0x01); // Clear display
    delay(2);          // Delay for clear display
}

void lcd_command(int cmd) {
    int upper = cmd & 0xF0;
    int lower = (cmd << 4) & 0xF0;

    wiringPiI2CWrite(i2c_fd, upper | 0x04 | 0x08); // Enable pulse
    wiringPiI2CWrite(i2c_fd, upper | 0x08);        // Disable pulse
    wiringPiI2CWrite(i2c_fd, lower | 0x04 | 0x08); // Enable pulse
    wiringPiI2CWrite(i2c_fd, lower | 0x08);        // Disable pulse
}

void lcd_data(int data) {
    int upper = data & 0xF0;
    int lower = (data << 4) & 0xF0;

    wiringPiI2CWrite(i2c_fd, upper | 0x05 | 0x08); // Enable pulse, RS=1
    wiringPiI2CWrite(i2c_fd, upper | 0x09);        // Disable pulse, RS=1
    wiringPiI2CWrite(i2c_fd, lower | 0x05 | 0x08); // Enable pulse, RS=1
    wiringPiI2CWrite(i2c_fd, lower | 0x09);        // Disable pulse, RS=1
}

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick) {
    pulse_count++;
}

// Function to update the LCD display
void update_display() {
    double flow_rate = (double)pulse_count / PULSES_PER_LITER * 60.0;
    total_volume += (double)pulse_count / PULSES_PER_LITER / 10.0; // Accumulate volume every 10 seconds
    pulse_count = 0;

    char buffer[32];
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow_rate);
    lcd_clear();
    lcd_string(buffer);

    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
    lcd_string(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    lcd_clear();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt on GPIO17
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL);

    // Initialize LCD
    wiringPiSetup();
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        update_display();
        sleep(10);
    }

    return 0;
}

