#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define ANEMOMETER_PULSES_PER_MINUTE 1000.0 // Example value, calibrate
#define ANEMOMETER_PULSE_DURATION_MS 1000 // Interrupt duration in ms
#define ANEMOMETER_WIND_SPEED_FACTOR 0.5   // m/s per pulse
#define WIND_VANE_CHANNEL 0
#define LCD_I2C_ADDR 0x27
#define LCD_I2C_BUS 1
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
volatile int anemometer_pulses = 0;
int i2c_handle;
int spi_handle;
double wind_speed = 0.0;
double wind_direction = 0.0;

// Function prototypes
void anemometer_interrupt(int gpio, int level, uint32_t tick, void *user);
int read_wind_vane();
void update_lcd(double wind_speed, double wind_direction);
void signal_handler(int signal);

// LCD functions (PCF8574 I2C backpack)
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Anemometer interrupt handler
void anemometer_interrupt(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        anemometer_pulses++;
    }
}

// Function to read wind vane data from MCP3008
int read_wind_vane()
{
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // MCP3008 configuration: single-ended, channel 0
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | WIND_VANE_CHANNEL) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0)
    {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to update LCD display
void update_lcd(double wind_speed, double wind_direction)
{
    char buffer[17]; // 16 characters + null terminator

    lcd_clear();
    lcd_set_cursor(0, 0);
    snprintf(buffer, sizeof(buffer), "Speed: %.1f m/s", wind_speed);
    lcd_print(buffer);

    lcd_set_cursor(1, 0);
    snprintf(buffer, sizeof(buffer), "Dir: %.0f deg", wind_direction);
    lcd_print(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// LCD functions (PCF8574 I2C backpack)
void lcd_init()
{
    // Initialization sequence (adjust based on your LCD)
    gpioDelay(15000); // Wait for LCD to power up
    lcd_clear();
    gpioDelay(5000); // Wait after initialization
}

void lcd_clear()
{
    char data[2] = {0x00, 0x01}; // Clear display command
    i2cWriteDevice(i2c_handle, data, 2);
    gpioDelay(2000); // Wait for clear command to complete
}

void lcd_set_cursor(int row, int col)
{
    unsigned char data[2];
    data[0] = 0x00; // Control byte: RS=0 (command), RW=0 (write), E=0 (low)
    data[1] = 0x80 + (row * 0x40) + col; // Set cursor position
    i2cWriteDevice(i2c_handle, data, 2);
    gpioDelay(1000); // Delay for command to execute
}

void lcd_print(const char *str)
{
    int i;
    unsigned char data[2];
    data[0] = 0x01; // Control byte: RS=1 (data), RW=0 (write), E=0 (low)

    for (i = 0; str[i] != '\0'; i++)
    {
        data[1] = str[i];
        i2cWriteDevice(i2c_handle, data, 2);
        gpioDelay(1000); // Delay for data to execute
    }
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error: I2C open failed (LCD)\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI connection
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0)
    {
        fprintf(stderr, "Error: SPI open failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set anemometer GPIO as input
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);

    // Set interrupt handler for anemometer
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_interrupt, NULL) != 0)
    {
        fprintf(stderr, "Error: Failed to set ISR for anemometer\n");
        spiClose(spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running)
    {
        // Calculate wind speed
        wind_speed = (double)anemometer_pulses * ANEMOMETER_WIND_SPEED_FACTOR * (60.0 / ANEMOMETER_PULSES_PER_MINUTE); // m/s
        anemometer_pulses = 0; // Reset pulse count for next sample window

        // Read wind vane data
        int adc_value = read_wind_vane();
        if (adc_value >= 0)
        {
            // Map ADC value to wind direction (0-359 degrees)
            wind_direction = (double)adc_value / 1023.0 * 360.0;
        }
        else
        {
            fprintf(stderr, "Error: Failed to read wind vane data\n");
            wind_direction = 0.0; // Set to a default value
        }

        // Update LCD display
        update_lcd(wind_speed, wind_direction);

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Cleanup
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

