#define PCF8574_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

#define LCD_LINE_1 0x80 // LCD RAM address for the 1st line
#define LCD_LINE_2 0xC0 // LCD RAM address for the 2nd line

#define ENABLE 0b00000100 // Enable bit

// Global variables
volatile int pulse_count = 0;
int i2c_fd;

// Function prototypes
void flow_sensor_callback(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulses);
void lcd_init();
