void lcd_clear();
void lcd_set_cursor(int col, int row);
void signal_handler(int signal);

// LCD functions
void lcd_init() {
    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // Turn on display, cursor off, blink off
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    delayMicroseconds(500);
}

void lcd_byte(int bits, int mode) {
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command

    int bits_high = mode | (bits & 0xF0) | ENABLE;
    int bits_low = mode | (bits & 0xF0);

    wiringPiI2CWriteReg8(i2c_fd, 0, bits_high);
    delayMicroseconds(1);
    wiringPiI2CWriteReg8(i2c_fd, 0, bits_low);
    delayMicroseconds(100);
}

void lcd_string(const char *s) {
    // Send string to display
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

void lcd_clear() {
    lcd_byte(0x01, LCD_CMD);
    delayMicroseconds(500);
}

void lcd_set_cursor(int col, int row) {
    int addr;
    if (row == 0) {
        addr = LCD_LINE_1 + col;
    } else {
        addr = LCD_LINE_2 + col;
    }
    lcd_byte(addr, LCD_CMD);
}

// Callback function for flow sensor
void flow_sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate
float calculate_flow_rate(int pulses) {
    return (float)pulses / 7.5;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    // Set alert function for rising edge detection
    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, flow_sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(PCF8574_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C communication.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pulses_in_interval;
    float flow_rate;
    char flow_rate_str[16];

    // Main loop
    while (1) {
        pulses_in_interval = pulse_count;
        pulse_count = 0; // Reset pulse count

        flow_rate = calculate_flow_rate(pulses_in_interval);

        // Display flow rate on LCD
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_string("Flow Rate:");
        lcd_set_cursor(0, 1);
        snprintf(flow_rate_str, sizeof(flow_rate_str), "%.2f L/min", flow_rate);
        lcd_string(flow_rate_str);

        printf("Flow Rate: %.2f L/min\n", flow_rate);

        delay(1000); // Wait for 1 second
    }

    return 0;
}

