#include <unistd.h>

// Define GPIO chip and lines
#define GPIOCHIP "gpiochip0"
#define ROW_LINES {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_LINES {14, 15, 18, 23, 24, 25, 8, 7}

// Define wave parameters
#define WAVE_SPEED 0.01  // Adjust for desired speed
#define WAVE_AMPLITUDE 4  // Adjust for desired amplitude

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *row_lines[8];
struct gpiod_line *col_lines[8];

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < 8; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    int row_pins[] = ROW_LINES;
    int col_pins[] = COL_LINES;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get row lines
    for (int i = 0; i < 8; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            perror("Error getting row line");
            goto cleanup_row;
        }
        if (gpiod_line_request_output(row_lines[i], "wave", 0) < 0) {
            perror("Error requesting row line output");
            goto cleanup_row;
        }
    }

    // Get column lines
    for (int i = 0; i < 8; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            perror("Error getting column line");
            goto cleanup_col;
        }
        if (gpiod_line_request_output(col_lines[i], "wave", 0) < 0) {
            perror("Error requesting column line output");
            goto cleanup_col;
        }
    }

    return 0;

cleanup_col:
    for (int j = 0; j < i; j++) {
        gpiod_line_release(col_lines[j]);
    }

cleanup_row:
    for (int j = 0; j < i; j++) {
        gpiod_line_release(row_lines[j]);
    }
    return -1;
}

// Function to clear the matrix
void clear_matrix()
{
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(col_lines[i], 1); // Set column HIGH
        gpiod_line_set_value(row_lines[i], 0); // Set row LOW
    }
}

// Function to set a specific row and column
void set_pixel(int row, int col)
{
    gpiod_line_set_value(col_lines[col], 0); // Set column LOW
    gpiod_line_set_value(row_lines[row], 1); // Set row HIGH
}

// Function to create the wave pattern
void create_wave(int col)
{
    clear_matrix();
    for (int row = 0; row < 8; row++) {
        // Calculate the wave value for this row and column
        double wave_value = WAVE_AMPLITUDE * sin(2 * M_PI * (col + WAVE_SPEED * row));

        // Map the wave value to a brightness level (0-7)
        int brightness = (int)((wave_value / WAVE_AMPLITUDE) * 7); // Scale to 0-7

        // Set the pixel if the brightness is above a threshold (e.g., 3)
        if (brightness > 3) {
            set_pixel(row, col);
        }
    }
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        for (int col = 0; col < 8; col++) {
            create_wave(col);
            usleep(150000); // 150 ms delay
        }
    }

    return 0;
}

