                    fprintf(stderr, "Error logging data, but continuing...\n");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/3)\n", retry_count + 1);
                retry_count++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (retry_count == 3) {
            fprintf(stderr, "I2C read failed after multiple retries, logging error.\n");
            log_data(65535); // Log error value
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

