void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145 sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read PART ID from Si1145 sensor.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART ID (0x%02X) from Si1145 sensor. Expected 0x45.\n", part_id);
        return -1;
    }

    // Configure measurement rates (adjust as needed)
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, 0x07) < 0) { // Enable force mode for ALS
        fprintf(stderr, "Error: Failed to set measurement rates.\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the sensor
int read_sensor_data(int *proximity, int *ambient_light) {
    // Trigger a measurement
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete

    // Read ambient light data
    int als_vis_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    int als_vis_high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);
    if (als_vis_low < 0 || als_vis_high < 0) {
        fprintf(stderr, "Error: Failed to read ambient light data.\n");
        return -1;
    }
    *ambient_light = (als_vis_high << 8) | als_vis_low;

    // Read proximity data
    int ps1_low = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
    int ps1_high = i2cReadByteData(i2c_handle, REG_PS1_DATA0 + 1);
    if (ps1_low < 0 || ps1_high < 0) {
        fprintf(stderr, "Error: Failed to read proximity data.\n");
        return -1;
    }
    *proximity = (ps1_high << 8) | ps1_low;

    return 0;
}

