// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define GPIO chip name
#define GPIOCHIP_NAME "gpiochip4"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL;
struct gpiod_line *led_line = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
void control_led(int state);
void log_event();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO lines and chip
int initialize_gpio() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            perror("Error opening GPIO chip (fallback)");
            return -1;
        }
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Error getting sensor line");
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        return -1;
    }

    // Request sensor line as input
    ret = gpiod_line_request_input(sensor_line, "proximity_sensor");
    if (ret < 0) {
        perror("Error requesting sensor line as input");
        return -1;
    }

    // Request LED line as output
    ret = gpiod_line_request_output(led_line, "proximity_led", 0);
    if (ret < 0) {
        perror("Error requesting LED line as output");
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor() {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Control LED state
void control_led(int state) {
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        perror("Error setting LED value");
    }
}

// Log event to file
void log_event() {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    char timestamp[32];

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open log file in append mode
    fp = fopen("proximity.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    // Write timestamped event to log file
    fprintf(fp, "%s Object detected\n", timestamp);

    // Close log file
    fclose(fp);
}

// Cleanup GPIO lines and chip
void cleanup_gpio() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

