#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define LOG_FILE "biometric_data.log"

// Si1145 Registers
#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_CH_LIST 0x4F
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_COMMAND 0x30
#define REG_PS1_DATA0 0x18
#define REG_PS1_DATA1 0x19
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_proximity();
int read_ambient_light();
char* get_iso8601_timestamp();
int log_data(char *timestamp, int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    // Verify PART_ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    int write_result = i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17);
    if (write_result < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", write_result);
        return -1;
    }

    // Configure CH_LIST
    write_result = i2cWriteByteData(i2c_handle, REG_CH_LIST, 0x17); // Enable PS1 and ALS_VIS
    if (write_result < 0) {
        fprintf(stderr, "Error writing CH_LIST: %d\n", write_result);
        return -1;
    }

    // Configure Measurement Rates
    write_result = i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x00); // Default rate
    if (write_result < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0: %d\n", write_result);
        return -1;
    }
    write_result = i2cWriteByteData(i2c_handle, REG_MEAS_RATE1, 0x00); // Default rate
    if (write_result < 0) {
        fprintf(stderr, "Error writing MEAS_RATE1: %d\n", write_result);
        return -1;
    }

    return 0;
}

// Read proximity data from the sensor
int read_proximity() {
    int write_result = i2cWriteByteData(i2c_handle, REG_COMMAND, 0x07); // PS_FORCE
    if (write_result < 0) {
        fprintf(stderr, "Error writing COMMAND (PS_FORCE): %d\n", write_result);
        return -1;
    }

    int data0 = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
    int data1 = i2cReadByteData(i2c_handle, REG_PS1_DATA1);

    if (data0 < 0 || data1 < 0) {
        fprintf(stderr, "Error reading proximity data: %d %d\n", data0, data1);
        return -1;
    }

    return (data1 << 8) | data0;
}

// Read ambient light data from the sensor
int read_ambient_light() {
    int write_result = i2cWriteByteData(i2c_handle, REG_COMMAND, 0x06); // ALS_FORCE
    if (write_result < 0) {
        fprintf(stderr, "Error writing COMMAND (ALS_FORCE): %d\n", write_result);
        return -1;
    }

    int data0 = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    int data1 = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA1);

    if (data0 < 0 || data1 < 0) {
        fprintf(stderr, "Error reading ambient light data: %d %d\n", data0, data1);
        return -1;
    }

    return (data1 << 8) | data0;
}

// Get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log the data to a CSV file
int log_data(char *timestamp, int proximity, int ambient_light) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        if (proximity >= 0 && ambient_light >= 0) {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();

            // Log data
            if (log_data(timestamp, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

