    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
pulse_t measure_pulse_width() {
    pulse_t pulse;
    int timeout = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0 && !timeout) {
        gpioDelay(1); // Check every 1 us
        clock_gettime(CLOCK_MONOTONIC, &pulse.start);
        timeout++;
        if (timeout > TIMEOUT_US) {
            pulse.start.tv_sec = 0;
            pulse.start.tv_nsec = 0;
            pulse.end.tv_sec = 0;
            pulse.end.tv_nsec = 0;
            return pulse; // Timeout
        }
    }

    if (pulse.start.tv_sec == 0 && pulse.start.tv_nsec == 0) {
        return pulse; // Timeout
    }

    // Wait for the echo pin to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && !timeout) {
        gpioDelay(1); // Check every 1 us
        clock_gettime(CLOCK_MONOTONIC, &pulse.end);
        timeout++;
        if (timeout > TIMEOUT_US) {
            pulse.start.tv_sec = 0;
            pulse.start.tv_nsec = 0;
            pulse.end.tv_sec = 0;
            pulse.end.tv_nsec = 0;
            return pulse; // Timeout
        }
    }

    if (pulse.end.tv_sec == 0 && pulse.end.tv_nsec == 0) {
        return pulse; // Timeout
    }

    return pulse;
}

// Calculate the distance in centimeters
double calculate_distance(pulse_t pulse) {
    if (pulse.start.tv_sec == 0 && pulse.start.tv_nsec == 0) {
        return -1.0; // Indicate timeout or error
    }

    double pulse_seconds = (pulse.end.tv_sec - pulse.start.tv_sec) +
                           (pulse.end.tv_nsec - pulse.start.tv_nsec) / 1000000000.0;

    if (pulse_seconds <= 0) {
        return -1.0; // Indicate invalid pulse width
    }

    return (pulse_seconds * SPEED_OF_SOUND) / 2.0;
}

// Log data to file
void log_data(double distance, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm, Message: %s\n", timestamp, distance, message);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Check proximity and log watering reminder
void check_proximity(double distance) {
    if (distance > 0 && distance < WATERING_THRESHOLD) {
        log_data(distance, "Time to water the plant!");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Plant watering reminder started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        pulse_t pulse = measure_pulse_width();

        // Calculate the distance
        double distance = calculate_distance(pulse);

        // Log the data
        if (distance > 0) {
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_data(distance, "OK");
                check_proximity(distance);
            } else {
                log_data(distance, "Invalid distance reading");
            }
        } else {
            log_data(-1.0, "Timeout or error");
        }

        // Wait 60 seconds
        gpioDelay(60000); // 60 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

