    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue;
    uint8_t proximity;

    // Main loop
    while (!terminate) {
        if (apds9960_read_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (apds9960_init() < 0) {
                    fprintf(stderr, "APDS9960 re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

