#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define PART_ID_REG 0x00
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25
#define EXPECTED_PART_ID 0x82
#define SAMPLE_RATE_MS 100
#define CSV_FILENAME "heartrate.csv"

// Global variables
int i2c_fd;
FILE *csv_file;
volatile sig_atomic_t running = 1;

// Function prototypes
int i2c_read_reg(int reg);
int i2c_write_reg(int reg, int value);
int init_si1182();
int read_proximity_data(uint16_t *proximity);
float calculate_bpm(uint16_t proximity);
int log_data(time_t timestamp, float bpm);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int reg) {
    int result = i2cReadByteData(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// I2C write function
int i2c_write_reg(int reg, int value) {
    int result = i2cWriteByteData(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Initialize Si1182 sensor
int init_si1182() {
    // Verify PART_ID
    int part_id = i2c_read_reg(PART_ID_REG);
    if (part_id < 0 || part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Incorrect PART_ID (0x%02X, expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    // Configure measurement rate (adjust as needed)
    if (i2c_write_reg(MEAS_RATE0_REG, 0x0A) < 0) { // Example: 100ms rate
        return -1;
    }

    // Reset and start measurement
    if (i2c_write_reg(COMMAND_REG, 0x01) < 0) { // Reset
        return -1;
    }
    gpioDelay(10); // Short delay after reset
    if (i2c_write_reg(COMMAND_REG, 0x07) < 0) { // Start
        return -1;
    }

    return 0;
}

// Read proximity data from Si1182
int read_proximity_data(uint16_t *proximity) {
    int ps0_low = i2c_read_reg(PS_DATA0_REG);
    int ps0_high = i2c_read_reg(PS_DATA1_REG);

    if (ps0_low < 0 || ps0_high < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    *proximity = (uint16_t)((ps0_high << 8) | ps0_low);
    return 0;
}

// Calculate BPM from proximity data (placeholder)
float calculate_bpm(uint16_t proximity) {
    // Simple placeholder: replace with actual BPM calculation logic
    return (float)proximity / 10.0; // Example: BPM based on proximity
}

// Log data to CSV file
int log_data(time_t timestamp, float bpm) {
    struct tm *timeinfo;
    char timestamp_str[30];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(csv_file, "%s,%.2f\n", timestamp_str, bpm);
    fflush(csv_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1182 sensor
    if (init_si1182() < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t proximity;
    time_t current_time;
    float bpm;

    while (running) {
        if (read_proximity_data(&proximity) == 0) {
            current_time = time(NULL);
            bpm = calculate_bpm(proximity);
            log_data(current_time, bpm);
        } else {
            fprintf(stderr, "Error reading proximity data, skipping sample\n");
        }

        gpioDelay(SAMPLE_RATE_MS); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_fd);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

