        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t proximity;
    time_t current_time;
    float bpm;

    while (running) {
        if (read_proximity_data(&proximity) == 0) {
