int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, int reg, int *data);
int write_sensor_data(int i2c_handle, int reg, int data);
int log_data(FILE *log_file, int proximity, int ambient);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, int reg, int *data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, reg);
        if (result >= 0) {
            *data = result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d. Retrying...\n", reg, result);
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg);
    return -1; // Failure
}

// Function to write data to the sensor
int write_sensor_data(int i2c_handle, int reg, int data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteWordData(i2c_handle, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, data 0x%04X): %d. Retrying...\n", reg, data, result);
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, data 0x%04X).\n", reg, data);
    return -1; // Failure
}

// Function to log data to a file
int log_data(FILE *log_file, int proximity, int ambient) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Proximity: %d, Ambient: %d\n", timestamp, proximity, ambient) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    int proximity, ambient;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data logging... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, PROXIMITY_REG, &proximity) == 0 &&
            read_sensor_data(i2c_handle, AMBIENT_REG, &ambient) == 0) {
            // Log data
            if (log_data(log_file, proximity, ambient) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(SLEEP_MS); // Sleep for 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

