#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x71
#define DISTANCE_MSB_REG 0x59
#define DISTANCE_LSB_REG 0x5A
#define LED_GPIO 17

// Global variables
int i2c_handle;
FILE *log_file;
int distance_threshold = 100; // Default threshold

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void log_data(int distance);
void control_led(int distance);
void signal_handler(int signal);

// Structure to hold sensor configuration (example)
typedef struct {
    int integration_time;
    int range;
} sensor_config_t;

sensor_config_t sensor_config = {0, 0}; // Initialize configuration

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        distance_threshold = atoi(argv[1]);
        printf("Distance threshold set to %d mm\n", distance_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    int distance;
    while (1) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(50); // 50 ms delay
    }

    return 0;
}

// Initialize the sensor
int initialize_sensor() {
    int who_am_i;

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }

    // Verify WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
