#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define MEASURE_COMMAND {0x50, 0x0A, 0x00, 0x01}
#define MEASURE_COMMAND_LENGTH 4
#define RESPONSE_LENGTH 15
#define HEADER_OFFSET 0
#define DISTANCE_OFFSET 11
#define INTRUSION_THRESHOLD 1000 // mm
#define LOG_FILE "intrusion_log.txt"
#define SAMPLE_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_open(const char *bus);
int i2c_ioctl(int fd, int request, int addr);
int i2c_write(int fd, const uint8_t *buf, int len);
int i2c_read(int fd, uint8_t *buf, int len);
int i2c_close(int fd);
int read_distance(int fd, int *distance);
int validate_response(const uint8_t *response);
int calculate_average_distance(const int *distances, int num_samples);
int log_intrusion(int distance);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C ioctl function
int i2c_ioctl(int fd, int request, int addr) {
    if (ioctl(fd, request, addr) < 0) {
        perror("Error performing I2C ioctl");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, const uint8_t *buf, int len) {
    ssize_t bytes_written = write(fd, buf, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *buf, int len) {
    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C bus");
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int fd, int *distance) {
    uint8_t measure_command[] = MEASURE_COMMAND;
    uint8_t response[RESPONSE_LENGTH];

    // Send measurement command
    if (i2c_write(fd, measure_command, MEASURE_COMMAND_LENGTH) < 0) {
        fprintf(stderr, "Error sending measurement command\n");
        return -1;
    }

    // Wait for at least 10 ms
    usleep(10000); // 10 ms

    // Read response
    if (i2c_read(fd, response, RESPONSE_LENGTH) < 0) {
        fprintf(stderr, "Error reading response\n");
        return -1;
    }

    // Validate response
    if (validate_response(response) < 0) {
        fprintf(stderr, "Invalid response\n");
        return -1;
    }

    // Extract distance
    *distance = (response[DISTANCE_OFFSET + 1] << 8) | response[DISTANCE_OFFSET];

    return 0;
}

// Validate response header
int validate_response(const uint8_t *response) {
    if (response[HEADER_OFFSET] != 0x50) {
        fprintf(stderr, "Invalid header: 0x%02X\n", response[HEADER_OFFSET]);
        return -1;
    }
    return 0;
}

// Calculate average distance
int calculate_average_distance(const int *distances, int num_samples) {
    long sum = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return (int)(sum / num_samples);
}

// Log intrusion event
int log_intrusion(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s - Intrusion detected! Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    int distances[10];
    int average_distance;
    int i;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (i2c_ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        i2c_close(i2c_fd);
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Sample the sensor 10 times
        for (i = 0; i < 10; i++) {
            if (read_distance(i2c_fd, &distances[i]) < 0) {
                fprintf(stderr, "Error reading distance, retrying...\n");
                i--; // Retry the sample
                usleep(10000); // Wait before retrying
            }
            usleep(SAMPLE_DELAY_MS * 1000); // Delay between samples
        }

        // Calculate average distance
        average_distance = calculate_average_distance(distances, 10);

        // Log intrusion if within range
        if (average_distance < INTRUSION_THRESHOLD) {
            log_intrusion(average_distance);
        }

        printf("Average distance: %d mm\n", average_distance);
    }

    // Close I2C bus and log file
    i2c_close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

