    if (i2c_ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        i2c_close(i2c_fd);
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Sample the sensor 10 times
        for (i = 0; i < 10; i++) {
            if (read_distance(i2c_fd, &distances[i]) < 0) {
                fprintf(stderr, "Error reading distance, retrying...\n");
                i--; // Retry the sample
                usleep(10000); // Wait before retrying
            }
            usleep(SAMPLE_DELAY_MS * 1000); // Delay between samples
        }

        // Calculate average distance
        average_distance = calculate_average_distance(distances, 10);

        // Log intrusion if within range
        if (average_distance < INTRUSION_THRESHOLD) {
            log_intrusion(average_distance);
        }

        printf("Average distance: %d mm\n", average_distance);
    }

    // Close I2C bus and log file
    i2c_close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

