// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// Expected model ID
#define VL53L0X_MODEL_ID 0xEE

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance(int handle) {
    // Start a single measurement
    if (i2c_write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Wait for the measurement to complete (or timeout)
    int timeout = 100; // Timeout after 100ms
    while (timeout > 0) {
        int interrupt_status = i2c_read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
        if (interrupt_status < 0) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }

        if (interrupt_status & 0x01) {
            break; // Measurement complete
        }

        gpioDelay(1); // Wait 1ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read the distance
    int distance_low = i2c_read_byte(handle, VL53L0X_REG_RESULT_RANGE_STATUS);
    int distance_high = i2c_read_byte(handle, VL53L0X_REG_RESULT_RANGE_STATUS + 1);

    if (distance_low < 0 || distance_high < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    int distance = (distance_high << 8) | distance_low;

    // Clear the interrupt
    if (i2c_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    int model_id = i2c_read_byte(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L0X_MODEL_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            // Get current time
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Print distance with timestamp
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

