#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SI1182_ADDR 0x39

// Define register addresses
#define REG_CONFIG 0x18
#define REG_IRQ_STATUS 0x25
#define REG_PROX_DATA_LSB 0x2A
#define REG_PROX_DATA_MSB 0x2B

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si1182 sensor
int init_si1182()
{
    // Enable proximity mode by writing 0x01 to the CONFIG register
    if (i2cWriteByteData(i2c_handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "Error writing to CONFIG register.\n");
        return -1;
    }
    return 0;
}

// Function to read proximity data from the Si1182 sensor
int read_proximity_data(unsigned short *proximity)
{
    int lsb, msb;

    // Check if data is ready by reading the IRQ_STATUS register
    lsb = i2cReadByteData(i2c_handle, REG_IRQ_STATUS);
    if (lsb < 0) {
        fprintf(stderr, "Error reading IRQ_STATUS register.\n");
        return -1;
    }

    // Check if bit 0 is set (data ready)
    if (!(lsb & 0x01)) {
        fprintf(stderr, "Data not ready.\n");
        return -1;
    }

    // Read the LSB and MSB of the proximity data
    lsb = i2cReadByteData(i2c_handle, REG_PROX_DATA_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB register.\n");
        return -1;
    }

    msb = i2cReadByteData(i2c_handle, REG_PROX_DATA_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB register.\n");
        return -1;
    }

    // Combine the LSB and MSB to form the 16-bit proximity value
    *proximity = (msb << 8) | lsb;

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (init_si1182() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        unsigned short proximity;

        // Read proximity data
        if (read_proximity_data(&proximity) == 0) {
            // Print the proximity value
            printf("Proximity: %u\n", proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data.\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500);
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

