#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define DISTANCE_REG_SIZE 2
#define CONVERSION_FACTOR 0.125

int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
}

int main() {
    uint8_t buffer[DISTANCE_REG_SIZE];
    int16_t raw_distance;
    float distance_mm;
    struct timespec sleep_time = {0, 500000000}; // 500 ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence (read a register)
    if (read(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read distance data
        if (read(i2c_fd, buffer, DISTANCE_REG_SIZE) != DISTANCE_REG_SIZE) {
            fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
            nanosleep(&sleep_time, NULL); // Retry after sleep
            continue;
        }

        // Convert to signed 16-bit integer
        raw_distance = (int16_t)((buffer[1] << 8) | buffer[0]);

        // Convert to millimetres
        distance_mm = raw_distance * CONVERSION_FACTOR;

        // Print distance
        printf("Distance: %.2f mm\n", distance_mm);

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(i2c_fd);
    return 0;
}

