#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TIMEOUT_US 200000         // microseconds (200ms)
#define MAX_DISTANCE 400          // cm (38ms is the max range of HC-SR04)

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width_us);
void log_data(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to send a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            echo_received = 1; // Indicate rising edge received
        } else if (level == 0 && echo_received == 1) {
            echo_end_tick = tick;
            echo_received = 2; // Indicate falling edge received
        }
    }
}

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width_us) {
    return (pulse_width_us * 0.0343) / 2.0;
}

// Function to log data with timestamp
void log_data(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Send trigger pulse
        trigger_pulse();

        // Wait for echo to be received with timeout
        int start_tick = gpioTick();
        while (!echo_received) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo\n");
                echo_received = 0; // Reset flag
                break;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Calculate pulse width
        int pulse_width_us = 0;
        if (echo_received == 2) {
            pulse_width_us = echo_end_tick - echo_start_tick;
            echo_received = 0; // Reset flag
        }

        // Validate pulse width
        if (pulse_width_us > 0 && pulse_width_us <= MAX_DISTANCE * 58) { // 58us per cm
            // Calculate distance
            float distance = calculate_distance(pulse_width_us);

            // Log data
            log_data(distance);
        } else {
            fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width_us);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    return 0;
}

