#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_LED 17
#define RANGE_RESOLUTION 0.0486f
#define RANGE_BINS 64
#define INTRUSION_THRESHOLD 1.0f
#define LOG_FILE "intrusion_log.csv"

// Global variables
volatile sig_atomic_t terminate = 0;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for UART configuration
typedef struct {
    int fd;
    struct termios tty;
} uart_config_t;

// Function prototypes
int uart_init(uart_config_t *config);
int uart_read_frame(uart_config_t *config, unsigned char *frame, int frame_size);
int process_range_profile(const unsigned char *frame, int *range_profile);
float calculate_distance(int range_index);
int detect_intrusion(const int *range_profile, float threshold);
void trigger_alert(int gpio_pin);
void log_intrusion(float distance);
void signal_handler(int signal);
void cleanup();

// UART initialization function
int uart_init(uart_config_t *config) {
    config->fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (config->fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    if (tcgetattr(config->fd, &config->tty) != 0) {
        perror("Error getting termios attributes");
        close(config->fd);
        return -1;
    }

    config->tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    config->tty.c_iflag = IGNPAR;
    config->tty.c_oflag = 0;
    config->tty.c_lflag = 0;
    config->tty.c_cc[VMIN] = 0;      // Non-blocking read
    config->tty.c_cc[VTIME] = 5;     // Timeout of 0.5 seconds

    if (tcsetattr(config->fd, TCSANOW, &config->tty) != 0) {
        perror("Error setting termios attributes");
        close(config->fd);
        return -1;
    }

    return 0;
}

// UART read frame function
int uart_read_frame(uart_config_t *config, unsigned char *frame, int frame_size) {
    int bytes_read = 0;
    unsigned char buffer[1];

    while (bytes_read < frame_size) {
        ssize_t result = read(config->fd, buffer, 1);
        if (result > 0) {
            frame[bytes_read++] = buffer[0];
        } else if (result < 0) {
            perror("Error reading from UART");
            return -1;
        } else {
            // Timeout or no data available
            break;
        }
    }

    return bytes_read == frame_size ? 0 : -1;
}

// Process range profile function
int process_range_profile(const unsigned char *frame, int *range_profile) {
    // Check for magic word
    unsigned char magic_word[8] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(frame, magic_word, 8) != 0) {
        fprintf(stderr, "Invalid magic word received.\n");
        return -1;
    }

    // Extract range profile data
    for (int i = 0; i < RANGE_BINS; i++) {
        range_profile[i] = (frame[8 + i * 2] & 0xFF) | ((frame[8 + i * 2 + 1] & 0xFF) << 8);
    }

    return 0;
}

// Calculate distance function
float calculate_distance(int range_index) {
    return (float)range_index * RANGE_RESOLUTION;
}

// Detect intrusion function
int detect_intrusion(const int *range_profile, float threshold) {
    for (int i = 0; i < RANGE_BINS; i++) {
        float distance = calculate_distance(i);
        if (distance <= threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Trigger alert function
void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(2000);        // Wait for 2 seconds
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Log intrusion function
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    uart_config_t uart_config;
    unsigned char frame[128];
    int range_profile[RANGE_BINS];
    int intrusion_detected;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize UART
    if (uart_init(&uart_config) != 0) {
        cleanup();
        return 1;
    }
    uart_fd = uart_config.fd;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read a frame from the UART
        if (uart_read_frame(&uart_config, frame, sizeof(frame)) == 0) {
            // Process the range profile
            if (process_range_profile(frame, range_profile) == 0) {
                // Detect intrusion
                intrusion_detected = detect_intrusion(range_profile, INTRUSION_THRESHOLD);

                if (intrusion_detected) {
                    // Trigger alert
                    trigger_alert(GPIO_LED);

                    // Log intrusion
                    for (int i = 0; i < RANGE_BINS; i++) {
                        float distance = calculate_distance(i);
                        if (distance <= INTRUSION_THRESHOLD) {
                            log_intrusion(distance);
                            break; // Log only the first detected intrusion
                        }
                    }
                }
            }
        } else {
            fprintf(stderr, "Failed to read frame. Retrying...\n");
        }

        gpioDelay(100); // Delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Intrusion detection system stopped.\n");
    return 0;
}

