#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_REGISTER_HIGH 0x31
#define DISTANCE_REGISTER_LOW 0x32
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL 100 // ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(int i2c_handle);
void log_distance(int distance);
void trigger_alert(int distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is off initially

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read distance from the sensor
int read_distance(int i2c_handle) {
    char buffer[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REGISTER_HIGH, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int distance = (buffer[0] << 8) | buffer[1];
    return distance;
}

// Log distance to file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Trigger alert if distance is below threshold
void trigger_alert(int distance) {
    if (distance < (int)(DISTANCE_THRESHOLD * 10)) { // Convert cm to mm
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        gpioDelay(1000); // 1 second
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is off
    gpioTerminate();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Starting distance measurement...\n");

    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            log_distance(distance);
            trigger_alert(distance);
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL); // Delay for 100ms
    }

    cleanup();
    return 0;
}

