#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x45
#define LED_GPIO 18
#define DISTANCE_REG 0x00 // Example register address, adjust as needed
#define DISTANCE_SCALE 0.1 // Example scaling factor, adjust as needed
#define MIN_DISTANCE 50.0  // Minimum distance in mm
#define MAX_DISTANCE 500.0 // Maximum distance in mm
#define MIN_FREQUENCY 10.0  // Minimum blink frequency in Hz
#define MAX_FREQUENCY 1.0   // Maximum blink frequency in Hz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
float map_distance_to_frequency(float distance);
void control_led(float frequency);
void log_data(float distance, float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int16_t raw_distance = (buf[0] << 8) | buf[1];
            *distance = (float)raw_distance * DISTANCE_SCALE;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Map distance to blink frequency
float map_distance_to_frequency(float distance) {
    float frequency;

    if (distance < MIN_DISTANCE) {
        frequency = MAX_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        frequency = MIN_FREQUENCY;
    } else {
        frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    return frequency;
}

// Control the LED blink frequency
void control_led(float frequency) {
    // Calculate the on-time and off-time for the PWM signal
    // The frequency is the reciprocal of the period.
    // The period is 1/frequency.
    // The duty cycle is 50% (on-time = off-time).
    // The on-time is half the period.
    // The off-time is also half the period.
