#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define LOG_FILE "proximity_log.txt"

// Structure to hold sensor state and last transition time
typedef struct {
    int gpio;
    int state;
    long long last_transition_time;
} sensor_t;

sensor_t sensor1, sensor2;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(sensor_t *sensor);
int log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

int main() {
    // Initialize sensors
    sensor1.gpio = SENSOR_1_GPIO;
    sensor1.state = gpioRead(SENSOR_1_GPIO);
    sensor1.last_transition_time = gpioTick();

    sensor2.gpio = SENSOR_2_GPIO;
    sensor2.state = gpioRead(SENSOR_2_GPIO);
    sensor2.last_transition_time = gpioTick();

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor 1
        int new_state1 = read_sensor(&sensor1);
        if (new_state1 != sensor1.state) {
            if (new_state1 == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            sensor1.state = new_state1;
        }

        // Read sensor 2
        int new_state2 = read_sensor(&sensor2);
        if (new_state2 != sensor2.state) {
            if (new_state2 == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            sensor2.state = new_state2;
        }

        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

// Initializes pigpio and sets GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    return 0;
}

// Reads sensor value with debouncing
int read_sensor(sensor_t *sensor) {
    int raw_value = gpioRead(sensor->gpio);
    long long current_time = gpioTick();

    if (raw_value != sensor->state) {
        if (current_time - sensor->last_transition_time > DEBOUNCE_MS * 1000) {
            sensor->last_transition_time = current_time;
            return raw_value;
        }
    }

    return sensor->state;
}

// Logs event to file with ISO 8601 timestamp
int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s,%d,%s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return 1;
    }
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

