int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int read_distance(int fd);
void log_data(FILE *fp, int distance_mm);
void signal_handler(int sig);

// I2C read register function
int i2c_read_register(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return buf[0];
}

// I2C write register function
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read distance function
int read_distance(int fd) {
    // Trigger measurement
    if (i2c_write_register(fd, MEAS_TRIGGER_REG, 0x01) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for data ready
    int timeout_count = 0;
    while (1) {
        int status = i2c_read_register(fd, MEAS_STATUS_REG);
        if (status < 0) {
            fprintf(stderr, "Error reading measurement status\n");
            return -1;
        }

        if (status & DATA_READY_BIT) {
            break;
        }

        usleep(1000); // 1 ms
        timeout_count++;
        if (timeout_count > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            return -1;
        }
    }

    // Read distance
    int dist_high = i2c_read_register(fd, DIST_HIGH_REG);
    int dist_low = i2c_read_register(fd, DIST_LOW_REG);

    if (dist_high < 0 || dist_low < 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    return (dist_high << 8) | dist_low;
}

