    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            log_data(csv_file, distance);
        } else {
            fprintf(stderr, "Error reading distance, skipping sample\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for SAMPLE_INTERVAL_MS
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

