// Define the I2C address of the VL53L5CX sensor
#define VL53L5CX_ADDR 0x29

// Define the number of zones in the grid
#define NUM_ZONES 64

// Define the I2C bus number
#define I2C_BUS 1

// Define the I2C device file path
#define I2C_DEV_PATH "/dev/i2c-1"

// Define the register addresses for the VL53L5CX sensor
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L5CX_REG_SYSTEM_START 0x000D
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_SPAD_NB_DETECTED 0x0022
#define VL53L5CX_REG_RESULT_DISTANCE 0x001E

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint16_t reg, uint8_t *value) {
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write (address) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_vl53l5cx(int fd) {
    uint8_t model_id, revision_id;

    // Check the sensor ID
    if (i2c_read_byte(fd, VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (i2c_read_byte(fd, VL53L5CX_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    printf("VL53L5CX Model ID: 0x%02X\n", model_id);
    printf("VL53L5CX Revision ID: 0x%02X\n", revision_id);

    // Start the sensor (example configuration - adjust as needed)
    if (i2c_write_byte(fd, VL53L5CX_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error starting sensor\n");
        return -1;
    }

    // Add more initialization steps here as needed for your specific application

    return 0;
}

// Function to read distance data from the VL53L5CX sensor
int read_distance_data(int fd, uint16_t zone_index, uint16_t *distance) {
    uint8_t range_status;
    uint8_t spad_count;

    // Read range status
    if (i2c_read_byte(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read SPAD count
    if (i2c_read_byte(fd, VL53L5CX_REG_RESULT_SPAD_NB_DETECTED, &spad_count) != 0) {
        fprintf(stderr, "Error reading SPAD count\n");
        return -1;
    }

    // Read distance
    uint8_t distance_msb, distance_lsb;
    if (i2c_read_byte(fd, VL53L5CX_REG_RESULT_DISTANCE, &distance_msb) != 0) {
        fprintf(stderr, "Error reading distance MSB\n");
        return -1;
    }
    if (i2c_read_byte(fd, VL53L5CX_REG_RESULT_DISTANCE + 1, &distance_lsb) != 0) {
        fprintf(stderr, "Error reading distance LSB\n");
        return -1;
    }

    *distance = (uint16_t)((distance_msb << 8) | distance_lsb);

    return 0;
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the I2C device file
    i2c_fd = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the I2C slave address for the sensor
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the VL53L5CX sensor
    if (init_vl53l5cx(i2c_fd) != 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read distance data from the sensor
    while (1) {
        uint16_t distances[NUM_ZONES];
        int i;

        // Read distance data for each zone
        for (i = 0; i < NUM_ZONES; i++) {
            if (read_distance_data(i2c_fd, i, &distances[i]) != 0) {
                fprintf(stderr, "Error reading distance data for zone %d\n", i);
                // Attempt to re-initialize the sensor
                if (init_vl53l5cx(i2c_fd) != 0) {
                    fprintf(stderr, "VL53L5CX re-initialization failed\n");
                    // If re-initialization fails, exit the program
                    close(i2c_fd);
                    return 1;
                }
            }
        }

        // Print the distance data for each zone
        for (i = 0; i < NUM_ZONES; i++) {
            printf("Zone %d: %d mm\n", i, distances[i]);
        }

        // Wait for 500 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500 * 1000 * 1000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach this point due to the infinite loop
    return 0;
}

