#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance reading (adjust as needed)
#define DISTANCE_REG 0x00

// Global variables for graceful shutdown
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle) {
    int retries = 3;
    int distance = -1;

    while (retries > 0) {
        distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (distance >= 0) {
            // Success, break out of the retry loop
            break;
        } else {
            fprintf(stderr, "I2C read failed, retrying... (%d retries left)\n", retries);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    if (distance < 0) {
        fprintf(stderr, "I2C read failed after multiple retries.\n");
        return -1; // Indicate failure
    }

    return distance;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
