// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// Register addresses
#define REG_SOFT_RESET 0x7FFF
#define REG_START_RANGING 0x0009
#define REG_INTERRUPT_STATUS 0x0046
#define REG_DISTANCE_HIGH 0x0096
#define REG_DISTANCE_LOW 0x0097

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(uint16_t *distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...");
    terminate = 1;
}

// Initialize the VL53L4CX sensor
int init_sensor() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    // Start ranging
    if (i2cWriteByteData(i2c_handle, REG_START_RANGING, 0x01) < 0) {
        fprintf(stderr, "Error: Start ranging failed\n");
        return -1;
    }

    return 0;
}

// Read distance data from the sensor
int read_distance(uint16_t *distance) {
    int high_byte, low_byte;

    high_byte = i2cReadByteData(i2c_handle, REG_DISTANCE_HIGH);
    if (high_byte < 0) {
        fprintf(stderr, "Error: Failed to read high byte\n");
        return -1;
    }

    low_byte = i2cReadByteData(i2c_handle, REG_DISTANCE_LOW);
    if (low_byte < 0) {
        fprintf(stderr, "Error: Failed to read low byte\n");
        return -1;
    }

    *distance = (uint16_t)((high_byte << 8) | low_byte);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;
    struct timespec ts;
    char timestamp[30];

    // Main loop
    while (!terminate) {
        // Poll interrupt status
        int interrupt_status = i2cReadByteData(i2c_handle, REG_INTERRUPT_STATUS);
        if (interrupt_status < 0) {
            fprintf(stderr, "Error: Failed to read interrupt status\n");
            continue; // Continue to the next cycle
        }

        if (interrupt_status & 0x01) {
            // Read distance
            if (read_distance(&distance) == 0) {
                // Get timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    // Format timestamp
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

                    // Log distance
                    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
                } else {
                    fprintf(stderr, "Error: Failed to get timestamp\n");
                }
            } else {
                fprintf(stderr, "Error: Failed to read distance\n");
            }
        } else {
            // Interrupt not set, skip cycle
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

