int vl53l1x_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Set I2C slave address
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: I2C slave address setting failed\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Continuous ranging start failed\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle) {
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM);
    if (distance < 0) {
        fprintf(stderr, "Error: Distance read failed\n");
        return -1;
    }
    return distance;
}

