            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C open failed after re-initialization\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (vl53l1x_init(i2c_handle) < 0) {
                    fprintf(stderr, "Error: VL53L1X initialisation failed after re-initialization\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(500); // Trigger distance readings every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    buzzer_off(BUZZER_PIN);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

