#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/msg.h>
#include <sys/ipc.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_KEY 1234

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SOFTWARE_RESET 0x0000
#define VL53L1X_REG_TIMING_BUDGET 0x008E
#define VL53L1X_REG_START_RANGING 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Message structure for message queue
struct msgbuf {
    long mtype;
    int distance;
};

// Global variables
int i2c_handle;
int msg_queue_id;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void buzzer_control(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Check sensor model ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }
    printf("VL53L1X model ID: 0x%02X\n", model_id);

    // Software reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFTWARE_RESET, 0x01) < 0) {
        fprintf(stderr, "Error writing software reset: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFTWARE_RESET, 0x00) < 0) {
        fprintf(stderr, "Error writing software reset: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set timing budget (50ms)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_TIMING_BUDGET, 0x32) < 0) {
        fprintf(stderr, "Error writing timing budget: %d\n", i2c_handle);
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_RANGING, 0x01) < 0) {
        fprintf(stderr, "Error writing start ranging: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int *distance) {
    // Poll data-ready bit
    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", range_status);
        return -1;
    }

    if (!(range_status & 0x01)) {
        // Data not ready yet
        return -1;
    }

    // Read distance
    int distance_low = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    int distance_high = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);

    if (distance_low < 0 || distance_high < 0) {
        fprintf(stderr, "Error reading distance: %d %d\n", distance_low, distance_high);
        return -1;
    }

    *distance = (distance_high << 8) | distance_low;

    return 0;
}

// Buzzer control function
void buzzer_control(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Create message queue
    msg_queue_id = msgget(MESSAGE_QUEUE_KEY, IPC_CREAT | 0666);
    if (msg_queue_id < 0) {
        perror("msgget");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int distance;
    struct msgbuf message;
    message.mtype = 1; // Message type

    while (!terminate) {
        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            // Send distance to message queue
            message.distance = distance;
            if (msgsnd(msg_queue_id, &message, sizeof(int), 0) == -1) {
                perror("msgsnd");
            }

            // Control buzzer
            buzzer_control(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
    msgctl(msg_queue_id, IPC_RMID, NULL);

    return 0;
}

