#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define BUZZER_DURATION 500000 // 0.5 seconds

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, unsigned int tick);
float calculateDistance(unsigned int pulse_width);
void controlBuzzer(float distance);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echoCallback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that echo started
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Indicate that echo ended
    }
}

// Function to calculate distance from pulse width
float calculateDistance(unsigned int pulse_width) {
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
    return distance;
}

// Function to control the buzzer
void controlBuzzer(float distance) {
    if (distance < 30.0) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
        gpioDelay(BUZZER_DURATION);
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Register callback function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Wait for echo or timeout
        int count = 0;
        while (!echo_received && count < TIMEOUT_US) {
            gpioDelay(1); // Wait 1 microsecond
            count++;
        }

        // Calculate pulse width
        unsigned int pulse_width;
        if (echo_received) {
            pulse_width = end_tick - start_tick;
        } else {
            fprintf(stderr, "Timeout: No echo received\n");
            pulse_width = 0; // Indicate timeout
        }

        // Calculate distance
        float distance = calculateDistance(pulse_width);

        // Validate distance
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
        } else {
            // Control the buzzer
            controlBuzzer(distance);

            // Print distance
            printf("Distance: %.2f cm\n", distance);
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    return 0;
}

