        echo_received = 1; // Indicate that echo started
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0; // Indicate that echo ended
    }
}

// Function to calculate distance from pulse width
float calculateDistance(unsigned int pulse_width) {
    float distance = (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
    return distance;
}

// Function to control the buzzer
void controlBuzzer(float distance) {
    if (distance < 30.0) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
        gpioDelay(BUZZER_DURATION);
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

