    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Register callback function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Wait for echo or timeout
        int count = 0;
        while (!echo_received && count < TIMEOUT_US) {
            gpioDelay(1); // Wait 1 microsecond
            count++;
        }

        // Calculate pulse width
        unsigned int pulse_width;
        if (echo_received) {
            pulse_width = end_tick - start_tick;
        } else {
            fprintf(stderr, "Timeout: No echo received\n");
            pulse_width = 0; // Indicate timeout
        }

        // Calculate distance
        float distance = calculateDistance(pulse_width);

        // Validate distance
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
