#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define MIN_PULSE_WIDTH 100   // us
#define MAX_PULSE_WIDTH 30000 // us
#define TIMEOUT_MS 60         // ms

// Global variables
FILE *log_file = NULL;
volatile int rising_edge_tick = 0;
volatile int falling_edge_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_data(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        rising_edge_tick = tick;
        echo_received = 1; // Indicate rising edge received
    } else if (level == 0) {
        falling_edge_tick = tick;
        echo_received = 2; // Indicate falling edge received
    }
}

// Function to calculate distance from pulse width
double calculate_distance(int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to log data to file and stdout
void log_data(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance < 0) {
        fprintf(stderr, "Error: Invalid distance value (%.2f cm).\n", distance);
        fprintf(log_file, "%s,ERROR,Invalid distance value (%.2f cm)\n", timestamp, distance);
    } else {
        fprintf(stdout, "%s,%.2f\n", timestamp, distance);
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    }
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        echo_received = 0; // Reset flag
        rising_edge_tick = 0;
        falling_edge_tick = 0;

        trigger_sensor();

        // Wait for echo or timeout
        int start_time = gpioTick();
        while (echo_received == 0) {
            if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
                fprintf(stderr, "Timeout waiting for echo!\n");
                fprintf(log_file, "%s,TIMEOUT\n", __TIME__);
                log_data(-1.0); // Log timeout
                break;
            }
            gpioDelay(10); // Small delay to prevent busy-waiting
        }

        if (echo_received == 2) {
            int pulse_width = falling_edge_tick - rising_edge_tick;

            // Validate pulse width
            if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width);
                fprintf(log_file, "%s,INVALID_PULSE_WIDTH,%d\n", __TIME__, pulse_width);
                log_data(-1.0); // Log invalid pulse width
            } else {
                double distance = calculate_distance(pulse_width);
                log_data(distance);
            }
        }

        gpioDelay(200); // 200 ms delay
    }

    return 0;
}

