  // Set GPIO modes
  gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
  gpioSetMode(INTERRUPT_PIN, PI_INPUT);
  gpioSetMode(SERVO_PIN, PI_OUTPUT);

  // Set PWM frequency (adjust as needed)
