int init_vl53l1x();
int read_distance();
void control_motor(int distance);
void isr_trigger(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
void log_message(const char *message);

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x()
{
    // Soft reset
    if (write_register(i2c_handle, 0x0000, 0x00) != 0) {
        log_message("VL53L1X soft reset failed");
        return -1;
    }
    gpioDelay(1); // Wait 1 ms

    // Check sensor ID (optional)
    uint8_t sensor_id;
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id) != 0) {
        log_message("VL53L1X ID read failed");
        return -1;
    }
    if (sensor_id != 0xEA) {
        fprintf(stderr, "VL53L1X sensor ID mismatch: 0x%02X\n", sensor_id);
        return -1;
    }

    // Configure for short-range mode (example)
    // This is a simplified example.  Refer to the VL53L1X datasheet
    // for the full configuration sequence.
    if (write_register(i2c_handle, 0x002d, 0x04) != 0) { // set signal rate limit
        log_message("VL53L1X signal rate limit failed");
        return -1;
    }
    if (write_register(i2c_handle, 0x002e, 0x01) != 0) { // set sigma threshold
        log_message("VL53L1X sigma threshold failed");
        return -1;
    }
    if (write_register(i2c_handle, 0x002f, 0x00) != 0) { // set VHV settings
        log_message("VL53L1X VHV settings failed");
        return -1;
    }
    if (write_register(i2c_handle, 0x0030, 0x00) != 0) { // set ALS period
        log_message("VL53L1X ALS period failed");
        return -1;
    }
    if (write_register(i2c_handle, 0x0088, 0x00) != 0) { // set intermeasurement period
        log_message("VL53L1X intermeasurement period failed");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance()
{
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;
    int distance_mm;

    // Start measurement
    if (write_register(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        log_message("VL53L1X start measurement failed");
        return -1;
    }

    // Wait for data ready (polling with timeout)
    int timeout = 100; // 100ms timeout
    while (timeout > 0) {
        if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
            log_message("VL53L1X read range status failed");
            return -1;
        }
        if (range_status & 0x01) {
            break; // Data ready
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        log_message("VL53L1X data not ready");
        return -1;
    }

    // Read distance
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_msb) != 0) {
        log_message("VL53L1X read distance MSB failed");
        return -1;
    }
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &distance_lsb) != 0) {
        log_message("VL53L1X read distance LSB failed");
        return -1;
    }

    distance_mm = (distance_msb << 8) | distance_lsb;

    return distance_mm;
}

// Function to control the DC motor based on the distance
void control_motor(int distance)
{
    if (distance < DISTANCE_THRESHOLD_FORWARD) {
        if (motor_state != MOTOR_FORWARD) {
