int gpio_set_output(struct gpiod_line *line, int value);
int gpio_set_outputs(struct gpiod_line **lines, int *values, int num_pins);
int map_touch_to_led_pattern(uint16_t touch_status);
void log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (i2c_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0) {
        log_event("MPR121 soft reset failed");
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    // Verify sensor presence (read a register)
    uint8_t sensor_id;
    if (i2c_read_reg(fd, MPR121_ELECONFIG0, &sensor_id) < 0) {
        log_event("MPR121 verification failed");
        return -1;
    }
    if (sensor_id != 0x5A) {
        log_event("MPR121 not found");
        return -1;
    }

    // Stop mode
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x00) < 0) {
        log_event("MPR121 stop mode failed");
        return -1;
    }

    // Baseline filtering
    if (i2c_write_reg(fd, 0x5B, 0x01) < 0) {
        log_event("MPR121 MHDR failed");
        return -1;
    }
    if (i2c_write_reg(fd, 0x5C, 0x01) < 0) {
        log_event("MPR121 NHDR failed");
        return -1;
    }
    if (i2c_write_reg(fd, 0x5D, 0x0E) < 0) {
        log_event("MPR121 NCLR failed");
        return -1;
    }
    if (i2c_write_reg(fd, 0x5E, 0x00) < 0) {
        log_event("MPR121 FDLR failed");
        return -1;
    }

    // Auto-configuration thresholds
    if (i2c_write_reg(fd, 0x5A, 0x0B) < 0) {
        log_event("MPR121 ELE_THRESH failed");
        return -1;
    }
    if (i2c_write_reg(fd, 0x5D, 0xC8) < 0) {
        log_event("MPR121 ELE_THRESH failed");
        return -1;
    }
    if (i2c_write_reg(fd, 0x5E, 0x82) < 0) {
        log_event("MPR121 ELE_THRESH failed");
        return -1;
    }
    if (i2c_write_reg(fd, 0x5F, 0xB4) < 0) {
        log_event("MPR121 ELE_THRESH failed");
        return -1;
    }

    // Enable electrodes
    if (i2c_write_reg(fd, MPR121_ELECONFIG0, 0x0C) < 0) {
        log_event("MPR121 enable electrodes failed");
        return -1;
    }

    log_event("MPR121 initialized successfully");
    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd, uint16_t *touch_status) {
    uint8_t touch_status_l, touch_status_h;

    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_L, &touch_status_l) < 0) {
        log_event("MPR121 read touch status L failed");
        return -1;
    }
    if (i2c_read_reg(fd, MPR121_TOUCHSTATUS_H, &touch_status_h) < 0) {
        log_event("MPR121 read touch status H failed");
        return -1;
    }

    *touch_status = (touch_status_h << 8) | touch_status_l;
    return 0;
}

// GPIO set output function
int gpio_set_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("GPIO set value failed");
        return -1;
    }
    return 0;
}

// GPIO set outputs function
int gpio_set_outputs(struct gpiod_line **lines, int *values, int num_pins) {
    for (int i = 0; i < num_pins; i++) {
        if (gpio_set_output(lines[i], values[i]) < 0) {
            return -1;
        }
    }
    return 0;
}

// Map touch status to LED pattern function
int map_touch_to_led_pattern(uint16_t touch_status) {
    int pattern = 0;
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (touch_status & (1 << i)) {
            pattern |= (1 << i);
        }
    }
    return pattern;
}

// Log event function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    log_event("Signal received, cleaning up...");
}

// Cleanup function
void cleanup() {
    log_event("Cleaning up resources...");

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
        log_event("I2C device closed");
    }

    // Release GPIO lines
    if (gpio_lines != NULL) {
        for (int i = 0; i < sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]); i++) {
            if (gpio_lines[i]) {
                gpiod_line_release(gpio_lines[i]);
                log_event("GPIO line released");
            }
        }
        gpiod_chip_close(gpio_chip);
        log_event("GPIO chip closed");
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        log_event("Log file closed");
    }

    exit(0);
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }
    log_event("Program started");

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        log_event("Failed to open I2C device");
        cleanup();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        log_event("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        log_event("MPR121 initialization failed");
        cleanup();
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        log_event("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    // Get GPIO lines
    gpio_lines = malloc(sizeof(struct gpiod_line *) * sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]));
    if (!gpio_lines) {
        perror("Failed to allocate memory for GPIO lines");
        log_event("Failed to allocate memory for GPIO lines");
        cleanup();
        return 1;
    }

    for (int i = 0; i < sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]); i++) {
        gpio_lines[i] = gpiod_chip_get_line(gpio_chip, GPIO_PINS[i]);
        if (!gpio_lines[i]) {
            perror("Failed to get GPIO line");
            log_event("Failed to get GPIO line");
            cleanup();
            return 1;
        }

        if (gpiod_line_request_output(gpio_lines[i], "proximity_art", 0) < 0) {
            perror("Failed to request GPIO line as output");
            log_event("Failed to request GPIO line as output");
            cleanup();
            return 1;
        }
    }

    // Main loop
    uint16_t touch_status;
    int led_pattern;
    int gpio_values[sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0])];

    while (!terminate) {
        // Read touch status
        if (mpr121_read_touch_status(i2c_fd, &touch_status) < 0) {
            log_event("Failed to read touch status");
            usleep(POLLING_INTERVAL_MS * 1000); // Sleep even on error
            continue;
        }

        // Map touch status to LED pattern
        led_pattern = map_touch_to_led_pattern(touch_status);

        // Set GPIO outputs
        for (int i = 0; i < sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0]); i++) {
            gpio_values[i] = (led_pattern >> i) & 1;
        }

        if (gpio_set_outputs(gpio_lines, gpio_values, sizeof(GPIO_PINS) / sizeof(GPIO_PINS[0])) < 0) {
            log_event("Failed to set GPIO outputs");
        }

        // Log event
        if (touch_status == 0) {
            log_event("No electrode active");
        } else {
            char log_message[256];
            snprintf(log_message, sizeof(log_message), "Touch status: 0x%04X, LED pattern: 0x%04X", touch_status, led_pattern);
            log_event(log_message);
        }

        usleep(POLLING_INTERVAL_MS * 1000); // Sleep for polling interval
    }

    cleanup();
    return 0;
}

