#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define ELECTRODE_TO_MONITOR 0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_mpr121_register(int reg);
int write_mpr121_register(int reg, int value);
int is_proximity_detected();
void control_led(int state);
void log_proximity_event();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the MPR121 sensor
int initialize_mpr121() {
    // Verify device ID
    int device_id = read_mpr121_register(0x5F);
    if (device_id != 0x5A) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }

    // Stop mode
    if (write_mpr121_register(0x80, 0x63) < 0) return -1;
    gpioDelay(10000); // 10ms

    // Configure Electrode 0
    if (write_mpr121_register(0x41, TOUCH_THRESHOLD) < 0) return -1;
    if (write_mpr121_register(0x42, RELEASE_THRESHOLD) < 0) return -1;

    // Enter Run mode
    if (write_mpr121_register(0x80, 0x10) < 0) return -1;
    gpioDelay(10000); // 10ms

    return 0;
}

// Function to read a register from the MPR121
int read_mpr121_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a register to the MPR121
int write_mpr121_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%X with value 0x%X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to check if proximity is detected on electrode 0
int is_proximity_detected() {
    int touch_status = read_mpr121_register(0x00);
    if (touch_status < 0) return 0; // Return 0 on error
    return (touch_status & (1 << ELECTRODE_TO_MONITOR));
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Function to log proximity events
void log_proximity_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("proximity.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening proximity.log for writing\n");
        return;
    }

    fprintf(fp, "%s: Proximity detected on electrode %d\n", timestamp, ELECTRODE_TO_MONITOR);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Proximity detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (is_proximity_detected()) {
            control_led(1); // Turn on LED
            log_proximity_event();
            gpioDelay(1000000); // Wait for 1 second
            control_led(0); // Turn off LED
        }
        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Proximity detection stopped.\n");
    return 0;
}

