#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_DURATION 30    // ms
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

// Function prototypes
int initialize_gpio();
int trigger_sensor();
int read_echo();
double calculate_distance(long pulse_width);
int log_distance(double distance);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        printf("Caught SIGINT, exiting...\n");
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
int trigger_sensor() {
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return -1;
    }
    usleep(5); // 5 us

    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return -1;
    }
    usleep(TRIGGER_PULSE_DURATION); // 10 us

    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return -1;
    }

    return 0;
}

// Read the echo pulse width
int read_echo() {
    struct timespec start, end;
    int timeout_count = 0;

    // Wait for rising edge
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        timeout_count++;
        if (timeout_count > TIMEOUT_DURATION * 1000) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }
        usleep(1); // Check every 1 us
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    timeout_count = 0;

    // Wait for falling edge
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        timeout_count++;
        if (timeout_count > TIMEOUT_DURATION * 1000) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
        usleep(1); // Check every 1 us
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    long pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    return pulse_width;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // cm
}

// Log the distance to a file
int log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        fprintf(log_file, "%s ERROR: Distance out of range: %.2f cm\n", timestamp, distance);
    } else {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
    }

    fflush(log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");

    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

