#define TRIGGER_PULSE_DURATION 10 // microseconds
#define MAX_PULSE_WIDTH 25000 // microseconds (25ms)
#define MIN_PULSE_WIDTH 58 // microseconds

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt service routine (ISR) for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that echo started
    } else if (level == 0) {
        if (echo_received) {
            echo_end_tick = tick;
            echo_received = 0; // Reset flag
        }
    }
}

// Function to calculate distance in meters
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0;
}

// Function to log distance to file
