    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Disable interrupt handler
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for echo pin
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback);

    // Main loop
    while (running) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for a short period to allow the sensor to settle
        gpioDelay(50); // 50ms

        // Calculate pulse width
        int pulse_width = echo_end_tick - echo_start_tick;

        // Validate pulse width
        if (pulse_width > 0 && pulse_width < MAX_PULSE_WIDTH) {
            // Calculate distance
            double distance = calculate_distance(pulse_width);

            // Log distance
            log_distance(distance);

            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid pulse width: %d us\n", pulse_width);
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000ms = 1 second
    }

    return 0;
}

