#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_GPIO 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define CONTINUOUS_MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance, int *status);
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Configure continuous mode
    if (i2cWriteByteData(i2c_handle, CONTINUOUS_MODE_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to continuous mode register");
        return -1;
    }

    // Configure timeout
    if (i2cWriteByteData(i2c_handle, TIMEOUT_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to timeout register");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to start ranging register");
        return -1;
    }

    return 0;
}

// Read distance and status from VL53L1X
int read_distance(int *distance, int *status) {
    char buffer[3]; // Buffer for distance and status

    // Read 3 bytes from the sensor (distance and status)
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 3) != 3) {
        syslog(LOG_ERR, "Failed to read distance and status");
        return -1;
    }

    // Extract distance and status from the buffer
    *distance = (buffer[0] << 8) | buffer[1];
    *status = buffer[2];

    return 0;
}

// Log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s - Distance: %d mm, Status: 0x%02X", timestamp, distance, status);
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO27 as output and high
    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioWrite(TRIGGER_GPIO, 1); // Set high initially

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    int distance, status;
    while (!terminate) {
        if (read_distance(&distance, &status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance and status");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

