#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0     // cm
#define MIN_DISTANCE 2.0       // cm
#define SERVO_MIN_PULSE_WIDTH 500 // us
#define SERVO_MAX_PULSE_WIDTH 2500 // us
#define SERVO_CENTER_ANGLE 90.0  // degrees
#define SERVO_CENTER_PULSE_WIDTH (SERVO_MIN_PULSE_WIDTH + (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) * (SERVO_CENTER_ANGLE / 180.0))
#define TIMEOUT_US 30000         // 30 ms
#define SAMPLE_SIZE 5
#define LOG_FILE "distance_log.csv"

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_valid = 0;
volatile int echo_timeout = 0;

FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
double calculateDistance(int pulse_width);
double movingAverage(double new_value);
double logMap(double distance);
int setServoAngle(double angle);
void signalHandler(int signal);
int initializeGPIO();
int openLogFile();
void closeLogFile();

// Moving average filter buffer
double distance_buffer[SAMPLE_SIZE];
int buffer_index = 0;
double sum = 0.0;

int main() {
    // Initialize pigpio
    if (initializeGPIO() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    if (openLogFile() != 0) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signalHandler);

    // Main loop
    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us

        // Reset echo variables
        echo_start_tick = 0;
        echo_end_tick = 0;
        echo_valid = 0;
        echo_timeout = 0;

        // Wait for echo to be valid or timeout
        int timeout_count = 0;
        while (!echo_valid && timeout_count < 100) {
            gpioDelay(1000); // Check every 1 ms
            timeout_count++;
        }

        // Calculate pulse width
        int pulse_width;
        if (echo_valid) {
            pulse_width = echo_end_tick - echo_start_tick;
        } else {
            pulse_width = -1; // Indicate timeout or invalid reading
        }

        // Calculate distance
        double distance = calculateDistance(pulse_width);

        // Apply moving average filter
        double filtered_distance = movingAverage(distance);

        // Map distance to servo angle
        double angle = logMap(filtered_distance);

        // Set servo angle
        int servo_result = setServoAngle(angle);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to file
        if (log_file != NULL) {
            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, filtered_distance, angle);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }
    }

    return 0;
}

// Initialize pigpio
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency for servo control
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz
    gpioSetPWMrange(SERVO_PIN, 20000); // Set PWM range for 20ms period

    return 0;
}

// Open log file
int openLogFile() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance(cm),ServoAngle(degrees)\n");
    }

    return 0;
}

// Close log file
void closeLogFile() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
        } else if (level == 0) {
            echo_end_tick = tick;
            if (echo_end_tick < echo_start_tick) {
                // Handle tick counter wrap-around
                echo_end_tick += 0x100000000; // Add 2^32 to handle wrap-around
            }
            echo_valid = 1;
        }
    }
}

// Calculate distance from pulse width
double calculateDistance(int pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate timeout or invalid reading
    }

    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate out-of-range reading
    }

    return distance;
}

// Moving average filter
double movingAverage(double new_value) {
    sum -= distance_buffer[buffer_index];
    distance_buffer[buffer_index] = new_value;
    sum += new_value;
    buffer_index = (buffer_index + 1) % SAMPLE_SIZE;
    return sum / SAMPLE_SIZE;
}

// Non-linear mapping to servo angle
double logMap(double distance) {
    if (distance < 0) {
        return SERVO_CENTER_ANGLE; // Default to center if invalid distance
    }

    // Use a logarithmic mapping to map distance to angle
    double angle = SERVO_CENTER_ANGLE - (log10(distance) - log10(MIN_DISTANCE)) / (log10(MAX_DISTANCE) - log10(MIN_DISTANCE)) * 180.0;

    // Clamp the angle to the valid range
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    return angle;
}

// Set servo angle
int setServoAngle(double angle) {
    // Convert angle to pulse width
    double pulse_width = SERVO_MIN_PULSE_WIDTH + (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) * (angle / 180.0);

    // Set servo pulse width
    int result = gpioServo(SERVO_PIN, pulse_width);

    if (result != 0) {
        fprintf(stderr, "Error setting servo angle: %d\n", result);
        return result;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop the servo
    gpioServo(SERVO_PIN, 0); // Disable PWM

    // Close the log file
    closeLogFile();

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

