#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables (minimize usage)
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile int running = 1;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int gpio_pin = DEFAULT_GPIO_PIN;

// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Structure to hold sensor data
typedef struct {
    int proximity;
    time_t timestamp;
} sensor_data_t;

// Queue structure
typedef struct {
    sensor_data_t data[10]; // Fixed-size queue
    int head;
    int tail;
    int count;
} queue_t;

queue_t queue;

// Function prototypes
int init_i2c(int address);
int init_gpio(int pin);
int read_proximity(int handle);
void log_data(int proximity, int status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void *main_loop(void *arg);
void signal_handler(int signal);
void queue_init(queue_t *q);
int queue_is_empty(queue_t *q);
int queue_is_full(queue_t *q);
int queue_enqueue(queue_t *q, sensor_data_t data);
int queue_dequeue(queue_t *q, sensor_data_t *data);

// Initialize the queue
void queue_init(queue_t *q) {
    q->head = 0;
    q->tail = 0;
    q->count = 0;
}

// Check if the queue is empty
int queue_is_empty(queue_t *q) {
    return q->count == 0;
}

// Check if the queue is full
int queue_is_full(queue_t *q) {
    return q->count == 10;
}

// Enqueue data into the queue
int queue_enqueue(queue_t *q, sensor_data_t data) {
    if (queue_is_full(q)) {
        fprintf(stderr, "Error: Queue is full\n");
        return -1;
    }
    q->data[q->tail] = data;
    q->tail = (q->tail + 1) % 10;
    q->count++;
    return 0;
}

// Dequeue data from the queue
int queue_dequeue(queue_t *q, sensor_data_t *data) {
    if (queue_is_empty(q)) {
        fprintf(stderr, "Error: Queue is empty\n");
        return -1;
    }
    *data = q->data[q->head];
    q->head = (q->head + 1) % 10;
    q->count--;
    return 0;
}

// Initialize I2C
int init_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Initialize GPIO
int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Could not set GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Could not set pull-down resistor\n");
        return -1;
    }
    if (gpioSetISRFuncEx(pin, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Could not set ISR function\n");
        return -1;
    }
    return 0;
}

// Read proximity value from Si1102
int read_proximity(int handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, 0x08, buf, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error: Could not read proximity data: %d\n", result);
        return -1;
    }
    return (buf[0] << 8) | buf[1]; // Combine high and low bytes
}

// Log data to file
void log_data(int proximity, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status == 'A' ? "ALERT" : "SAFE");
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
    pthread_mutex_unlock(&mutex);
}

// Interrupt handler
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    int proximity = read_proximity(i2c_handle);
    if (proximity < 0) {
        fprintf(stderr, "Error: Could not read proximity in interrupt handler\n");
        return;
    }

    sensor_data_t data;
    data.proximity = proximity;
    data.timestamp = time(NULL);

    queue_enqueue(&queue, data);
}

// Main loop (runs in a separate thread)
void *main_loop(void *arg) {
    (void)arg; // unused
    sensor_data_t data;

    while (running) {
        if (!queue_is_empty(&queue)) {
            if (queue_dequeue(&queue, &data) == 0) {
                char status = (data.proximity > threshold) ? 'A' : 'S';
                log_data(data.proximity, status);
            }
        }
        gpioDelay(100); // Check every 100ms
    }
    return NULL;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // unused
    running = 0;
    printf("Exiting...\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:g:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            case 'g':
                gpio_pin = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold] [-g gpio_pin]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(gpio_pin) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize queue
    queue_init(&queue);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create a thread for the main loop
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, main_loop, NULL) != 0) {
        fprintf(stderr, "Error: Could not create thread\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for the thread to finish (which it won't, unless running is set to 0)
    pthread_join(thread_id, NULL);

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

