#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 200000      // 200 ms

// Global variables
volatile int echo_start = 0;
volatile int echo_end = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
double getDistance();
double calculateFrequency(double distance);
void setSpeakerFrequency(double frequency);
void signalHandler(int signal);

// Callback function for echo pin
void echoCallback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1) // Rising edge
        {
            echo_start = tick;
            echo_received = 0; // Reset echo_received flag
        }
        else if (level == 0) // Falling edge
        {
            echo_end = tick;
            echo_received = 1; // Set echo_received flag
        }
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
double getDistance()
{
    echo_start = 0;
    echo_end = 0;
    echo_received = 0;

    triggerSensor();

    // Wait for echo or timeout
    int start_time = gpioTick();
    while (!echo_received)
    {
        if (gpioTick() - start_time > TIMEOUT_US)
        {
            fprintf(stderr, "Error: Timeout waiting for echo.\n");
            return -1.0; // Indicate timeout error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (echo_start == 0 || echo_end == 0) {
        fprintf(stderr, "Error: Invalid echo start or end time.\n");
        return -1.0;
    }

    double pulse_duration = (double)(echo_end - echo_start);
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2

    return distance;
}

// Function to calculate the frequency based on the distance
double calculateFrequency(double distance)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE)
    {
        fprintf(stderr, "Error: Distance out of range (%f cm). Using previous frequency.\n", distance);
        return -1.0; // Indicate out-of-range error
    }

    double frequency = 200.0 * exp(distance / 50.0);
    return frequency;
}

// Function to set the speaker frequency using pigpio's hardware-timed PWM
void setSpeakerFrequency(double frequency)
{
    if (frequency < 0)
    {
        fprintf(stderr, "Error: Invalid frequency (%f Hz).\n", frequency);
        return;
    }

    // Calculate the period in microseconds
    double period_us = 1000000.0 / frequency;

    // Calculate the duty cycle (50%)
    double duty_cycle = 0.5;

    // Calculate the on and off times in microseconds
    int on_time_us = (int)(period_us * duty_cycle);
    int off_time_us = (int)(period_us * (1.0 - duty_cycle));

    // Create a waveform
    gpioWaveClear();

    gpioPulse_t pulse[2];

    pulse[0].gpioOn = (1 << SPEAKER_PIN);
    pulse[0].gpioOff = 0;
    pulse[0].usDelay = on_time_us;

    pulse[1].gpioOn = 0;
    pulse[1].gpioOff = (1 << SPEAKER_PIN);
    pulse[1].usDelay = off_time_us;

    gpioWaveAddGeneric(2, pulse);

    int wave_id = gpioWaveCreate();

    if (wave_id >= 0)
    {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_REPEAT); // Transmit the wave repeatedly
    }
    else
    {
        fprintf(stderr, "Error: Failed to create waveform.\n");
    }
}

// Signal handler for graceful shutdown
void signalHandler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWaveTxStop(); // Stop the waveform transmission
    gpioWaveDelete(0); // Delete the waveform
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range (optional, but recommended for accurate frequency control)
    gpioSetPWMrange(SPEAKER_PIN, 1000); // Set PWM range to 1000 for finer control
    gpioSetPWMfrequency(SPEAKER_PIN, 1000); // Set PWM frequency to 1 kHz

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Set up callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    double previous_frequency = 0.0;

    // Main loop
    while (1)
    {
        double distance = getDistance();

        if (distance > 0)
        {
            double frequency = calculateFrequency(distance);

            if (frequency > 0)
            {
                setSpeakerFrequency(frequency);
                previous_frequency = frequency;
            }
            else
            {
                setSpeakerFrequency(previous_frequency); // Use previous frequency if out of range
            }
        }
        else
        {
            fprintf(stderr, "Error: Failed to get distance.\n");
            setSpeakerFrequency(previous_frequency); // Use previous frequency if error
        }

        gpioDelay(10); // Delay to avoid excessive CPU usage
    }

    return 0;
}

