    {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range (optional, but recommended for accurate frequency control)
    gpioSetPWMrange(SPEAKER_PIN, 1000); // Set PWM range to 1000 for finer control
    gpioSetPWMfrequency(SPEAKER_PIN, 1000); // Set PWM frequency to 1 kHz

