// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_DISTANCE 5.0  // cm
#define MAX_DISTANCE 50.0 // cm
#define MIN_FREQUENCY 200  // Hz
#define MAX_FREQUENCY 2000 // Hz
#define TIMEOUT_US 100000   // 100 ms
#define MAX_DURATION 1000000 // 1 second

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
float get_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(int frequency);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (gpio == ECHO_PIN)
    {
        if (level == 1) // Rising edge
        {
            echo_start_tick = tick;
            echo_received = 0; // Reset flag
        }
        else if (level == 0) // Falling edge
        {
            echo_end_tick = tick;
            echo_received = 1; // Set flag
        }
    }
}

// Function to get distance from ultrasonic sensor
float get_distance()
{
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    int timeout_counter = 0;
    while (!echo_received && timeout_counter < TIMEOUT_US)
    {
        gpioDelay(1); // Check every 1 us
        timeout_counter++;
    }

    if (!echo_received)
    {
        fprintf(stderr, "Error: Timeout waiting for echo.\n");
        return -1.0; // Indicate error
    }

    int pulse_width = echo_end_tick - echo_start_tick;
    if (pulse_width < 0) {
        pulse_width += MAX_DURATION; // Handle tick rollover
    }

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (pulse_width / 1000000.0) * 34300.0 / 2.0; // cm

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance)
{
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE)
    {
        distance = MIN_DISTANCE;
    }
    else if (distance > MAX_DISTANCE)
    {
        distance = MAX_DISTANCE;
    }

    // Map distance to frequency
    float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set buzzer frequency using hardware PWM
void set_buzzer_frequency(int frequency)
{
    gpioHardwarePWM(BUZZER_PIN, frequency, 500000); // 500000 is duty cycle (50%)
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Ctrl+C pressed. Exiting...\n");
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
    gpioTerminate();                   // Terminate pigpio
    exit(0);
}

