    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for ECHO_PIN
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float distance;
    float frequency;

    // Main loop
    while (1)
    {
        distance = get_distance();

        if (distance > 0) // Check for valid distance reading
        {
            frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency((int)frequency);

            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        }
        else
        {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        gpioDelay(10); // Delay 10 ms
    }

    return 0;
}

