#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1 ms

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us
        gpioWrite(TRIGGER_PIN, 0);

        int start_tick = gpioTick();
        int end_tick = start_tick;

        while (gpioRead(ECHO_PIN) == 0) {
            start_tick = gpioTick();
            if (gpioTick() - start_tick > 50000) { // Timeout after 50 ms
                fprintf(stderr, "Timeout waiting for echo start\n");
                goto cleanup;
            }
        }

        while (gpioRead(ECHO_PIN) == 1) {
            end_tick = gpioTick();
            if (gpioTick() - end_tick > 50000) { // Timeout after 50 ms
                fprintf(stderr, "Timeout waiting for echo end\n");
                goto cleanup;
            }
        }

        int pulse_width = end_tick - start_tick;
        double distance = (pulse_width / 2.0) / 29.1;

        if (distance < 2.0 || distance > 400.0) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10.0) {
                printf(" Too close!\n");
            } else {
                printf("\n");
            }
        }

        gpioDelay(500); // 500 ms
    }

cleanup:
    gpioTerminate();
    return 0;
}

