// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define DISTANCE_LOG_FILE "distance_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(int *distance);
int log_distance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize the sensor
int init_sensor() {
    char tx_buffer[3];
    char rx_buffer[3];

    // Set continuous measurement mode
    tx_buffer[0] = 0x01; // Register address
    tx_buffer[1] = 0x01; // Value to write
    tx_buffer[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the sensor
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    // Set range to 5 meters
    tx_buffer[0] = 0x02; // Register address
    tx_buffer[1] = 0x00; // Value to write
    tx_buffer[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the sensor
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    // Trigger a measurement
    tx_buffer[0] = 0x00; // Register address
    tx_buffer[1] = 0x01; // Value to write
    tx_buffer[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the sensor
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Read distance data (2 bytes)
    tx_buffer[0] = 0x0C; // Low byte register address
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the sensor
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the sensor

    // Combine the two bytes to form the distance
    *distance = (rx_buffer[1] << 8) | rx_buffer[2];

    return 0;
}

// Log distance to file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the sensor initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(DISTANCE_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            if (distance >= 200 && distance <= 5000) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Distance out of range: %d mm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

