#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define RESET_REG 0x30
#define PART_ID_REG 0x00
#define ALS_LOW_REG 0x22
#define ALS_HIGH_REG 0x23
#define PS1_LOW_REG 0x18
#define PS1_HIGH_REG 0x19
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1120();
int read_si1120_data(uint16_t *als, uint16_t *ps1);
void log_data(uint16_t als, uint16_t ps1);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize Si1120 sensor
int init_si1120() {
    int result;
    int part_id;

    // Reset the sensor
    result = i2cWriteByteData(i2c_handle, RESET_REG, 0x01);
    if (result != 0) {
        fprintf(stderr, "Error resetting Si1120: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify Part ID
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x41) {
        fprintf(stderr, "Error: Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    return 0;
}

// Read ALS and Proximity data from Si1120
int read_si1120_data(uint16_t *als, uint16_t *ps1) {
    int retries = RETRY_COUNT;
    int result;
    uint8_t als_low, als_high, ps1_low, ps1_high;

    while (retries > 0) {
        als_low = i2cReadByteData(i2c_handle, ALS_LOW_REG);
        if (als_low < 0) {
            fprintf(stderr, "Error reading ALS low byte: %d\n", als_low);
            gpioDelay(RETRY_DELAY_MS);
            retries--;
            continue;
        }

        als_high = i2cReadByteData(i2c_handle, ALS_HIGH_REG);
        if (als_high < 0) {
            fprintf(stderr, "Error reading ALS high byte: %d\n", als_high);
            gpioDelay(RETRY_DELAY_MS);
            retries--;
            continue;
        }

        ps1_low = i2cReadByteData(i2c_handle, PS1_LOW_REG);
        if (ps1_low < 0) {
            fprintf(stderr, "Error reading PS1 low byte: %d\n", ps1_low);
            gpioDelay(RETRY_DELAY_MS);
            retries--;
            continue;
        }

        ps1_high = i2cReadByteData(i2c_handle, PS1_HIGH_REG);
        if (ps1_high < 0) {
            fprintf(stderr, "Error reading PS1 high byte: %d\n", ps1_high);
            gpioDelay(RETRY_DELAY_MS);
            retries--;
            continue;
        }

        *als = (als_high << 8) | als_low;
        *ps1 = (ps1_high << 8) | ps1_low;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read Si1120 data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Log data to file
void log_data(uint16_t als, uint16_t ps1) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, PS1: %u\n", timestamp, als, ps1);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int result;
    uint16_t als, ps1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1120 sensor
    if (init_si1120() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_si1120_data(&als, &ps1) == 0) {
            log_data(als, ps1);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

