#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define sensor-specific constants
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x08
#define SI1182_ALS_DATA_REG_L 0x22
#define SI1182_ALS_DATA_REG_H 0x23
#define SI1182_PS_DATA_REG_L 0x24
#define SI1182_PS_DATA_REG_H 0x25

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_reg(int fd, unsigned char reg);
int i2c_write_reg(int fd, unsigned char reg, unsigned char value);
int init_si1182(int fd);
int read_sensor_data(int fd, unsigned int *ambient_light, unsigned int *proximity);
float convert_ambient_light(unsigned int raw_value);
void log_data(float lux, unsigned int proximity);
void print_data(float lux, unsigned int proximity);
void signal_handler(int signal);

// I2C read register function
int i2c_read_reg(int fd, unsigned char reg) {
    int result;
    result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write register function
int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    int result;
    result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize Si1182 sensor
int init_si1182(int fd) {
    int part_id;

    // Verify part ID
    part_id = i2c_read_reg(fd, SI1182_PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading part ID. Sensor may not be present.\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect part ID: 0x%02X. Expected 0x82.\n", part_id);
        return -1;
    }

    // Configure measurement rate
    if (i2c_write_reg(fd, SI1182_MEAS_RATE_REG, 0x07) < 0) {
        fprintf(stderr, "Error configuring measurement rate.\n");
        return -1;
    }

    printf("Si1182 sensor initialized successfully.\n");
    return 0;
}

// Read sensor data
int read_sensor_data(int fd, unsigned int *ambient_light, unsigned int *proximity) {
    int als_low, als_high, ps_low, ps_high;

    als_low = i2c_read_reg(fd, SI1182_ALS_DATA_REG_L);
    als_high = i2c_read_reg(fd, SI1182_ALS_DATA_REG_H);
    ps_low = i2c_read_reg(fd, SI1182_PS_DATA_REG_L);
    ps_high = i2c_read_reg(fd, SI1182_PS_DATA_REG_H);

    if (als_low < 0 || als_high < 0 || ps_low < 0 || ps_high < 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    *ambient_light = (als_high << 8) | als_low;
    *proximity = (ps_high << 8) | ps_low;

    return 0;
}

// Convert ambient light to lux
float convert_ambient_light(unsigned int raw_value) {
    return (float)raw_value * 0.1;
}

// Log data to file
void log_data(float lux, unsigned int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, lux, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print data to stdout
void print_data(float lux, unsigned int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s,%.2f,%u\n", timestamp, lux, proximity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
