    int als_low, als_high, ps_low, ps_high;

    als_low = i2c_read_reg(fd, SI1182_ALS_DATA_REG_L);
    als_high = i2c_read_reg(fd, SI1182_ALS_DATA_REG_H);
    ps_low = i2c_read_reg(fd, SI1182_PS_DATA_REG_L);
    ps_high = i2c_read_reg(fd, SI1182_PS_DATA_REG_H);

    if (als_low < 0 || als_high < 0 || ps_low < 0 || ps_high < 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    *ambient_light = (als_high << 8) | als_low;
    *proximity = (ps_high << 8) | ps_low;

    return 0;
}

// Convert ambient light to lux
float convert_ambient_light(unsigned int raw_value) {
    return (float)raw_value * 0.1;
}

