#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MAX_DISTANCE 400.0    // cm
#define MIN_DISTANCE 20.0     // cm
#define MAX_PULSE_WIDTH 2500  // us
#define MIN_PULSE_WIDTH 500   // us

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04 sensor
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // 1 us delay
    }
    if (count >= 10000) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0;
    }
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // 1 us delay
    }
    if (count >= 10000) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0;
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float time = (float)diff / 1000000.0; // Time in seconds
    float distance = (time * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

// Function to set servo angle based on distance
void set_servo_angle(float distance) {
    int pulse_width;

    if (distance > MAX_DISTANCE) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (distance < MIN_DISTANCE) {
        pulse_width = MAX_PULSE_WIDTH;
    } else {
        // Linear interpolation
        pulse_width = (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
    }

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            set_servo_angle(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Stop the servo motor
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Parking assist system stopped.\n");

    return 0;
}

