#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE 0.0
#define MAX_ANGLE 180.0
#define MIN_PULSE_WIDTH 500   // us
#define MAX_PULSE_WIDTH 2500  // us
#define TIMEOUT_US 50000      // us

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
long getPulseWidth();
double calculateDistance(long pulse_width);
double mapDistanceToAngle(double distance);
void setServoAngle(double angle);
void signalHandler(int signal);

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth() {
    echo_received = 0; // Reset the flag
    echo_start_tick = 0;
    echo_end_tick = 0;

    // Wait for the rising edge
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        echo_start_tick = gpioTick();
        if (timeout_count > TIMEOUT_US) {
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    // Wait for the falling edge
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        echo_end_tick = gpioTick();
        if (timeout_count > TIMEOUT_US) {
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    echo_received = 1; // Set the flag to indicate echo received

    if (echo_start_tick == 0 || echo_end_tick == 0) {
        return -1; // Error if start or end tick is 0
    }

    return echo_end_tick - echo_start_tick;
}

// Function to calculate the distance in centimeters
double calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map distance to angle
double mapDistanceToAngle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the servo angle
void setServoAngle(double angle) {
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    int pulse_width = MIN_PULSE_WIDTH + (int)((angle / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulse_width = getPulseWidth();

        // Calculate the distance
        double distance = calculateDistance(pulse_width);

        // Map the distance to an angle
        double angle = mapDistanceToAngle(distance);

        // Set the servo angle
        setServoAngle(angle);

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        // Delay for 100 ms
        gpioDelay(100);
    }

    return 0;
}

