#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si7005 sensor
int init_si7005()
{
    // Write 0x00 to the CONFIG register to select internal temperature sensor and disable heater
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    return 0;
}

// Function to read temperature and humidity from the Si7005 sensor
int read_si7005(float *temperature, float *humidity)
{
    unsigned short raw_temp, raw_humidity;

    // Read temperature register
    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading temperature register\n");
        return -1;
    }

    // Read humidity register
    raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);
    if (raw_humidity == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading humidity register\n");
        return -1;
    }

    // Convert raw readings to temperature and humidity
    *temperature = (175.72 * raw_temp) / 65536.0 - 46.85;
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si7005 sensor
    if (init_si7005() != 0) {
        fprintf(stderr, "Si7005 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float temperature, humidity;
    while (1) {
        if (read_si7005(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait 100ms before re-opening
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            if (init_si7005() != 0) {
                fprintf(stderr, "Si7005 re-initialization failed\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }
        gpioDelay(2000); // Wait 2 seconds
    }

    return 0;
}

