#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define SAMPLE_RATE  0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define WHO_AM_I     0x75
#define ACCEL_XOUT_H 0x3B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an MPU-6050 register
int read_register(int handle, uint8_t reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an MPU-6050 register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6050
int init_mpu6050(int handle)
{
    // Verify sensor presence
    int who_am_i = read_register(handle, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x68\n", who_am_i);
        return -1;
    }

    // Reset the device
    if (write_register(handle, PWR_MGMT_1, 0x80) < 0) return -1;
    gpioDelay(100); // Wait for reset

    // Wake up the device
    if (write_register(handle, PWR_MGMT_1, 0x00) < 0) return -1;
    gpioDelay(100); // Wait for stabilization

    // Set sample rate divider
    if (write_register(handle, SAMPLE_RATE, 0x07) < 0) return -1;

    // Configure accelerometer range
    if (write_register(handle, ACCEL_CONFIG, 0x00) < 0) return -1; // ±2g

    // Configure gyroscope range
    if (write_register(handle, GYRO_CONFIG, 0x00) < 0) return -1; // ±250 deg/s

    return 0;
}

// Function to read raw sensor data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *temperature)
{
    char buffer[14];
    int result = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buffer, 14);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *temperature = (int16_t)((buffer[6] << 8) | buffer[7]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
