#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW 0x06
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sts30(float *temperature);
int log_data(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts30_address;
    const char *log_file_name;
    const char *error_log_file_name;
    int sample_interval;
} config_t;

config_t config = {
    I2C_BUS,
    STS30_ADDR,
    LOG_FILE,
    ERROR_LOG_FILE,
    SAMPLE_INTERVAL_SEC
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(config.error_log_file_name, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        cleanup();
        return 1;
    }

    float temperature;
    // Main loop
    while (!terminate) {
        if (read_sts30(&temperature) == 0) {
            if (log_data(temperature) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read temperature");
        }

        gpioSleep(PI_TIME_RELATIVE, config.sample_interval, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.sts30_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from STS30-DIS
int read_sts30(float *temperature) {
    char cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    char buf[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return 1;
    }

    gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Wait 100ms for measurement

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }

    // Convert raw data to temperature (Celsius)
    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * (float)raw_temp / 65535.0);

    return 0;
}

// Log data to file
int log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s, %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

