#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REP 0xFD
#define CRC_POLYNOMIAL 0x31
#define MAX_RETRIES 3

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT40 sensor
int read_sht40(int fd, float *temperature, float *humidity) {
    unsigned char buf[6];
    unsigned char cmd = MEASURE_HIGH_REP;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, &cmd, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(10000); // Wait for measurement (at least 10ms)

        if (read(fd, buf, 6) != 6) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // CRC Check
        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC check failed\n");
            retries++;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Convert data
        unsigned short temperature_raw = (buf[0] << 8) | buf[1];
        unsigned short humidity_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
        *humidity = 100.0 * (float)humidity_raw / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, closing I2C and log file...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

int main() {
    float temperature, humidity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5); // Wait 5 seconds
    }

    return 0;
}

