#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "sensor_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int cmd, float *value);
float convert_temperature(unsigned int raw_temp);
float convert_humidity(unsigned int raw_humidity);
void log_data(float temperature, float humidity);
void print_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

// Function to read sensor data with retry
int read_sensor_data(int cmd, float *value) {
    int retries = RETRY_COUNT;
    unsigned char buf[2];
    int result;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, cmd);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %s\n", pigpio_error(result));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait for measurement (20ms)

        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            unsigned int raw_value = (buf[0] << 8) | buf[1];
            if (cmd == TEMP_CMD) {
                *value = convert_temperature(raw_value);
            } else if (cmd == HUMID_CMD) {
                *value = convert_humidity(raw_value);
            } else {
                fprintf(stderr, "Invalid command for conversion.\n");
                return -1;
            }
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %s\n", pigpio_error(result));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to convert raw humidity to percentage RH
float convert_humidity(unsigned int raw_humidity) {
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to print data to console
void print_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float temperature, humidity;
    while (!terminate) {
        // Read temperature
        if (read_sensor_data(TEMP_CMD, &temperature) != 0) {
            fprintf(stderr, "Failed to read temperature.\n");
            continue; // Skip to the next iteration
        }

        // Read humidity
        if (read_sensor_data(HUMID_CMD, &humidity) != 0) {
            fprintf(stderr, "Failed to read humidity.\n");
            continue; // Skip to the next iteration
        }

        // Log and print data
        log_data(temperature, humidity);
        print_data(temperature, humidity);

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

