#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define TRIGGER_MEASUREMENT_CMD 0x362F
#define DATA_LENGTH 9
#define LOG_FILE "airflow_data.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int send_command(int fd, uint16_t command);
int read_data(int fd, uint8_t *data, int length);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t process_data(const uint8_t *data);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int sig);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Send command to the sensor
int send_command(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int fd, uint8_t *data, int length) {
    if (read(fd, data, length) != length) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Process raw data and convert to pressure and temperature
sensor_data_t process_data(const uint8_t *data) {
    sensor_data_t result;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t scale_factor = (data[6] << 8) | data[7];

    // CRC validation
    if (crc8(data, 2) != data[2] ||
        crc8(data + 3, 2) != data[5] ||
        crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC validation failed. Using default values.\n");
        result.pressure = -999.0; // Indicate error
        result.temperature = -999.0;
        return result;
    }

    // Convert to physical units
    result.pressure = (float)raw_pressure / scale_factor;
    result.temperature = (float)raw_temperature / 200.0 - 45.0;

    return result;
}

// Log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
