// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, int cmd);
int read_data(int handle, char *buf, int count);
unsigned char crc8(const unsigned char *data, int len);
float convert_to_celsius(unsigned short raw_value);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, float temperature);
int log_error(const char *timestamp, const char *message);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int sts30_address;
    int sample_interval;
} config_t;

config_t config = {I2C_BUS, STS30_ADDR, SAMPLE_INTERVAL};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char timestamp[32];
        strcpy(timestamp, get_iso8601_timestamp());

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            log_error(timestamp, "Failed to send measurement command");
            continue; // Retry
        }

        gpioDelay(15000); // Wait for conversion (15 ms)

        // Read data
        char data[3];
        if (read_data(i2c_handle, data, 3) != 0) {
            log_error(timestamp, "Failed to read data");
            continue; // Retry
        }

        // Validate CRC
        unsigned char crc = crc8((unsigned char*)data, 2);
        if (crc != (unsigned char)data[2]) {
            char error_message[128];
            snprintf(error_message, sizeof(error_message), "CRC mismatch: expected 0x%02X, got 0x%02X", crc, (unsigned char)data[2]);
            log_error(timestamp, error_message);
            continue; // Retry
        }

        // Convert to Celsius
        unsigned short raw_value = (data[0] << 8) | data[1];
        float temperature = convert_to_celsius(raw_value);

        // Log data
        if (log_data(timestamp, temperature) != 0) {
            log_error(timestamp, "Failed to log data");
        }

        gpioDelay(config.sample_interval * 1000000); // Sleep for sample interval
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

