int send_command(int handle, int cmd) {
    char buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return 1;
    }
    return 0;
}

// Read data from STS30
int read_data(int handle, char *buf, int count) {
    int result = i2cReadDevice(handle, buf, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return 1;
    }
    return 0;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw value to Celsius
float convert_to_celsius(unsigned short raw_value) {
    return -45.0 + 175.0 * (raw_value / 65535.0);
}

