    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[32]; // Static buffer to avoid stack allocation issues

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

