int log_data(const char *timestamp, float temperature) {
    FILE *fp = fopen("enclosure_temp_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Log error to file
int log_error(const char *timestamp, const char *message) {
    FILE *fp = fopen("error_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        return 1;
    }

    fprintf(fp, "%s,%s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

