typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
sensor_data_t process_sensor_data(uint8_t *data);
