        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    sensor_data_t processed_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            if (processed_data.pressure != -999.0) {
                log_data(processed_data);
            } else {
                fprintf(stderr, "Invalid sensor data, skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

