#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Structure for sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_si7021(int handle, float *temperature, float *humidity);
void control_fan(int gpio, int state);
void add_to_buffer(SensorData data);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature and humidity from Si7021
int read_si7021(int handle, float *temperature, float *humidity) {
    unsigned char cmd_temp[] = {0xE3};
    unsigned char cmd_humidity[] = {0xE5};
    unsigned char buf[2];
    int result;

    // Temperature measurement
    result = i2cWriteDevice(handle, cmd_temp, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for measurement
    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    *temperature = 175.72 * raw_temp / 65536.0 - 46.85;

    // Humidity measurement
    result = i2cWriteDevice(handle, cmd_humidity, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for measurement
    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return 0;
}

// Function to control the cooling fan
void control_fan(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to add data to the circular buffer
void add_to_buffer(SensorData data) {
    buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temp: %.2f C, Humidity: %.2f %%\n", timestamp_str, buffer[index].temperature, buffer[index].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    float temperature, humidity;
    SensorData data;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting sensor monitoring...\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_si7021(i2c_handle, &temperature, &humidity) == 0) {
                // Data validation
                if (temperature >= -40.0 && temperature <= 85.0 && humidity >= 0.0 && humidity <= 100.0) {
                    data.timestamp = time(NULL);
                    data.temperature = temperature;
                    data.humidity = humidity;
                    add_to_buffer(data);

                    // Fan control based on temperature
                    if (temperature > TEMP_THRESHOLD_HIGH) {
                        control_fan(FAN_GPIO, 1); // Turn fan ON
                    } else if (temperature < TEMP_THRESHOLD_LOW) {
                        control_fan(FAN_GPIO, 0); // Turn fan OFF
                    }

                    // Print buffer every 5 seconds
                    if (data.timestamp % 5 == 0) {
                        print_buffer();
                    }

                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Invalid sensor data: Temperature=%.2f, Humidity=%.2f\n", temperature, humidity);
                }
            } else {
                fprintf(stderr, "Error reading sensor data, retry %d\n", retry + 1);
            }
            retry++;
            gpioDelay(RETRY_DELAY_MS);
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    control_fan(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

