// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// File to log data
#define LOG_FILE "air_quality.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_data(uint16_t *co2, float *temperature, float *humidity);
int verify_crc(uint16_t data, uint8_t crc);
int log_data(uint16_t co2, float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len, uint8_t crc)
{
    for (int i = 0; i < len; i++)
    {
        crc ^= data[i];
        for (int j = 0; j < 8; j++)
        {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c()
{
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SCD40
int send_command(uint16_t command)
{
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0)
    {
        fprintf(stderr, "Error sending command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(uint16_t *co2, float *temperature, float *humidity)
{
    char buf[9];
    int result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9)
    {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Verify CRC for each 2-byte word
    for (int i = 0; i < 4; i++)
    {
        uint16_t data = (buf[2 * i] << 8) | buf[2 * i + 1];
        uint8_t crc = buf[2 * i + 2];

        if (!verify_crc(data, crc))
        {
            fprintf(stderr, "CRC check failed for data word %d\n", i);
            return -1;
        }
    }

    // Extract CO2, temperature, and humidity
    *co2 = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

// Verify CRC checksum
int verify_crc(uint16_t data, uint8_t crc)
{
    uint8_t calculated_crc = crc8((uint8_t *)&data, 2, 0xFF);
    return (calculated_crc == crc);
}

// Log data to file
int log_data(uint16_t co2, float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Ctrl+C pressed. Stopping periodic measurement and exiting.\n");
    terminate = 1;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0)
    {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Start periodic measurement
    if (send_command(0x21B1) != 0)
    {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for at least 1 second
    gpioDelay(1000000); // 1 second

    // Main loop
    while (!terminate)
    {
        uint16_t co2;
        float temperature, humidity;

        // Poll data-ready flag
        if (send_command(0xE4B8) != 0)
        {
            fprintf(stderr, "Error sending data-ready command\n");
            continue; // Retry
        }

        char buf[3];
        int result = i2cReadDevice(i2c_handle, buf, 3);
        if (result != 3)
        {
            fprintf(stderr, "Error reading data-ready flag: %d\n", result);
            gpioDelay(100000); // 100ms
            continue;
        }

        uint16_t data_ready = (buf[0] << 8) | buf[1];

        if (data_ready & 0x0001) // Check bit 0
        {
            // Read data
            if (send_command(0xEC05) != 0)
            {
                fprintf(stderr, "Error sending read data command\n");
                continue; // Retry
            }

            if (read_data(&co2, &temperature, &humidity) == 0)
            {
                // Log data
                log_data(co2, temperature, humidity);
            }
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Stop periodic measurement
    if (send_command(0x3F86) != 0)
    {
        fprintf(stderr, "Error sending stop periodic measurement command\n");
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

