#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL 5 // seconds

// Data structure for sensor readings
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
    time_t timestamp;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int start_periodic_measurement();
int get_data_ready_status(uint8_t *data);
int read_measurement(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_crc(uint8_t data[], int nbrOfBytes);
void process_sensor_data(uint8_t *data);
void add_to_buffer(sensor_data_t data);
void print_buffer();
void control_led(uint16_t co2);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// GPIO initialization function
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Start periodic measurement function
int start_periodic_measurement() {
    char buf[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Get data ready status function
int get_data_ready_status(uint8_t *data) {
    char cmd[2] = {0xE4, 0xB8};
    char buf[2];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing get_data_ready_status command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading get_data_ready_status: %d\n", result);
        return -1;
    }

    data[0] = buf[0];
    data[1] = buf[1];

    return 0;
}

// Read measurement function
int read_measurement(uint8_t *data) {
    char cmd[2] = {0xEC, 0x05};
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing read_measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading measurement data: %d\n", result);
        return -1;
    }

    return 0;
}

// CRC-8 checksum calculation function
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;
    int byteNr;

    for (byteNr = 0; byteNr < nbrOfBytes; ++byteNr) {
        crc ^= (data[byteNr]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// CRC-8 checksum validation function
int validate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = calculate_crc(data, nbrOfBytes - 1);
    return (crc == data[nbrOfBytes - 1]);
}

// Process sensor data function
void process_sensor_data(uint8_t *data) {
    uint16_t co2 = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[3] << 8) | data[4];
    uint16_t humidity_raw = (data[6] << 8) | data[7];

    float temperature = -45 + 175 * (float)temperature_raw / 65535.0;
    float humidity = 100 * (float)humidity_raw / 65535.0;

    sensor_data_t sensor_data = {co2, temperature, humidity, time(NULL)};
    add_to_buffer(sensor_data);
}

// Add data to circular buffer function
void add_to_buffer(sensor_data_t data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print circular buffer function
void print_buffer() {
    printf("\n--- Sensor Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        printf("[%d] CO2: %d ppm, Temp: %.2f C, Hum: %.2f %%RH, Timestamp: %ld\n",
               index, circular_buffer[index].co2, circular_buffer[index].temperature, circular_buffer[index].humidity, circular_buffer[index].timestamp);
    }
    printf("--- End of Buffer ---\n\n");
}

// Control LED function
void control_led(uint16_t co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    // Stop periodic measurement
    char stop_cmd[2] = {0x3F, 0x86};
    i2cWriteDevice(i2c_handle, stop_cmd, 2);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Release GPIO
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set back to input

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data_ready[2];
    uint8_t measurement_data[9];

    // Main loop
    while (!terminate) {
        // Get data ready status
        if (get_data_ready_status(data_ready) == 0) {
            // Check if data is ready
            if (data_ready[0] & 0x01) {
                // Read measurement data
                if (read_measurement(measurement_data) == 0) {
                    // Validate CRC checksums
                    if (validate_crc(measurement_data, 3) &&
                        validate_crc(measurement_data + 3, 3) &&
                        validate_crc(measurement_data + 6, 3)) {
                        // Process sensor data
                        process_sensor_data(measurement_data);

                        // Control LED
                        uint16_t co2 = (measurement_data[0] << 8) | measurement_data[1];
                        control_led(co2);

                        // Print buffer
                        print_buffer();
                    } else {
                        fprintf(stderr, "CRC checksum validation failed\n");
                    }
                } else {
                    fprintf(stderr, "Failed to read measurement data\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to get data ready status\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

