#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_MS 50
#define MAX_FAILURES 3

static volatile int running = 1;
static int failure_count = 0;
static FILE *log_file = NULL;

// Structure to hold GPIO edge timestamps
typedef struct {
    uint32_t rising_edge;
    uint32_t falling_edge;
} EdgeTimestamps;

// Function prototypes
int initialize_gpio();
int read_sensor(EdgeTimestamps *timestamps);
double calculate_temperature(uint32_t high_pulse_width, uint32_t total_pulse_width);
int log_temperature(double temperature);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the pigpio library and sets the GPIO pin mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Reads the sensor data and logs errors if the sensor is absent or stuck
int read_sensor(EdgeTimestamps *timestamps) {
    int timeout_counter = 0;

    // Wait for rising edge
    while (gpioRead(GPIO_PIN) == 0 && timeout_counter < TIMEOUT_MS) {
        gpioDelay(1); // Wait 1 ms
        timeout_counter++;
    }
    if (timeout_counter >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }
    timestamps->rising_edge = gpioTick();

    timeout_counter = 0;
    // Wait for falling edge
    while (gpioRead(GPIO_PIN) == 1 && timeout_counter < TIMEOUT_MS) {
        gpioDelay(1); // Wait 1 ms
        timeout_counter++;
    }
    if (timeout_counter >= TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }
    timestamps->falling_edge = gpioTick();

    return 0;
}

// Calculates the temperature in degrees Celsius
double calculate_temperature(uint32_t high_pulse_width, uint32_t total_pulse_width) {
    if (total_pulse_width == 0) {
        fprintf(stderr, "Error: Total pulse width is zero\n");
        return -999.0; // Indicate an error
    }
    return 4215.0 - (2143.0 * (double)high_pulse_width / (double)total_pulse_width);
}

// Logs the temperature reading to a file with an ISO-8601 timestamp
int log_temperature(double temperature) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    if (temperature < -40.0 || temperature > 150.0) {
        fprintf(stderr, "Error: Temperature reading out of range (-40.0 to 150.0)\n");
        fprintf(log_file, "%s ERROR: Temperature reading out of range (-40.0 to 150.0)\n", timestamp);
        free(timestamp);
        return -1;
    }

    fprintf(log_file, "%s Temperature: %.2f °C\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

// Gets the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main() {
    EdgeTimestamps timestamps;
    double temperature;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sensor(&timestamps) == 0) {
            uint32_t high_pulse_width = timestamps.falling_edge - timestamps.rising_edge;
            uint32_t total_pulse_width = timestamps.falling_edge - timestamps.rising_edge;

            temperature = calculate_temperature(high_pulse_width, total_pulse_width);

            if (temperature != -999.0) {
                if (log_temperature(temperature) != 0) {
                    failure_count = 0; // Reset failure count on successful log
                } else {
                    failure_count = 0; // Reset failure count on successful log
                }
            } else {
                fprintf(stderr, "Error: Invalid temperature reading\n");
                fprintf(log_file, "%s ERROR: Invalid temperature reading\n", get_iso8601_timestamp());
                failure_count++;
            }
        } else {
            fprintf(stderr, "Error reading sensor\n");
            fprintf(log_file, "%s ERROR: Sensor read failure\n", get_iso8601_timestamp());
            failure_count++;
        }

        if (failure_count >= MAX_FAILURES) {
            fprintf(log_file, "%s SENSOR MALFUNCTION\n", get_iso8601_timestamp());
            fprintf(stderr, "SENSOR MALFUNCTION\n");
            failure_count = 0; // Reset failure count after logging
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Wait for the specified interval
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

