#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD 0x2400
#define DATA_LENGTH 6
#define RETRY_COUNT 3
#define SLEEP_SECONDS 5
#define SINUSOIDAL_PERIOD_HOURS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_pigpio();
int open_i2c_device(int bus, int addr);
int read_sensor_data(int handle, unsigned char *data);
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes);
int validate_crc(unsigned char data[], int nbrOfBytes);
SensorData convert_raw_data(unsigned char data[]);
SensorData add_sinusoidal_offset(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);

// CRC lookup table
const unsigned char crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data with retries
int read_sensor_data(int handle, unsigned char *data) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, (char *)data, DATA_LENGTH);
        if (result == DATA_LENGTH) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(1000); // Wait 1 second
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to calculate CRC8 checksum
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = 0xFF;
    unsigned char bit;
    int byteNr;

    for (byteNr = 0; byteNr < nbrOfBytes; ++byteNr) {
        crc ^= (data[byteNr]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = calculate_crc(data, nbrOfBytes);
    return (crc == data[nbrOfBytes]);
}

// Function to convert raw data to temperature and humidity
SensorData convert_raw_data(unsigned char data[]) {
    SensorData sensor_data;
    unsigned short temperature_raw = (data[0] << 8) | data[1];
    unsigned short humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Function to add sinusoidal offset to temperature and humidity
SensorData add_sinusoidal_offset(SensorData data) {
    time_t now = time(NULL);
