        uint8_t raw_data[9];

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        gpioDelay(45000); // Wait for conversion (45ms)

        // Read sensor data
        if (read_data(i2c_handle, raw_data, 9) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Validate CRC checksums
        if (!validate_crc(raw_data, 3) || !validate_crc(raw_data + 3, 3) || !validate_crc(raw_data + 6, 3)) {
            fprintf(stderr, "CRC checksum error, discarding data...\n");
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(raw_data);

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data!\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

