// I2C open function
int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len, unsigned char crc) {
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data = {0.0, 0.0};
    unsigned char buf[3];
    unsigned char crc;
    int retries = 3;

    // Measure temperature
    unsigned char temp_cmd = TEMP_MEASURE_CMD;
    while (retries > 0) {
        if (i2c_write(fd, &temp_cmd, 1) == 0) {
            usleep(10000); // Wait 10 ms
            if (i2c_read(fd, buf, 3) == 0) {
                crc = crc8(buf, 2, CRC_INITIAL);
                if (crc == buf[2]) {
