                    data.temperature = 175.72 * raw_temp / 65536.0 - 46.85;
                    break;
                } else {
                    fprintf(stderr, "Temperature CRC error\n");
                }
            } else {
                fprintf(stderr, "Temperature read error\n");
            }
        } else {
            fprintf(stderr, "Temperature write error\n");
        }
        retries--;
        usleep(100000); // Wait 100 ms before retry
    }
    if (retries == 0) {
        fprintf(stderr, "Temperature read failed after multiple retries\n");
        data.temperature = -999.0; // Indicate error
    }

