                } else {
                    fprintf(stderr, "Humidity CRC error\n");
                }
            } else {
                fprintf(stderr, "Humidity read error\n");
            }
        } else {
            fprintf(stderr, "Humidity write error\n");
        }
        retries--;
        usleep(100000); // Wait 100 ms before retry
    }
    if (retries == 0) {
        fprintf(stderr, "Humidity read failed after multiple retries\n");
        data.humidity = -999.0; // Indicate error
    }

    return data;
}

// Function to log data to CSV file
void log_data(sensor_data_t data) {
    FILE *fp = fopen("environment.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    if (data.temperature == -999.0 || data.humidity == -999.0) {
        fprintf(fp, "%s,ERROR,ERROR\n", timestamp);
        fprintf(stderr, "Logging ERROR values\n");
    } else {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    }

    fclose(fp);
}

// Signal handler function
