    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device, exiting\n");
        return 1;
    }

