int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[9];
    int result = i2cReadDevice(handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8((uint8_t *)buf, 2) != buf[2] ||
        crc8((uint8_t *)buf + 3, 2) != buf[5] ||
        crc8((uint8_t *)buf + 6, 1) != buf[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
