    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command\n");
            cleanup();
            return 1;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS * 1000); // Convert ms to us

        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Convert pressure
            float pressure = convert_pressure(sensor_data.pressure);

            // Log data
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

