#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 10.0
#define FLOW_RATE_MIN_COUNT 1638
#define FLOW_RATE_MAX_COUNT 14745
#define FLOW_RATE_RANGE (FLOW_RATE_MAX_COUNT - FLOW_RATE_MIN_COUNT)
#define FLOW_RATE_SCALE (FLOW_RATE_MAX - FLOW_RATE_MIN)
#define FLOW_RATE_OFFSET FLOW_RATE_MIN
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, uint16_t *raw_data);
float convert_flow_rate(uint16_t raw_data);
int set_fan_speed(int gpio, float flow_rate);
int log_data(FILE *log_file, float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read sensor data
int read_sensor(int i2c_handle, uint16_t *raw_data) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1; // Indicate failure
    }

    *raw_data = ((uint16_t)buffer[0] << 8) | (uint16_t)buffer[1];
    return 0; // Indicate success
}

// Function to convert raw data to flow rate
float convert_flow_rate(uint16_t raw_data) {
    // Mask off status bits
    uint16_t flow_data = raw_data >> 2;

    // Scale and offset the flow rate
    float flow_rate = ((float)flow_data - FLOW_RATE_MIN_COUNT) * FLOW_RATE_SCALE / FLOW_RATE_RANGE + FLOW_RATE_OFFSET;

    return flow_rate;
}

// Function to set fan speed based on flow rate
int set_fan_speed(int gpio, float flow_rate) {
    // Clamp flow rate to the defined range
    if (flow_rate < FLOW_RATE_MIN) {
        flow_rate = FLOW_RATE_MIN;
    } else if (flow_rate > FLOW_RATE_MAX) {
        flow_rate = FLOW_RATE_MAX;
    }

    // Calculate PWM duty cycle (0-255)
    int duty_cycle = (int)((flow_rate - FLOW_RATE_MIN) / FLOW_RATE_SCALE * 255.0);

    // Set PWM duty cycle
    gpioPWM(gpio, duty_cycle);

