#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LPS33HW_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C
#define WHO_AM_I_VALUE 0xB1
#define CTRL_REG1_VALUE 0xB0
#define SAMPLE_RATE_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(float *pressure, float *temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize sensor
int init_sensor() {
    int who_am_i;
    int status;

    // Check WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Configure CTRL_REG1
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, CTRL_REG1_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(float *pressure, float *temperature) {
    int32_t press_raw;
    int16_t temp_raw;
    int status;

    // Read pressure data
    int press_xl = i2cReadByteData(i2c_handle, PRESS_OUT_XL);
    int press_l = i2cReadByteData(i2c_handle, PRESS_OUT_L);
    int press_h = i2cReadByteData(i2c_handle, PRESS_OUT_H);

    if (press_xl < 0 || press_l < 0 || press_h < 0) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    press_raw = (int32_t)((press_h << 16) | (press_l << 8) | press_xl);
    *pressure = (float)press_raw / 4096.0;

    // Read temperature data
    int temp_l = i2cReadByteData(i2c_handle, TEMP_OUT_L);
    int temp_h = i2cReadByteData(i2c_handle, TEMP_OUT_H);

    if (temp_l < 0 || temp_h < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    temp_raw = (int16_t)((temp_h << 8) | temp_l);
    *temperature = 42.5 + (float)temp_raw / 480.0;

    return 0;
}

// Log data to file
void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float pressure, temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(SAMPLE_RATE_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

