#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 10
#define LED_GPIO 17
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, double *temperature);
void update_buffer(double temperature, double *buffer, int buffer_size, int *index);
double calculate_average(double *buffer, int buffer_size);
void control_led(int gpio_pin, double average_temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read temperature from STLM75 sensor
int read_temperature(int i2c_handle, double *temperature) {
    int raw_temperature;
    int result;

    result = i2cReadWordData(i2c_handle, TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    raw_temperature = ((result & 0xFF00) >> 8) | ((result & 0x00FF) << 8); // Swap bytes
    raw_temperature = raw_temperature >> 7; // Right-shift by 7 bits

    *temperature = (double)raw_temperature * 0.5;
    return 0;
}

// Function to update the circular buffer
void update_buffer(double temperature, double *buffer, int buffer_size, int *index) {
    buffer[*index] = temperature;
    *index = (*index + 1) % buffer_size;
}

// Function to calculate the running average
double calculate_average(double *buffer, int buffer_size) {
    double sum = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i];
    }
    return sum / buffer_size;
}

// Function to control the LED based on average temperature
void control_led(int gpio_pin, double average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(gpio_pin, 1); // Turn LED on
    } else {
        gpioWrite(gpio_pin, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize temperature buffer with zeros
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        double temperature;

        if (read_temperature(i2c_handle, &temperature) == 0) {
            update_buffer(temperature, temperature_buffer, BUFFER_SIZE, &buffer_index);
            double average_temperature = calculate_average(temperature_buffer, BUFFER_SIZE);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
            control_led(LED_GPIO, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        time_sleep(1.0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

