        }

        time_sleep(1.0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
