int initialize_sensor();
int read_sensor_data(float *co2, float *temperature, float *humidity);
int verify_crc(unsigned char data[], int nbrOfBytes);
int log_data(float co2, float temperature, float humidity);
VentilationState control_ventilation(float co2);
void signal_handler(int signal);

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len, unsigned char crc)
{
    unsigned char i;
    for (i = 0; i < len; i++)
    {
        crc ^= data[i];
        for (int j = 0; j < 8; j++)
        {
            if ((crc & 0x80) != 0)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Initialize the SCD30 sensor
int initialize_sensor() {
    // Stop periodic measurement
    unsigned char stop_periodic_cmd[2] = {0x0104, 0x00};
    if (i2cWriteDevice(i2c_handle, (char *)stop_periodic_cmd, 2) != 0) {
        fprintf(log_file, "%s", "Error: Failed to stop periodic measurement.\n");
        fflush(log_file);
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Set measurement interval to 2 seconds
    unsigned char set_measurement_interval_cmd[3] = {0x4600, 0x00, 0x02};
    if (i2cWriteDevice(i2c_handle, (char *)set_measurement_interval_cmd, 3) != 0) {
        fprintf(log_file, "%s", "Error: Failed to set measurement interval.\n");
        fflush(log_file);
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Start continuous measurement with ambient pressure compensation disabled
    unsigned char start_measurement_cmd[2] = {0x0010, 0x00};
    if (i2cWriteDevice(i2c_handle, (char *)start_measurement_cmd, 2) != 0) {
        fprintf(log_file, "%s", "Error: Failed to start continuous measurement.\n");
        fflush(log_file);
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    return 0;
}

// Read data from the SCD30 sensor
int read_sensor_data(float *co2, float *temperature, float *humidity) {
    unsigned char data_ready_cmd[2] = {0x0202, 0x00};
    unsigned char data[3];

    // Poll data-ready flag
    if (i2cWriteDevice(i2c_handle, (char *)data_ready_cmd, 2) != 0) {
        fprintf(log_file, "%s", "Error: Failed to write data-ready command.\n");
        fflush(log_file);
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    if (i2cReadDevice(i2c_handle, (char *)data, 3) != 3) {
        fprintf(log_file, "%s", "Error: Failed to read data-ready response.\n");
        fflush(log_file);
        return -1;
    }

    if (verify_crc(data, 3) != 0) {
        fprintf(log_file, "%s", "Error: CRC mismatch for data-ready response.\n");
        fflush(log_file);
        return -1;
    }

    if (data[0] != 0x01) {
        fprintf(log_file, "%s", "Error: Data not ready.\n");
        fflush(log_file);
        return -1;
    }

    // Read measurement
    unsigned char read_measurement_cmd[2] = {0x0300, 0x00};
    unsigned char measurement_data[18];

    if (i2cWriteDevice(i2c_handle, (char *)read_measurement_cmd, 2) != 0) {
        fprintf(log_file, "%s", "Error: Failed to write read measurement command.\n");
        fflush(log_file);
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    if (i2cReadDevice(i2c_handle, (char *)measurement_data, 18) != 18) {
        fprintf(log_file, "%s", "Error: Failed to read measurement data.\n");
        fflush(log_file);
        return -1;
    }

    // Verify CRC for each value
    for (int i = 0; i < 18; i += 3) {
        if (verify_crc(&measurement_data[i], 3) != 0) {
            fprintf(log_file, "%s", "Error: CRC mismatch for measurement data.\n");
            fflush(log_file);
            return -1;
        }
    }

    // Convert data to float values
    *co2 = *(float *)&measurement_data[0];
    *temperature = *(float *)&measurement_data[6];
    *humidity = *(float *)&measurement_data[12];

    return 0;
}

