int verify_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = crc8(data, nbrOfBytes - 1, 0xFF);
    if (crc != data[nbrOfBytes - 1]) {
        return -1;
    }
    return 0;
}

