    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Control ventilation system based on CO2 reading
VentilationState control_ventilation(float co2) {
    if (co2 < 800) {
        return OFF;
    } else if (co2 >= 800 && co2 <= 1199) {
        return LOW;
    } else {
        return HIGH;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "%s", "Info: Received signal, shutting down...\n");
    fflush(log_file);

    // Stop periodic measurement
    unsigned char stop_periodic_cmd[2] = {0x0104, 0x00};
    i2cWriteDevice(i2c_handle, (char *)stop_periodic_cmd, 2);
    gpioDelay(100000); // 100ms delay

    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

