    i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(log_file, "Error: Failed to open I2C bus (%d)\n", i2c_handle);
        fflush(log_file);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(log_file, "%s", "Error: Sensor initialization failed.\n");
        fflush(log_file);
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float co2, temperature, humidity;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(&co2, &temperature, &humidity) == 0) {
            // Log data
            log_data(co2, temperature, humidity);

            // Control ventilation
            VentilationState new_state = control_ventilation(co2);
            if (new_state != ventilation_state) {
                ventilation_state = new_state;
                fprintf(log_file, "Info: Ventilation state changed to: %d\n", ventilation_state);
                fflush(log_file);
            }
        } else {
            fprintf(log_file, "%s", "Error: Failed to read sensor data.\n");
            fflush(log_file);
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000000); // Delay for measurement interval
    }

    return 0;
}

