#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define SAMPLE_INTERVAL_DEFAULT 1000 // milliseconds
#define SAMPLE_INTERVAL_MIN 100
#define SAMPLE_INTERVAL_MAX 10000
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *data);
void log_sensor_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to SDP32
int send_command(int handle, uint16_t command) {
    uint8_t cmd[2];
    cmd[0] = (command >> 8) & 0xFF;
    cmd[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Pressure
    int16_t raw_pressure = (data[0] << 8) | data[1];
    uint8_t pressure_crc = data[2];

    // Temperature
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint8_t temperature_crc = data[5];

    // Scale Factor
    uint16_t raw_scale_factor = (data[6] << 8) | data[7];
    uint8_t scale_factor_crc = data[8];

    // CRC Check
    uint8_t pressure_data[2] = {data[0], data[1]};
    uint8_t temperature_data[2] = {data[3], data[4]};
    uint8_t scale_factor_data[2] = {data[6], data[7]};

    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        sensor_data.pressure = -999.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / (float)raw_scale_factor;
    }

    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        sensor_data.temperature = (float)raw_temperature / 200.0; // Example scaling
    }

    if (crc8(scale_factor_data, 2) != scale_factor_crc) {
        fprintf(stderr, "Scale Factor CRC check failed!\n");
        sensor_data.scale_factor = 0; // Indicate error
    } else {
        sensor_data.scale_factor = raw_scale_factor;
    }

    return sensor_data;
}

// Log sensor data
void log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C, Scale Factor: %u\n",
           timestamp, data.pressure, data.temperature, data.scale_factor);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int sample_interval = SAMPLE_INTERVAL_DEFAULT;

    // Parse command-line argument
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval < SAMPLE_INTERVAL_MIN || sample_interval > SAMPLE_INTERVAL_MAX) {
            fprintf(stderr, "Invalid sample interval. Using default: %d ms\n", SAMPLE_INTERVAL_DEFAULT);
            sample_interval = SAMPLE_INTERVAL_DEFAULT;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        cleanup();
        return 1;
    }

    uint8_t data[9];
    sensor_data_t sensor_data;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(i2c_handle, data) == 0) {
                sensor_data = process_sensor_data(data);
                log_sensor_data(sensor_data);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break; // Exit main loop if max retries reached
        }

        gpioDelay(sample_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

