#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x3615
#define DATA_LENGTH 9

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nSignal received, terminating program...\n");
    terminate = 1;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    uint8_t data[DATA_LENGTH];
    int result;

    // Send continuous measurement command
    uint8_t cmd[2] = {(CONTINUOUS_MEASUREMENT_CMD >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for at least 45 ms
    gpioDelay(45000);

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC for each 3-byte data word
    for (int i = 0; i < DATA_LENGTH / 3; i++) {
        uint8_t crc = crc8(data + (i * 3), 3);
        if (crc != data[i * 3 + 3]) {
            fprintf(stderr, "CRC mismatch for word %d: calculated 0x%02X, received 0x%02X\n", i, crc, data[i * 3 + 3]);
            return -1;
        }
    }

    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint8_t scale_factor_pressure = data[6];
    uint8_t scale_factor_temperature = data[7];

    // Convert raw values using scale factors
    *pressure = (float)raw_pressure / (float)scale_factor_pressure;
    *temperature = (float)raw_temperature / 200.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            // Log the results
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

