#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00

int i2c_fd = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to configure the HDC1000 sensor
int configure_hdc1000() {
    unsigned char config_data[2];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x00; // Reset

    if (write(i2c_fd, config_data, 2) != 2) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait 10ms

    config_data[0] = CONFIG_REG;
    config_data[1] = 0x00; // Configure for 14-bit resolution, single measurement

    if (write(i2c_fd, config_data, 2) != 2) {
        fprintf(stderr, "Error writing to config register: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait 10ms

    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int read_hdc1000(float *temperature, float *humidity) {
    unsigned char temp_reg = TEMP_REG;
    unsigned char data[4];
    unsigned int raw_temperature, raw_humidity;

    if (write(i2c_fd, &temp_reg, 1) != 1) {
        fprintf(stderr, "Error writing to temperature register: %s\n", strerror(errno));
        return -1;
    }

    usleep(20000); // Wait 20ms for conversion

    if (read(i2c_fd, data, 4) != 4) {
        fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
        return -1;
    }

    raw_temperature = (data[0] << 8) | data[1];
    raw_humidity = (data[2] << 8) | data[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure the sensor
    if (configure_hdc1000() != 0) {
        fprintf(stderr, "Error configuring HDC1000 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_hdc1000(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

