#define SI7051_ADDR 0x40

// I2C bus
#define I2C_BUS 1

// Measurement command
#define MEASURE_TEMP_CMD 0xE3

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from Si7051
float read_temperature() {
    int raw_temperature;
    float temperature_celsius;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, MEASURE_TEMP_CMD, 0) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1000.0; // Indicate error
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, 0);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1000.0; // Indicate error
    }

    // Convert raw data to Celsius
    temperature_celsius = (175.72 * raw_temperature / 65536.0) - 46.85;

    return temperature_celsius;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

