#include <pigpio.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register address, check datasheet
#define PRESSURE_SCALE 0.1 // Example scaling factor, check datasheet

int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read pressure from the sensor
float read_pressure() {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1.0; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Apply scaling factor
    float pressure = (float)raw_pressure * PRESSURE_SCALE;

    return pressure;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float pressure = read_pressure();

        if (pressure >= 0) {
            // Get current timestamp
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

            // Log the pressure reading with timestamp
            printf("%s Pressure: %.2f kPa\n", buf, pressure);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying...\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

