#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Sensor I2C address
#define I2C_ADDR 0x63

// I2C bus
#define I2C_BUS 1

// Calibration data command
#define CALIBRATION_CMD 0x50

// Measurement command
#define MEASUREMENT_CMD 0x40

// Measurement delay (7 ms)
#define MEASUREMENT_DELAY 7000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c00;
    uint16_t c10;
    uint16_t c01;
    uint16_t c11;
    uint16_t c20;
    uint16_t c21;
} calibration_data_t;

// Function prototypes
int read_calibration_data(int i2c_handle, calibration_data_t *calibration_data);
int read_sensor_data(int i2c_handle, uint32_t *raw_pressure, uint16_t *raw_temperature);
void compensate_data(uint32_t raw_pressure, uint16_t raw_temperature, calibration_data_t calibration_data, float *temperature, float *pressure);
void log_data(float temperature, float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read calibration data from the sensor
int read_calibration_data(int i2c_handle, calibration_data_t *calibration_data) {
    char buffer[8];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, CALIBRATION_CMD, buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calibration_data->c0 = (buffer[0] << 8) | buffer[1];
    calibration_data->c1 = (buffer[2] << 8) | buffer[3];
    calibration_data->c00 = (buffer[4] << 8) | buffer[5];
    calibration_data->c10 = (buffer[6] << 8) | buffer[7];

    result = i2cReadI2CBlockData(i2c_handle, CALIBRATION_CMD + 8, buffer, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration data (continued): %d\n", result);
        return -1;
    }

    calibration_data->c01 = (buffer[0] << 8) | buffer[1];
    calibration_data->c11 = (buffer[2] << 8) | buffer[3];
    calibration_data->c20 = (buffer[4] << 8) | buffer[5];
    calibration_data->c21 = (buffer[6] << 8) | buffer[7];

    return 0;
}

// Function to read raw sensor data
int read_sensor_data(int i2c_handle, uint32_t *raw_pressure, uint16_t *raw_temperature) {
    char buffer[6];
    int result;

    result = i2cWriteByte(i2c_handle, MEASUREMENT_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY);

    result = i2cReadI2CBlockData(i2c_handle, 0, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *raw_temperature = (buffer[0] << 8) | buffer[1];
    *raw_pressure = ((uint32_t)buffer[2] << 16) | ((uint32_t)buffer[3] << 8) | buffer[4];

    return 0;
}

// Function to compensate raw data
void compensate_data(uint32_t raw_pressure, uint16_t raw_temperature, calibration_data_t calibration_data, float *temperature, float *pressure) {
    // Placeholder for actual compensation formulas from the datasheet
    // This is a simplified example and needs to be replaced with the actual formulas
    *temperature = (float)raw_temperature / 100.0; // Example conversion
    *pressure = (float)raw_pressure / 100.0;      // Example conversion
}

// Function to log data with timestamp
void log_data(float temperature, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    calibration_data_t calibration_data;
    uint32_t raw_pressure;
    uint16_t raw_temperature;
    float temperature, pressure;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_pressure, &raw_temperature) == 0) {
            // Compensate data
            compensate_data(raw_pressure, raw_temperature, calibration_data, &temperature, &pressure);

            // Log data
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

