#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x60
#define PRESSURE_REG_MSB 0xAA
#define PRESSURE_REG_LSB 0xAB
#define SCALE_FACTOR 0.1

int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read pressure from the sensor
int read_pressure(int fd, float *pressure) {
    unsigned char msb, lsb;
    int raw_pressure;

    // Trigger measurement
    if (write(fd, &PRESSURE_REG_MSB, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    // Read MSB
    if (read(fd, &msb, 1) != 1) {
        fprintf(stderr, "Error reading MSB from I2C device.\n");
        return -1;
    }

    // Read LSB
    if (read(fd, &lsb, 1) != 1) {
        fprintf(stderr, "Error reading LSB from I2C device.\n");
        return -1;
    }

    // Combine MSB and LSB
    raw_pressure = (msb << 8) | lsb;

    // Convert to kPa
    *pressure = raw_pressure * SCALE_FACTOR;

    return 0;
}

// Function to log pressure data with timestamp
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

int main() {
    float pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", I2C_BUS);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: 0x%02X\n", MLX90819_ADDR);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_pressure(i2c_fd, &pressure) == 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        sleep(1);
    }

    return 0;
}

