#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define DATA_LENGTH 9
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, uint8_t addr, uint16_t command);
int i2c_read(int fd, uint8_t addr, uint8_t *data, int length);
uint8_t crc8(const uint8_t *data, int len, uint8_t crc);
sensor_data_t process_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint16_t command) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    uint8_t buf[3];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t addr, uint8_t *data, int length) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t crc) {
    uint8_t polynomial = 0x31;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Data processing function
sensor_data_t process_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // CRC validation
    if (crc8(data, 2, 0xFF) != data[2] ||
        crc8(data + 3, 2, 0xFF) != data[5] ||
        crc8(data + 6, 1, 0xFF) != data[8]) {
        fprintf(stderr, "CRC validation failed\n");
        sensor_data.pressure = -999.0; // Indicate error
        sensor_data.temperature = -999.0;
        return sensor_data;
    }

    sensor_data.pressure = (float)raw_pressure / 60.0;
    sensor_data.temperature = (float)raw_temperature / 200.0;

    return sensor_data;
}

// Data logging function
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send continuous measurement command
        if (i2c_write(i2c_fd, SDP800_ADDR, CONTINUOUS_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Error sending command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait 45 ms
        usleep(45000);

        // Read data
        uint8_t data[DATA_LENGTH];
        if (i2c_read(i2c_fd, SDP800_ADDR, data, DATA_LENGTH) < 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Process data
        sensor_data_t sensor_data = process_data(data);

        // Log data
        if (sensor_data.pressure != -999.0) {
            if (log_data(sensor_data) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Invalid sensor data, not logging\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

