#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01
#define MIN_PRESSURE 200.0
#define MAX_PRESSURE 250.0
#define LOG_FILE "pressure_log.csv"
#define MAX_RETRIES 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_pressure(uint16_t *pressure);
float convert_to_kpa(uint16_t raw_pressure);
void log_pressure(float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from sensor
int read_pressure(uint16_t *pressure) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
        if (bytes_read == 2) {
            *pressure = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw pressure to kPa
float convert_to_kpa(uint16_t raw_pressure) {
    return (float)raw_pressure * SCALE_FACTOR;
}

// Log pressure to CSV file
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return;
        }
        // Check if the file is empty and write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }
        fseek(log_file, 0, SEEK_END); // Reset file pointer to append
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk
}

// Check pressure range and log warning
void check_pressure_range(float pressure) {
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure out of range: %.2f kPa\n", pressure);
    }
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint16_t raw_pressure;
    float pressure_kpa;

    // Main loop
    while (!terminate) {
        if (read_pressure(&raw_pressure) == 0) {
            pressure_kpa = convert_to_kpa(raw_pressure);
            log_pressure(pressure_kpa);
            check_pressure_range(pressure_kpa);
        } else {
            fprintf(stderr, "Failed to read pressure. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

