#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB

int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    fprintf(stderr, "\nSignal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to trigger a measurement on the HIH6130 sensor
int trigger_measurement() {
    char buf[1] = {0x00};
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the HIH6130 sensor
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate the sensor status bits
int validate_status_bits(const unsigned char *data) {
    if ((data[0] & 0xC0) != 0x00) {
        fprintf(stderr, "Sensor status indicates an error\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and humidity
void convert_data(const unsigned char *data, float *temperature, float *humidity) {
    unsigned int raw_T = ((data[0] & 0x3F) << 8) | data[1];
    unsigned int raw_H = (data[2] << 6) | (data[3] >> 2);

    *temperature = raw_T * 165.0 / 16383.0 - 40.0;
    *humidity = raw_H * 100.0 / 16383.0;
}

// Function to get the current timestamp in ISO 8601 format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to log data to a file
int log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Check file size and truncate if necessary
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size > LOG_FILE_SIZE_LIMIT) {
        fclose(fp);
        fp = fopen(LOG_FILE, "w"); // Open in write mode to truncate
        if (fp == NULL) {
            fprintf(stderr, "Failed to open log file for truncation\n");
            return -1;
        }
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    unsigned char data[4];
    float temperature, humidity;
    char timestamp[21];

    while (!terminate) {
        if (trigger_measurement() == 0) {
            gpioDelay(40000); // Wait 40 ms
            if (read_sensor_data(data) == 0) {
                if (validate_status_bits(data) == 0) {
                    convert_data(data, &temperature, &humidity);
                    get_timestamp(timestamp);
                    if (log_data(timestamp, temperature, humidity) != 0) {
                        fprintf(stderr, "Failed to log data\n");
                    }
                    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
                } else {
                    fprintf(stderr, "Data validation failed\n");
                }
            } else {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to trigger measurement\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

