#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define STATUS_NIBBLE_TICKS 3
#define DATA_NIBBLE_TICKS 3
#define CHECKSUM_NIBBLE_TICKS 3

#define MIN_PULSE_WIDTH_US 12
#define MAX_PULSE_WIDTH_US 271

#define SENT_SYNC_PULSE_US 100
#define SENT_STATUS_PULSE_US 200
#define SENT_DATA_PULSE_US 300
#define SENT_CHECKSUM_PULSE_US 400

#define SENT_SYNC_WIDTH_US 56
#define SENT_STATUS_WIDTH_US 120
#define SENT_DATA_WIDTH_US 180
#define SENT_CHECKSUM_WIDTH_US 240

#define SENT_SYNC_WIDTH_TICKS (SENT_SYNC_WIDTH_US / TICK_TIME_US)
#define SENT_STATUS_WIDTH_TICKS (SENT_STATUS_WIDTH_US / TICK_TIME_US)
#define SENT_DATA_WIDTH_TICKS (SENT_DATA_WIDTH_US / TICK_TIME_US)
#define SENT_CHECKSUM_WIDTH_TICKS (SENT_CHECKSUM_WIDTH_US / TICK_TIME_US)

#define SENT_SYNC_PULSE_TICKS (SENT_SYNC_PULSE_US / TICK_TIME_US)
#define SENT_STATUS_PULSE_TICKS (SENT_STATUS_PULSE_US / TICK_TIME_US)
#define SENT_DATA_PULSE_TICKS (SENT_DATA_PULSE_US / TICK_TIME_US)
#define SENT_CHECKSUM_PULSE_TICKS (SENT_CHECKSUM_PULSE_US / TICK_TIME_US)

#define MAX_PULSES 100
#define TIMEOUT_US 100000 // 100ms

#define SENT_SYNC_PULSE_MIN_TICKS (SENT_SYNC_PULSE_TICKS - 2)
#define SENT_SYNC_PULSE_MAX_TICKS (SENT_SYNC_PULSE_TICKS + 2)

#define SENT_STATUS_PULSE_MIN_TICKS (SENT_STATUS_PULSE_TICKS - 2)
#define SENT_STATUS_PULSE_MAX_TICKS (SENT_STATUS_PULSE_TICKS + 2)

#define SENT_DATA_PULSE_MIN_TICKS (SENT_DATA_PULSE_TICKS - 2)
#define SENT_DATA_PULSE_MAX_TICKS (SENT_DATA_PULSE_TICKS + 2)

#define SENT_CHECKSUM_PULSE_MIN_TICKS (SENT_CHECKSUM_PULSE_TICKS - 2)
#define SENT_CHECKSUM_PULSE_MAX_TICKS (SENT_CHECKSUM_PULSE_TICKS + 2)

#define SENT_STATUS_MIN_TICKS (SENT_STATUS_WIDTH_TICKS - 2)
#define SENT_STATUS_MAX_TICKS (SENT_STATUS_WIDTH_TICKS + 2)

#define SENT_DATA_MIN_TICKS (SENT_DATA_WIDTH_TICKS - 2)
#define SENT_DATA_MAX_TICKS (SENT_DATA_WIDTH_TICKS + 2)

#define SENT_CHECKSUM_MIN_TICKS (SENT_CHECKSUM_WIDTH_TICKS - 2)
#define SENT_CHECKSUM_MAX_TICKS (SENT_CHECKSUM_WIDTH_TICKS + 2)


volatile int pulse_count = 0;
volatile int pulse_widths[MAX_PULSES];
volatile int pulse_timestamps[MAX_PULSES];
volatile int pulse_index = 0;
volatile int last_timestamp = 0;
volatile int last_pulse_width = 0;
volatile int timeout_flag = 0;

FILE *log_file = NULL;

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        if (pulse_index < MAX_PULSES) {
            pulse_widths[pulse_index] = tick - last_timestamp;
            pulse_timestamps[pulse_index] = tick;
            pulse_index++;
        }
        last_timestamp = tick;
    }
}

int validate_checksum(int status, int data1, int data2, int data3, int checksum) {
    int calculated_checksum = (status + data1 + data2 + data3) % 16;
    return (calculated_checksum == checksum);
}

float convert_to_pressure(int raw_value) {
    // Linear transfer function: pressure = raw_value * scale + offset
    // These values are example and MUST be calibrated for your specific sensor.
    float scale = 0.01; // Example: 0.01 Pa per unit
    float offset = 0.0;  // Example: 0 Pa offset
    return raw_value * scale + offset;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);

    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int status, data1, data2, data3, checksum;
    int raw_pressure;
    float pressure;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    while (1) {
        pulse_count = 0;
        pulse_index = 0;
        timeout_flag = 0;
        gpioDelay(TIMEOUT_US); // Wait for a timeout

        if (timeout_flag) {
            fprintf(stderr, "Timeout error: No SENT signal received.\n");
            fprintf(log_file, "Timeout error: No SENT signal received.\n");
            fflush(log_file);
            continue;
        }

        if (pulse_count < 10) {
            fprintf(stderr, "Too few pulses received (%d).\n", pulse_count);
            fprintf(log_file, "Too few pulses received (%d).\n", pulse_count);
            fflush(log_file);
            continue;
        }

        // Validate SENT sync pulse
        if (pulse_widths[0] < SENT_SYNC_PULSE_MIN_TICKS || pulse_widths[0] > SENT_SYNC_PULSE_MAX_TICKS) {
            fprintf(stderr, "Invalid SENT sync pulse width: %d ticks\n", pulse_widths[0]);
            fprintf(log_file, "Invalid SENT sync pulse width: %d ticks\n", pulse_widths[0]);
            fflush(log_file);
            continue;
        }

        // Extract status nibble
        status = (pulse_widths[1] - SENT_STATUS_MIN_TICKS) / STATUS_NIBBLE_TICKS;
        if (status < 0 || status > 15) {
            fprintf(stderr, "Invalid status nibble: %d\n", status);
            fprintf(log_file, "Invalid status nibble: %d\n", status);
            fflush(log_file);
            continue;
        }

        // Extract data nibbles
        data1 = (pulse_widths[2] - SENT_DATA_MIN_TICKS) / DATA_NIBBLE_TICKS;
        data2 = (pulse_widths[3] - SENT_DATA_MIN_TICKS) / DATA_NIBBLE_TICKS;
        data3 = (pulse_widths[4] - SENT_DATA_MIN_TICKS) / DATA_NIBBLE_TICKS;

        if (data1 < 0 || data1 > 15 || data2 < 0 || data2 > 15 || data3 < 0 || data3 > 15) {
            fprintf(stderr, "Invalid data nibble(s): %d, %d, %d\n", data1, data2, data3);
            fprintf(log_file, "Invalid data nibble(s): %d, %d, %d\n", data1, data2, data3);
            fflush(log_file);
            continue;
        }

        // Extract checksum nibble
        checksum = (pulse_widths[5] - SENT_CHECKSUM_MIN_TICKS) / CHECKSUM_NIBBLE_TICKS;
        if (checksum < 0 || checksum > 15) {
            fprintf(stderr, "Invalid checksum nibble: %d\n", checksum);
            fprintf(log_file, "Invalid checksum nibble: %d\n", checksum);
            fflush(log_file);
            continue;
        }

        // Validate checksum
        if (!validate_checksum(status, data1, data2, data3, checksum)) {
            fprintf(stderr, "Checksum validation failed\n");
            fprintf(log_file, "Checksum validation failed\n");
            fflush(log_file);
            continue;
        }

        // Convert data to raw pressure value
        raw_pressure = (data1 << 8) | (data2 << 4) | data3;

        // Convert raw pressure to pressure in Pascals
        pressure = convert_to_pressure(raw_pressure);

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log pressure reading
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file);

        printf("%s, Pressure: %.2f Pa\n", timestamp, pressure);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

