#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define DEVICE_ID_REG 0x01
#define TEMP_REG 0x00
#define EXPECTED_DEVICE_ID 0x0117
#define SAMPLE_INTERVAL_SEC 60
#define FILENAME "greenhouse_temps.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int verify_device_id();
int read_temperature(float *temperature);
int write_temperature_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Device ID verification function
int verify_device_id() {
    int device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Error: Incorrect device ID. Expected 0x%04X, got 0x%04X\n", EXPECTED_DEVICE_ID, device_id);
        return -1;
    }

    printf("Device ID verified successfully: 0x%04X\n", device_id);
    return 0;
}

// Temperature reading function
int read_temperature(float *temperature) {
    int raw_temperature = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temperature);
        return -1;
    }

    // Convert raw temperature to Celsius
    *temperature = (float)raw_temperature * 0.0078125;
    return 0;
}

// Temperature writing to file function
int write_temperature_to_file(float temperature) {
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", FILENAME);
        return -1;
    }

    // Write temperature as a 4-byte float
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing temperature to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    float temperature;
    time_t last_write_time = 0;

    printf("Starting temperature monitoring...\n");

    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);

            // Get current time
            time_t current_time = time(NULL);

            // Check if enough time has passed since the last write
            if (current_time - last_write_time >= SAMPLE_INTERVAL_SEC) {
                // Write temperature to file
                if (write_temperature_to_file(temperature) != 0) {
                    fprintf(stderr, "Error writing temperature to file, but continuing...\n");
                }
                last_write_time = current_time;
            }
        } else {
            fprintf(stderr, "Error reading temperature, but continuing...\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

