#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define HIGH_PRECISION_MEASUREMENT 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define LOG_FILE "environmental_data.txt"
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int bus, int addr);
int send_command(int handle, int command);
int read_sensor_data(int handle, unsigned char *data);
unsigned char calculate_crc(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len, unsigned char crc);
SensorData process_sensor_data(const unsigned char *data);
int log_data(const SensorData *data);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to send a command to the SHT40
int send_command(int handle, int command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, unsigned char *data) {
    int bytes_read = i2cReadI2CBlockData(handle, 0, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
unsigned char calculate_crc(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(const unsigned char *data, int len, unsigned char crc) {
    unsigned char calculated_crc = calculate_crc(data, len);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Function to process sensor data
SensorData process_sensor_data(const unsigned char *data) {
    SensorData sensor_data;
    unsigned short raw_temp = (data[0] << 8) | data[1];
    unsigned short raw_hum = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    sensor_data.humidity = -6.0 + 125.0 * (raw_hum / 65535.0);

    return sensor_data;
}

// Function to log data to file
int log_data(const SensorData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection(I2C_BUS, SHT40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char data[6];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Send high-precision measurement command
        if (send_command(i2c_handle, HIGH_PRECISION_MEASUREMENT) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 8.5 ms)

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC checksums
        if (validate_crc(data, 2, data[2]) != 0 || validate_crc(data + 3, 2, data[5]) != 0) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Process sensor data
        sensor_data = process_sensor_data(data);

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n", sensor_data.temperature, sensor_data.humidity);

        gpioDelay(SLEEP_DURATION * 1000); // Sleep for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

