    sensor_data.temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    sensor_data.humidity = -6.0 + 125.0 * (raw_hum / 65535.0);

    return sensor_data;
}

// Function to log data to file
int log_data(const SensorData *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->temperature, data->humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection(I2C_BUS, SHT40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char data[6];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Send high-precision measurement command
        if (send_command(i2c_handle, HIGH_PRECISION_MEASUREMENT) != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(10); // Wait for measurement (at least 8.5 ms)

        // Read sensor data
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC checksums
        if (validate_crc(data, 2, data[2]) != 0 || validate_crc(data + 3, 2, data[5]) != 0) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Process sensor data
        sensor_data = process_sensor_data(data);

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n", sensor_data.temperature, sensor_data.humidity);

        gpioDelay(SLEEP_DURATION * 1000); // Sleep for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

