#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHTC3_ADDR 0x70
#define MEASURE_CMD 0x7866
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "shtc3_environment.log"

int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_shtc3(SensorData *data);
unsigned char crc8(const unsigned char *data, int len);
int validate_data(unsigned char *data);
void convert_data(unsigned char *data, SensorData *sensor_data);
int log_data(SensorData data);
void print_data(SensorData data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHTC3 sensor
int read_shtc3(SensorData *data) {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    unsigned char buffer[6];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(12000); // Wait for conversion (12.4 ms)

    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    if (validate_data(buffer) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    convert_data(buffer, data);

    return 0;
}

// CRC-8 checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_data(unsigned char *data) {
    unsigned char crc_data[2];
    crc_data[0] = data[0];
    crc_data[1] = data[1];
    if (crc8(crc_data, 2) != data[2]) return -1;

    crc_data[0] = data[3];
    crc_data[1] = data[4];
    if (crc8(crc_data, 2) != data[5]) return -1;

    return 0;
}

// Convert raw data to temperature and humidity
void convert_data(unsigned char *data, SensorData *sensor_data) {
    unsigned short temperature_raw = (data[0] << 8) | data[1];
    unsigned short humidity_raw = (data[3] << 8) | data[4];

    sensor_data->temperature = 175.0 * temperature_raw / 65535.0 - 45.0;
    sensor_data->humidity = 100.0 * humidity_raw / 65535.0;
}

// Log data to file
int log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, data.temperature, data.humidity);
    fclose(fp);
    return 0;
}

// Print data to stdout
void print_data(SensorData data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    SensorData sensor_data;

    while (!terminate) {
        if (read_shtc3(&sensor_data) == 0) {
            if (sensor_data.temperature >= -40.0 && sensor_data.temperature <= 125.0 &&
                sensor_data.humidity >= 0.0 && sensor_data.humidity <= 100.0) {
                print_data(sensor_data);
                log_data(sensor_data);
            } else {
                fprintf(stderr, "Out-of-range values: Temperature=%.2f, Humidity=%.2f\n", sensor_data.temperature, sensor_data.humidity);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

