    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,magnetic_field_gauss,temperature_celsius\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    return 0;
}

// Function to read raw data from the sensor
int read_sensor(int *raw_value) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw data to magnetic field and temperature
void convert_data(int raw_value, float *magnetic_field, float *temperature) {
    *magnetic_field = (float)raw_value * 0.1;
    *temperature = (float)raw_value * 0.01 - 25.0;
}

// Function to log data to a CSV file
void log_data(float magnetic_field, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
