    gpioTerminate();
    exit(0);
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);

    int raw_value;
    float magnetic_field, temperature;

    while (1) {
        if (read_sensor(&raw_value) == 0) {
            convert_data(raw_value, &magnetic_field, &temperature);
            log_data(magnetic_field, temperature);
        } else {
            fprintf(stderr, "Sensor read failed, logging NaN values\n");
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    return 0;
}

