#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define LOG_FILE "flow_log.txt"

int i2c_handle;
FILE *log_file;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_handle, unsigned char *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to convert raw data to flow rate and temperature
void convert_data(unsigned char *data, float *flow_rate, float *temperature) {
    unsigned int raw_flow = ((data[0] & 0x3F) << 8) | data[1];
    unsigned int raw_temp = (data[2] << 4) | (data[3] >> 4);

    *flow_rate = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
    *temperature = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;
}

// Function to log data to a file
void log_data(float flow_rate, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, flow_rate, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char data[4];
    float flow_rate, temperature;
    int retry_count = 0;
    const int max_retries = 3;

    // Handle initial read failures
    if (read_sensor_data(i2c_handle, data) != 0) {
        fprintf(stderr, "Initial read failed, retrying...\n");
        retry_count++;
        gpioDelay(1000); // Wait 1 second before retrying
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Second initial read failed, exiting...\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_handle, data) == 0) {
            convert_data(data, &flow_rate, &temperature);
            log_data(flow_rate, temperature);
            retry_count = 0; // Reset retry count on successful read
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            retry_count++;
            if (retry_count > max_retries) {
                fprintf(stderr, "Max retries reached, exiting...\n");
                fclose(log_file);
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }
        }
        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

