#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 100
#define SAMPLE_INTERVAL_S 2

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
    int checksum;
} DHT11Data;

// Function prototypes
int initialize_gpio();
int read_dht11(DHT11Data *data);
int validate_checksum(DHT11Data data);
int log_data(DHT11Data data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initializes the pigpio library and sets the GPIO pin mode
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    return 0;
}

// Reads data from the DHT11 sensor
int read_dht11(DHT11Data *data) {
    int i, j;
    unsigned int tick;
    unsigned int start_tick, end_tick;
    int pulse_lengths[40];

    // Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18); // 18 ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // 20 us

    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for response (low for 80 us, then high for 80 us)
    tick = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for response\n");
            return 1;
        }
    }

    tick = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for response\n");
            return 1;
        }
    }

    tick = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for response\n");
            return 1;
        }
    }

    // Read 40 data bits
    for (i = 0; i < 40; i++) {
        tick = gpioTick();
        while (gpioRead(DHT11_GPIO) == 0) {
            if (gpioTick() - tick > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for data bit start\n");
                return 1;
            }
        }

        start_tick = gpioTick();
        tick = gpioTick();
        while (gpioRead(DHT11_GPIO) == 1) {
            if (gpioTick() - tick > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for data bit end\n");
                return 1;
            }
        }
        end_tick = gpioTick();

        pulse_lengths[i] = end_tick - start_tick;
    }

    // Convert pulse lengths to data bits
    int data_bits[40];
    for (i = 0; i < 40; i++) {
        data_bits[i] = (pulse_lengths[i] > 30) ? 1 : 0; // Adjust threshold as needed
    }

    // Convert data bits to bytes
    int bytes[5];
    for (i = 0; i < 5; i++) {
        bytes[i] = 0;
        for (j = 0; j < 8; j++) {
            bytes[i] <<= 1;
            bytes[i] |= data_bits[i * 8 + j];
        }
    }

    // Validate checksum
    if (validate_checksum({bytes[0], bytes[1], bytes[2], bytes[3], bytes[4]})) {
        data->humidity = bytes[0];
        data->temperature = bytes[2];
        data->checksum = bytes[4];
        return 0; // Success
    } else {
        fprintf(stderr, "Checksum validation failed\n");
        return 1; // Checksum failure
    }
}

// Validates the checksum of the DHT11 data
int validate_checksum(DHT11Data data) {
    int sum = data.humidity + data.temperature;
    return (sum & 0xFF) == data.checksum;
}

// Logs the temperature and humidity data to a file
int log_data(DHT11Data data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    DHT11Data dht11_data;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio()) {
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    fprintf(stderr, "DHT11 sensor reader started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_dht11(&dht11_data) == 0) {
            log_data(dht11_data);
        } else {
            fprintf(stderr, "Failed to read DHT11 data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_S * 1000000); // Sample every 2 seconds
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "DHT11 sensor reader stopped.\n");

    return 0;
}

