#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "sht31d_data.log"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_measurement_command();
int read_sensor_data(unsigned char *data);
unsigned char calculate_crc(const unsigned char *data, int len);
int validate_crc(const unsigned char *data, int len);
sensor_data_t convert_data(const unsigned char *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send the measurement command
int send_measurement_command() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(15000); // Wait 15 ms
    return 0;
}

// Function to read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8 checksum
unsigned char calculate_crc(const unsigned char *data, int len) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = calculate_crc(data, len);
    if (crc != data[len]) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", crc, data[len]);
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and humidity
sensor_data_t convert_data(const unsigned char *data) {
    sensor_data_t sensor_data;
    unsigned short temperature_raw = (data[0] << 8) | data[1];
    unsigned short humidity_raw = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    unsigned char data[6];
    sensor_data_t sensor_data;
    int retries = 3;

    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Read sensor data with retries
        int read_result = -1;
        for (int i = 0; i < retries; i++) {
            read_result = read_sensor_data(data);
            if (read_result == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Failed to read sensor data, attempt %d/%d, retrying...\n", i + 1, retries);
                gpioDelay(100000); // Wait 100ms before retrying
            }
        }

        if (read_result != 0) {
            fprintf(stderr, "Failed to read sensor data after multiple retries\n");
            continue; // Skip to the next iteration
        }

        // Validate CRC checksums
        if (validate_crc(data, 2) != 0 || validate_crc(data + 3, 2) != 0) {
            fprintf(stderr, "CRC validation failed, skipping data logging\n");
            continue;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Log data
        if (log_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

