int read_register(int i2c_handle, uint8_t reg_addr, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, reg_addr, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg_addr, result);
        return -1; // Indicate error
    }

    *value = (buf[1] << 8) | buf[0];
    return 0; // Indicate success
}

// Function to verify the device ID
int verify_device_id(int i2c_handle) {
    uint16_t device_id;
    if (read_register(i2c_handle, DEVICE_ID_REG, &device_id) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }

    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%04X (expected 0x%04X)\n", device_id, EXPECTED_DEVICE_ID);
        return -1;
    }

    return 0;
}

// Function to read RGB values from the ADPD105
int read_rgb(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_register(i2c_handle, RED_REG, red) != 0) {
        fprintf(stderr, "Error reading red value\n");
        return -1;
    }
    if (read_register(i2c_handle, GREEN_REG, green) != 0) {
        fprintf(stderr, "Error reading green value\n");
        return -1;
    }
    if (read_register(i2c_handle, BLUE_REG, blue) != 0) {
        fprintf(stderr, "Error reading blue value\n");
        return -1;
    }
    return 0;
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float r = (float)red;
    float g = (float)green;
    float b = (float)blue;

    float n = (r + g + b) / 2.0f;
    float cct = (K1 * r * r) + (K2 * g * g) + (K3 * b * b);
    cct = cct / n;
    cct = cct * 0.0014388; // Convert to CCT in Kelvin

    return cct;
}

// Function to log CCT data to a CSV file
int log_cct_data(float cct1, float cct2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("cct_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,Average_CCT\n"); // Write header if file is new
    }

    float average_cct = (cct1 + cct2) / 2.0f;
    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Verify device IDs
    if (verify_device_id(i2c_handle1) != 0) {
        fprintf(stderr, "Device ID verification failed for sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    if (verify_device_id(i2c_handle2) != 0) {
        fprintf(stderr, "Device ID verification failed for sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        float cct1, cct2;

        // Read RGB values from sensor 1
        if (read_rgb(i2c_handle1, &red1, &green1, &blue1) != 0) {
            fprintf(stderr, "Error reading RGB values from sensor 1\n");
        } else {
            // Calculate CCT for sensor 1
            cct1 = calculate_cct(red1, green1, blue1);
        }

        // Read RGB values from sensor 2
        if (read_rgb(i2c_handle2, &red2, &green2, &blue2) != 0) {
            fprintf(stderr, "Error reading RGB values from sensor 2\n");
        } else {
            // Calculate CCT for sensor 2
            cct2 = calculate_cct(red2, green2, blue2);
        }

        // Log the average CCT
        if (log_cct_data(cct1, cct2) != 0) {
            fprintf(stderr, "Error logging CCT data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

