        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_pressure = read_raw_pressure();
        int raw_temperature = read_raw_temperature();

        if (raw_pressure != -1 && raw_temperature != -1) {
            float pressure_kPa = convert_pressure(raw_pressure);
            float temperature_C = convert_temperature(raw_temperature);

            if (log_data(pressure_kPa, temperature_C) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging\n");
