#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x4A
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TEMP_REGISTER 0x00
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define TEMP_SCALE 0.0625

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
float convert_to_celsius(int16_t raw_temp);
int gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);

// I2C read word function
int i2c_read_word(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

// Temperature conversion function
float convert_to_celsius(int16_t raw_temp) {
    return (float)raw_temp * TEMP_SCALE;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("GPIO set value failed");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature from sensor
        int raw_temp = i2c_read_word(i2c_fd, TEMP_REGISTER);
        if (raw_temp < 0) {
            fprintf(stderr, "Failed to read temperature, errno: %d\n", errno);
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(raw_temp);

        // Log temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Control LED based on temperature
        if (temperature > TEMP_THRESHOLD_HIGH) {
            if (gpio_set_value(gpio_line, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO high, errno: %d\n", errno);
            }
        } else if (temperature < TEMP_THRESHOLD_LOW) {
            if (gpio_set_value(gpio_line, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO low, errno: %d\n", errno);
            }
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

