#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define SCALE_FACTOR_CMD 0x062F
#define DATA_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    int scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len, uint8_t crc);
sensor_data_t process_data(const char *buffer);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int read_scale_factor(int handle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(const char *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Process raw data and convert to physical units
sensor_data_t process_data(const char *buffer) {
    sensor_data_t data;
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    data.scale_factor = (buffer[6] << 8) | buffer[7];

    // CRC validation
    if (!validate_crc(buffer, 2, buffer[2])) {
        fprintf(stderr, "Pressure CRC validation failed!\n");
        data.pressure = -999.0; // Indicate error
    } else {
        data.pressure = (float)raw_pressure / data.scale_factor;
    }

    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "Temperature CRC validation failed!\n");
        data.temperature = -999.0; // Indicate error
    } else {
        data.temperature = (float)raw_temperature / 200.0;
    }

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.pressure, data.temperature, data.scale_factor);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Read scale factor from the sensor
int read_scale_factor(int handle) {
    char buf[2];
    buf[0] = (SCALE_FACTOR_CMD >> 8) & 0xFF;
    buf[1] = SCALE_FACTOR_CMD & 0xFF;

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing scale factor command\n");
        return -1;
    }

    char read_buf[3];
    if (i2cReadDevice(handle, read_buf, 3) != 3) {
        fprintf(stderr, "Error reading scale factor\n");
        return -1;
    }

    return (read_buf[0] << 8) | read_buf[1];
}

int main() {
