    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send continuous measurement command
        if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Error sending command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(45000); // Wait 45 ms

        // Read data
        char buffer[DATA_LENGTH];
