#define MEASURE_TEMP_CMD 0xF3
#define MEASURE_HUMID_CMD 0xF5
#define READ_PREV_TEMP_CMD 0xE0

int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the sensor
int read_raw_temperature(unsigned short *raw_temp) {
    char cmd = MEASURE_TEMP_CMD;
    char buf[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }

    gpioDelay(20); // Wait for measurement

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw humidity data from the sensor
int read_raw_humidity(unsigned short *raw_humidity) {
    char cmd = MEASURE_HUMID_CMD;
    char buf[2];
    int result;

    result = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }

    gpioDelay(20); // Wait for measurement

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }

    *raw_humidity = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw temperature to Celsius
float convert_temperature(unsigned short raw_temp) {
    return 175.72 * raw_temp / 65536.0 - 46.85;
}

// Function to convert raw humidity to percentage
float convert_humidity(unsigned short raw_humidity) {
    float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Function to log data to stdout and environment.log
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(stdout);

    FILE *fp = fopen("environment.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(fp);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening environment.log for writing\n");
    }
}

// Function to log errors to stderr and environment.log
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(stderr, "%s: %s\n", timestamp, message);

    FILE *fp = fopen("environment.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s: %s\n", timestamp, message);
        fflush(fp);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening environment.log for writing\n");
    }
}

// Function to validate the sensor presence
int validate_sensor() {
    char buf[1];
    int result;

    result = i2cWriteDevice(i2c_handle, NULL, 0); // Send no data to check for presence
    if (result != 0) {
        log_error("Sensor not present or I2C communication error.");
        return -1;
    }

    gpioDelay(10); // Wait for a short time

    result = i2cReadDevice(i2c_handle, buf, 1);
    if (result != 1) {
        log_error("Sensor not present or I2C communication error.");
        return -1;
    }

    return 0;
}

int main() {
    unsigned short raw_temp, raw_humidity;
    float temperature, humidity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and I2C
    if (initialize() != 0) {
        return 1;
    }

    // Validate the sensor
    if (validate_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw temperature and humidity
        if (read_raw_temperature(&raw_temp) == 0 && read_raw_humidity(&raw_humidity) == 0) {
            // Convert raw values to Celsius and percentage
            temperature = convert_temperature(raw_temp);
            humidity = convert_humidity(raw_humidity);

            // Log the data
            log_data(temperature, humidity);
        } else {
            log_error("Failed to read temperature or humidity.");
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

