#include <signal.h>
#include <pigpio.h>

#define HDC1080_ADDR 0x40
#define CONFIG_REG 0x02
#define MEASUREMENT_REG 0x00

int i2c_handle;

// Function to initialize the HDC1080 sensor
int hdc1080_init(int i2c_handle) {
    // Configure the sensor for 14-bit temperature and humidity resolution
    char config_data[2] = {CONFIG_REG, 0x00}; // Default configuration
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1080 sensor
int hdc1080_read(int i2c_handle, float *temperature, float *humidity) {
    char trigger_data[1] = {MEASUREMENT_REG};
    char buffer[4];
    int result;

    // Trigger measurement
    result = i2cWriteDevice(i2c_handle, trigger_data, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    int raw_temp = (buffer[0] << 8) | buffer[1];
    int raw_humidity = (buffer[2] << 8) | buffer[3];

    *temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Function to log data to a file
void log_data(float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("enviro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HDC1080 sensor
    if (hdc1080_init(i2c_handle) != 0) {
        fprintf(stderr, "HDC1080 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature and humidity
        result = hdc1080_read(i2c_handle, &temperature, &humidity);

        if (result == 0) {
            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

