#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD 0x2C
#define MEASURE_ARG 0xE0
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"

int i2c_fd = -1;
FILE *log_fp = NULL;

// Function to calculate CRC8 checksum
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40 sensor
float read_sts40_temperature() {
    unsigned char buf[3];
    unsigned char cmd[2] = {MEASURE_CMD, MEASURE_ARG};
    int ret;

    // Send measurement command
    ret = write(i2c_fd, cmd, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Wait for conversion (10 ms)
    usleep(10000); // 10 ms

    // Read 3 bytes of data
    ret = read(i2c_fd, buf, 3);
    if (ret != 3) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Validate CRC
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature
    unsigned short raw_temperature = (buf[0] << 8) | buf[1];
    float temperature = -45.0 + 175.0 * raw_temperature / 65535.0;

    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_fp, "%s, %.2f\n", timestamp, temperature);
    fflush(log_fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    fprintf(stderr, "Signal received, closing resources...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_sts40_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping log.\n");
        }

        sleep(5); // Wait 5 seconds
    }

    return 0;
}

