// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x3615
#define LOG_FILE "hvac_pressure_log.txt"
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int init_i2c();
int init_logging();
void close_resources();
void signal_handler(int signal);
int read_sensor_data(SensorData *data);
uint8_t crc8(const uint8_t *data, int len);
int validate_data(const uint8_t *data);
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(SensorData data);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize logging
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

// Function to close resources
void close_resources() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read sensor data
int read_sensor_data(SensorData *data) {
    uint8_t buffer[9];
    int bytes_read;

    // Send continuous measurement command
    uint8_t cmd[2] = {(CONTINUOUS_MEASUREMENT_CMD >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for at least 50 ms
    gpioDelay(50000); // 50 ms

    // Read 9 bytes from the sensor
    bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C device: %d bytes read\n", bytes_read);
        return -1;
    }

    // Validate the data
    if (validate_data(buffer) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert the data
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    uint16_t scale_factor = (buffer[6] << 8) | buffer[7];
    int16_t raw_temperature = (buffer[2] << 8) | buffer[3];

    data->pressure = convert_pressure(raw_pressure, scale_factor);
    data->temperature = convert_temperature(raw_temperature);

    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate the data
int validate_data(const uint8_t *data) {
    uint8_t pressure_crc = data[2];
    uint8_t temperature_crc = data[5];
    uint8_t scale_factor_crc = data[8];

    uint8_t pressure_data[2] = {data[0], data[1]};
    uint8_t temperature_data[2] = {data[2], data[3]};
    uint8_t scale_factor_data[3] = {data[6], data[7], data[8]};

    if (crc8(pressure_data, 2) != pressure_crc) return -1;
    if (crc8(temperature_data, 2) != temperature_crc) return -1;
    if (crc8(scale_factor_data, 3) != scale_factor_crc) return -1;

    return 0;
}

// Function to convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0;
}

// Function to log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        close_resources();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }
        sleep(1);
    }

    // Close resources before exiting
    close_resources();

    return 0;
}

