#include <stdarg.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define BUFFER_CAPACITY 100
#define LOG_INTERVAL_SEC 60
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xE000
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Data Structures
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global Variables
volatile sig_atomic_t running = 1;
int i2c_handle;
CircularBuffer buffer;
pthread_t logging_thread;

// Function Prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
int validate_crc(uint8_t data[], int len, uint8_t checksum);
float convert_co2(uint16_t raw_co2);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
void buffer_init(CircularBuffer *buffer);
int buffer_add(CircularBuffer *buffer, SensorData data);
int buffer_get(CircularBuffer *buffer, SensorData *data);
void *logging_thread_func(void *arg);
void signal_handler(int signal);
void log_error(const char *format, ...);
void log_data(const char *format, ...);

// CRC-8-ATM Checksum Calculation
uint8_t crc8(uint8_t data[], int len, uint8_t checksum) {
    uint8_t crc = checksum;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send Command
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        log_error("Failed to write command 0x%04X: %d", command, result);
        return -1;
    }
    return 0;
}

// Read Data
int read_data(int handle, uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    char buf[9];
    int result = i2cReadDevice(handle, buf, 9);
    if (result != 9) {
        log_error("Failed to read data: %d", result);
        return -1;
    }

    uint8_t co2_data[2] = {buf[0], buf[1]};
    uint8_t temperature_data[2] = {buf[3], buf[4]};
    uint8_t humidity_data[2] = {buf[6], buf[7]};

    uint8_t co2_crc = buf[2];
    uint8_t temperature_crc = buf[5];
    uint8_t humidity_crc = buf[8];

    if (!validate_crc(co2_data, 2, co2_crc)) {
        log_error("CO2 CRC check failed");
        return -1;
    }
    if (!validate_crc(temperature_data, 2, temperature_crc)) {
        log_error("Temperature CRC check failed");
        return -1;
    }
    if (!validate_crc(humidity_data, 2, humidity_crc)) {
        log_error("Humidity CRC check failed");
        return -1;
    }

    *co2 = (uint16_t)co2_data[0] << 8 | co2_data[1];
    *temperature = (uint16_t)temperature_data[0] << 8 | temperature_data[1];
    *humidity = (uint16_t)humidity_data[0] << 8 | humidity_data[1];

    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int len, uint8_t checksum) {
    return crc8(data, len, 0xFF) == checksum;
}

// Convert CO2
float convert_co2(uint16_t raw_co2) {
    return (float)raw_co2;
}

// Convert Temperature
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Convert Humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Circular Buffer Initialization
void buffer_init(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Circular Buffer Add
int buffer_add(CircularBuffer *buffer, SensorData data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count == BUFFER_CAPACITY) {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Circular Buffer Get
int buffer_get(CircularBuffer *buffer, SensorData *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }
    *data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging Thread Function
void *logging_thread_func(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (running) {
        sleep(LOG_INTERVAL_SEC);

        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        pthread_mutex_unlock(&buffer.mutex);

        if (count > 0) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char filename[256];
            strftime(filename, sizeof(filename), LOG_DIR "%Y-%m-%d_%H-%M-%S.csv", tstruct);

            FILE *fp = fopen(filename, "w");
            if (fp == NULL) {
                log_error("Failed to open log file: %s", filename);
                continue;
            }

            fprintf(fp, "timestamp,CO2,temperature,humidity\n");

            pthread_mutex_lock(&buffer.mutex);
            int i = buffer.tail;
            for (int j = 0; j < count; j++) {
                fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", buffer.data[i].timestamp, buffer.data[i].co2, buffer.data[i].temperature, buffer.data[i].humidity);
                i = (i + 1) % BUFFER_CAPACITY;
            }
            pthread_mutex_unlock(&buffer.mutex);

            fclose(fp);
        }
    }
    return NULL;
}

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    log_data("Received signal %d, stopping...", signal);
}

// Log Error
void log_error(const char *format, ...) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(fp, "%s: ", timestamp);
    va_list args;
    va_start(args, format);
    vfprintf(fp, format, args);
    va_end(args);
    fprintf(fp, "\n");
    fclose(fp);
}

// Log Data
void log_data(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
    printf("\n");
}

int main() {
    // Create log directory if it doesn't exist
    if (access(LOG_DIR, F_OK) == -1) {
        if (mkdir(LOG_DIR, 0777) != 0) {
            perror("Failed to create log directory");
            return 1;
        }
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize Circular Buffer
    buffer_init(&buffer);

    // Start Logging Thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set Signal Handler
    signal(SIGINT, signal_handler);

    // Start Periodic Measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        running = 0; // Stop the main loop if starting measurement fails
    }

    // Main Loop
    while (running) {
        sleep(5);

        uint16_t raw_co2, raw_temperature, raw_humidity;
        if (read_data(i2c_handle, &raw_co2, &raw_temperature, &raw_humidity) == 0) {
            float co2 = convert_co2(raw_co2);
            float temperature = convert_temperature(raw_temperature);
            float humidity = convert_humidity(raw_humidity);

            time_t now = time(NULL);
            SensorData data = {now, co2, temperature, humidity};
            buffer_add(&buffer, data);

            log_data("CO2: %.2f ppm, Temperature: %.2f C, Humidity: %.2f %%", co2, temperature, humidity);
        } else {
            log_error("Failed to read sensor data");
        }
    }

    // Stop Periodic Measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Join Logging Thread
    pthread_join(logging_thread, NULL);

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    log_data("Program terminated gracefully");

    return 0;
}

