#define MEASURE_CMD 0x362F
#define LOG_FILE "sdp810_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_Pa;
    float temperature_C;
} SensorData;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
SensorData process_sensor_data(const uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

