        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Function to verify the sensor ID
int verify_sensor_id(int handle) {
    int who_am_i = i2cReadByteData(handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02x (expected 0x%02x)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    printf("Sensor ID verified successfully: 0x%02x\n", who_am_i);
    return 0;
}

// Function to read calibration coefficients
int read_calibration_coefficients(int handle, int32_t *c0, int32_t *c1, int32_t *c2, int32_t *c3) {
    char buffer[CALIB_END_REG - CALIB_START_REG + 1];
    int bytes_read = i2cReadI2CBlockData(handle, CALIB_START_REG, buffer, CALIB_END_REG - CALIB_START_REG + 1);

    if (bytes_read != CALIB_END_REG - CALIB_START_REG + 1) {
        fprintf(stderr, "Failed to read calibration coefficients: %d\n", bytes_read);
        return -1;
    }

    *c0 = (int32_t)((((uint32_t)buffer[0]) << 24) | (((uint32_t)buffer[1]) << 16) | (((uint32_t)buffer[2]) << 8) | ((uint32_t)buffer[3]));
    *c1 = (int32_t)((((uint32_t)buffer[4]) << 24) | (((uint32_t)buffer[5]) << 16) | (((uint32_t)buffer[6]) << 8) | ((uint32_t)buffer[7]));
    *c2 = (int32_t)((((uint32_t)buffer[8]) << 24) | (((uint32_t)buffer[9]) << 16) | (((uint32_t)buffer[10]) << 8) | ((uint32_t)buffer[11]));
    *c3 = (int32_t)((((uint32_t)buffer[12]) << 24) | (((uint32_t)buffer[13]) << 16) | (((uint32_t)buffer[14]) << 8) | ((uint32_t)buffer[15]));

    printf("Calibration coefficients read successfully:\n");
    printf("  c0: 0x%08x\n", *c0);
    printf("  c1: 0x%08x\n", *c1);
    printf("  c2: 0x%08x\n", *c2);
    printf("  c3: 0x%08x\n", *c3);

    return 0;
}

// Function to trigger a measurement
int trigger_measurement(int handle) {
    int result = i2cWriteByteData(handle, MEASURE_CMD_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, int32_t *pressure, int32_t *temperature) {
    char buffer[DATA_LENGTH];
    int bytes_read = i2cReadI2CBlockData(handle, DATA_START_REG, buffer, DATA_LENGTH);

    if (bytes_read != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)buffer[0]) << 24) | (((uint32_t)buffer[1]) << 16) | (((uint32_t)buffer[2]) << 8) | ((uint32_t)buffer[3]));
    *temperature = (int32_t)((((uint32_t)buffer[4]) << 24) | (((uint32_t)buffer[5]) << 16) | (((uint32_t)buffer[6]) << 8) | ((uint32_t)buffer[7]));

