    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, ICP10110_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_handle, &c0, &c1, &c2, &c3) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;

        // Trigger measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Error triggering measurement, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Wait for measurement to complete (adjust delay as needed)
        gpioDelay(10); // 10 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert data
        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Print data to stdout
        printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);

        free(timestamp);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

