    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            return raw_temp;
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, raw_temp);
            gpioDelay(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            retries--;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state
    static float last_temp = 0.0; // Track last temperature

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        last_temp = object_temp; // Update last temperature
    } else if (object_temp < (TEMP_THRESHOLD_LOW - HYSTERESIS_DELTA) && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        last_temp = object_temp; // Update last temperature
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw temperatures
        int raw_ambient = read_raw_temperature(i2c_handle, AMBIENT_TEMP_REG);
        int raw_object = read_raw_temperature(i2c_handle, OBJECT_TEMP_REG);

        if (raw_ambient >= 0 && raw_object >= 0) {
            // Convert to Celsius
            float ambient_temp = convert_to_celsius(raw_ambient);
            float object_temp = convert_to_celsius(raw_object);

            // Log temperature data
            log_temperature(ambient_temp, object_temp);

            // Control the fan
            control_fan(object_temp);

            printf("Ambient: %.2f C, Object: %.2f C\n", ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Failed to read temperatures. Skipping log entry.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

