#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int i2c_handle = -1;
int server_fd = -1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(SensorData *data);
int convert_data(unsigned short raw_temperature, unsigned short raw_humidity, SensorData *data);
int start_http_server();
void handle_client(int client_socket);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(SensorData *data) {
    unsigned char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(10); // Wait for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result == 6) {
            unsigned short raw_temperature = (buf[0] << 8) | buf[1];
            unsigned short raw_humidity = (buf[3] << 8) | buf[4];

            if (convert_data(raw_temperature, raw_humidity, data) != 0) {
                fprintf(stderr, "Data conversion failed (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(100);
                continue;
            }

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100);
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw data to temperature and humidity
int convert_data(unsigned short raw_temperature, unsigned short raw_humidity, SensorData *data) {
    data->temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
    data->humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);

    // Clamp humidity to 0-100%
    if (data->humidity < 0.0) data->humidity = 0.0;
    if (data->humidity > 100.0) data->humidity = 100.0;

    return 0;
}

// Function to start the HTTP server
int start_http_server() {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 8080
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 8080
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        return -1;
    }

    printf("HTTP server listening on port %d\n", PORT);
    return 0;
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    SensorData sensor_data;

    read(client_socket, buffer, 1024);

    if (read_sensor_data(&sensor_data) == 0) {
        char response[2048];
        snprintf(response, sizeof(response), 
                 "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n"
                 "<!DOCTYPE html><html><head><title>SHT40 Sensor Data</title></head><body>"
                 "<h1>SHT40 Sensor Data</h1>"
                 "<p>Temperature: %.2f &deg;C</p>"
                 "<p>Humidity: %.2f %%</p>"
                 "</body></html>",
                 sensor_data.temperature, sensor_data.humidity);

        send(client_socket, response, strlen(response), 0);
    } else {
        const char *error_response = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n"
                                     "<!DOCTYPE html><html><head><title>Error</title></head><body>"
                                     "<h1>Error</h1>"
                                     "<p>Failed to read sensor data</p>"
                                     "</body></html>";
        send(client_socket, error_response, strlen(error_response), 0);
    }

    close(client_socket);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (server_fd >= 0) {
        close(server_fd);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Start HTTP server
    if (start_http_server() != 0) {
        fprintf(stderr, "HTTP server startup failed. Exiting.\n");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int new_socket;

    while (!terminate) {
        // Accept incoming connections
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen))<0) {
            perror("accept");
            break;
        }

        // Handle client connection
        handle_client(new_socket);
    }

    // Cleanup resources before exiting
    cleanup();

    printf("Exiting.\n");
    return 0;
}

