#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define SLEEP_SECONDS 5
#define LOG_FILE "temperature_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(int *raw_temp);
float convert_to_celsius(int raw_temp);
int log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from TMP102
int read_temperature(int *raw_temp) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    *raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    if (*raw_temp & 0x800) {
        *raw_temp |= 0xF000; // Sign extend for 12-bit
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    return raw_temp * 0.0625;
}

// Log temperature to CSV file
int log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_temp;
        if (read_temperature(&raw_temp) == 0) {
            float temperature = convert_to_celsius(raw_temp);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping log.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

