{
    uint8_t config_data = 0x00; // Disable heater, 14-bit resolution
    if (write_register(handle, CONFIG, config_data) != 0) {
        fprintf(stderr, "Failed to write config register\n");
        return -1;
    }

    uint8_t measurement_data = 0x01; // Trigger measurement
    if (write_register(handle, MEASUREMENT_CONFIG, measurement_data) != 0) {
        fprintf(stderr, "Failed to write measurement config register\n");
        return -1;
    }

    // Wait for measurement to complete (polling MEASUREMENT_CONFIG bit 0)
