#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define DATA_LENGTH 6

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection(int bus, int addr);
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int n, uint8_t checksum);
int verify_crc(uint8_t data[], int n, uint8_t crc);
sensor_data_t parse_sensor_data(uint8_t *data);
void log_sensor_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int n, uint8_t checksum) {
    uint8_t crc = checksum;
    for (int i = 0; i < n; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Verify CRC checksum
int verify_crc(uint8_t data[], int n, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, n, 0xFF);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Parse sensor data
sensor_data_t parse_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;
    sensor_data.pressure = (int16_t)((data[0] << 8) | data[1]);
    sensor_data.temperature = (int16_t)((data[3] << 8) | data[4]);
    return sensor_data;
}

// Log sensor data
void log_sensor_data(sensor_data_t data) {
    printf("Pressure: %d Pa, Temperature: %d °C\n", data.pressure, data.temperature);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    i2c_handle = open_i2c_connection(I2C_BUS, SDP800_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send continuous measurement command
        if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Failed to send command, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement to complete (45 ms)
        gpioDelay(50); // Wait 50 ms

        // Read sensor data
        uint8_t data[DATA_LENGTH];
        if (read_sensor_data(i2c_handle, data, DATA_LENGTH) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Verify CRC checksums
        if (verify_crc(data, 2, data[2]) != 0 || verify_crc(data + 3, 2, data[5]) != 0) {
            fprintf(stderr, "CRC check failed, skipping data point...\n");
            continue;
        }

        // Parse sensor data
        sensor_data_t sensor_data = parse_sensor_data(data);

        // Log sensor data
        log_sensor_data(sensor_data);

        // Wait 500 ms
        gpioDelay(500000);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

