#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define TARGET_TEMP_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define MAX_SPI_RETRIES 3
#define SPI_RETRY_DELAY_MS 10

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for PID controller state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

// Function Prototypes
int read_max6675(int spi_handle, float *temperature);
int parse_target_profile(const char *filename, float **target_temperatures, int *times);
int initialize_gpio(int gpio_pin);
int set_relay_duty_cycle(int gpio_pin, float duty_cycle);
float calculate_pid(float setpoint, float actual_temperature, PIDState *pid_state, float kp, float ki, float kd);
void log_data(FILE *log_file, float temperature, float duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_max6675(int spi_handle, float *temperature) {
    char tx_buf[2] = {0x00, 0x00};
    char rx_buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_SPI_RETRIES) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
        if (result == 0) {
            // Success
            int raw_data = (rx_buf[0] << 8) | rx_buf[1];
            raw_data >>= 3; // Remove fault bit

            if (raw_data & 0x400) {
                fprintf(stderr, "Error: MAX6675 fault detected (open circuit).\n");
                return -1; // Indicate error
            }

            *temperature = (float)(raw_data & 0x07FF) * 0.25;
            return 0; // Success
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d).\n", retries + 1);
            retries++;
            gpioDelay(SPI_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Error: MAX6675 read failed after %d retries.\n", MAX_SPI_RETRIES);
    return -1; // Indicate failure after retries
}

// Function to parse target temperature profile from file
int parse_target_profile(const char *filename, float **target_temperatures, int **times) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open target temperature profile file.\n");
        return -1;
    }

    char line[256];
    int num_points = 0;

    // Count the number of lines in the file
    while (fgets(line, sizeof(line), fp) != NULL) {
        num_points++;
    }

    rewind(fp); // Reset file pointer to the beginning

    *target_temperatures = (float *)malloc(num_points * sizeof(float));
    *times = (int *)malloc(num_points * sizeof(int));

    if (*target_temperatures == NULL || *times == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        fclose(fp);
        return -1;
    }

    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%d,%f", &(*times)[i], &(*target_temperatures)[i]) == 2) {
            i++;
        } else {
            fprintf(stderr, "Error: Invalid line format in target temperature profile file.\n");
            fclose(fp);
            free(*target_temperatures);
            free(*times);
            return -1;
        }
    }

    fclose(fp);
    return num_points;
}

// Function to initialize GPIO
int initialize_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to set relay duty cycle
