// Function to read temperature from MAX6675
int read_max6675(int spi_handle, float *temperature) {
    char tx_buf[2] = {0x00, 0x00};
    char rx_buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_SPI_RETRIES) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
        if (result == 0) {
            // Success
            int raw_data = (rx_buf[0] << 8) | rx_buf[1];
            raw_data >>= 3; // Remove fault bit

            if (raw_data & 0x400) {
                fprintf(stderr, "Error: MAX6675 fault detected (open circuit).\n");
                return -1; // Indicate error
            }

            *temperature = (float)(raw_data & 0x07FF) * 0.25;
            return 0; // Success
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d).\n", retries + 1);
            retries++;
            gpioDelay(SPI_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Error: MAX6675 read failed after %d retries.\n", MAX_SPI_RETRIES);
    return -1; // Indicate failure after retries
}

