// Configuration
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "greenhouse.log"
#define SENSOR_DIR "/sys/bus/w1/devices/"
#define SENSOR_ID "28-xxxxxxxxxxxx" // Replace with your sensor ID
#define SENSOR_PATH SENSOR_DIR SENSOR_ID "/w1_slave"

// Default values
#define DEFAULT_SETPOINT 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// Global variables
static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *heater_line;
static struct gpiod_line *pwm_line;
static FILE *log_file;

// PID parameters
static double setpoint = DEFAULT_SETPOINT;
static double kp = DEFAULT_KP;
static double ki = DEFAULT_KI;
static double kd = DEFAULT_KD;

// PID variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
void signal_handler(int sig);
int initialize_gpio();
int initialize_pwm();
int read_temperature(double *temperature);
double calculate_pid(double setpoint, double kp, double ki, double kd, double current_temperature);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(double temperature, double setpoint, double pid_output, int duty_cycle);
int cleanup();

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        keep_running = 0;
    }
}

// Initialize GPIO
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    heater_line = gpiod_chip_get_line(chip, HEATER_GPIO);
    if (!heater_line) {
        perror("Error getting heater GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(heater_line, "greenhouse", 0) < 0) {
        perror("Error requesting heater GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!pwm_line) {
        perror("Error getting PWM GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse", 0) < 0) {
        perror("Error requesting PWM GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Initialize PWM
int initialize_pwm() {
