    //     perror("Error enabling PWM");
    //     return -1;
    // }

    return 0;
}

// Read temperature from DS18B20 sensor
int read_temperature(double *temperature) {
    FILE *fp;
    char buffer[256];
    char *token;
    int crc_ok = 0;
    double temp_value = 0.0;

    fp = fopen(SENSOR_PATH, "r");
    if (fp == NULL) {
        perror("Error opening sensor file");
        return -1;
    }

    // Read the file line by line
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (strstr(buffer, "YES")) {
            crc_ok = 1;
        }
        if (strstr(buffer, "t=")) {
            token = strstr(buffer, "t=") + 2;
            temp_value = atof(token) / 1000.0;
        }
    }

    fclose(fp);

    if (!crc_ok) {
        fprintf(stderr, "CRC check failed for sensor %s\n", SENSOR_ID);
        return -1;
    }

    *temperature = temp_value;
    return 0;
}

// Calculate PID output
double calculate_pid(double setpoint, double kp, double ki, double kd, double current_temperature) {
    double error = setpoint - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    // No direct PWM control in libgpiod.  We need to use sysfs.
    // This is a simplified example.  A real implementation would involve
    // writing to /sys/class/pwm/pwmchip0/pwm0/duty_cycle.
    // This example just sets the duty cycle to a fixed value.
    // For a real application, you would need to calculate the duty cycle
    // based on the desired percentage and the period.

    // Example: Set PWM duty cycle (in nanoseconds)
