int main(int argc, char *argv[]) {
    int opt;
    double temperature;
    double pid_output;
    int duty_cycle;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:k:i:d:")) != -1) {
        switch (opt) {
            case 's':
                setpoint = atof(optarg);
                break;
            case 'k':
                kp = atof(optarg);
                break;
            case 'i':
                ki = atof(optarg);
                break;
            case 'd':
                kd = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s setpoint] [-k kp] [-i ki] [-d kd]\n", argv[0]);
                return 1;
        }
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize PWM
    if (initialize_pwm() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Greenhouse control started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", setpoint, kp, ki, kd);

    // Main loop
    while (keep_running) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Calculate PID output
            pid_output = calculate_pid(setpoint, kp, ki, kd, temperature);

            // Set PWM duty cycle
            duty_cycle = (int)pid_output; // Assuming duty cycle is an integer percentage
            set_pwm_duty_cycle(duty_cycle);

            // Log data
            log_data(temperature, setpoint, pid_output, duty_cycle);

            printf("Temperature: %.2f, Setpoint: %.2f, PID Output: %.2f, Duty Cycle: %d\n", temperature, setpoint, pid_output, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature. Check sensor connection.\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

