#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define RELAY_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define POLL_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_aht20();
int read_aht20_data(float *humidity, float *temperature);
void control_relay(float humidity);
void log_data(float humidity, float temperature);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize AHT20 sensor
int initialize_aht20() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, init_cmd, 3);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "AHT20 initialization failed (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    fprintf(stderr, "AHT20 initialization failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read data from AHT20 sensor
int read_aht20_data(float *humidity, float *temperature) {
    char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    char data[6];
    int retries = 0;
    int result;

    // Trigger measurement
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, trigger_cmd, 3);
        if (result == 0) {
            break; // Success
        }
        fprintf(stderr, "AHT20 trigger failed (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "AHT20 trigger failed after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    // Read data
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, data, 6);
        if (result == 6) {
            break; // Success
        }
        fprintf(stderr, "AHT20 data read failed (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "AHT20 data read failed after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Verify status byte
    if ((data[0] & 0x80) != 0) {
        fprintf(stderr, "AHT20 sensor busy or not calibrated.\n");
        return -1;
    }

    // Calculate humidity and temperature
    unsigned long humidity_raw = ((unsigned long)data[1] << 12) | ((unsigned long)data[2] << 4) | (data[3] >> 4);
    unsigned long temperature_raw = ((unsigned long)(data[3] & 0x0F) << 16) | ((unsigned long)data[4] << 8) | data[5];

    *humidity = ((float)humidity_raw / 0x100000) * 100;
    *temperature = ((float)temperature_raw / 0x100000) * 200 - 50;

    return 0;
}

// Control relay based on humidity
void control_relay(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    }
}

// Log data with timestamp
void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Humidity: %.2f%%, Temperature: %.2f°C\n", timestamp, humidity, temperature);
}

int main() {
    float humidity, temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (initialize_aht20() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_aht20_data(&humidity, &temperature) == 0) {
            log_data(humidity, temperature);
            control_relay(humidity);
        } else {
            fprintf(stderr, "Failed to read AHT20 data\n");
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

