#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SLEEP_SECONDS 60

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *device);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg);
int read_htu21d(int fd, sensor_data_t *data);
int post_data(const char *url, const char *data);
void signal_handler(int sig);

// CRC-8-H2F checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial: x^8 + x^5 + x^4 + 1
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C initialization function
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", device);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: 0x%02X", HTU21D_ADDR);
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (i2c_write_byte(fd, reg) != 0) {
            syslog(LOG_ERR, "Failed to write register address: 0x%02X", reg);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            syslog(LOG_ERR, "I2C read failed (attempt %d/%d): %s", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
        }
    }

    syslog(LOG_ERR, "I2C read failed after %d retries.", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from HTU21D
int read_htu21d(int fd, sensor_data_t *data) {
    uint8_t buf[3];
    uint16_t raw_humidity;
    uint16_t raw_temperature;

    // Trigger humidity measurement
    if (i2c_write_byte(fd, 0xE5) != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement");
        return -1;
    }
    usleep(50000); // Wait 50ms

    if (i2c_read_bytes(fd, 0x00, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to read humidity data");
        return -1;
    }

    raw_humidity = (buf[0] << 8) | buf[1];
    uint8_t humidity_crc = buf[2];

    // Trigger temperature measurement
    if (i2c_write_byte(fd, 0xE3) != 0) {
        syslog(LOG_ERR, "Failed to trigger temperature measurement");
        return -1;
    }
    usleep(50000); // Wait 50ms

    if (i2c_read_bytes(fd, 0x00, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to read temperature data");
        return -1;
    }

    raw_temperature = (buf[0] << 8) | buf[1];
    uint8_t temperature_crc = buf[2];

    // CRC Check
    uint8_t humidity_data[2] = {buf[0], buf[1]};
    uint8_t temperature_data[2] = {buf[0], buf[1]};

