// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 registers
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_DATA_PRESS_MSB 0xF7

// Oversampling settings
#define BMP280_OVERSAMPLING_1X 0x01
#define BMP280_OVERSAMPLING_2X 0x02
#define BMP280_OVERSAMPLING_4X 0x03
#define BMP280_OVERSAMPLING_8X 0x04
#define BMP280_OVERSAMPLING_16X 0x05

// Forced mode
#define BMP280_FORCED_MODE 0x01

// Pressure threshold
#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int verify_chip_id();
int read_calibration_data();
int write_register(int reg, int value);
int read_register(int reg, char *buf, int len);
int read_raw_data(int32_t *raw_pressure, int32_t *raw_temperature);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
void log_pressure_threshold(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify BMP280 chip ID
int verify_chip_id() {
    char buf[1];
    if (read_register(BMP280_REG_CHIP_ID, buf, 1) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }
    if (buf[0] != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", buf[0]);
        return -1;
    }
    return 0;
}

// Read calibration data
int read_calibration_data() {
    char buf[26];
    if (read_register(BMP280_REG_CALIB_00, buf, 26) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    calib.dig_T2 = (int16_t)buf[2] | ((int16_t)buf[3] << 8);
    calib.dig_T3 = (int16_t)buf[4] | ((int16_t)buf[5] << 8);
    calib.dig_P1 = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);
    calib.dig_P2 = (int16_t)buf[8] | ((int16_t)buf[9] << 8);
    calib.dig_P3 = (int16_t)buf[10] | ((int16_t)buf[11] << 8);
    calib.dig_P4 = (int16_t)buf[12] | ((int16_t)buf[13] << 8);
    calib.dig_P5 = (int16_t)buf[14] | ((int16_t)buf[15] << 8);
    calib.dig_P6 = (int16_t)buf[16] | ((int16_t)buf[17] << 8);
    calib.dig_P7 = (int16_t)buf[18] | ((int16_t)buf[19] << 8);
    calib.dig_P8 = (int16_t)buf[20] | ((int16_t)buf[21] << 8);
    calib.dig_P9 = (int16_t)buf[22] | ((int16_t)buf[23] << 8);

    return 0;
}

// Write a register
int write_register(int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read a register
int read_register(int reg, char *buf, int len) {
    int result = i2cWriteDevice(i2c_handle, (char *)&reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, buf, len);
    if (result != len) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read raw data
int read_raw_data(int32_t *raw_pressure, int32_t *raw_temperature) {
    char buf[6];
    if (read_register(BMP280_REG_DATA_PRESS_MSB, buf, 6) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *raw_temperature = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);

    return 0;
}

// Compensate temperature
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temperature / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
