}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    if (verify_chip_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ctrl_meas
    if (write_register(BMP280_REG_CTRL_MEAS, BMP280_OVERSAMPLING_1X << 5 | BMP280_OVERSAMPLING_1X << 2 | BMP280_FORCED_MODE) != 0) {
