        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;
        double temperature, pressure;

        // Trigger measurement
        if (write_register(BMP280_REG_CTRL_MEAS, BMP280_OVERSAMPLING_1X << 5 | BMP280_OVERSAMPLING_1X << 2 | BMP280_FORCED_MODE) != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait 100ms before retry
            continue;
