        gpioDelay(10); // Wait for conversion (adjust as needed)

        // Read raw data
        if (read_raw_data(&raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            gpioDelay(100); // Wait 100ms before retry
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Log pressure threshold
        if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
            log_pressure_threshold(pressure);
        }

        printf("Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", temperature, pressure);

        gpioDelay(2000); // Sample every 2 seconds
    }

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

