    calib.dig_P6 = (int16_t)buf[16] | ((int16_t)buf[17] << 8);
    calib.dig_P7 = (int16_t)buf[18] | ((int16_t)buf[19] << 8);
    calib.dig_P8 = (int16_t)buf[20] | ((int16_t)buf[21] << 8);
    calib.dig_P9 = (int16_t)buf[22] | ((int16_t)buf[23] << 8);

    return 0;
}

// Write a register
int write_register(int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read a register
int read_register(int reg, char *buf, int len) {
    int result = i2cWriteDevice(i2c_handle, (char *)&reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, buf, len);
    if (result != len) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read raw data
int read_raw_data(int32_t *raw_pressure, int32_t *raw_temperature) {
    char buf[6];
    if (read_register(BMP280_REG_DATA_PRESS_MSB, buf, 6) != 0) {
