#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define TMP117_TEMP_REG 0x00
#define AHT20_INIT_CMD 0xBE
#define AHT20_MEASURE_CMD 0xAC
#define TMP117_TEMP_SCALE 0.0078125
#define AHT20_HUMIDITY_SCALE 0.000125
#define AHT20_TEMPERATURE_SCALE 0.001953125
#define MAX_RETRIES 3
#define BACKOFF_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *data, int len);
float read_tmp117_temperature(int fd);
float read_aht20_humidity(int fd);
float read_aht20_temperature(int fd);
int read_pir_sensor(struct gpiod_line *line);
int log_data(float temperature, float humidity, int motion);
void signal_handler(int sig);
int check_sensor_presence(int fd);

// I2C read function with retry and backoff
int i2c_read_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        ioctl(fd, I2C_SLAVE, addr);
        result = read(fd, data, len);

        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(BACKOFF_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retry and backoff
int i2c_write_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    int result;
    uint8_t combined_data[len + 1];
    combined_data[0] = reg;
    memcpy(combined_data + 1, data, len);

    while (retries < MAX_RETRIES) {
        ioctl(fd, I2C_SLAVE, addr);
        result = write(fd, combined_data, len + 1);

        if (result == len + 1) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            usleep(BACKOFF_DELAY_MS * 1000); // Exponential backoff
        }
    }

    fprintf(stderr, "I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read temperature from TMP117 sensor
float read_tmp117_temperature(int fd) {
    uint8_t data[2];
    int16_t raw_temp;

    if (i2c_read_bytes(fd, TMP117_ADDR, TMP117_TEMP_REG, data, 2) != 0) {
        fprintf(stderr, "Failed to read temperature from TMP117.\n");
        return -1000.0; // Indicate error
    }

    raw_temp = (data[0] << 8) | data[1];
    return (float)raw_temp * TMP117_TEMP_SCALE;
}

// Read humidity from AHT20 sensor
float read_aht20_humidity(int fd) {
    uint8_t data[6];
    uint32_t raw_humidity;

    // Trigger measurement
    uint8_t init_cmd[] = {AHT20_INIT_CMD, 0x08, 0x00};
    if (i2c_write_bytes(fd, AHT20_ADDR, 0x00, init_cmd, 3) != 0) {
        fprintf(stderr, "Failed to initialize AHT20.\n");
        return -1.0;
    }
    usleep(10000); // Wait for initialization

    uint8_t measure_cmd[] = {AHT20_MEASURE_CMD, 0x33, 0x00};
    if (i2c_write_bytes(fd, AHT20_ADDR, 0x00, measure_cmd, 3) != 0) {
        fprintf(stderr, "Failed to trigger measurement on AHT20.\n");
        return -1.0;
    }
    usleep(80000); // Wait for measurement (at least 75ms)

    if (i2c_read_bytes(fd, AHT20_ADDR, 0x00, data, 6) != 0) {
        fprintf(stderr, "Failed to read data from AHT20.\n");
        return -1.0;
    }

    // Check busy bit
    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 is busy.\n");
        return -1.0;
    }

    raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    return ((float)raw_humidity * AHT20_HUMIDITY_SCALE) * 100.0; // Percentage
}

// Read temperature from AHT20 sensor
float read_aht20_temperature(int fd) {
    uint8_t data[6];
    uint32_t raw_temperature;

    // Trigger measurement
    uint8_t init_cmd[] = {AHT20_INIT_CMD, 0x08, 0x00};
    if (i2c_write_bytes(fd, AHT20_ADDR, 0x00, init_cmd, 3) != 0) {
        fprintf(stderr, "Failed to initialize AHT20.\n");
        return -1.0;
    }
    usleep(10000); // Wait for initialization

    uint8_t measure_cmd[] = {AHT20_MEASURE_CMD, 0x33, 0x00};
    if (i2c_write_bytes(fd, AHT20_ADDR, 0x00, measure_cmd, 3) != 0) {
        fprintf(stderr, "Failed to trigger measurement on AHT20.\n");
        return -1.0;
    }
    usleep(80000); // Wait for measurement (at least 75ms)

    if (i2c_read_bytes(fd, AHT20_ADDR, 0x00, data, 6) != 0) {
        fprintf(stderr, "Failed to read data from AHT20.\n");
        return -1.0;
    }

    // Check busy bit
    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 is busy.\n");
        return -1.0;
    }

    raw_temperature = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | ((uint32_t)data[5]);
    return ((float)raw_temperature * AHT20_TEMPERATURE_SCALE);
}

// Read PIR sensor value
int read_pir_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Failed to read PIR sensor value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Log data to CSV file
int log_data(float temperature, float humidity, int motion) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Check sensor presence by reading temperature from TMP117
int check_sensor_presence(int fd) {
    float temperature = read_tmp117_temperature(fd);
    if (temperature < -900.0) { // Arbitrary low temperature to indicate failure
        fprintf(stderr, "TMP117 sensor not found.\n");
        return 0; // Sensor not present
    }
    return 1; // Sensor present
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Check TMP117 sensor presence
    if (!check_sensor_presence(i2c_fd)) {
        fprintf(stderr, "TMP117 sensor not found. Continuing without it.\n");
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line as input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Create log file
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[64];
    strftime(filename, sizeof(filename), "home_automation_%Y-%m-%d.csv", t);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    fflush(log_file);

    // Main loop
    while (!terminate) {
        float temperature = -1000.0; // Initialize to an invalid value
        float humidity = -1.0;
        int motion = -1;

        // Read sensor data
        if (check_sensor_presence(i2c_fd)) {
            temperature = read_tmp117_temperature(i2c_fd);
            humidity = read_aht20_humidity(i2c_fd);
            read_aht20_temperature(i2c_fd); // Read temperature even if humidity fails
        }

        motion = read_pir_sensor(gpio_line);

        // Log data
        if (log_data(temperature, humidity, motion) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        sleep(1);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

