    if (direction == 1) { // Forward
        ret = gpiod_line_set_value(in1_line, 1);
        if (ret < 0) {
            log_event("Error setting IN1 high");
            return -1;
        }
        ret = gpiod_line_set_value(in2_line, 0);
        if (ret < 0) {
            log_event("Error setting IN2 low");
