    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_sensor_line || !motor_ena_line || !motor_in1_line || !motor_in2_line) {
        perror("Error getting GPIO line");
        log_event("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input and output
    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor") < 0) {
        perror("Error requesting rain sensor line for input");
        log_event("Error requesting rain sensor line for input");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(motor_ena_line, "motor_ena", 0) < 0) {
        perror("Error requesting motor ENA line for output");
        log_event("Error requesting motor ENA line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0) < 0) {
        perror("Error requesting motor IN1 line for output");
        log_event("Error requesting motor IN1 line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0) < 0) {
        perror("Error requesting motor IN2 line for output");
        log_event("Error requesting motor IN2 line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    log_event("Rain sensor monitoring started");

    // Main loop
    while (1) {
        rain_detected = read_rain_sensor(rain_sensor_line);
        if (rain_detected == 0) {
            log_event("Rain detected!");
            if (control_motor(motor_ena_line, motor_in1_line, motor_in2_line, 1) == 0) {
                log_event("Motor started (forward)");
                sleep(5);
                if (control_motor(motor_ena_line, motor_in1_line, motor_in2_line, 0) == 0) {
                    log_event("Motor stopped");
                } else {
                    log_event("Error stopping motor");
                }
            } else {
                log_event("Error starting motor");
            }
        } else if (rain_detected < 0) {
            log_event("Error reading rain sensor");
        }

        sleep(2);
    }

    return 0;
}

