#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variables for CPU load and pigpio initialization
double cpu_load = 0.0;
int pigpio_initialized = 0;

// Function prototypes
double calculate_cpu_load();
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Terminate pigpio
    if (pigpio_initialized) {
        gpioTerminate();
    }

    exit(0);
}

// Function to calculate CPU load
double calculate_cpu_load() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    double cpu_usage;
    static unsigned long long prev_total = 0, prev_idle_total = 0;
    unsigned long long total, idle_total;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return 0.0; // Return 0.0 on error
    }

    fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    idle_total = idle + iowait;

    if (prev_total != 0) {
        unsigned long long delta_total = total - prev_total;
        unsigned long long delta_idle = idle_total - prev_idle_total;
        cpu_usage = (double)(delta_total - delta_idle) / delta_total;
    } else {
        cpu_usage = 0.0;
    }

    prev_total = total;
    prev_idle_total = idle_total;

    return cpu_usage;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Clamp values to 0-255 range
    if (red < 0) red = 0;
    if (red > 255) red = 255;
    if (green < 0) green = 0;
    if (green > 255) green = 255;
    if (blue < 0) blue = 0;
    if (blue > 255) blue = 255;

    // Set PWM duty cycle for each channel
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Main loop
    while (1) {
        // Calculate CPU load
        cpu_load = calculate_cpu_load();

        // Map CPU load to RGB color gradient
        int red = 0, green = 0, blue = 0;
        if (cpu_load < 0.5) {
            green = (int)(cpu_load * 2 * 255);
        } else {
            red = (int)((cpu_load - 0.5) * 2 * 255);
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Wait for 500 milliseconds
        gpioDelay(500000); // pigpio's delay function takes microseconds
    }

    return 0;
}

