    static unsigned long long prev_total = 0, prev_idle_total = 0;
    unsigned long long total, idle_total;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return 0.0; // Return 0.0 on error
    }

    fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
           &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    idle_total = idle + iowait;

    if (prev_total != 0) {
        unsigned long long delta_total = total - prev_total;
        unsigned long long delta_idle = idle_total - prev_idle_total;
        cpu_usage = (double)(delta_total - delta_idle) / delta_total;
    } else {
        cpu_usage = 0.0;
    }

    prev_total = total;
    prev_idle_total = idle_total;

    return cpu_usage;
}

