    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Main loop
    while (1) {
        // Calculate CPU load
        cpu_load = calculate_cpu_load();

        // Map CPU load to RGB color gradient
        int red = 0, green = 0, blue = 0;
        if (cpu_load < 0.5) {
            green = (int)(cpu_load * 2 * 255);
        } else {
            red = (int)((cpu_load - 0.5) * 2 * 255);
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Wait for 500 milliseconds
        gpioDelay(500000); // pigpio's delay function takes microseconds
    }

    return 0;
}

