    float temperature;
    int pwm_duty_cycle;
} TemperatureReading;

// Circular buffer
TemperatureReading temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int speed, int mode);
int read_max31855(int spi_handle, uint32_t *data);
float extract_temperature(uint32_t raw_data);
int check_fault(uint32_t raw_data);
int calculate_pwm_duty_cycle(float temperature);
int set_fan_speed(int gpio, int duty_cycle);
void add_to_buffer(time_t timestamp, float temperature, int pwm_duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi(int channel, int speed, int mode) {
    int spi_handle = spiOpen(channel, speed, mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return spi_handle;
}

// Function to read data from MAX31855
int read_max31855(int spi_handle, uint32_t *data) {
    char tx_buf[4] = {0, 0, 0, 0}; // Dummy data for reading
    char rx_buf[4];

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (result != 4) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    *data = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];
    return 0;
}

// Function to extract temperature from raw data
float extract_temperature(uint32_t raw_data) {
    // Check for fault bit
    if (raw_data & 0x00000001) {
        fprintf(stderr, "MAX31855 Fault detected: %08X\n", raw_data);
        return -1000.0; // Indicate an error
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask and shift

    // Handle negative temperatures
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend
    }

    return thermocouple_data * 0.25;
}

// Function to check for faults
int check_fault(uint32_t raw_data) {
    if (raw_data & 0x00000001) {
        if (raw_data & 0x00000002) {
            fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        } else if (raw_data & 0x00000004) {
            fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        } else if (raw_data & 0x00000008) {
            fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        } else {
            fprintf(stderr, "MAX31855 Fault: Unknown\n");
        }
        return -1;
    }
    return 0;
}

// Function to calculate PWM duty cycle
int calculate_pwm_duty_cycle(float temperature) {
    if (temperature < TEMP_MIN) {
        return 0;
    } else if (temperature < TEMP_MIN + 10) {
        return (int)((temperature - TEMP_MIN) * 50.0 / 10.0);
    } else if (temperature < TEMP_MIN + 30) {
        return 50 + (int)((temperature - (TEMP_MIN + 10)) * 50.0 / 30.0);
    } else if (temperature < TEMP_MIN + 50) {
        return 100 + (int)((temperature - (TEMP_MIN + 30)) * 100.0 / 20.0);
    } else {
        return 255;
    }
}

// Function to set fan speed
int set_fan_speed(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }
    gpioPWM(gpio, duty_cycle);
    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int pwm_duty_cycle) {
    temperature_buffer[buffer_index].timestamp = timestamp;
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].pwm_duty_cycle = pwm_duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&temperature_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C, PWM: %d\n", timestamp_str, temperature_buffer[index].temperature, temperature_buffer[index].pwm_duty_cycle);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    int spi_handle = initialize_spi(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, 1000); // 1 kHz
    gpioSetPWMrange(FAN_GPIO, 255);

    uint32_t raw_data;
    float temperature;
    int pwm_duty_cycle;
    time_t current_time;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &raw_data) == 0) {
            // Extract temperature
            temperature = extract_temperature(raw_data);

            // Check for errors
            if (temperature > -999.0) {
                // Calculate PWM duty cycle
                pwm_duty_cycle = calculate_pwm_duty_cycle(temperature);

                // Set fan speed
                if (set_fan_speed(FAN_GPIO, pwm_duty_cycle) != 0) {
                    fprintf(stderr, "Failed to set fan speed\n");
                }

                // Get current timestamp
                current_time = time(NULL);

                // Add to buffer
                add_to_buffer(current_time, temperature, pwm_duty_cycle);

                // Print buffer (every 5th reading)
                if (buffer_index % 5 == 0) {
                    print_buffer();
                }
            } else {
                fprintf(stderr, "Failed to read temperature\n");
            }
        } else {
            fprintf(stderr, "Failed to read MAX31855 data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Stop the fan
    spiClose(spi_handle);
    gpioTerminate();

    // Print the final buffer
    print_buffer();

    return 0;
}

