#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int gpio_init(const char *chip, int pin);
int max31865_init();
int read_max31865_register(unsigned char reg, unsigned char *value);
int write_max31865_register(unsigned char reg, unsigned char value);
int read_rtd_data(unsigned short *rtd_value);
int check_fault_status(unsigned char *fault_status);
double calculate_temperature(unsigned short rtd_value);
int log_data(double temperature);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device) {
    spi_fd = open(device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    unsigned char mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed (1 MHz)
    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(const char *chip, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "rtd_monitor", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// MAX31865 initialization function
int max31865_init() {
    // Configure for 3-wire RTD mode with bias voltage enabled
    unsigned char config_value = 0xC2; // RTD_POL_HIGH, 3-WIRE, 50HZ, 500MS_FILTER, VBIAS_ON
    if (write_max31865_register(MAX31865_CONFIG_REG, config_value) < 0) {
        fprintf(stderr, "Error configuring MAX31865\n");
        return -1;
    }
    return 0;
}

// Read data from a specific register
int read_max31865_register(unsigned char reg, unsigned char *value) {
    unsigned char tx_buf[2];
    unsigned char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00;       // Dummy byte for reading

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error reading SPI message");
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

// Write data to a specific register
int write_max31865_register(unsigned char reg, unsigned char value) {
    unsigned char tx_buf[2];
    unsigned char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = value;

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error writing SPI message");
        return -1;
    }

    return 0;
}

// Read RTD value from the MAX31865
int read_rtd_data(unsigned short *rtd_value) {
    unsigned char rtd_msb, rtd_lsb;

    if (read_max31865_register(MAX31865_RTD_MSB_REG, &rtd_msb) < 0) {
        fprintf(stderr, "Error reading RTD MSB\n");
        return -1;
    }

    if (read_max31865_register(MAX31865_RTD_LSB_REG, &rtd_lsb) < 0) {
        fprintf(stderr, "Error reading RTD LSB\n");
        return -1;
    }

    *rtd_value = ((unsigned short)rtd_msb << 8) | rtd_lsb;
    *rtd_value = *rtd_value >> 1; // Remove fault bit

    return 0;
}

// Check the fault status register
int check_fault_status(unsigned char *fault_status) {
    if (read_max31865_register(MAX31865_FAULT_REG, fault_status) < 0) {
        fprintf(stderr, "Error reading fault status\n");
        return -1;
    }
    return 0;
}

// Calculate temperature using the Callendar-Van Dusen equation
double calculate_temperature(unsigned short rtd_value) {
    // Assuming 100k ohm load resistance
    double rtd_resistance = rtd_value * 430.0 / 32768.0; // 430 ohms is the typical value
    double temperature = (rtd_resistance - 100.0) / 0.385; // Callendar-Van Dusen equation
    return temperature;
}

// Log data to a CSV file
int log_data(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init(SPI_DEVICE) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize MAX31865
    if (max31865_init() < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fprintf(stderr, "RTD monitor started. Logging to %s\n", LOG_FILE);

    // Main loop
    while (!terminate) {
        unsigned short rtd_value;
        unsigned char fault_status;
        double temperature;

        // Read RTD data
        if (read_rtd_data(&rtd_value) < 0) {
            fprintf(stderr, "Error reading RTD data\n");
            // Continue to the next iteration even if reading fails
        } else {
            // Check fault status
            if (check_fault_status(&fault_status) < 0) {
                fprintf(stderr, "Error checking fault status\n");
                // Continue to the next iteration even if fault checking fails
            } else {
                // Calculate temperature
                temperature = calculate_temperature(rtd_value);

                // Log data
                if (log_data(temperature) < 0) {
                    fprintf(stderr, "Error logging data\n");
                }

                // Print temperature to console
                printf("Temperature: %.2f C\n", temperature);
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "RTD monitor terminated.\n");
    return 0;
}

