#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define ALERT_GPIO 24
#define BUFFER_SIZE 60 // seconds * 10 Hz
#define SAMPLE_INTERVAL_MS 50
#define ALERT_THRESHOLD_HPA 5.0
#define OSS 0 // Ultra-low power

// BMP180 Registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration Data Registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Global Variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular Buffer Structure
typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

PressureReading pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Calibration Data Structure
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} BMP180CalibrationData;

BMP180CalibrationData calibration_data;

// Function Prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_pressure(int raw_temperature, int raw_pressure);
void add_to_buffer(float pressure);
float calculate_rolling_average();
void check_pressure_deviation(float current_pressure, float rolling_average);
void timer_callback();
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C device
int read_i2c_word(int handle, uint8_t reg, int16_t *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C word from register 0x%02X\n", reg);
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to write a byte to the I2C device
int write_i2c_byte(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) != 0) {
        fprintf(stderr, "Error writing I2C byte to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, &calibration_data.ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &calibration_data.ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &calibration_data.ac3) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC4, (int16_t*)&calibration_data.ac4) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC5, (int16_t*)&calibration_data.ac5) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC6, (int16_t*)&calibration_data.ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, &calibration_data.b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, &calibration_data.b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, &calibration_data.mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, &calibration_data.mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, &calibration_data.md) != 0) return -1;

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temperature) {
    if (write_i2c_byte(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) return -1; // Request temperature reading
    gpioDelay(5000); // Wait 5ms

    int16_t ut;
    if (read_i2c_word(i2c_handle, BMP180_REG_MSB, &ut) != 0) return -1;

    *raw_temperature = ut;
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure) {
    if (write_i2c_byte(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) return -1; // Request pressure reading
    gpioDelay(2 + (3 << OSS)) ; // Wait for conversion

    int32_t up;
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - OSS);

    *raw_pressure = up;
    return 0;
}

// Function to calculate the compensated pressure value
float calculate_pressure(int raw_temperature, int raw_pressure) {
    int32_t X1, X2, X3, B3, B5, B6, p;
    uint32_t B4, B7;

    X1 = ((int32_t)raw_temperature - (int32_t)calibration_data.ac6) * ((int32_t)calibration_data.ac5) / pow(2, 15);
    X2 = ((int32_t)calibration_data.mc * pow(2, 11)) / (X1 + calibration_data.md);
    B5 = X1 + X2;

    B6 = B5 - 4000;
    X1 = (calibration_data.b2 * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    X2 = calibration_data.ac2 * B6 / pow(2, 11);
    X3 = X1 + X2;
    B3 = (((calibration_data.ac1 * 4 + X3) << OSS) + 2) / 4;

    X1 = calibration_data.ac3 * B6 / pow(2, 13);
    X2 = (calibration_data.b1 * (B6 * B6 / pow(2, 12))) / pow(2, 16);
    X3 = ((X1 + X2) + 2) / pow(2, 2);
    B4 = calibration_data.ac4 * (uint32_t)(X3 + 32768) / pow(2, 15);
    B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);

    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    p = p + (X1 + X2 + 3791) / pow(2, 4);

    return (float)p;
}

// Function to add a new pressure reading to the circular buffer
void add_to_buffer(float pressure) {
    time(&pressure_buffer[buffer_index].timestamp);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of the pressure readings
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / BUFFER_SIZE;
}

// Function to check for pressure deviation and trigger an alert
void check_pressure_deviation(float current_pressure, float rolling_average) {
    float deviation = current_pressure - rolling_average;
    if (deviation < 0) deviation = -deviation; // Absolute value

    if (deviation > ALERT_THRESHOLD_HPA) {
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        fprintf(stderr, "ALERT: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa, Deviation: %.2f hPa\n", current_pressure, rolling_average, deviation);
    } else {
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Timer callback function
void timer_callback() {
    int raw_temperature, raw_pressure;
    float pressure;
    float rolling_average;

    if (read_raw_temperature(&raw_temperature) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }

    pressure = calculate_pressure(raw_temperature, raw_pressure);

    add_to_buffer(pressure);
    rolling_average = calculate_rolling_average();
    check_pressure_deviation(pressure, rolling_average);

    printf("Timestamp: %ld, Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", time(NULL), pressure, rolling_average);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for alert
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Initially LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer callback function
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and exit
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

