#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "fan_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp = -1.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000.0;
    }

    fclose(fp);
    return temp;
}

// Function to set fan speed using PWM
void set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
    }
}

// Function to map temperature to duty cycle
int map_temp_to_duty(float temperature) {
    int duty_cycle = 0;

    if (temperature < 40.0) {
        duty_cycle = 0;
    } else if (temperature > 70.0) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 255.0);
    }

    return duty_cycle;
}

// Function to log data to file
void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f°C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Stop the fan
    set_fan_speed(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        float temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read CPU temperature\n");
        } else {
            int duty_cycle = map_temp_to_duty(temperature);
            set_fan_speed(duty_cycle);
            log_data(temperature, duty_cycle);
        }

        sleep(5);
    }

    return 0;
}

