#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// BMP280 I2C address
#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77

// BMP280 registers
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_PRESS_MSB 0xF7

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP_X1 0x01
#define BMP280_OVERSAMPLING_PRESS_X1 0x01
#define BMP280_MODE_FORCED 0x01

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static int bmp280_address = BMP280_ADDR_1;

// Function prototypes
int init_i2c(int bus, int addr);
int read_register(int fd, uint8_t reg, uint8_t *data, int len);
int write_register(int fd, uint8_t reg, uint8_t data);
int read_calibration_data(int fd, bmp280_calib_data *calib);
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temp, bmp280_calib_data calib);
double compensate_pressure(int32_t raw_press, int32_t t_fine, bmp280_calib_data calib);
int log_data(double temperature, double pressure);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", filename);
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address: 0x%02x\n", addr);
        close(fd);
        return -1;
    }
    return fd;
}

// Read a register
int read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    return 0;
}

// Write a register
int write_register(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    return 0;
}

// Read calibration data
int read_calibration_data(int fd, bmp280_calib_data *calib) {
    uint8_t data[24];
    if (read_register(fd, BMP280_REG_CALIB_00, data, 24) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw data
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (read_register(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature
double compensate_temperature(int32_t raw_temp, bmp280_calib_data calib) {
    double var1, var2, T;
    double dig_T1 = (double)calib.dig_T1;
    double dig_T2 = (double)calib.dig_T2;
    double dig_T3 = (double)calib.dig_T3;
    double adc_T = (double)raw_temp;

    var1 = (adc_T / 16384.0 - dig_T1 / 1024.0) * dig_T2;
    var2 = ((adc_T / 131072.0 - dig_T1 / 8192.0) * (adc_T / 131072.0 - dig_T1 / 8192.0)) * dig_T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double compensate_pressure(int32_t raw_press, int32_t t_fine, bmp280_calib_data calib) {
    double var1, var2, p;
    double dig_P1 = (double)calib.dig_P1;
    double dig_P2 = (double)calib.dig_P2;
    double dig_P3 = (double)calib.dig_P3;
    double dig_P4 = (double)calib.dig_P4;
    double dig_P5 = (double)calib.dig_P5;
    double dig_P6 = (double)calib.dig_P6;
    double dig_P7 = (double)calib.dig_P7;
    double dig_P8 = (double)calib.dig_P8;
    double dig_P9 = (double)calib.dig_P9;
    double adc_P = (double)raw_press;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - adc_P;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = dig_P9 * p * p / 2147483648.0;
    var2 = p * dig_P8 / 32768.0;
    p = p + (var1 + var2 + dig_P7) / 16.0;

    return p;
}

// Log data to file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file);

    return 0;
}

int main() {
    bmp280_calib_data calib;
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;
    uint8_t chip_id;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("weather_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(1, BMP280_ADDR_1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C with address 0x%02x, trying 0x%02x\n", BMP280_ADDR_1, BMP280_ADDR_2);
        i2c_fd = init_i2c(1, BMP280_ADDR_2);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to initialize I2C with address 0x%02x\n", BMP280_ADDR_2);
            fclose(log_file);
            return 1;
        }
        bmp280_address = BMP280_ADDR_2;
    } else {
        bmp280_address = BMP280_ADDR_1;
    }

    // Verify chip ID
    if (read_register(i2c_fd, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Configure sensor for forced mode
        if (write_register(i2c_fd, BMP280_REG_CTRL_MEAS, (BMP280_OVERSAMPLING_TEMP_X1 << 5) | (BMP280_OVERSAMPLING_PRESS_X1 << 2) | BMP280_MODE_FORCED) != 0) {
            fprintf(stderr, "Error writing to ctrl_meas register\n");
            break;
        }

        // Wait for measurement to complete (with timeout)
        int timeout = 0;
        uint8_t status;
        do {
            if (read_register(i2c_fd, BMP280_REG_STATUS, &status, 1) != 0) {
                fprintf(stderr, "Error reading status register\n");
                break;
            }
            if (status & 0x08) {
                break; // Measuring bit is set, measurement is complete
            }
            usleep(10000); // Wait 10ms
            timeout++;
            if (timeout > 100) { // Timeout after 1000ms (100 * 10ms)
                fprintf(stderr, "Timeout waiting for measurement\n");
                break;
            }
        } while (!(status & 0x08));

        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data\n");
            break;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calib);
        pressure = compensate_pressure(raw_pressure, raw_temperature, calib);

        // Log data
        if (log_data(temperature, pressure) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        sleep(5);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

