        fprintf(stderr, "Error reading chip ID\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02x\n", chip_id);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Configure sensor for forced mode
        if (write_register(i2c_fd, BMP280_REG_CTRL_MEAS, (BMP280_OVERSAMPLING_TEMP_X1 << 5) | (BMP280_OVERSAMPLING_PRESS_X1 << 2) | BMP280_MODE_FORCED) != 0) {
            fprintf(stderr, "Error writing to ctrl_meas register\n");
            break;
        }

        // Wait for measurement to complete (with timeout)
        int timeout = 0;
        uint8_t status;
        do {
            if (read_register(i2c_fd, BMP280_REG_STATUS, &status, 1) != 0) {
                fprintf(stderr, "Error reading status register\n");
                break;
            }
            if (status & 0x08) {
                break; // Measuring bit is set, measurement is complete
            }
            usleep(10000); // Wait 10ms
            timeout++;
            if (timeout > 100) { // Timeout after 1000ms (100 * 10ms)
                fprintf(stderr, "Timeout waiting for measurement\n");
                break;
            }
        } while (!(status & 0x08));

        // Read raw data
        if (read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data\n");
            break;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calib);
        pressure = compensate_pressure(raw_pressure, raw_temperature, calib);

        // Log data
        if (log_data(temperature, pressure) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        sleep(5);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

