#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define CONFIG_FILE "config.json"
#define DEFAULT_TARGET_TEMPERATURE 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MAX_SPI_RETRIES 3

// Global variables
static int spi_handle;
static int gpio_pin;
static double target_temperature;
static double kp, ki, kd;
static volatile sig_atomic_t terminate = 0;

// PID variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
int read_config(const char *filename, double *target_temp, double *kp, double *ki, double *kd);
int init_gpio(int pin);
int init_spi(int channel, int speed);
int init_max31865(int spi_handle);
double read_temperature(int spi_handle);
double calculate_pid(double setpoint, double actual_value, double kp, double ki, double kd);
void set_pwm_duty_cycle(int pin, int duty_cycle);
void signal_handler(int signal);
void log_error(const char *message);

// Function to read configuration from JSON file
int read_config(const char *filename, double *target_temp, double *kp, double *ki, double *kd) {
    json_t *root, *config;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        *target_temp = DEFAULT_TARGET_TEMPERATURE;
        *kp = DEFAULT_KP;
        *ki = DEFAULT_KI;
        *kd = DEFAULT_KD;
        return -1;
    }

    config = json_object_get(root, "heater_control");
    if (!config) {
        fprintf(stderr, "Error: Could not find 'heater_control' in config file\n");
        json_decref(root);
        *target_temp = DEFAULT_TARGET_TEMPERATURE;
        *kp = DEFAULT_KP;
        *ki = DEFAULT_KI;
        *kd = DEFAULT_KD;
        return -1;
    }

    json_t *target = json_object_get(config, "target_temperature");
    json_t *p = json_object_get(config, "Kp");
    json_t *i = json_object_get(config, "Ki");
    json_t *d = json_object_get(config, "Kd");

    if (!target || !p || !i || !d) {
        fprintf(stderr, "Error: Could not find PID gains or target temperature in config file\n");
        json_decref(root);
        *target_temp = DEFAULT_TARGET_TEMPERATURE;
        *kp = DEFAULT_KP;
        *ki = DEFAULT_KI;
        *kd = DEFAULT_KD;
        return -1;
    }

    *target_temp = json_number_value(target);
    *kp = json_number_value(p);
    *ki = json_number_value(i);
    *kd = json_number_value(d);

    json_decref(root);
    return 0;
}

// Function to initialize GPIO
int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int init_spi(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        log_error("Failed to open SPI channel");
        return -1;
    }
    return handle;
}

// Function to initialize MAX31865
int init_max31865(int spi_handle) {
    char buf[2];
    buf[0] = 0x80; // Configuration register address
    buf[1] = 0xC1; // Enable VBIAS, auto-conversion, clear faults

    if (spiWrite(spi_handle, buf, 2) != 0) {
        log_error("Failed to write to MAX31865 configuration register");
        return -1;
    }
    return 0;
}

// Function to read temperature from MAX31865
double read_temperature(int spi_handle) {
    char buf[3];
    int retries = 0;
    int status;

    while (retries < MAX_SPI_RETRIES) {
        buf[0] = 0x01; // MSB register address
        if (spiXfer(spi_handle, buf, buf, 3) == 0) {
            // Check for fault bit (D0 of MSB)
            if (buf[1] & 0x01) {
                log_error("MAX31865 fault detected!");
                return -1000.0; // Indicate a fault
            }

            // Extract RTD code (15 bits)
            int16_t rtd_code = ((buf[1] << 8) | buf[2]) >> 1;

            // Convert RTD code to resistance
            double r_rtd = (double)rtd_code * 430.0 / 32768.0;

            // Convert resistance to temperature using Callendar-Van Dusen equation
            // Assuming R0 = 100 ohms, A = 0.0039083, B = -0.0000005775
            double temperature = (r_rtd - 100.0) / 0.39083;

            return temperature;
        } else {
            log_error("SPI read failed, retrying...");
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    log_error("MAX31865 read failed after multiple retries");
    return -1000.0; // Indicate a failure
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_value, double kp, double ki, double kd) {
    double error = setpoint - actual_value;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int pin, int duty_cycle) {
    gpioPWM(pin, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Read configuration
    if (read_config(CONFIG_FILE, &target_temperature, &kp, &ki, &kd) != 0) {
        fprintf(stderr, "Using default configuration values\n");
    }

    // Initialize GPIO
    gpio_pin = 18; // Hardware PWM on GPIO18
    if (init_gpio(gpio_pin) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    spi_handle = init_spi(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MAX31865
    if (init_max31865(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(gpio_pin, PWM_FREQUENCY);
    gpioSetPWMrange(gpio_pin, PWM_RANGE);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timeval tv;
    struct tm *tm_info;
    char timestamp[26];

    // Main loop
    while (!terminate) {
        // Read temperature
        double temperature = read_temperature(spi_handle);

        if (temperature < -900.0) { // Failure indicator
            log_error("Failed to read temperature, shutting down...");
            set_pwm_duty_cycle(gpio_pin, 0);
            break;
        }

        // Calculate PID output
        double pid_output = calculate_pid(target_temperature, temperature, kp, ki, kd);

        // Limit PID output to 0-100%
        if (pid_output < 0) pid_output = 0;
        if (pid_output > 100) pid_output = 100;

        // Set PWM duty cycle
        int duty_cycle = (int)(pid_output * PWM_RANGE / 100.0);
        set_pwm_duty_cycle(gpio_pin, duty_cycle);

        // Log data
        gettimeofday(&tv, NULL);
        tm_info = localtime(&tv.tv_sec);
        strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s, Temperature: %.2f°C, PID Output: %.2f, Duty Cycle: %d\n", timestamp, temperature, pid_output, duty_cycle);

        gpioDelay(100); // 100 ms delay
    }

    // Shutdown sequence
    set_pwm_duty_cycle(gpio_pin, 0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

