// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 0 // Standard resolution

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c(const char *device);
int read_calibration_data(int fd);
int read_raw_temperature(int fd);
int read_raw_pressure(int fd);
double calculate_temperature(int raw_temperature);
double calculate_pressure(int raw_pressure, int raw_temperature);
void log_breach(double temperature, double pressure);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Initialize I2C
int init_i2c(const char *device) {
    i2c_fd = open(device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read calibration data from BMP180
int read_calibration_data(int fd) {
    uint8_t buffer[22];
    if (read(fd, buffer, 22) != 22) {
        perror("Error reading calibration data");
        return -1;
    }

    ac1 = (buffer[0] << 8) | buffer[1];
    ac2 = (buffer[2] << 8) | buffer[3];
    ac3 = (buffer[4] << 8) | buffer[5];
    ac4 = (buffer[6] << 8) | buffer[7];
    ac5 = (buffer[8] << 8) | buffer[9];
    ac6 = (buffer[10] << 8) | buffer[11];
    b1 = (buffer[12] << 8) | buffer[13];
    b2 = (buffer[14] << 8) | buffer[15];
    mb = (buffer[16] << 8) | buffer[17];
    mc = (buffer[18] << 8) | buffer[19];
    md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Read raw temperature value
int read_raw_temperature(int fd) {
    uint8_t write_buffer[2];
    uint8_t read_buffer[2];

    write_buffer[0] = BMP180_REG_CONTROL;
    write_buffer[1] = 0x2E; // Temperature measurement command

    if (write(fd, write_buffer, 2) != 2) {
        perror("Error writing temperature measurement command");
        return -1;
    }

    usleep(5000); // Wait 4.5ms

    write_buffer[0] = BMP180_REG_MSB;
    if (write(fd, write_buffer, 1) != 1) {
        perror("Error writing to register for temperature read");
        return -1;
    }

    if (read(fd, read_buffer, 2) != 2) {
        perror("Error reading raw temperature");
        return -1;
    }

    return (read_buffer[0] << 8) | read_buffer[1];
}

// Read raw pressure value
int read_raw_pressure(int fd) {
    uint8_t write_buffer[2];
    uint8_t read_buffer[3];

    write_buffer[0] = BMP180_REG_CONTROL;
    write_buffer[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (write(fd, write_buffer, 2) != 2) {
        perror("Error writing pressure measurement command");
        return -1;
    }

    usleep(26000); // Wait 25.5ms (OSS = 0)

    write_buffer[0] = BMP180_REG_MSB;
    if (write(fd, write_buffer, 1) != 1) {
        perror("Error writing to register for pressure read");
        return -1;
    }

    if (read(fd, read_buffer, 3) != 3) {
        perror("Error reading raw pressure");
        return -1;
    }

    return ((read_buffer[0] << 16) | (read_buffer[1] << 8) | read_buffer[2]) >> (8 - BMP180_OSS);
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int raw_temperature) {
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temperature) {
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    unsigned long x5 = ((long)ac3 * b6) >> 13;
    unsigned long x6 = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long b4 = x5 + x6;

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Log breach to file
void log_breach(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c("/dev/i2c-1") < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd) < 0) {
        fprintf(stderr, "Calibration data read failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Monitoring BMP180 sensor...\n");

    while (!terminate) {
        // Read raw temperature and pressure
        int raw_temperature = read_raw_temperature(i2c_fd);
        int raw_pressure = read_raw_pressure(i2c_fd);

        if (raw_temperature < 0 || raw_pressure < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            sleep(1);
            continue;
        }

        // Calculate temperature and pressure
        double temperature = calculate_temperature(raw_temperature);
        double pressure = calculate_pressure(raw_pressure, raw_temperature);

        // Check for breaches
        if (temperature > 30.0 || pressure < 950.0) {
            log_breach(temperature, pressure);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

