// Function to read a short (2 bytes) from the I2C device
int read_short(int handle, char reg, short *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read an unsigned short (2 bytes) from the I2C device
int read_ushort(int handle, char reg, unsigned short *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_short(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
