{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Temperature calculations
    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
