        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt handler for falling edge detection
    gpioSetAlertFuncEx(GPIO_PIN, toggle_logging, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running)
    {
        if (logging_enabled)
        {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0)
            {
                // Calculate pressure
                pressure = calculate_pressure(raw_temp, raw_pressure);

                // Log data
                log_data(pressure);
            }
            else
            {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

