// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for data logging toggle
#define GPIO_PIN 27

// Global variables
static int i2c_handle;
static FILE *log_file;
static volatile int logging_enabled = 0;
static volatile int program_running = 1;

// Calibration data
static short ac1, ac2, ac3, b1, b2, mb, mc, md;
static unsigned short ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temp, int raw_pressure);
void log_data(double pressure);
void toggle_logging();
void signal_handler(int signal);

// Function to read a short (2 bytes) from the I2C device
int read_short(int handle, char reg, short *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read an unsigned short (2 bytes) from the I2C device
int read_ushort(int handle, char reg, unsigned short *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_short(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temp)
{
    char buf[2];
    char cmd = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    gpioDelay(5000); // Wait 5ms

    cmd = 0xF6;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) return -1;

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[3];
    char cmd = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    cmd = 0xF6;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, buf, 3) != 3) return -1;

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate the pressure in Pascals from the raw sensor values
double calculate_pressure(int raw_temp, int raw_pressure)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    // Temperature calculations
    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;

    // Pressure calculations
    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (double)p;
}

// Function to log the pressure data to a file
void log_data(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to toggle the data logging state
void toggle_logging()
{
    static unsigned long last_toggle_time = 0;
    unsigned long current_time = gpioTick();

    if (current_time - last_toggle_time > 200000) // Debounce: 200ms
    {
        logging_enabled = !logging_enabled;
        last_toggle_time = current_time;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

int main()
{
    int raw_temp, raw_pressure;
    double pressure;

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0)
    {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0)
    {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt handler for falling edge detection
    gpioSetAlertFuncEx(GPIO_PIN, toggle_logging, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running)
    {
        if (logging_enabled)
        {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0)
            {
                // Calculate pressure
                pressure = calculate_pressure(raw_temp, raw_pressure);

                // Log data
                log_data(pressure);
            }
            else
            {
                fprintf(stderr, "Failed to read sensor data\n");
            }
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

