#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define TARGET_TEMPERATURE 25.0 // Default target temperature
#define MAX_DUTY_CYCLE 80.0 // Maximum duty cycle percentage
#define LOG_FILE "heater_log.csv"

// PI Controller Gains
#define KP 1.0
#define KI 0.1

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double target_temperature = TARGET_TEMPERATURE;

// PI Controller State
static double integral = 0.0;

// Function Prototypes
double read_temperature();
double calculate_duty_cycle(double temperature, double target_temperature, double kp, double ki, double *integral);
void set_heater_duty_cycle(int duty_cycle);
void log_data(double temperature, int duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature,duty_cycle\n");
    }

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int result = spiRead(spi_handle, (char *)data, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: %s\n",
                (data[1] & 0x01) ? "Open Circuit" :
                ((data[1] & 0x02) ? "Short to GND" : "Short to VCC"));
        return -1000.0; // Indicate error
    }

    // Extract temperature data (ignoring fault bits)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate duty cycle using PI controller
double calculate_duty_cycle(double temperature, double target_temperature, double kp, double ki, double *integral) {
    double error = target_temperature - temperature;
    *integral += error;

    // Anti-windup
    double integral_limit = 100.0; // Adjust as needed
    if (*integral > integral_limit) *integral = integral_limit;
    if (*integral < -integral_limit) *integral = -integral_limit;

    double output = kp * error + ki * (*integral);

    // Limit duty cycle to MAX_DUTY_CYCLE
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
    if (output < 0.0) output = 0.0;

    return output;
}

// Function to set heater duty cycle using pigpio
void set_heater_duty_cycle(int duty_cycle) {
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to log data to CSV file
void log_data(double temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_duty_cycle(0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        printf("Target temperature set to %.2f\n", target_temperature);
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            double duty_cycle = calculate_duty_cycle(temperature, target_temperature, KP, KI, &integral);
            set_heater_duty_cycle((int)duty_cycle);
            log_data(temperature, (int)duty_cycle);
            printf("Temperature: %.2f, Duty Cycle: %.2f\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, setting heater to 0%%\n");
            set_heater_duty_cycle(0);
            log_data(-1000.0, 0); // Log error
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

