#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature thresholds (m°C)
#define TEMP_BLUE  40000
#define TEMP_GREEN 50000

// File path for CPU temperature
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    int temp_millidegrees;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", TEMP_FILE);
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_millidegrees) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_millidegrees;
}

// Function to set RGB LED color using PWM
void set_rgb(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main()
{
    int temperature;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temperature = read_cpu_temp();

        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using default color\n");
            red = 0;
            green = 0;
            blue = 255;
        } else {
            // Determine RGB color based on temperature
            if (temperature < TEMP_BLUE) {
                red = 0;
                green = 0;
                blue = 255;
            } else if (temperature < TEMP_GREEN) {
                red = 0;
                green = 255;
                blue = 0;
            } else {
                red = 255;
                green = 0;
                blue = 0;
            }
        }

        // Set RGB color
        set_rgb(red, green, blue);

        // Print temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temperature, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup and exit
    set_rgb(255, 255, 255); // Turn off LED
    gpioTerminate();
    return 0;
}

