    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temperature = read_cpu_temp();

        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using default color\n");
            red = 0;
            green = 0;
            blue = 255;
        } else {
            // Determine RGB color based on temperature
            if (temperature < TEMP_BLUE) {
                red = 0;
                green = 0;
                blue = 255;
            } else if (temperature < TEMP_GREEN) {
                red = 0;
                green = 255;
                blue = 0;
            } else {
                red = 255;
                green = 0;
                blue = 0;
            }
        }

        // Set RGB color
        set_rgb(red, green, blue);

        // Print temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temperature, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup and exit
    set_rgb(255, 255, 255); // Turn off LED
    gpioTerminate();
    return 0;
}

