#include <curl/curl.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5
#define LOG_FILE "dht22_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int read_dht22(int gpio, SensorData *data);
int validate_checksum(const unsigned char *data, int data_len);
int post_data(const char *url, const char *data);
void signal_handler(int signal);
void log_message(const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Logging function
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
        fflush(log_file);
    }
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, SensorData *data) {
    int i, j;
    unsigned char raw_data[5] = {0};
    unsigned char checksum;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // Start signal
    gpioWrite(gpio, 1);
    gpioDelay(30); // Wait for response

    gpioSetMode(gpio, PI_INPUT);

    // Read 40 bits
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for low
            while (gpioRead(gpio) == 0) {
                // Timeout
                if (gpioTick() > 100000) {
                    log_message("Timeout waiting for low signal.");
                    return -1;
                }
            }

            // Measure high time
            long start = gpioTick();
            while (gpioRead(gpio) == 1) {
                // Timeout
                if (gpioTick() - start > 100000) {
                    log_message("Timeout waiting for high signal.");
                    return -1;
                }
            }

            // Determine if bit is 0 or 1 based on high time
            if (gpioTick() - start > 40) {
                raw_data[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    checksum = (raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF;
    if (checksum != raw_data[4]) {
        log_message("Checksum validation failed.");
        return -1;
    }

    // Parse data
    data->humidity = (float)(((raw_data[0] << 8) | raw_data[1])) / 10.0;
    data->temperature = (float)(((raw_data[2] << 8) | raw_data[3])) / 10.0;
    if (data->temperature > 125) {
        data->temperature = data->temperature - 256;
    }

    return 0;
}

// Function to validate checksum
int validate_checksum(const unsigned char *data, int data_len) {
    unsigned char checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    return (checksum == data[4]);
}

// Function to post data to server
int post_data(const char *url, const char *data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            log_message(curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            char log_buffer[256];
            snprintf(log_buffer, sizeof(log_buffer), "HTTP POST successful, response code: %ld", response_code);
            log_message(log_buffer);
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    int retries = 0;
    SensorData sensor_data;
    char json_payload[256];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Starting DHT22 data acquisition and transmission.");

    while (running) {
        // Read DHT22 data
        if (read_dht22(DHT22_GPIO, &sensor_data) == 0) {
            // Format data as JSON
            snprintf(json_payload, sizeof(json_payload), "{\"temperature\": %.1f, \"humidity\": %.1f}", sensor_data.temperature, sensor_data.humidity);

            // Post data to server
            if (post_data(SERVER_URL, json_payload) != 0) {
                log_message("Failed to post data to server.");
                retries++;
                if (retries > MAX_RETRIES) {
                    log_message("Max retries reached. Exiting.");
                    running = 0;
                } else {
                    char retry_msg[64];
                    snprintf(retry_msg, sizeof(retry_msg), "Retrying in %d seconds...", RETRY_DELAY_SEC);
                    log_message(retry_msg);
                    sleep(RETRY_DELAY_SEC);
                }
            } else {
                retries = 0; // Reset retries on success
            }
        } else {
            log_message("Failed to read DHT22 data.");
            retries++;
            if (retries > MAX_RETRIES) {
                log_message("Max retries reached. Exiting.");
                running = 0;
            } else {
                char retry_msg[64];
                snprintf(retry_msg, sizeof(retry_msg), "Retrying in %d seconds...", RETRY_DELAY_SEC);
                log_message(retry_msg);
                sleep(RETRY_DELAY_SEC);
            }
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    log_message("Exiting program.");
    return 0;
}

