#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define BMP180_OSS 3

// GPIO pin for interrupt
#define GPIO_PIN 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000 // 200ms

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile uint32_t last_interrupt_time = 0;
static FILE *log_file = NULL;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temperature);
double calculate_pressure(int raw_pressure, int raw_temperature);
void log_data(double pressure);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C bus
int read_i2c_word(int handle, uint8_t reg, int16_t *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C word from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to read an unsigned 16-bit value from the I2C bus
int read_i2c_uword(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C word from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to write a byte to the I2C bus
int write_i2c_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[1];
    buf[0] = value;
    if (i2cWriteI2CBlockData(handle, reg, buf, 1) != 1) {
        fprintf(stderr, "Error writing I2C byte to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, (int16_t *)&ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, (int16_t *)&ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, (int16_t *)&ac3) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, (int16_t *)&b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, (int16_t *)&b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, (int16_t *)&mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, (int16_t *)&mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, (int16_t *)&md) != 0) return -1;

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    if (write_i2c_byte(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) return -1; // Request temperature reading
    gpioDelay(5000); // Wait 4.5ms (minimum)

    int16_t ut;
    if (read_i2c_word(i2c_handle, BMP180_REG_MSB, &ut) != 0) return -1;

    *raw_temperature = ut;
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    if (write_i2c_byte(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) return -1; // Request pressure reading
    gpioDelay(26000); // Wait for conversion (26ms for OSS=3)

    int32_t up;
    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        return -1;
    }

    up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);

    *raw_pressure = up;
    return 0;
}

// Function to calculate the temperature in degrees Celsius
double calculate_temperature(int raw_temperature)
{
    int32_t X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate the pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temperature)
{
    int32_t X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    int32_t X4 = ((int32_t)ac2 * B6) / pow(2, 11);
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) / 4;

    uint32_t X1_u = ((uint32_t)ac3 * B6) / pow(2, 13);
    uint32_t X2_u = ((uint32_t)b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    uint32_t B4 = X1_u + X2_u + ((uint32_t)ac4 * pow(2, 15));
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);

    double pressure = p + (X1 + X2 + 3791) / pow(2, 4);
    return pressure / 100.0; // Convert to hPa
}

// Function to log the pressure data to a file
void log_data(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick)
{
    uint32_t current_time = gpioTick();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME)
    {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;

        if (logging_enabled)
        {
            printf("Logging enabled.\n");
        } else {
            printf("Logging disabled.\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0)
    {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
