#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <getopt.h>
#include <time.h>

#define DHT22_GPIO 4
#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2
#define MAX_HUMIDITY 100.0
#define MIN_HUMIDITY 0.0

// Structure to hold program configuration
typedef struct {
    char *server_url;
    int gpio_initialized;
} ProgramConfig;

ProgramConfig config = {DEFAULT_SERVER_URL, 0};

// Function prototypes
int read_dht22(float *humidity);
int validate_checksum(const unsigned char data[40]);
int post_humidity(float humidity, const char *server_url);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, exiting gracefully...");
    if (config.gpio_initialized) {
        gpioTerminate();
    }
    curl_global_cleanup();
    closelog();
    exit(0);
}

// Logging function using syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Function to read DHT22 sensor data
int read_dht22(float *humidity) {
    int i, j;
    unsigned char data[5] = {0, 0, 0, 0, 0};
    unsigned char laststate = PI_HIGH;
    unsigned long pulse_start, pulse_end;
    unsigned long pulse_length;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(18); //18ms
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioSetMode(DHT22_GPIO, PI_INPUT);
    gpioSetPullUpDown(DHT22_GPIO, PI_PUD_UP);
    gpioDelay(40);

    pulse_start = gpioTick();
    while (gpioRead(DHT22_GPIO) == PI_HIGH) {
        if (gpioTick() - pulse_start > 100) return -1; // Timeout
    }
    pulse_start = gpioTick();
    while (gpioRead(DHT22_GPIO) == PI_LOW) {
        if (gpioTick() - pulse_start > 100) return -1; // Timeout
    }
    pulse_start = gpioTick();
    while (gpioRead(DHT22_GPIO) == PI_HIGH) {
        if (gpioTick() - pulse_start > 100) return -1; // Timeout
    }

    for (i = 0; i < 40; i++) {
        pulse_start = gpioTick();
        while (gpioRead(DHT22_GPIO) == laststate) {
            if (gpioTick() - pulse_start > 100) return -1; // Timeout
        }
        pulse_end = gpioTick();
        pulse_length = pulse_end - pulse_start;
        laststate = gpioRead(DHT22_GPIO);

        if (pulse_length > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (validate_checksum(data) != 0) {
        log_message(LOG_ERR, "Checksum validation failed");
        return -1;
    }

    *humidity = (float)(((unsigned long)data[0] << 8) | data[1]) / 10.0;

    return 0;
}

// Function to validate DHT22 checksum
int validate_checksum(const unsigned char data[40]) {
    unsigned char checksum = data[4];
    unsigned char sum = 0;
    for (int i = 0; i < 4; i++) {
        sum += data[i];
    }
    return (sum == checksum);
}

// Function to POST humidity data to server
int post_humidity(float humidity, const char *server_url) {
    CURL *curl;
    CURLcode res;
    char json_data[100];
    int retries = 0;

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    while (retries < MAX_RETRIES) {
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, server_url);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
            curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L); // Set timeout to 10 seconds

            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);

            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    log_message(LOG_INFO, "Humidity data posted successfully");
                    curl_slist_free_all(headers);
                    curl_easy_cleanup(curl);
                    return 0;
                } else {
                    log_message(LOG_ERR, "HTTP request failed with code: %ld", response_code);
                }
            } else {
                log_message(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            }

            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
        } else {
            log_message(LOG_ERR, "curl_easy_init() failed");
        }

        retries++;
        if (retries < MAX_RETRIES) {
            log_message(LOG_WARNING, "Retrying POST request...");
            sleep(BACKOFF_DELAY);
        }
    }

    log_message(LOG_ERR, "Failed to POST humidity data after %d retries", MAX_RETRIES);
    return -1;
}

int main(int argc, char *argv[]) {
    int opt;
    float humidity;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                config.server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_poster", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }
    config.gpio_initialized = 1;

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_dht22(&humidity) == 0) {
            // Validate humidity range
            if (humidity >= MIN_HUMIDITY && humidity <= MAX_HUMIDITY) {
                if (post_humidity(humidity, config.server_url) != 0) {
                    log_message(LOG_ERR, "Failed to post humidity data");
                }
            } else {
                log_message(LOG_ERR, "Humidity value out of range: %.2f", humidity);
            }
        } else {
            log_message(LOG_ERR, "Failed to read DHT22 sensor");
        }

        sleep(10);
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return 0;
}

