            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);

            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    log_message(LOG_INFO, "Humidity data posted successfully");
                    curl_slist_free_all(headers);
                    curl_easy_cleanup(curl);
                    return 0;
                } else {
                    log_message(LOG_ERR, "HTTP request failed with code: %ld", response_code);
                }
            } else {
                log_message(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            }

            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
        } else {
            log_message(LOG_ERR, "curl_easy_init() failed");
        }

        retries++;
        if (retries < MAX_RETRIES) {
            log_message(LOG_WARNING, "Retrying POST request...");
            sleep(BACKOFF_DELAY);
        }
    }

    log_message(LOG_ERR, "Failed to POST humidity data after %d retries", MAX_RETRIES);
    return -1;
}

int main(int argc, char *argv[]) {
    int opt;
    float humidity;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                config.server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_poster", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }
    config.gpio_initialized = 1;

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (read_dht22(&humidity) == 0) {
            // Validate humidity range
            if (humidity >= MIN_HUMIDITY && humidity <= MAX_HUMIDITY) {
                if (post_humidity(humidity, config.server_url) != 0) {
                    log_message(LOG_ERR, "Failed to post humidity data");
                }
            } else {
                log_message(LOG_ERR, "Humidity value out of range: %.2f", humidity);
            }
        } else {
            log_message(LOG_ERR, "Failed to read DHT22 sensor");
        }

        sleep(10);
    }

    // Cleanup (should not reach here under normal circumstances due to signal handler)
    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return 0;
}

