#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_SPEED_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_FAN_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"

// Global variable to track the current fan state
int current_fan_state = 0;

// Function prototypes
int read_cpu_temp();
int read_max_fan_state();
int set_fan_speed(int state);
int log_fan_speed(int state);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        set_fan_speed(0); // Turn off the fan
        log_fan_speed(0);  // Log the shutdown
        exit(0);
    }
}

// Function to read CPU temperature from sysfs
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;
    char buffer[10];

    fp = fopen(CPU_TEMP_PATH, "r");
    if (fp == NULL) {
        perror("Failed to open CPU temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer);
    } else {
        perror("Failed to read CPU temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to read the maximum fan state from sysfs
int read_max_fan_state() {
    FILE *fp;
    int max_state = -1;
    char buffer[10];

    fp = fopen(MAX_FAN_STATE_PATH, "r");
    if (fp == NULL) {
        perror("Failed to open max_state file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        max_state = atoi(buffer);
    } else {
        perror("Failed to read max_state");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return max_state;
}

// Function to set the fan speed using sysfs
int set_fan_speed(int state) {
    FILE *fp;
    char buffer[10];

    if (state < 0 || state > 3) {
        fprintf(stderr, "Invalid fan state: %d\n", state);
        return -1;
    }

    fp = fopen(FAN_SPEED_PATH, "w");
    if (fp == NULL) {
        perror("Failed to open fan speed file");
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", state);
    if (fputs(buffer, fp) == EOF) {
        perror("Failed to write fan speed");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to log fan speed changes to a file
int log_fan_speed(int state) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    if (state != current_fan_state) {
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: Fan speed set to %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, state);
        fclose(fp);
        current_fan_state = state;
        return 0;
    } else {
        fclose(fp);
        return 0;
    }
}

int main() {
    int cpu_temp, max_fan_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        max_fan_state = read_max_fan_state();
        if (max_fan_state == -1) {
            fprintf(stderr, "Failed to read max_fan_state, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        int fan_state;
        if (cpu_temp < 45000) {
            fan_state = 0;
        } else if (cpu_temp < 55000) {
            fan_state = 1;
        } else if (cpu_temp < 65000) {
            fan_state = 2;
        } else {
            fan_state = 3;
        }

        if (fan_state > max_fan_state) {
            fan_state = max_fan_state;
        }

        if (set_fan_speed(fan_state) == 0) {
            log_fan_speed(fan_state);
        } else {
            fprintf(stderr, "Failed to set fan speed, retrying in 5 seconds...\n");
        }

        sleep(5);
    }

    return 0;
}

