#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 500000

// Define PID parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define TARGET_TEMP 50.0

// Define temperature limits
#define TEMP_MIN 0.0
#define TEMP_MAX 100.0

// Define error codes
#define SPI_ERROR -1
#define PIGPIO_ERROR -2
#define MAX31855_ERROR -3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID controller variables
double integral = 0.0;
double previous_error = 0.0;

// Function prototypes
int read_max31855(double *temperature);
int pwm_control(int duty_cycle);
int pid_control(double temperature);
int log_data(double temperature, int duty_cycle, int pid_output);
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(double *temperature) {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(log_file, "%s SPI read failed: %d\n", __func__, result);
        fflush(log_file);
        return SPI_ERROR;
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(log_file, "%s MAX31855 Fault: Open Circuit\n", __func__);
        fflush(log_file);
        return MAX31855_ERROR;
    }
    if (data[3] & 0x02) {
        fprintf(log_file, "%s MAX31855 Fault: Short to GND\n", __func__);
        fflush(log_file);
        return MAX31855_ERROR;
    }
    if (data[3] & 0x04) {
        fprintf(log_file, "%s MAX31855 Fault: Short to VCC\n", __func__);
        fflush(log_file);
        return MAX31855_ERROR;
    }

    // Extract temperature data (bits 31:18 of the 32-bit word)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;

    // Convert to Celsius
    *temperature = (double)raw_temp * 0.25;

    return 0;
}

// Function to control heater via PWM
int pwm_control(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(log_file, "%s Invalid duty cycle: %d\n", __func__, duty_cycle);
        fflush(log_file);
        return PIGPIO_ERROR;
    }

    gpioPWM(HEATER_PIN, duty_cycle);
    return 0;
}

// Function to implement PID control
int pid_control(double temperature) {
    double error = TARGET_TEMP - temperature;

    // Integral term
    integral += error;

    // Anti-windup
    if (integral > 100) integral = 100;
    if (integral < 0) integral = 0;

    // Derivative term
    double derivative = error - previous_error;

    // Calculate output
    double output = Kp * error + Ki * integral + Kd * derivative;

    // Limit output to 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    previous_error = error;

    return (int)output;
}

// Function to log data to file
int log_data(double temperature, int duty_cycle, int pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %d\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(log_file, "Signal received, shutting down...\n");
    fflush(log_file);
    terminate = 1;
}

int main() {
    double temperature;
    int duty_cycle;
    int pid_output;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO18 as output for PWM
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Configure SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(log_file, "SPI open failed: %d\n", spi_handle);
        fflush(log_file);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(log_file, "Heater control started\n");
    fflush(log_file);

    while (!terminate) {
        // Read temperature
        if (read_max31855(&temperature) == 0) {
            // Check for valid temperature range
            if (temperature >= TEMP_MIN && temperature <= TEMP_MAX) {
                // Calculate PID output
                pid_output = pid_control(temperature);

                // Set PWM duty cycle
                duty_cycle = pid_output;
                if (pwm_control(duty_cycle) != 0) {
                    fprintf(log_file, "PWM control failed\n");
                    fflush(log_file);
                }

                // Log data
                log_data(temperature, duty_cycle, pid_output);
            } else {
                fprintf(log_file, "Temperature out of range: %.2f\n", temperature);
                fflush(log_file);
                pwm_control(0); // Disable heater
            }
        } else {
            fprintf(log_file, "Temperature reading failed\n");
            fflush(log_file);
            pwm_control(0); // Disable heater
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    pwm_control(0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

