#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius = 0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp_milli_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(int temp_milli_celsius) {
    int duty_cycle = 0;

    if (temp_milli_celsius < 40000) {
        duty_cycle = 0;
    } else if (temp_milli_celsius > 70000) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((float)(temp_milli_celsius - 40000) / (70000 - 40000)) * 100);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

