#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// Define I2C bus
#define I2C_BUS 1

// Define continuous measurement command
#define CONTINUOUS_MEASUREMENT_CMD 0x3608

// Define CRC polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle1, i2c_handle2;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int status;
} sensor_data_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor(int i2c_handle, int *raw_value);
int validate_crc(int raw_value, int crc);
float convert_to_flow_rate(int raw_value);
int log_data(float flow_rate1, float flow_rate2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read sensor data
int read_sensor(int i2c_handle, int *raw_value) {
    char buf[3];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, CONTINUOUS_MEASUREMENT_CMD >> 8, buf, 3);
        if (result == 3) {
            *raw_value = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", 4 - retries, result);
            retries--;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read sensor after multiple retries.\n");
    return -1; // Failure
}

// Validate CRC checksum
int validate_crc(int raw_value, int crc) {
    unsigned char data[2];
    data[0] = (raw_value >> 8) & 0xFF;
    data[1] = raw_value & 0xFF;

    unsigned char crc_calculated = 0;
    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    if (crc_calculated != crc) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02x, received 0x%02x\n", crc_calculated, crc);
        return -1; // CRC failure
    }

    return 0; // CRC success
}

// Convert raw value to flow rate
float convert_to_flow_rate(int raw_value) {
    return (float)raw_value * 0.01;
}

// Log data to file
int log_data(float flow_rate1, float flow_rate2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow_rate1, flow_rate2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_value1, raw_value2;
        int crc_value1, crc_value2;
        float flow_rate1, flow_rate2;

        // Read sensor 1
        if (read_sensor(i2c_handle1, &raw_value1) == 0) {
            crc_value1 = raw_value1 & 0xFF; // Extract CRC from the last byte
            if (validate_crc(raw_value1 >> 8, crc_value1) == 0) {
                flow_rate1 = convert_to_flow_rate(raw_value1 >> 8);
            } else {
                flow_rate1 = -1.0; // Indicate error
            }
        } else {
            flow_rate1 = -1.0; // Indicate error
        }

        // Read sensor 2
        if (read_sensor(i2c_handle2, &raw_value2) == 0) {
            crc_value2 = raw_value2 & 0xFF; // Extract CRC from the last byte
            if (validate_crc(raw_value2 >> 8, crc_value2) == 0) {
                flow_rate2 = convert_to_flow_rate(raw_value2 >> 8);
            } else {
                flow_rate2 = -1.0; // Indicate error
            }
        } else {
            flow_rate2 = -1.0; // Indicate error
        }

        // Log data
        log_data(flow_rate1, flow_rate2);

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

