#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the rotary encoder sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the number of quadrature states
#define NUM_STATES 4

// Define the quadrature state machine states
enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
};

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int update_state(int current_state, int sensor_a_value, int sensor_b_value);
void log_data(int state, float angle);
void signal_handler(int signal);

// Quadrature state machine transition table
int transition_table[NUM_STATES][2] = {
    {STATE_01, STATE_11}, // STATE_00
    {STATE_10, STATE_00}, // STATE_01
    {STATE_11, STATE_00}, // STATE_11
    {STATE_00, STATE_10}  // STATE_10
};

int main() {
    int current_state = STATE_00;
    int sensor_a_value, sensor_b_value;
    float angle = 0.0;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        sensor_a_value = read_sensor(SENSOR_A_GPIO);
        sensor_b_value = read_sensor(SENSOR_B_GPIO);

        // Update the state machine state
        current_state = update_state(current_state, sensor_a_value, sensor_b_value);

        // Calculate the angle
        switch (current_state) {
            case STATE_01:
                angle += 360.0 / PULSES_PER_REVOLUTION;
                break;
            case STATE_10:
                angle -= 360.0 / PULSES_PER_REVOLUTION;
                break;
            case STATE_11:
                angle += 360.0 / PULSES_PER_REVOLUTION;
                break;
            case STATE_00:
                angle -= 360.0 / PULSES_PER_REVOLUTION;
                break;
        }

        // Normalize the angle to 0-360 degrees
        while (angle < 0) {
            angle += 360.0;
        }
        while (angle >= 360.0) {
            angle -= 360.0;
        }

        // Log the data
        log_data(current_state, angle);

        // Delay for a short period
        gpioDelay(1); // 1 millisecond delay
    }

    // Close the log file
    if (log_file != NULL) {
