// Define GPIO pins for the rotary encoder sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the number of quadrature states
#define NUM_STATES 4

// Define the quadrature state machine states
enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
};

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
