int read_sensor(int gpio);
int update_state(int current_state, int sensor_a_value, int sensor_b_value);
void log_data(int state, float angle);
void signal_handler(int signal);

// Quadrature state machine transition table
int transition_table[NUM_STATES][2] = {
    {STATE_01, STATE_11}, // STATE_00
    {STATE_10, STATE_00}, // STATE_01
    {STATE_11, STATE_00}, // STATE_11
    {STATE_00, STATE_10}  // STATE_10
};

int main() {
    int current_state = STATE_00;
    int sensor_a_value, sensor_b_value;
    float angle = 0.0;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
