#define DEBOUNCE_DELAY_US 500

volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
void *rpm_calculator(void *arg);
void signal_handler(int signal);

// Interrupt service routine (ISR)
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        gpioDelay(DEBOUNCE_DELAY_US);
        if (gpioRead(gpio) == PI_HIGH) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }
    }
}

// Thread function to calculate RPM
void *rpm_calculator(void *arg) {
    while (1) {
        gpioDelay(1000000); // 1-second interval

        pthread_mutex_lock(&pulse_mutex);
        double rpm = (double)pulse_count * 60.0; // pulses per second * 60 = RPM
        pulse_count = 0; // Reset pulse count for the next interval
        pthread_mutex_unlock(&pulse_mutex);

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (log_file != NULL) {
            fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupt
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register interrupt service routine
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        pthread_mutex_destroy(&pulse_mutex);
        return 1;
    }

    // Create thread for RPM calculation
