#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define AUDIO_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(AUDIO_PIN, PI_INPUT);
    gpioSetMode(GAIN_PIN, PI_OUTPUT);
    gpioWrite(GAIN_PIN, 0); // Set gain to 60dB

    return 0;
}

// Function to set the gain of the MAX9814
int set_gain() {
    gpioWrite(GAIN_PIN, 0); // Set gain to 60dB
    gpioDelay(1000); // Wait for 1ms
    return 0;
}

// Function to read the audio pin
int read_audio_pin() {
    return gpioRead(AUDIO_PIN);
}

// Function to detect rising edges
int detect_rising_edge(int current_value, int previous_value) {
    return (current_value == 1 && previous_value == 0) ? 1 : 0;
}

// Function to log audio events
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s LEVEL %d\n", timestamp, level);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    int previous_value = 0;
    int current_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set gain
    if (set_gain() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    while (running) {
        current_value = read_audio_pin();

        if (detect_rising_edge(current_value, previous_value)) {
            if (log_event(1) != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        }

        previous_value = current_value;
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exited cleanly.\n");
    return 0;
}

