unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the sensor
int initialize_sensor() {
    char buf[2];
    buf[0] = (START_MEASUREMENT_CMD >> 8) & 0xFF;
    buf[1] = START_MEASUREMENT_CMD & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *raw_flow, int *crc) {
    char buf[3];
    int result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *raw_flow = (buf[0] << 8) | buf[1];
    *crc = buf[2];

    return 0;
}

// Validate CRC
int validate_crc(int raw_flow, int crc) {
    unsigned char data[2];
    data[0] = (raw_flow >> 8) & 0xFF;
    data[1] = raw_flow & 0xFF;

    unsigned char calculated_crc = crc8(data, 2);

    if (calculated_crc != (unsigned char)crc) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, crc);
        return -1;
    }
    return 0;
}

// Convert to flow rate
float convert_to_flow_rate(int raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE;
}

// Log flow rate
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.6f\n", timestamp, flow_rate);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int raw_flow, crc;
    float flow_rate;
    while (!terminate) {
        if (read_sensor_data(&raw_flow, &crc) == 0) {
            if (validate_crc(raw_flow, crc) == 0) {
                flow_rate = convert_to_flow_rate(raw_flow);
                log_flow_rate(flow_rate);
            }
        }
        gpioDelay(1000); // 1000 ms delay
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

