#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 27

// Tamper detection threshold in seconds
#define TAMPER_THRESHOLD 5

// Global variables for GPIO lines and chip
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;
struct gpiod_line *sensor3_line = NULL;
struct gpiod_chip *chip = NULL;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor state and timer
typedef struct {
    int sensor_number;
    int touched;
    struct timespec last_touch_time;
} sensor_state_t;

sensor_state_t sensor_states[3];

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line1, struct gpiod_line **line2, struct gpiod_line **line3) {
    int ret;

    // Open GPIO chip
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request GPIO lines as inputs
    *line1 = gpiod_chip_get_line(*chip, SENSOR1_GPIO);
    if (!*line1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR1_GPIO, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    *line2 = gpiod_chip_get_line(*chip, SENSOR2_GPIO);
    if (!*line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR2_GPIO, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    *line3 = gpiod_chip_get_line(*chip, SENSOR3_GPIO);
    if (!*line3) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR3_GPIO, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    ret = gpiod_line_request_input(*line1, "ttp223_tamper");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", SENSOR1_GPIO, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    ret = gpiod_line_request_input(*line2, "ttp223_tamper");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", SENSOR2_GPIO, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    ret = gpiod_line_request_input(*line3, "ttp223_tamper");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", SENSOR3_GPIO, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to process sensor data
void process_sensor_data(int sensor_number, int value) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (value == 1) { // Sensor touched
        sensor_states[sensor_number].touched = 1;
        clock_gettime(CLOCK_MONOTONIC, &sensor_states[sensor_number].last_touch_time);
    } else { // Sensor released
        sensor_states[sensor_number].touched = 0;
    }

    if (sensor_states[sensor_number].touched) {
        // Check if the touch duration exceeds the threshold
        double elapsed_time = (now.tv_sec - sensor_states[sensor_number].last_touch_time.tv_sec) +
                              (now.tv_nsec - sensor_states[sensor_number].last_touch_time.tv_nsec) / 1e9;

        if (elapsed_time >= TAMPER_THRESHOLD) {
            printf("Intrusion Alert: Sensor %d touched for %.2f seconds\n", sensor_number, elapsed_time);
            sensor_states[sensor_number].touched = 0; // Reset the touch state after alert
        }
    }
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 100000000}; // 100 ms

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensor states
    for (int i = 0; i < 3; i++) {
        sensor_states[i].sensor_number = i + 1;
        sensor_states[i].touched = 0;
        clock_gettime(CLOCK_MONOTONIC, &sensor_states[i].last_touch_time);
    }

    // Initialize GPIO
    if (initialize_gpio(&chip, &sensor1_line, &sensor2_line, &sensor3_line) < 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);
        int sensor3_value = read_sensor(sensor3_line);

        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor values, exiting...\n");
            break;
        }

        // Process sensor data
        process_sensor_data(0, sensor1_value);
        process_sensor_data(1, sensor2_value);
        process_sensor_data(2, sensor3_value);

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor3_line) {
        gpiod_line_release(sensor3_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

