#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define GPIO_PIN 17
#define SAMPLE_RATE 16000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16
#define FRAME_SIZE 3
#define FILENAME "audio_capture.pcm"

// Global variables for signal handling
static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *fp = NULL;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    keep_running = 0;
}

// Function to initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle, snd_pcm_hw_params_t **params)
{
    int rc;
    snd_pcm_hw_params_t *hwparams;

    rc = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (rc < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(rc));
        return -1;
    }

    snd_pcm_hw_params_alloca(hwparams);

    rc = snd_pcm_hw_params_any(*pcm_handle, hwparams);
    if (rc < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_access(*pcm_handle, hwparams, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (rc < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_format(*pcm_handle, hwparams, SND_PCM_FORMAT_S16_LE);
    if (rc < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params_set_channels(*pcm_handle, hwparams, NUM_CHANNELS);
    if (rc < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    rc = snd_pcm_hw_params_set_rate_near(*pcm_handle, hwparams, &rate, 0);
    if (rc < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    rc = snd_pcm_hw_params(*pcm_handle, hwparams);
    if (rc < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(rc));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    *params = hwparams;
    return 0;
}

// Function to read audio data from ALSA
int read_audio_data(snd_pcm_t *pcm_handle, int16_t *buffer, int frames)
{
    int rc = snd_pcm_readi(pcm_handle, buffer, frames);
    if (rc == -EPIPE) {
        /* EPIPE means overrun */
        fprintf(stderr, "Overrun occurred\n");
        snd_pcm_prepare(pcm_handle);
    } else if (rc < 0) {
        fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(rc));
        return -1;
    } else if (rc != frames) {
        fprintf(stderr, "Short read, read %d frames\n", rc);
    }
    return 0;
}

// Function to write audio data to file
int write_audio_data(FILE *fp, int16_t *buffer, int frames)
{
    size_t bytes_written = fwrite(buffer, sizeof(int16_t), frames, fp);
    if (bytes_written != frames) {
        fprintf(stderr, "Error writing to file: wrote %zu frames, expected %d\n", bytes_written, frames);
        return -1;
    }
    return 0;
}

// Function to select the left channel
int select_left_channel(int gpio_pin)
{
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0); // Select left channel
    return 0;
}

int main()
{
    int rc;
    int16_t *buffer;
    int frames = 1024; // Number of frames to read at a time

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize ALSA
    snd_pcm_hw_params_t *params;
    if (init_alsa(&pcm_handle, &params) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the output file
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", FILENAME);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Allocate memory for the audio buffer
    buffer = (int16_t *)malloc(frames * sizeof(int16_t));
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for buffer\n");
        fclose(fp);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Select the left channel
    if (select_left_channel(GPIO_PIN) != 0) {
        fprintf(stderr, "Error selecting left channel\n");
        free(buffer);
        fclose(fp);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read audio data
        if (read_audio_data(pcm_handle, buffer, frames) != 0) {
            fprintf(stderr, "Error reading audio data\n");
            break;
        }

        // Write audio data to file
        if (write_audio_data(fp, buffer, frames) != 0) {
            fprintf(stderr, "Error writing audio data\n");
            break;
        }
    }

    // Clean up
    free(buffer);
    fclose(fp);
    snd_pcm_close(pcm_handle);
    gpioTerminate();

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

