#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time (50ms)
#define DEBOUNCE_TIME 50000 // microseconds

// Define flame duration timeout (1 second)
#define FLAME_DURATION_TIMEOUT 1000000 // microseconds

// Global variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event_description);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 100); // Set PWM range to 100 for percentage control

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int sensor_value = gpioRead(FLAME_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to control the cooling fan
void control_fan(int flame_detected) {
    static unsigned long flame_start_time = 0;
    unsigned long current_time = gpioTick();

    if (flame_detected) {
        if (flame_start_time == 0) {
            flame_start_time = current_time;
        }

        // Calculate flame duration in seconds
        double flame_duration = (double)(current_time - flame_start_time) / 1000000.0; // in seconds

        // Calculate duty cycle based on flame duration (exponential curve)
        double duty_cycle = 0.8 * (1.0 - exp(-flame_duration / 2.0)); // Exponential decay

        // Ensure duty cycle is within 0-100%
        if (duty_cycle < 0.0) duty_cycle = 0.0;
        if (duty_cycle > 1.0) duty_cycle = 1.0;

        // Set PWM duty cycle
        gpioPWM(FAN_PIN, (int)(duty_cycle * 100.0)); // Convert percentage to 0-100 range

        log_event("Flame detected, fan running");
    } else {
        // No flame detected
        gpioPWM(FAN_PIN, 0); // Turn off fan
        flame_start_time = 0; // Reset flame start time
        log_event("No flame detected, fan off");
    }
}

// Function to log events to a file
void log_event(const char *event_description) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_description);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_PIN, 0); // Turn off fan
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    log_event("System started");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int flame_detected = 0;
    unsigned long flame_start_time = 0;

    // Main loop
    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error reading sensor, exiting");
            break;
        }

        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (!flame_detected) {
                flame_detected = 1;
                flame_start_time = gpioTick();
            }

            control_fan(1);

            // Debounce the sensor
            gpioDelay(DEBOUNCE_TIME);
        } else { // No flame detected (HIGH signal)
            if (flame_detected) {
                flame_detected = 0;
                control_fan(0);
            }

            // Check for flame duration timeout
            if (flame_start_time != 0) {
                unsigned long current_time = gpioTick();
                if ((current_time - flame_start_time) > FLAME_DURATION_TIMEOUT) {
                    flame_start_time = 0;
                    flame_detected = 0;
                    control_fan(0);
                    log_event("Flame duration timeout");
                }
            }

            gpioDelay(DEBOUNCE_TIME);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

