#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int log_event(const char *event);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read flame sensor
int read_flame_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line value");
        return -1; // Indicate error
    }
    return value;
}

// Log event to file
int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Cleanup resources
void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    int previous_state = -1; // Initialize to an invalid state

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int current_state = read_flame_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            if (initialize_gpio() < 0) {
                fprintf(stderr, "GPIO re-initialization failed. Exiting.\n");
                break;
            }
            usleep(100000); // Wait before retrying
            continue;
        }

        if (current_state != previous_state) {
            if (current_state == 0) {
                log_event("Flame detected");
                printf("Flame detected\n");
            } else {
                log_event("Flame cleared");
                printf("Flame cleared\n");
            }
            previous_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 100ms
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

