#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define RESULT_REG 0x00
#define CONFIG_REG 0x01
#define CONFIG_VALUE 0xC810 // Continuous mode, 100ms conversion time
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(unsigned short *raw_data);
float unpack_and_calculate_lux(unsigned short raw_data);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (CONFIG_VALUE >> 8) & 0xFF;
    buf[2] = CONFIG_VALUE & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned short *raw_data) {
    char buf[1];
    char read_buf[2];
    int result;

    buf[0] = RESULT_REG;

    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to result register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    *raw_data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Unpack and calculate lux value
float unpack_and_calculate_lux(unsigned short raw_data) {
    unsigned short exponent = (raw_data >> 12) & 0x0F;
    unsigned short mantissa = raw_data & 0x0FFF;
    return 0.01 * pow(2, exponent) * mantissa;
}

// Log data to file
int log_data(float lux_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    unsigned short raw_data;
    float lux_value;
    int retry;

    while (!terminate) {
        retry = 0;
