#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read the flame detection status from the GPIO line
int read_flame_detection(struct gpiod_line *line)
{
    int value;

    value = gpiod_line_request_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }

    return value;
}

// Function to log the flame detection status to the console
void log_flame_status(int status)
{
    char *timestamp = get_timestamp();

    if (status == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }
}

int main()
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct gpiod_line_settings settings;
    int status;

    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the GPIO line as an input with bias pulled up
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    status = gpiod_line_request(line, &config, 0);
    if (status < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(-status));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        status = read_flame_detection(line);
        if (status >= 0) {
            log_flame_status(status);
        } else {
            fprintf(stderr, "Error reading flame detection status, exiting.\n");
            break;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    // Clean up resources before exiting
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

