#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins for the TTP226 sensor
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8];

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_channels; i++)
    {
        if (lines[i])
        {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip)
    {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        fprintf(stderr, "Error: Could not open GPIO chip.\n");
        return 1;
    }

    // Request GPIO lines for each channel
    for (int i = 0; i < num_channels; i++)
    {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i])
        {
            fprintf(stderr, "Error: Could not get line for GPIO pin %d.\n", gpio_pins[i]);
            // Release previously acquired lines before exiting
            for (int j = 0; j < i; j++)
            {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Request the line for input
        if (gpiod_line_request_input(lines[i], "ttp226_sensor") < 0)
        {
            fprintf(stderr, "Error: Could not request input for GPIO pin %d.\n", gpio_pins[i]);
            // Release previously acquired lines before exiting
            for (int j = 0; j <= i; j++)
            {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to read sensor data
    while (1)
    {
        for (int i = 0; i < num_channels; i++)
        {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0)
            {
                fprintf(stderr, "Error: Could not read value from GPIO pin %d.\n", gpio_pins[i]);
                // Release previously acquired lines before exiting
                for (int j = 0; j <= i; j++)
                {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }
            printf("Channel %d: %d\n", i + 1, value);
        }
        usleep(100000); // 100 ms delay
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    for (int i = 0; i < num_channels; i++)
    {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

