    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Define an array of GPIO pins to be initialized
    int pins[] = {TTP226_PIN_1, TTP226_PIN_2, TTP226_PIN_3, TTP226_PIN_4,
