#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the GPIO pins connected to the TTP226 sensors
const int sensor_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of all sensors
int read_sensors(int *sensor_values) {
    for (int i = 0; i < num_sensors; i++) {
        sensor_values[i] = gpioRead(sensor_pins[i]);
        if (sensor_values[i] < 0) {
            fprintf(stderr, "Error reading sensor %d: %d\n", i, sensor_values[i]);
            return -1; // Indicate an error
        }
    }
    return 0; // Indicate success
}

// Function to format the sensor data into a CSV string
int format_csv(int *sensor_values, char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(buffer, buffer_size, "%s", timestamp);
    for (int i = 0; i < num_sensors; i++) {
        snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), ",%d", sensor_values[i]);
    }
    snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), "\n");

    return 0;
}

// Function to print the CSV string to stdout
void print_csv(const char *csv_string) {
    printf("%s", csv_string);
    fflush(stdout); // Ensure data is written immediately
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the GPIO pins as inputs with pull-down resistors
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Allocate memory for sensor values and CSV buffer
    int *sensor_values = (int *)malloc(num_sensors * sizeof(int));
    if (sensor_values == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
        return 1;
    }

    char *csv_buffer = (char *)malloc(256 * sizeof(char)); // Adjust buffer size as needed
    if (csv_buffer == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(sensor_values);
        gpioTerminate();
        return 1;
    }

    // Main loop to read sensors and print CSV data
    while (!terminate) {
        // Read sensor values
        if (read_sensors(sensor_values) != 0) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        // Format CSV data
        if (format_csv(sensor_values, csv_buffer, sizeof(csv_buffer)) != 0) {
            fprintf(stderr, "Error formatting CSV, exiting...\n");
            break;
        }

        // Print CSV data
        print_csv(csv_buffer);

        // Wait for 50 milliseconds
        gpioDelay(50);
    }

    // Clean up resources before exiting
    free(sensor_values);
    free(csv_buffer);
    gpioTerminate();

    return 0;
}

