#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_init_result;
    int current_state, previous_state = -1; // Initialize to an invalid state
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    gpio_init_result = gpioInitialise();
    if (gpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", gpio_init_result);
        return 1;
    }

    // Configure GPIO 4 as an input with pull-up resistor
    gpioSetMode(TILT_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_state = gpioRead(TILT_GPIO);

        if (current_state != previous_state) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the tilt state with timestamp
            if (current_state == 0) {
                printf("%s - Tilted\n", timestamp);
            } else {
                printf("%s - Not Tilted\n", timestamp);
            }

            fflush(stdout); // Ensure the log is written immediately
            previous_state = current_state;
        }

        gpioDelay(100); // Poll every 100 milliseconds
    }

    // Terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

