#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 Registers
#define REG_PART_ID 0x00
#define REG_HW_KEY  0x07
#define REG_CHLIST  0x01
#define REG_ALS_VIS_DATA0 0x22
#define REG_UV_INDEX_DATA0 0x2C
#define REG_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_si1145_data(float *uv_index, int *als_visible);
void log_data(float uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize the Si1145 sensor
int si1145_init() {
    int part_id;

    // Verify PART ID
    part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }
    fprintf(stderr, "Si1145 PART ID: 0x%02X\n", part_id);

    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Configure CHLIST
    if (i2cWriteByteData(i2c_handle, REG_CHLIST, 0x03) < 0) {
        fprintf(stderr, "Error writing CHLIST\n");
        return -1;
    }

    return 0;
}

// Read UV index and Visible ALS data from the Si1145
int read_si1145_data(float *uv_index, int *als_visible) {
    int als_vis_low, als_vis_high, uv_index_low, uv_index_high;

    // Trigger ALS measurement
    if (i2cWriteByteData(i2c_handle, REG_ALS_FORCE, 0x01) < 0) {
        fprintf(stderr, "Error triggering ALS measurement\n");
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(10); // 10ms delay

    // Read ALS_VIS data
    als_vis_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
