#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define GPIO_PIN 17
#define FLOW_LOG_FILE "flow_log.txt"
#define ALARM_THRESHOLD 0.5
#define SCALE_FACTOR 0.036
#define START_MEASUREMENT_COMMAND 0x3608

// Sensor addresses
const int sensor_addresses[] = {0x36, 0x37};
const int num_sensors = sizeof(sensor_addresses) / sizeof(sensor_addresses[0]);

// Global variables
int i2c_fds[2]; // File descriptors for I2C devices
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(int fd, int address, int *flow, int *temperature);
int validate_crc(uint8_t data[], int length, uint8_t crc);
float convert_flow(int raw_flow);
void log_flow_data(float flow1, float flow2);
void control_alarm(float average_flow);
void signal_handler(int signal);
void cleanup();

// CRC-8-ATM polynomial 0x8C
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x8C;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C and start measurements
    for (int i = 0; i < num_sensors; i++) {
        i2c_fds[i] = initialize_i2c(sensor_addresses[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to initialize sensor at address 0x%02X\n", sensor_addresses[i]);
            cleanup();
            return 1;
        }

        // Send start measurement command
        uint8_t command[2] = {(START_MEASUREMENT_COMMAND >> 8) & 0xFF, START_MEASUREMENT_COMMAND & 0xFF};
        if (write(i2c_fds[i], command, 2) != 2) {
            perror("Error writing start measurement command");
            cleanup();
            return 1;
        }
        gpioDelay(100); // Wait for measurement to start
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        float flow1 = 0.0, flow2 = 0.0;
        int raw_flow1, raw_flow2, raw_temp1, raw_temp2;

        // Read data from sensor 1
        if (read_sensor_data(i2c_fds[0], sensor_addresses[0], &raw_flow1, &raw_temp1) == 0) {
            flow1 = convert_flow(raw_flow1);
        } else {
            fprintf(stderr, "Error reading sensor 1\n");
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_fds[1], sensor_addresses[1], &raw_flow2, &raw_temp2) == 0) {
            flow2 = convert_flow(raw_flow2);
        } else {
            fprintf(stderr, "Error reading sensor 2\n");
        }

        // Log data
        log_flow_data(flow1, flow2);

        // Control alarm
        control_alarm((flow1 + flow2) / 2.0);

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data
int read_sensor_data(int fd, int address, int *flow, int *temperature) {
    uint8_t buffer[9];

    // Read 9 bytes from register 0x00
    if (read(fd, buffer, 9) != 9) {
        perror("Error reading sensor data");
        return -1;
    }

    // Extract flow, temperature, and CRC from the buffer
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    uint8_t crc = buffer[8];

    // Validate CRC
    uint8_t data[6] = {buffer[0], buffer[1], buffer[2], buffer[3], buffer[4], buffer[5]};
    if (!validate_crc(data, 6, crc)) {
        fprintf(stderr, "CRC validation failed for sensor at address 0x%02X\n", address);
        return -1;
    }

    *flow = raw_flow;
    *temperature = raw_temperature;

    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int length, uint8_t crc) {
    return crc8(data, length) == crc;
}

// Convert raw flow to ml/min
float convert_flow(int raw_flow) {
    return raw_flow * SCALE_FACTOR;
}

// Log flow data to file
void log_flow_data(float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, flow1, flow2);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control alarm based on average flow
void control_alarm(float average_flow) {
    if (average_flow < ALARM_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    // Close I2C file descriptors
    for (int i = 0; i < num_sensors; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO pin
    gpioWrite(GPIO_PIN, 0); // Set low before terminating
    gpioTerminate();
}

