#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_LSB_REG 0x2A
#define ACCEL_X_MSB_REG 0x2B
#define ACCEL_Y_LSB_REG 0x2C
#define ACCEL_Y_MSB_REG 0x2D
#define ACCEL_Z_LSB_REG 0x2E
#define ACCEL_Z_MSB_REG 0x2F
#define SCALE_FACTOR 0.0009765625f
#define SAMPLE_INTERVAL_MS 500
#define TIMEOUT_SEC 1

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_d7s();
int read_acceleration(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C initialization
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", I2C_BUS);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: 0x%02X\n", D7S_ADDR);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// D7S initialization
int init_d7s() {
    uint8_t mode_control_value = 0x10; // Active mode
    uint8_t write_buffer[2];
    write_buffer[0] = MODE_CONTROL_REG;
    write_buffer[1] = mode_control_value;

    if (write(i2c_fd, write_buffer, 2) != 2) {
        fprintf(stderr, "Error writing to MODE_CONTROL_REG\n");
        return -1;
    }

    // Wait for sensor to become active
    time_t start_time = time(NULL);
    while (1) {
        uint8_t read_buffer[1];
        read_buffer[0] = OPERATING_STATUS_REG;
        if (write(i2c_fd, read_buffer, 1) != 1) {
            fprintf(stderr, "Error writing to OPERATING_STATUS_REG for read\n");
            return -1;
        }

        uint8_t status_value[1];
        if (read(i2c_fd, status_value, 1) != 1) {
            fprintf(stderr, "Error reading from OPERATING_STATUS_REG\n");
            return -1;
        }

        if (status_value[0] & 0x01) {
            break; // Sensor active
        }

        if (difftime(time(NULL), start_time) > TIMEOUT_SEC) {
            fprintf(stderr, "Timeout waiting for D7S to become active\n");
            return -1;
        }

        usleep(10000); // 10ms delay
    }

    return 0;
}

// Read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    uint8_t read_buffer[1];
    uint8_t data_buffer[6];

    // Read X, Y, and Z acceleration registers
    read_buffer[0] = ACCEL_X_LSB_REG;
    if (write(i2c_fd, read_buffer, 1) != 1) {
        fprintf(stderr, "Error writing to ACCEL_X_LSB_REG for read\n");
        return -1;
    }

    if (read(i2c_fd, data_buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine LSB and MSB, convert to signed 16-bit integer
    int16_t raw_x = (int16_t)((data_buffer[1] << 8) | data_buffer[0]);
    int16_t raw_y = (int16_t)((data_buffer[3] << 8) | data_buffer[2]);
    int16_t raw_z = (int16_t)((data_buffer[5] << 8) | data_buffer[4]);

    // Convert to g
    *x = (float)raw_x * SCALE_FACTOR;
    *y = (float)raw_y * SCALE_FACTOR;
    *z = (float)raw_z * SCALE_FACTOR;

    return 0;
}

// Log data to CSV file
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (csv_file == NULL) {
        csv_file = fopen("fan_health.csv", "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file\n");
            return;
        }
        fprintf(csv_file, "Timestamp,X,Y,Z\n"); // Write header
    }

    fprintf(csv_file, "%s,%.8f,%.8f,%.8f\n", timestamp, x, y, z);
    fflush(csv_file); // Ensure data is written immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize D7S sensor
    if (init_d7s() != 0) {
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 500ms
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();

    return 0;
}

