#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_PIN\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    *sensor1_value = gpioRead(SENSOR_1_PIN);
    if (*sensor1_value < 0) {
        fprintf(stderr, "Failed to read SENSOR_1_PIN\n");
        return -1;
    }

    *sensor2_value = gpioRead(SENSOR_2_PIN);
    if (*sensor2_value < 0) {
        fprintf(stderr, "Failed to read SENSOR_2_PIN\n");
        return -1;
    }

    return 0;
}

// Function to control the LED
void control_led(int sensor1_value, int sensor2_value) {
    if (sensor1_value == 0 || sensor2_value == 0) {
        gpioWrite(LED_PIN, 1); // Turn LED ON
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED OFF
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int sensor1_value, sensor2_value;

    // Main loop
    while (program_running) {
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            control_led(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

