#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_MS 2000
#define LOG_FILE "stall_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} SensorData;

// Function prototypes
int initialize_gpio();
SensorData read_sensors();
int is_stall_detected(SensorData data);
int log_stall_event();
void signal_handler(int signal);
void cleanup();

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    time_t last_log_time = 0; // Initialize to 0 to log on the first stall

    while (program_running) {
        SensorData sensor_data = read_sensors();

        if (is_stall_detected(sensor_data)) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_log_time) >= 2) {
                if (log_stall_event() == 0) {
                    last_log_time = current_time;
                }
            }
        }

