#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define CSV_FILE "magnetic_log.csv"
#define SAMPLE_INTERVAL_MS 100

// TMAG5170 Registers
#define REG_DEVICE_ID 0x00
#define REG_X_AXIS_LSB 0x01
#define REG_X_AXIS_MSB 0x02
#define REG_Y_AXIS_LSB 0x03
#define REG_Y_AXIS_MSB 0x04
#define REG_Z_AXIS_LSB 0x05
#define REG_Z_AXIS_MSB 0x06
#define REG_CONTROL 0x07

// Configuration values
#define CONFIG_CONTINUOUS_MODE 0x03 // Enable X, Y, Z axes, 50 mT range

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
int configure_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mt(int16_t raw_value);
int log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, REG_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != 0x8D) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x8D)\n", device_id);
        return -1;
    }

    printf("Device ID verified: 0x%02X\n", device_id);
    return 0;
}

// Configure the sensor
int configure_sensor() {
    int status = i2cWriteByteData(i2c_handle, REG_CONTROL, CONFIG_CONTINUOUS_MODE);
    if (status < 0) {
        fprintf(stderr, "Error configuring sensor: %d\n", status);
        return -1;
    }
    printf("Sensor configured for continuous mode and 50 mT range\n");
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, REG_X_AXIS_LSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw data to mT
float convert_to_mt(int16_t raw_value) {
    // Assuming 50 mT range, LSB scale factor is 0.0001 mT/LSB
    return (float)raw_value * 0.0001;
}

// Log data to CSV file
int log_data(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,X,Y,Z\n");
    }
    rewind(fp);

    // Main loop
    int16_t x_raw, y_raw, z_raw;
    float x_mt, y_mt, z_mt;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to mT
            x_mt = convert_to_mt(x_raw);
            y_mt = convert_to_mt(y_raw);
            z_mt = convert_to_mt(z_raw);

            // Log data
            if (log_data(x_mt, y_mt, z_mt) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

