#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define POLL_INTERVAL_SEC 2
#define MAX_REINIT_ATTEMPTS 3

static volatile int running = 1;
static int log_fd = -1;
static int error_log_fd = -1;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure it's static to persist after function returns

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the flood_log.txt file
void log_message(const char *message) {
    char *timestamp = get_timestamp();
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s %s\n", timestamp, message);

    if (log_fd != -1) {
        if (write(log_fd, log_entry, strlen(log_entry)) == -1) {
            perror("Error writing to log file");
        }
    } else {
        fprintf(stderr, "Log file not opened. Message: %s", message);
    }
}

// Function to log an error message to the error_log.txt file
void log_error(const char *message) {
    char *timestamp = get_timestamp();
    char error_entry[256];
    snprintf(error_entry, sizeof(error_entry), "%s ERROR: %s\n", timestamp, message);

    if (error_log_fd != -1) {
        if (write(error_log_fd, error_entry, strlen(error_entry)) == -1) {
            perror("Error writing to error log file");
        }
    } else {
        fprintf(stderr, "Error log file not opened. Message: %s", message);
    }
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to read the water level sensor
int read_sensor() {
    int level = gpioRead(GPIO_PIN);
    if (level == PI_BAD_GPIO) {
        log_error("Failed to read sensor value");
        return -1; // Indicate error
    }
    return level;
}

// Function to handle the water level alert
void handle_alert() {
    log_message("ALERT: Water detected");
}

// Function to re-initialize the pigpio library
int reinitialize_pigpio() {
    gpioTerminate();
    sleep(1); // Give it some time to fully terminate
    return initialize_pigpio();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log files
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        return 1;
    }

    error_log_fd = open(ERROR_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (error_log_fd == -1) {
        perror("Error opening error log file");
        close(log_fd);
        return 1;
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        close(log_fd);
        close(error_log_fd);
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    int reinit_attempts = 0;

    printf("Water level monitoring daemon started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            handle_alert();
        } else if (sensor_value == -1) {
            // Sensor read error, attempt re-initialization
            reinit_attempts++;
            if (reinit_attempts <= MAX_REINIT_ATTEMPTS) {
                log_error("Sensor read failed. Attempting to re-initialize...");
                if (reinitialize_pigpio() != 0) {
                    log_error("Failed to re-initialize pigpio. Retry attempts exhausted.");
                    reinit_attempts = MAX_REINIT_ATTEMPTS + 1; // Stop retrying
                } else {
                    log_message("pigpio re-initialized successfully.");
                    reinit_attempts = 0; // Reset retry counter
                }
            } else {
                log_error("Sensor read failed and re-initialization attempts exhausted.");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    // Clean up resources
    gpioTerminate();
    close(log_fd);
    close(error_log_fd);

    printf("Water level monitoring daemon stopped.\n");

    return 0;
}

