void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log files
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        return 1;
    }

    error_log_fd = open(ERROR_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (error_log_fd == -1) {
        perror("Error opening error log file");
        close(log_fd);
        return 1;
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        close(log_fd);
        close(error_log_fd);
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    int reinit_attempts = 0;

    printf("Water level monitoring daemon started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            handle_alert();
        } else if (sensor_value == -1) {
            // Sensor read error, attempt re-initialization
            reinit_attempts++;
            if (reinit_attempts <= MAX_REINIT_ATTEMPTS) {
                log_error("Sensor read failed. Attempting to re-initialize...");
                if (reinitialize_pigpio() != 0) {
                    log_error("Failed to re-initialize pigpio. Retry attempts exhausted.");
                    reinit_attempts = MAX_REINIT_ATTEMPTS + 1; // Stop retrying
                } else {
                    log_message("pigpio re-initialized successfully.");
                    reinit_attempts = 0; // Reset retry counter
                }
            } else {
                log_error("Sensor read failed and re-initialization attempts exhausted.");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    // Clean up resources
    gpioTerminate();
    close(log_fd);
    close(error_log_fd);

    printf("Water level monitoring daemon stopped.\n");

    return 0;
}

