#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the quadrature state machine states
typedef enum {
    STATE_A,
    STATE_B,
    STATE_C,
    STATE_D
} QuadState;

// Define rotation directions
typedef enum {
    CLOCKWISE,
    COUNTER_CLOCKWISE,
    UNKNOWN
} RotationDirection;

// Global variables
static volatile QuadState current_state = STATE_A;
static volatile RotationDirection rotation_direction = UNKNOWN;
static volatile int running = 1; // Flag to control the main loop
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void log_rotation_event(RotationDirection direction);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Set the running flag to 0 to exit the main loop

    // Release mutex
    pthread_mutex_unlock(&mutex);

    // Close the log file
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to log rotation events to a file
void log_rotation_event(RotationDirection direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Get milliseconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    // Lock the mutex
    pthread_mutex_lock(&mutex);

    // Write the log entry
    fprintf(log_file, "%s.%03ld: Rotation %s\n", timestamp, milliseconds,
            (direction == CLOCKWISE) ? "CW" : "CCW");

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);

    // Flush the log file
    fflush(log_file);

    // Close the log file
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing
}

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&mutex);

    switch (current_state) {
        case STATE_A:
            if (level == 1) {
                current_state = STATE_B;
            } else {
                current_state = STATE_D;
            }
            break;
        case STATE_B:
            if (level == 1) {
                current_state = STATE_C;
                rotation_direction = CLOCKWISE;
            } else {
                current_state = STATE_A;
            }
            break;
        case STATE_C:
            if (level == 1) {
                current_state = STATE_D;
            } else {
                current_state = STATE_B;
            }
            break;
        case STATE_D:
            if (level == 1) {
                current_state = STATE_A;
                rotation_direction = COUNTER_CLOCKWISE;
            } else {
                current_state = STATE_C;
            }
            break;
    }

    pthread_mutex_unlock(&mutex);

    log_rotation_event(rotation_direction);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&mutex);

    switch (current_state) {
        case STATE_A:
            if (level == 1) {
                current_state = STATE_D;
            } else {
                current_state = STATE_B;
            }
            break;
        case STATE_B:
            if (level == 1) {
                current_state = STATE_A;
                rotation_direction = COUNTER_CLOCKWISE;
            } else {
                current_state = STATE_C;
            }
            break;
        case STATE_C:
            if (level == 1) {
                current_state = STATE_B;
            } else {
                current_state = STATE_D;
            }
            break;
        case STATE_D:
            if (level == 1) {
                current_state = STATE_C;
                rotation_direction = CLOCKWISE;
            } else {
                current_state = STATE_A;
            }
            break;
    }

    pthread_mutex_unlock(&mutex);

    log_rotation_event(rotation_direction);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes to input with pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Set interrupt service routines for both sensors
    if (gpioSetAlertFunc(SENSOR_A_GPIO, sensor_a_isr) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFunc(SENSOR_B_GPIO, sensor_b_isr) != 0) {
        fprintf(stderr, "Failed to set alert function for Sensor B\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Sleep for 1 second to reduce CPU usage
    }

    return 0;
}

