#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *touch_line;
static struct gpiod_line *led_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Failed to get touch sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(touch_line, "touch_sensor", 0) < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read the touch sensor value
int read_touch_sensor() {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read touch sensor value");
        return -1;
    }
    return value;
}

// Control the LED state
int control_led(int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        syslog(LOG_ERR, "Failed to set LED value");
        return -1;
    }
    return 0;
}

// Log an event to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);

    syslog(LOG_INFO, "%s", log_message);
}

// Cleanup GPIO resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up GPIO resources...");

