#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define log buffer size
#define LOG_BUFFER_SIZE 100

// Structure to store log entries
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

// Global variables
volatile sig_atomic_t program_running = 1;
int log_buffer_index = 0;
LogEntry log_buffer[LOG_BUFFER_SIZE];
int overflow_count = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int control_led(int pin, int state);
void log_event(int sensor_pin, int state);
void print_log_buffer();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read sensor value with debouncing
int read_sensor(int pin) {
    int i, reading;
    int sum = 0;
    int threshold = 5; // Adjust threshold for sensitivity

    for (i = 0; i < threshold; i++) {
        reading = gpioRead(pin);
        if (reading < 0) {
            fprintf(stderr, "Failed to read sensor on pin %d\n", pin);
            return 0; // Return 0 on error
        }
        sum += reading;
        gpioDelay(DEBOUNCE_TIME * 1000); // Delay in microseconds
    }

    return (sum >= threshold) ? 1 : 0; // Return 1 if majority is high, 0 otherwise
}

// Control LED state
int control_led(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write to pin %d\n", pin);
        return 1;
    }
    return 0;
}

// Log sensor event
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);

    log_buffer[log_buffer_index].sensor_pin = sensor_pin;
    log_buffer[log_buffer_index].timestamp = now;
    log_buffer[log_buffer_index].state = state;

    log_buffer_index = (log_buffer_index + 1) % LOG_BUFFER_SIZE;

    if (log_buffer_index == 0) {
        overflow_count++;
    }
}

// Print log buffer contents
void print_log_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        printf("Index: %d, Sensor Pin: %d, Timestamp: %ld, State: %d\n",
               i, log_buffer[i].sensor_pin, log_buffer[i].timestamp, log_buffer[i].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor1_state = read_sensor(SENSOR_1_PIN);
        int sensor2_state = read_sensor(SENSOR_2_PIN);

        if (control_led(LED_1_PIN, sensor1_state) != 0) {
            program_running = 0;
            break;
        }
        if (control_led(LED_2_PIN, sensor2_state) != 0) {
            program_running = 0;
            break;
        }

        if (sensor1_state != log_buffer[log_buffer_index].state || log_buffer_index == 0) {
            log_event(SENSOR_1_PIN, sensor1_state);
        }
        if (sensor2_state != log_buffer[log_buffer_index].state || log_buffer_index == 0) {
            log_event(SENSOR_2_PIN, sensor2_state);
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    gpioTerminate();
    print_log_buffer();

    return 0;
}

