#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in microseconds
#define DEBOUNCE_TIME 5000

// Number of pulses per revolution (assuming 2 pulses per revolution)
#define PULSES_PER_REVOLUTION 2

// Global variables
volatile int sensor1_state = 0;
volatile int sensor2_state = 0;
volatile unsigned long last_interrupt_time1 = 0;
volatile unsigned long last_interrupt_time2 = 0;

FILE *log_file = NULL;

// Function prototypes
void sensor1_callback(int gpio, int level, unsigned int tick, void *user_data);
void sensor2_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_rpm(unsigned long pulse_count, double time_elapsed);
void log_data(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (current_time - last_interrupt_time1 > DEBOUNCE_TIME) {
        sensor1_state = level; // Update sensor state
        last_interrupt_time1 = current_time;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (current_time - last_interrupt_time2 > DEBOUNCE_TIME) {
        sensor2_state = level; // Update sensor state
        last_interrupt_time2 = current_time;
    }
}

// Function to calculate RPM
double calculate_rpm(unsigned long pulse_count, double time_elapsed) {
    if (time_elapsed > 0) {
        return (double)pulse_count / time_elapsed * 60.0;
    } else {
        return 0.0;
    }
}

// Function to log data to a CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Disable interrupts
    gpioSetAlertFuncEx(SENSOR1_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, NULL, NULL);

    // Terminate pigpio
    gpioTerminate();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Set up interrupt handlers for both sensors
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned long start_time, end_time;
    unsigned long pulse_count1 = 0;
    unsigned long pulse_count2 = 0;
    double time_elapsed;
    double rpm1, rpm2;

    // Main loop
    while (1) {
        start_time = gpioTick();

        // Wait for a short period to collect pulses
        gpioDelay(100000); // 100ms

        end_time = gpioTick();

        time_elapsed = (double)(end_time - start_time) / 1000000.0; // Time in seconds

        // Calculate RPM for each sensor
        rpm1 = calculate_rpm(pulse_count1, time_elapsed);
        rpm2 = calculate_rpm(pulse_count2, time_elapsed);

        // Print RPM values
        printf("Sensor 1 RPM: %.2f, Sensor 2 RPM: %.2f\n", rpm1, rpm2);

        // Log data
        log_data(sensor1_state, sensor2_state);

        // Reset pulse counts
        pulse_count1 = 0;
        pulse_count2 = 0;
    }

    return 0;
}

