#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int verify_sensor(int handle);
int configure_sensor(int handle);
int read_sensor_data(int handle, int *heart_rate, int *spo2);
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    int config_value;
} sensor_config_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Function to verify the sensor
int verify_sensor(int handle) {
    int part_id = i2cReadByteData(handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register: %d\n", part_id);
        return -1;
    }

    // Check if the PART_ID is correct (replace with the correct value)
    if (part_id != 0x50) { // Example value, check datasheet
        fprintf(stderr, "Incorrect PART_ID: 0x%02x\n", part_id);
        return -1;
    }

    printf("Sensor verified successfully. PART_ID: 0x%02x\n", part_id);
    return 0;
}

// Function to configure the sensor
int configure_sensor(int handle) {
    // Example configuration (replace with actual configuration)
    int config_value = 0x01; // Example value
    int result = i2cWriteByteData(handle, CONFIG_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to CONFIG register: %d\n", result);
        return -1;
    }

    printf("Sensor configured successfully. CONFIG_REG: 0x%02x\n", config_value);
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, int *heart_rate, int *spo2) {
    int hr, sp;

    hr = i2cReadByteData(handle, HEART_RATE_REG);
    if (hr < 0) {
        fprintf(stderr, "Failed to read HEART_RATE_REG: %d\n", hr);
        return -1;
    }

    sp = i2cReadByteData(handle, SPO2_REG);
    if (sp < 0) {
        fprintf(stderr, "Failed to read SPO2_REG: %d\n", sp);
        return -1;
    }

    *heart_rate = hr;
    *spo2 = sp;

    return 0;
}

// Function to log data to a file
int log_data(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI1182_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int heart_rate, spo2;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &heart_rate, &spo2) == 0) {
            // Log data
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

