#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_REG 0x28
#define ACCEL_Y_REG 0x2A
#define ACCEL_Z_REG 0x2C
#define VIBRATION_THRESHOLD 500
#define LED_GPIO 17
#define RETRY_COUNT 3
#define SAMPLE_PERIOD_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(double vibration_magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the sensor by checking its presence and clearing the power-down bit
int initialize_sensor() {
    int status;
    int retries = 0;

    // Check sensor presence by reading a register (e.g., CTRL1)
    while (retries < RETRY_COUNT) {
        status = i2cReadByteData(i2c_handle, CTRL1_REG);
        if (status >= 0) {
            // Sensor found
            break;
        } else {
            fprintf(stderr, "Error reading CTRL1 register (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read CTRL1 register after %d retries. Exiting.\n", RETRY_COUNT);
        return -1;
    }

    // Clear the power-down bit (set bit 7 to 0)
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00); // Assuming CTRL1 register is 0x1F
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL1 register (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write to CTRL1 register after %d retries. Exiting.\n", RETRY_COUNT);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Reads the 3-axis acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        status = i2cReadI2CBlockData(i2c_handle, ACCEL_X_REG, buffer, 6);
        if (status == 6) {
            // Success
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0;
        } else {
            fprintf(stderr, "Error reading acceleration data (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Failed to read acceleration data after %d retries.\n", RETRY_COUNT);
    return -1;
}

// Calculates the Euclidean vibration magnitude
double calculate_vibration_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Logs the event to a file with an ISO-8601 timestamp
void log_event(double vibration_magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, vibration_magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int status;
    int16_t x, y, z;
    double vibration_magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate vibration magnitude
            vibration_magnitude = calculate_vibration_magnitude(x, y, z);

            // Check if threshold is exceeded
            if (vibration_magnitude > VIBRATION_THRESHOLD) {
                printf("Vibration threshold exceeded: %.2f\n", vibration_magnitude);

                // Turn on LED
                gpioWrite(LED_GPIO, 1);

                // Log the event
                log_event(vibration_magnitude);

                // Wait for 1 second
                gpioDelay(1000000); // 1 second = 1000000 microseconds

                // Turn off LED
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying in %d ms.\n", SAMPLE_PERIOD_MS);
        }

        // Delay for 100ms
        gpioDelay(SAMPLE_PERIOD_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

