#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins for the flame sensors
const int sensor_pins[] = {2, 3, 4, 17, 27};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Debounce time in milliseconds
const int debounce_time_ms = 50;

// Log file path
const char *log_file_path = "/var/log/flame_events.log";

// Global variables
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[5] = {NULL};
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int pin);
int debounce_sensor(int pin);
void log_event(int pin, int sensor_id);
void signal_handler(int sig);
void cleanup();

// Function to read the sensor value from a given GPIO pin
int read_sensor(int pin) {
    int value = -1;
    struct gpiod_line *line = lines[pin - 2];

    if (!line) {
        syslog(LOG_ERR, "Error: Line for pin %d not initialized", pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading value from pin %d: %s", pin, strerror(errno));
        return -1;
    }

    return value;
}

// Function to debounce the sensor reading
int debounce_sensor(int pin) {
    int value = read_sensor(pin);
    if (value < 0) return -1;

    struct timespec delay = {0, debounce_time_ms * 1000000L}; // Convert ms to ns
    nanosleep(&delay, NULL);

    int new_value = read_sensor(pin);
    if (new_value < 0) return -1;

    return (value == 0 && new_value == 1) ? 1 : 0; // Rising edge
}

// Function to log the flame detection event
void log_event(int pin, int sensor_id) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen(log_file_path, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Error opening log file: %s", strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Error locking log file: %s", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, pin);
    fflush(fp);

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Error unlocking log file: %s", strerror(errno));
    }

    fclose(fp);
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");

    // Release lines
    for (int i = 0; i < num_sensors; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    closelog();
}

int main() {
    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_USER, LOG_USER);
    syslog(LOG_INFO, "Starting flame monitor...");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Request lines
    for (int i = 0; i < num_sensors; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Error getting line %d: %s", sensor_pins[i], strerror(errno));
            cleanup();
            return 1;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Error requesting line %d: %s", sensor_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < num_sensors; i++) {
            int debounced_value = debounce_sensor(sensor_pins[i]);
            if (debounced_value > 0) {
                log_event(sensor_pins[i], i + 1);
            }
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    syslog(LOG_INFO, "Exiting.");
    return 0;
}

