        fprintf(stderr, "Error allocating memory for lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request each line for input
    for (i = 0; i < NUM_SENSORS; i++) {
        snprintf(line_name, sizeof(line_name), "%s%d", LINE_PREFIX, i);
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %s: %s\n", line_name, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            free(lines);
            gpiod_chip_close(chip);
            return 1;
        }

        ret = gpiod_line_request_input(lines[i], line_name);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %s: %s\n", line_name, strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            free(lines);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to read and log touch events
    int previous_states[NUM_SENSORS] = {0}; // Initialize previous states
    while (1) {
        for (i = 0; i < NUM_SENSORS; i++) {
            int current_state = read_touch_sensor(i);
            if (current_state != previous_states[i]) {
                log_touch_event(i, sensor_pins[i], current_state);
                previous_states[i] = current_state;
            }
        }
        gpiod_chip_sleep(chip, 0.05); // Sleep for 50 milliseconds
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig)
{
    int i;

    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release all lines
    if (lines) {
        for (i = 0; i < NUM_SENSORS; i++) {
            if (lines[i]) {
                gpiod_line_release(lines[i]);
            }
        }
        free(lines);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp: %s\n", strerror(errno));
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to read the state of a single touch sensor
int read_touch_sensor(int sensor_index)
{
    int value;

    if (!lines[sensor_index]) {
        fprintf(stderr, "Error: Line for sensor %d not initialized\n", sensor_index);
        return -1; // Indicate an error
    }

    value = gpiod_line_get_value(lines[sensor_index]);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", sensor_index, strerror(errno));
        return -1; // Indicate an error
    }

    return value;
}

// Function to log a touch event
void log_touch_event(int sensor_index, int pin, int state)
{
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp, skipping log entry\n");
        return;
    }

    if (state == 1) {
        printf("%s Sensor %d (BCM %d) touched\n", timestamp, sensor_index, pin);
    } else {
        printf("%s Sensor %d (BCM %d) released\n", timestamp, sensor_index, pin);
    }

    free(timestamp);
}

