#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define LED_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

// VEML7700 Registers
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int config_veml7700();
int read_veml7700(unsigned int *raw_data);
float convert_to_lux(unsigned int raw_data);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700
int config_veml7700() {
    unsigned short config_value = 0x0000; // ALS_IT = 100ms, ALS_GAIN = 1/8
    char buf[3];
    buf[0] = VEML7700_CONFIG;
    buf[1] = config_value & 0xFF;
    buf[2] = (config_value >> 8) & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write config: %d\n", result);
        return -1;
    }
    return 0;
}

// Read VEML7700 data
int read_veml7700(unsigned int *raw_data) {
    char buf[1];
    buf[0] = VEML7700_ALS;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write ALS register address: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return -1;
    }

    *raw_data = (data[1] << 8) | data[0];
    return 0;
}

// Convert raw data to lux
float convert_to_lux(unsigned int raw_data) {
    return raw_data * 0.0576;
}

// Set LED brightness based on lux value
int set_led_brightness(float lux) {
    int brightness = 0;

    if (lux < 100) {
        brightness = 100;
    } else if (lux < 500) {
        brightness = 75;
    } else if (lux < 1000) {
        brightness = 50;
    } else {
        brightness = 25;
    }

    gpioPWM(LED_GPIO, brightness);
    return brightness;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700
    if (config_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    unsigned int raw_data;
    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read VEML7700 data
        if (read_veml7700(&raw_data) == 0) {
            // Convert to lux
            lux = convert_to_lux(raw_data);

            // Set LED brightness
            brightness = set_led_brightness(lux);

            // Log data
            log_data(lux, brightness, 0); // Error code 0 for success
        } else {
            fprintf(stderr, "Error reading VEML7700 data\n");
            log_data(0.0, 0, -1); // Log error with error code -1
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

