#include <string.h>

// Define GPIO pins
#define LED_PIN 17
#define TOUCH_PINS {2, 3, 4, 5, 6, 7, 8, 9}

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold touch state and timestamp
typedef struct {
    int touched;
    unsigned long last_touched_time;
} touch_state_t;

touch_state_t touch_states[8];

// Function prototypes
int initialize_gpio();
int read_touch_channels(int *channels);
void log_touch_event(int channel);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    running = 0;
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    // Turn off the LED
    gpioWrite(LED_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set touch sensor pins as inputs with pull-down resistors
    int touch_pins[] = TOUCH_PINS;
    for (int i = 0; i < 8; i++) {
        gpioSetMode(touch_pins[i], PI_INPUT);
        gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN);
    }

    return 0;
}

// Read touch sensor channels
int read_touch_channels(int *channels) {
    int touch_pins[] = TOUCH_PINS;
    for (int i = 0; i < 8; i++) {
        channels[i] = gpioRead(touch_pins[i]);
    }
    return 0;
}

// Log touch event to file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fclose(log_file);
}

// Control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize touch states
    for (int i = 0; i < 8; i++) {
        touch_states[i].touched = 0;
        touch_states[i].last_touched_time = 0;
    }

    int channels[8];

    // Main loop
    while (running) {
        if (read_touch_channels(channels) == 0) {
            for (int i = 0; i < 8; i++) {
                if (channels[i] == 1) {
                    // Debounce logic
                    unsigned long now = gpioTick();
                    if (!touch_states[i].touched || (now - touch_states[i].last_touched_time) > DEBOUNCE_TIME * 1000) {
                        log_touch_event(i + 1);
                        touch_states[i].touched = 1;
                        touch_states[i].last_touched_time = now;
                        control_led(1); // Turn on LED
                    }
                } else {
                    touch_states[i].touched = 0;
                }
            }
        } else {
            fprintf(stderr, "Error reading touch channels\n");
        }

        gpioDelay(50); // Poll every 50 ms
    }

    return 0;
}

