#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_opt3001();
int read_opt3001(float *lux);
int log_data(float lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize OPT3001 sensor
int init_opt3001() {
    // Write configuration word to configuration register
    int config_word_be = (CONFIG_WORD >> 8) | (CONFIG_WORD << 8); // Byte swap
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_word_be);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }

    // Wait for at least 100 ms for the first conversion
    gpioDelay(100000); // 100 ms

    return 0;
}

// Read OPT3001 sensor data
int read_opt3001(float *lux) {
    int raw_data = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading result register: %d\n", raw_data);
        return -1;
    }

    // Byte swap the raw data
    int result_be = (raw_data >> 8) | (raw_data << 8);

    // Extract exponent and mantissa
    int exponent = (result_be >> 12) & 0x0F;
    int mantissa = result_be & 0x0FFF;

    // Calculate lux value
