#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL_MS 50
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "Signal received, exiting gracefully...\n");
}

// Function to get the current timestamp in the format YYYY-MM-DD HH:MM:SS
char *get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(20 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the touch event to the file
int log_touch_event(const char *event_type)
{
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to get timestamp.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file);
    free(timestamp);
    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor()
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to initialize the GPIO line
int initialize_gpio()
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_logger";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int last_state = -1; // Initialize to an invalid state
    struct timespec debounce_delay = {0, DEBOUNCE_INTERVAL_MS * 1000000L}; // 50ms

    fprintf(stderr, "Touch logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int current_state = read_touch_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                if (log_touch_event("Touch Detected") < 0) {
                    fprintf(stderr, "Error logging touch detected event.\n");
                }
            } else {
                if (log_touch_event("Touch Released") < 0) {
                    fprintf(stderr, "Error logging touch released event.\n");
                }
            }
            last_state = current_state;
            nanosleep(&debounce_delay, NULL); // Debounce
        }
        usleep(1000); // Check every 1ms
    }

    // Cleanup
    cleanup_gpio();
    fclose(log_file);

    fprintf(stderr, "Touch logger stopped.\n");
    return EXIT_SUCCESS;
}

