#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define START_MEASUREMENT_CMD 0x3608
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int16_t *raw_flow, uint8_t *crc);
float convert_flow_rate(int16_t raw_flow);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
void log_data(float flow_rate, const char *status);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data;
        float flow_rate;
        char status[10];

        // Read sensor data
        if (read_sensor_data(&sensor_data.raw_flow, &sensor_data.crc) != 0) {
            strcpy(status, "ERROR");
            flow_rate = -1.0; // Indicate error
        } else {
            // Validate CRC
            if (validate_crc((uint8_t*)&sensor_data.raw_flow, 2, sensor_data.crc) != 0) {
                strcpy(status, "CRC ERROR");
                flow_rate = -1.0; // Indicate error
            } else {
                // Convert flow rate
                flow_rate = convert_flow_rate(sensor_data.raw_flow);

                // Validate flow rate
                if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
                    strcpy(status, "INVALID");
                } else {
                    strcpy(status, "OK");
                }
            }
        }

        // Log data
        log_data(flow_rate, status);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Start continuous measurement
    char cmd[2] = {(START_MEASUREMENT_CMD >> 8) & 0xFF, START_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
