#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <gpiod.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define CSV file name
#define CSV_FILE "path_log.csv"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *middle_line = NULL;
static struct gpiod_line *right_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(struct gpiod_line *line);
char *get_timestamp();
int log_data(const char *timestamp, int left, int middle, int right);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        terminate = 1;
        printf("Caught SIGINT, exiting gracefully.\n");
    }
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!left_line) {
        perror("Error getting left sensor line");
        cleanup();
        return -1;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    if (!middle_line) {
        perror("Error getting middle sensor line");
        cleanup();
        return -1;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!right_line) {
        perror("Error getting right sensor line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(left_line, "path_logger") < 0) {
        perror("Error requesting left sensor line as input");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(middle_line, "path_logger") < 0) {
        perror("Error requesting middle sensor line as input");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(right_line, "path_logger") < 0) {
        perror("Error requesting right sensor line as input");
        cleanup();
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Get current timestamp in ISO 8601 format
char *get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to CSV file
int log_data(const char *timestamp, int left, int middle, int right) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    // Open CSV file for appending
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);

        if (left_value < 0 || middle_value < 0 || right_value < 0) {
            fprintf(stderr, "Error reading sensor values. Retrying...\n");
            usleep(50000); // Wait 50ms before retrying
            continue;
        }

        // Get timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp. Retrying...\n");
            usleep(50000); // Wait 50ms before retrying
            continue;
        }

        // Log data
        if (log_data(timestamp, left_value, middle_value, right_value) < 0) {
            fprintf(stderr, "Error logging data. Retrying...\n");
        }

        free(timestamp); // Free the allocated memory

        usleep(50000); // Wait 50ms
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

