int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP_NAME, strerror(errno));
        return -1;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
