            struct timespec delay = {0, 100000000}; // 100ms
            nanosleep(&delay, NULL);
        }

        // Poll for 1 second
        struct timespec timeout = {1, 0}; // 1 second
        int ret = gpiod_line_event_wait(touch_line, &timeout);
