#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define constants
#define CHIP_NAME "gpiochip0"
#define LOG_FILE "alert_log.txt"
#define BUZZER_DURATION_MS 2000
#define POLL_INTERVAL_MS 500
#define BUZZER_STEP_MS 100

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_flame_sensor(void);
int activate_buzzer(int duration_ms);
int log_event(const char *message);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        fprintf(stderr, "Signal received, cleaning up...\n");
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read flame sensor value
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Activate buzzer for a specified duration
int activate_buzzer(int duration_ms) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value to 1: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < duration_ms; i += BUZZER_STEP_MS) {
        if (terminate) return 0; // Check for termination signal
        usleep(BUZZER_STEP_MS * 1000); // Sleep for 100 ms
    }

    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value to 0: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Log event to file
int log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup resources before exiting
void cleanup(void) {
    log_event("System stopped");

    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0); // Turn off buzzer
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Log system start
    log_event("System started");

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        fclose(log_file);
        return 1;
    }

    int last_flame_state = 1; // Initialize to HIGH (no flame)

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting\n");
            break;
        }

        if (flame_detected == 0 && last_flame_state == 1) {
            // Flame detected (LOW to HIGH transition)
            log_event("Flame detected!");
            if (activate_buzzer(BUZZER_DURATION_MS) < 0) {
                fprintf(stderr, "Buzzer activation failed, exiting\n");
                break;
            }
        }

        last_flame_state = flame_detected;
        usleep(POLL_INTERVAL_MS * 1000); // Poll every 500 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

