#include <string.h>
#include <errno.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_MS 200

static FILE *log_file = NULL;
static volatile int running = 1;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the timestamp to the file
int log_timestamp(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to toggle the LED state
void toggle_led(int pin) {
    int current_level = gpioRead(pin);
    if (current_level == 0) {
        gpioWrite(pin, 1);
    } else {
        gpioWrite(pin, 0);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int result;
    int last_level = 0;
    unsigned int last_debounce_time = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_level = gpioRead(TOUCH_PIN);

        if (current_level != last_level) {
            unsigned int now = gpioTick();
            if ((now - last_debounce_time) > (DEBOUNCE_MS * 1000)) { // Debounce
                if (current_level == 1) { // Rising edge detected
                    char *timestamp = get_iso8601_timestamp();
                    if (timestamp != NULL) {
                        if (log_timestamp(timestamp) != 0) {
                            fprintf(stderr, "Error logging timestamp.\n");
                        }
                        free(timestamp);
                        toggle_led(LED_PIN);
                    } else {
                        fprintf(stderr, "Error getting timestamp.\n");
                    }
                }
                last_debounce_time = now;
            }
            last_level = current_level;
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup before exiting
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

