    }
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    if (gpioSetMode(SENSOR_3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_3_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(SENSOR_3_GPIO, PI_PUD_UP);

    return 0;
}

