        int sensor3_value = read_sensor(SENSOR_3_GPIO);

        if (sensor1_value != -1 && sensor1_value != current_states.sensor1_state) {
            log_event(1, sensor1_value);
            current_states.sensor1_state = sensor1_value;
        }

        if (sensor2_value != -1 && sensor2_value != current_states.sensor2_state) {
            log_event(2, sensor2_value);
            current_states.sensor2_state = sensor2_value;
        }

        if (sensor3_value != -1 && sensor3_value != current_states.sensor3_state) {
            log_event(3, sensor3_value);
            current_states.sensor3_state = sensor3_value;
        }

        gpioDelay(100); // Poll every 100 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

