int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Function to verify the sensor
int verify_sensor(int handle) {
    int part_id, hw_rev;

    part_id = i2cReadByteData(handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID_REG: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    hw_rev = i2cReadByteData(handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Failed to read HW_REV_REG: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X\n", hw_rev);
        return -1;
    }

    return 0;
}

// Function to configure the sensor
int configure_sensor(int handle, sensor_config_t config) {
    if (i2cWriteByteData(handle, LED_CURRENT_REG, config.led_current) < 0) {
        fprintf(stderr, "Failed to write LED_CURRENT_REG\n");
        return -1;
    }
    if (i2cWriteByteData(handle, AVG_REG, config.averaging) < 0) {
        fprintf(stderr, "Failed to write AVG_REG\n");
        return -1;
    }
    if (i2cWriteByteData(handle, ENABLE_REG, config.enable) < 0) {
        fprintf(stderr, "Failed to write ENABLE_REG\n");
        return -1;
    }
    return 0;
}

// Function to read the heart-rate data
int read_heart_rate(int handle) {
    int raw_hr = i2cReadWordData(handle, HR_REG);
    if (raw_hr < 0) {
        fprintf(stderr, "Failed to read HR_REG: %d\n", raw_hr);
        return -1;
    }
    return raw_hr;
}

// Function to apply a moving average filter
float apply_moving_average(float new_value, float *buffer, int *index, int size) {
    static float sum = 0.0;
    sum -= buffer[*index];
    sum += new_value;
    buffer[*index] = new_value;
    *index = (*index + 1) % size;
    return sum / size;
}

// Function to validate the BPM value
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Function to log the data to a file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI1182_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    sensor_config_t config = {0x3F, 0x04, 0x01};
    if (configure_sensor(i2c_handle, config) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Moving average buffer
    float bpm_buffer[SAMPLE_SIZE] = {0.0};
    int bpm_index = 0;

    // Main loop
    while (!terminate) {
        int raw_hr = read_heart_rate(i2c_handle);
        if (raw_hr >= 0) {
            float bpm = (float)raw_hr * 0.5;
            float filtered_bpm = apply_moving_average(bpm, bpm_buffer, &bpm_index, SAMPLE_SIZE);

            if (validate_bpm(filtered_bpm)) {
                log_data(filtered_bpm);
            } else {
                fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        gpioDelay(1000); // Read every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

