#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_START_PIN 5
#define OUTPUT_START_PIN 17
#define NUM_CHANNELS 8

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY_MS 5

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line **sensor_lines;
static struct gpiod_line **output_lines;
static int counter = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int read_sensor();
void update_output(int counter);
void log_event(int channel, int counter);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO lines
int init_gpio() {
    int i;
    struct gpiod_line_request_config config;

    // Initialize sensor lines
    sensor_lines = malloc(NUM_CHANNELS * sizeof(struct gpiod_line *));
    if (!sensor_lines) {
        perror("Failed to allocate memory for sensor lines");
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "touch_counter";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    for (i = 0; i < NUM_CHANNELS; i++) {
        char pin_name[3];
        snprintf(pin_name, sizeof(pin_name), "%d", SENSOR_START_PIN + i);
        sensor_lines[i] = gpiod_chip_get_line(chip, pin_name);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Error getting line %s: %s\n", pin_name, strerror(errno));
            goto cleanup_sensor_lines;
        }

        if (gpiod_line_request(sensor_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %s: %s\n", pin_name, strerror(errno));
            goto cleanup_sensor_lines;
        }
    }

    // Initialize output lines
    output_lines = malloc(NUM_CHANNELS * sizeof(struct gpiod_line *));
    if (!output_lines) {
        perror("Failed to allocate memory for output lines");
        goto cleanup_sensor_lines;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "touch_counter";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    for (i = 0; i < NUM_CHANNELS; i++) {
        char pin_name[3];
        snprintf(pin_name, sizeof(pin_name), "%d", OUTPUT_START_PIN + i);
        output_lines[i] = gpiod_chip_get_line(chip, pin_name);
        if (!output_lines[i]) {
            fprintf(stderr, "Error getting line %s: %s\n", pin_name, strerror(errno));
            goto cleanup_output_lines;
        }

        if (gpiod_line_request(output_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %s: %s\n", pin_name, strerror(errno));
            goto cleanup_output_lines;
        }
    }

    return 0;

cleanup_output_lines:
    for (int j = 0; j < i; j++) {
        gpiod_line_release(output_lines[j]);
    }
    free(output_lines);

cleanup_sensor_lines:
    for (int j = 0; j < i; j++) {
        gpiod_line_release(sensor_lines[j]);
    }
    free(sensor_lines);
    return -1;
}

// Read sensor values
int read_sensor() {
    int i;
    int sensor_value = 0;
    int prev_sensor_value = 0;
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds

    for (i = 0; i < NUM_CHANNELS; i++) {
        int line_value = gpiod_line_get_value(sensor_lines[i]);
        if (line_value < 0) {
            fprintf(stderr, "Error reading line %d: %s\n", SENSOR_START_PIN + i, strerror(errno));
            return -1; // Indicate an error
        }

        // Debounce: Check if the value has changed within the debounce delay
        nanosleep(&delay, NULL);
        int debounced_value = gpiod_line_get_value(sensor_lines[i]);
        if (debounced_value < 0) {
            fprintf(stderr, "Error reading line %d after debounce: %s\n", SENSOR_START_PIN + i, strerror(errno));
            return -1; // Indicate an error
        }

        if (line_value == 1 && debounced_value == 1) {
            prev_sensor_value = (1 << i);
        } else {
            prev_sensor_value = 0;
        }

        sensor_value |= prev_sensor_value;
    }

    return sensor_value;
}

// Update output pins based on the counter
void update_output(int counter) {
    int i;
    for (i = 0; i < NUM_CHANNELS; i++) {
        int bit_value = (counter >> i) & 1;
        int ret = gpiod_line_set_value(output_lines[i], bit_value);
        if (ret < 0) {
            fprintf(stderr, "Error writing to line %d: %s\n", OUTPUT_START_PIN + i, strerror(errno));
        }
    }
}

// Log touch event to file
void log_event(int channel, int counter) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Warning: Could not write to log file. Log message: %s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter);
}

// Cleanup GPIO resources
void cleanup() {
    int i;

    // Release sensor lines
    if (sensor_lines) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            if (sensor_lines[i]) {
                gpiod_line_release(sensor_lines[i]);
            }
        }
        free(sensor_lines);
    }

    // Release output lines
    if (output_lines) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            if (output_lines[i]) {
                gpiod_line_release(output_lines[i]);
            }
        }
        free(output_lines);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int i;
    int sensor_value;
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 10000000; // 10 ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO lines
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    // Stabilization delay
    nanosleep(&delay, NULL);

    // Main loop
    while (!terminate) {
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            nanosleep(&delay, NULL); // Small delay before retrying
            continue;
        }

        // Update counter and output
        counter = (counter + sensor_value) & 0xFF; // Wrap around
        update_output(counter);

        // Log events
        for (i = 0; i < NUM_CHANNELS; i++) {
            if ((sensor_value >> i) & 1) {
                log_event(i + 1, counter);
            }
        }

        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

