#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18

// Define log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Debounce window in milliseconds
#define DEBOUNCE_WINDOW_MS 50

// Polling interval in milliseconds
#define POLLING_INTERVAL_MS 100

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor state and last event time
typedef struct {
    int last_value;
    struct timespec last_event_time;
} sensor_state_t;

static sensor_state_t sensor17_state = {1, {0, 0}}; // Initialize to no tilt
static sensor_state_t sensor18_state = {1, {0, 0}}; // Initialize to no tilt

// Function prototypes
int initialize_gpio();
int read_sensor(struct gpiod_line *line);
int log_event(int gpio_pin);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO17, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO18, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        return -1;
    }

    if (gpiod_line_request_input(line17, "tilt_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO17, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        return -1;
    }

    if (gpiod_line_request_input(line18, "tilt_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", GPIO18, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Log event to file
int log_event(int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, gpio_pin);
    fclose(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int value17 = read_sensor(line17);
        int value18 = read_sensor(line18);

        if (value17 < 0 || value18 < 0) {
            fprintf(stderr, "Error reading sensor values. Continuing...\n");
            usleep(POLLING_INTERVAL_MS * 1000); // Sleep for polling interval
            continue;
        }

        // Debounce and log events for sensor 17
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - sensor17_state.last_event_time.tv_sec) * 1000 +
                          (now.tv_nsec - sensor17_state.last_event_time.tv_nsec) / 1000000;

        if (value17 == 0 && sensor17_state.last_value == 1 && elapsed_ms >= DEBOUNCE_WINDOW_MS) {
            if (log_event(GPIO17) == 0) {
                sensor17_state.last_event_time = now;
            }
        }
        sensor17_state.last_value = value17;

        // Debounce and log events for sensor 18
        clock_gettime(CLOCK_MONOTONIC, &now);
        elapsed_ms = (now.tv_sec - sensor18_state.last_event_time.tv_sec) * 1000 +
                     (now.tv_nsec - sensor18_state.last_event_time.tv_nsec) / 1000000;

        if (value18 == 0 && sensor18_state.last_value == 1 && elapsed_ms >= DEBOUNCE_WINDOW_MS) {
            if (log_event(GPIO18) == 0) {
                sensor18_state.last_event_time = now;
            }
        }
        sensor18_state.last_value = value18;

        usleep(POLLING_INTERVAL_MS * 1000); // Sleep for polling interval
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

