#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Define log file name
#define LOG_FILE "obstacle_log.csv"

// Global variables
FILE *log_file = NULL;
int pigpio_initialized = 0;

// Function prototypes
int read_sensor(int gpio_pin);
int both_sensors_detect(int sensor1_value, int sensor2_value);
void control_led(int led_state);
void log_data(int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to check if both sensors detect an obstacle
int both_sensors_detect(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

// Function to control the LED
void control_led(int led_state) {
    gpioWrite(LED_PIN, led_state);
}

// Function to log data to file
void log_data(int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off the LED
    control_led(0);

    // Release GPIO resources
    if (pigpio_initialized) {
        gpioTerminate();
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Check if both sensors detect an obstacle
        int led_state = both_sensors_detect(sensor1_value, sensor2_value);

        // Control the LED
        control_led(led_state);

        // Log the data
        log_data(sensor1_value, sensor2_value, led_state);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    return 0;
}

