#include <time.h>
#include <sys/time.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Sampling period in microseconds
#define SAMPLING_PERIOD 125

// LED on duration in milliseconds
#define LED_ON_DURATION 100

// Global volatile flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read the microphone pin
int read_microphone()
{
    return gpioRead(MIC_PIN);
}

// Function to control the LED
void control_led(int on)
{
    gpioWrite(LED_PIN, on);
}

// Function to get millisecond-precision timestamp
long long get_timestamp_ms()
{
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (long long)(tv.tv_sec) * 1000 + (long long)(tv.tv_usec) / 1000;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    fprintf(stdout, "Microphone peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate)
    {
        // Read microphone
        int mic_value = read_microphone();

        // Check for peak
        if (mic_value == 1)
        {
            // Get timestamp
            long long timestamp = get_timestamp_ms();

            // Print timestamp
            fprintf(stdout, "%lld\n", timestamp);

            // Turn LED on
            control_led(1);

            // Wait for 100 ms
            gpioDelay(LED_ON_DURATION * 1000); // Convert ms to us

            // Turn LED off
            control_led(0);
        }

        // Delay for sampling period
        gpioDelay(SAMPLING_PERIOD);
    }

    // Cleanup
    gpioTerminate();
    fprintf(stdout, "Program terminated gracefully.\n");
    return 0;
}

