#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *left_line, *center_line, *right_line;

// Signal handler flag
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(-errno));
        return 1;
    }

    // Get GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !center_line || !right_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(-errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as inputs with pull-up
    struct gpiod_line_request_config config;
    config.consumer = "sensor_reader";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0; // No special flags needed for pull-up

    if (gpiod_line_request(left_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting left GPIO line: %s\n", strerror(-errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(center_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting center GPIO line: %s\n", strerror(-errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request(right_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting right GPIO line: %s\n", strerror(-errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        int left_value = read_sensor(left_line);
        int center_value = read_sensor(center_line);
        int right_value = read_sensor(right_line);

        // Log sensor values
        if (left_value >= 0 && center_value >= 0 && right_value >= 0) {
            printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);
        } else {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
        }

        // Wait 100 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines and chip
    gpiod_line_release(left_line);
    gpiod_line_release(center_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return 0;
}

