#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define NUM_CHANNELS 8

// Structure to hold GPIO chip and line information
struct gpio_context {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
};

// Global context for graceful shutdown
struct gpio_context context;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (context.lines[i] != NULL) {
            gpiod_line_release(context.lines[i]);
        }
    }

    // Close chip
    if (context.chip != NULL) {
        gpiod_chip_close(context.chip);
    }

    exit(0);
}

// Function to read the state of a single channel
int read_channel(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to format the log message
void format_log_message(int channel_states[NUM_CHANNELS], char *buffer, size_t buffer_size) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    snprintf(buffer, buffer_size, "[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
             timestamp, channel_states[0], channel_states[1], channel_states[2], channel_states[3],
             channel_states[4], channel_states[5], channel_states[6], channel_states[7]);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    context.chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!context.chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request lines as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        context.lines[i] = gpiod_chip_get_line(context.chip, i + 5); // BCM GPIO 5-12
        if (!context.lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", i + 5, strerror(errno));
            // Release previously acquired lines before exiting
            for (int j = 0; j < i; j++) {
                gpiod_line_release(context.lines[j]);
            }
            gpiod_chip_close(context.chip);
            return 1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "ttp226_reader";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(context.lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %d: %s\n", i + 5, strerror(errno));
            // Release previously acquired lines before exiting
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(context.lines[j]);
            }
            gpiod_chip_close(context.chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        int channel_states[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            channel_states[i] = read_channel(context.lines[i]);
            if (channel_states[i] < 0) {
                // Error reading channel, exit loop
                goto cleanup;
            }
        }

        char log_message[256];
        format_log_message(channel_states, log_message, sizeof(log_message));
        printf("%s", log_message);

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 200 milliseconds
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Cleanup resources before exiting
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (context.lines[i] != NULL) {
            gpiod_line_release(context.lines[i]);
        }
    }
    if (context.chip != NULL) {
        gpiod_chip_close(context.chip);
    }

    return 0;
}

