#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency
#define PWM_FREQUENCY 1000

// Number of steps for the fade
#define FADE_STEPS 50

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    return 0;
}

// Function to generate a random hue (0-359)
int generate_random_hue()
{
    return rand() % 360;
}

// Function to convert HSV to RGB
void hsv_to_rgb(int hue, int saturation, int value, int *red, int *green, int *blue)
{
    float h = (float)hue / 360.0;
    float s = (float)saturation / 100.0;
    float v = (float)value / 100.0;

    float c = v * s;
    float x = c * (1 - abs(fmod(h * 6.0, 2) - 1));
