#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define RED_THRESHOLD 200
#define POLL_INTERVAL_MS 200

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ENABLE_PON (1 << 0)
#define TCS34725_ENABLE_AEN (1 << 1)
#define TCS34725_ID 0x12
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Calibration values (example, adjust as needed)
#define RED_GAIN 1.0
#define RED_OFFSET 0.0
#define CLEAR_GAIN 1.0
#define CLEAR_OFFSET 0.0
#define GREEN_GAIN 1.0
#define GREEN_OFFSET 0.0
#define BLUE_GAIN 1.0
#define BLUE_OFFSET 0.0

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void tcs34725_calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_clear, float *calibrated_green, float *calibrated_blue);
int gpio_init(const char *chip_name, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
void cleanup(int fd, struct gpiod_line *line, struct gpiod_chip *chip);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// TCS34725 initialization function
int tcs34725_init(int fd) {
    uint8_t id;
    uint8_t enable_value = TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN;
    uint8_t atime_value = 0x00; // 154ms integration time
    uint8_t control_value = 0x00; // 1x gain

    // Check sensor ID
    if (read(fd, &id, 1) != 1) {
        perror("Failed to read sensor ID");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", id);
        return -1;
    }

    // Enable power and RGBC
    if (write(fd, &enable_value, 1) != 1) {
        perror("Failed to write enable register");
        return -1;
    }

    // Set integration time
    if (write(fd, &atime_value, 1) != 1) {
        perror("Failed to write ATIME register");
        return -1;
    }

    // Set gain
    if (write(fd, &control_value, 1) != 1) {
        perror("Failed to write CONTROL register");
        return -1;
    }

    return 0;
}

// TCS34725 data reading function
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t reg_addr = TCS34725_CDATA; // Start reading from clear data register
    uint8_t buffer[8];

    // Set the register address to read from
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to set register address for reading");
        return -1;
    }

    // Read 8 bytes (4 channels * 2 bytes each)
    if (read(fd, buffer, 8) != 8) {
        perror("Failed to read color data");
        return -1;
    }

    // Combine bytes to form 16-bit values
    *clear = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];
    *red = (uint16_t)buffer[3] << 8 | (uint16_t)buffer[2];
    *green = (uint16_t)buffer[5] << 8 | (uint16_t)buffer[4];
    *blue = (uint16_t)buffer[7] << 8 | (uint16_t)buffer[6];

    return 0;
}

// TCS34725 data calibration function
void tcs34725_calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_clear, float *calibrated_green, float *calibrated_blue) {
    *calibrated_red = (float)red * RED_GAIN + RED_OFFSET;
    *calibrated_clear = (float)clear * CLEAR_GAIN + CLEAR_OFFSET;
    *calibrated_green = (float)green * GREEN_GAIN + GREEN_OFFSET;
    *calibrated_blue = (float)blue * BLUE_GAIN + BLUE_OFFSET;
}

// GPIO initialization function
int gpio_init(const char *chip_name, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "tcs34725_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup(int fd, struct gpiod_line *line, struct gpiod_chip *chip) {
    if (fd != -1) {
        close(fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int ret;
    uint16_t clear, red, green, blue;
    float calibrated_red, calibrated_clear, calibrated_green, calibrated_blue;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup(i2c_fd, NULL, NULL);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup(i2c_fd, NULL, NULL);
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup(i2c_fd, NULL, NULL);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) < 0) {
            fprintf(stderr, "Failed to read sensor data, attempting re-initialization...\n");
            tcs34725_init(i2c_fd); // Attempt to re-initialize the sensor
            usleep(100000); // Wait before retrying
            continue;
        }

        // Calibrate sensor data
        tcs34725_calibrate_data(clear, red, green, blue, &calibrated_red, &calibrated_clear, &calibrated_green, &calibrated_blue);

        // Display calibrated values
        printf("Clear: %.2f, Red: %.2f, Green: %.2f, Blue: %.2f\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);

        // Control LED based on red value
        if (calibrated_red > RED_THRESHOLD) {
            gpio_set_value(gpio_line, 1); // Set GPIO HIGH
        } else {
            gpio_set_value(gpio_line, 0); // Set GPIO LOW
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 200ms
    }

    // Cleanup resources before exiting
    cleanup(i2c_fd, gpio_line, gpio_chip);

    return 0;
}

