// Configuration
#define I2C_ADDR 0x23
#define I2C_BUS 1
#define GPIO_PIN 18
#define NUM_LEDS 10
#define PWM_FREQUENCY 800000 // 800 kHz
#define PWM_RANGE 1000000     // 1 ms period
#define MAX_LUX 1000.0
#define MAX_BRIGHTNESS 1000.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold LED data
typedef struct {
    uint8_t red;
    uint8_t green;
    uint8_t blue;
} led_data_t;

led_data_t leds[NUM_LEDS];

// Function prototypes
int read_bh1750(float *lux);
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        // Send measurement command (High Resolution Mode)
        if (i2cWriteByte(i2c_handle, 0x10) != 0) {
            fprintf(stderr, "Error writing to I2C device (retry %d)\n", retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(180000); // Wait 180 ms

        // Read 2 bytes of data
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert data to lux
            unsigned int raw_value = (buf[0] << 8) | buf[1];
            *lux = (float)raw_value / 1.2;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device (retry %d), result: %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to map lux value to brightness (non-linear mapping)
int map_lux_to_brightness(float lux) {
    // Clamp lux value to the defined maximum
    if (lux > MAX_LUX) {
        lux = MAX_LUX;
    }

    // Apply logarithmic mapping
    float brightness = log10(lux + 1) / log10(MAX_LUX + 1) * MAX_BRIGHTNESS;

    // Clamp brightness to the defined range
    if (brightness < 0) {
        brightness = 0;
    }
    if (brightness > MAX_BRIGHTNESS) {
        brightness = MAX_BRIGHTNESS;
    }

    return (int)brightness;
}

// Function to set the LED brightness using PWM
int set_led_brightness(int brightness) {
    // Calculate duty cycle (0-1000000)
    int duty_cycle = (int)((float)brightness / MAX_BRIGHTNESS * PWM_RANGE);

    // Set PWM duty cycle
    gpioPWM(GPIO_PIN, duty_cycle);

    return 0;
}

