#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define NUM_LEDS 10
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750(float *lux);
int map_lux_to_brightness(float lux);
int set_apa102_brightness(int brightness);
int send_apa102_frame(int brightness);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", sig);
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode and speed
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t buf[2];
    int ret;

    // Send measurement command (High Resolution Mode)
    uint8_t cmd = 0x20;
    ret = write(i2c_fd, &cmd, 1);
    if (ret != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 120 ms)
    usleep(120000); // 120 ms

    // Read 2 bytes of data
    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert to lux
    uint16_t raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Map lux to brightness (0-31)
int map_lux_to_brightness(float lux) {
    int brightness;

    if (lux < 10) {
        brightness = 0;
    } else if (lux > 300) {
        brightness = 31;
    } else {
        brightness = (int)((lux - 10) / (300 - 10) * 31);
    }

    return brightness;
}

// Set APA102 brightness (not implemented in this version)
int set_apa102_brightness(int brightness) {
    // This function is intentionally left blank.
    // The brightness is controlled by the APA102 frame sent by send_apa102_frame.
    return 0;
}

// Send APA102 frame
int send_apa102_frame(int brightness) {
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t led_frame[4];
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t buffer[4 * (NUM_LEDS + 2)]; // Start + LED frames + End frame
    int i, ret;

    // Start frame
    memcpy(buffer, start_frame, 4);

    // LED frames
    for (i = 0; i < NUM_LEDS; i++) {
        led_frame[0] = 0xE0 | brightness; // Global brightness
        led_frame[1] = 0x00; // Blue
        led_frame[2] = 0x00; // Green
        led_frame[3] = 0x00; // Red
        memcpy(buffer + 4 * (i + 1), led_frame, 4);
    }

    // End frame
    memcpy(buffer + 4 * (NUM_LEDS + 1), end_frame, 4);

    // Send data
    ret = write(spi_fd, buffer, sizeof(buffer));
    if (ret != sizeof(buffer)) {
        perror("Error writing to SPI device");
        return -1;
    }

    return 0;
}

int main() {
    float lux;
    int brightness;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("BH1750 and APA102 control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Send APA102 frame
            if (send_apa102_frame(brightness) != 0) {
                fprintf(stderr, "Error sending APA102 frame.\n");
            }

            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
        }

        usleep(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

