#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Configuration
#define GPIO_PIN 18
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define LUX_TO_BRIGHTNESS_FACTOR 0.0288
#define GAMMA 2.2
#define THRESHOLD_ON 100
#define THRESHOLD_OFF 50
#define NUM_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(int pin);
int init_i2c(const char *bus, int addr);
int veml7700_init(int fd);
int veml7700_read_als(int fd);
float veml7700_convert_to_lux(int raw_value);
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void cleanup(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    cleanup(signal);
    exit(0);
}

// Initialize GPIO
int init_gpio(int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    config.consumer = "ws2812b_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    i2c_fd = open(bus, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize VEML7700
int veml7700_init(int fd) {
    uint16_t config_value = 0x0000; // Integration time 100ms, Gain 1/8
    uint8_t data[3];
    data[0] = VEML7700_CONFIG_REG;
    data[1] = (config_value >> 8) & 0xFF;
    data[2] = config_value & 0xFF;

    if (write(fd, data, 3) != 3) {
        perror("Error writing to VEML7700 config register");
        return -1;
    }

    return 0;
}

// Read ALS data from VEML7700
int veml7700_read_als(int fd) {
    uint8_t data[2];
    data[0] = VEML7700_ALS_REG;

    if (write(fd, data, 1) != 1) {
        perror("Error writing to VEML7700 ALS register");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Error reading from VEML7700 ALS register");
        return -1;
    }

    return (data[1] << 8) | data[0];
}

// Convert raw value to lux
float veml7700_convert_to_lux(int raw_value) {
    return (float)raw_value * LUX_TO_BRIGHTNESS_FACTOR;
}

// Map lux to brightness using gamma correction
int map_lux_to_brightness(float lux) {
    float brightness_float = 255.0 * powf(lux / 120000.0, 1.0 / GAMMA);
    if (brightness_float < 0.0) brightness_float = 0.0;
    if (brightness_float > 255.0) brightness_float = 255.0;
    return (int)brightness_float;
}

// Set LED brightness using bit-banging
void set_led_brightness(int brightness) {
    // This is a placeholder.  A real implementation would
    // use gpiod_line_set_value_cansleep and gpiod_line_set_value_nowait
    // to toggle the GPIO pin at a high frequency.
    // For simplicity, we'll just print the brightness value.
    printf("Brightness: %d\n", brightness);
}

// Cleanup resources
void cleanup(int signal) {
    printf("Cleaning up...\n");

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(I2C_BUS, VEML7700_ADDR) < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup(0);
        return 1;
    }

    // Initialize VEML7700
    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed. Exiting.\n");
        cleanup(0);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_value = -1;
        int retries = 0;

        // Retry reading ALS data
        while (raw_value == -1 && retries < NUM_RETRIES) {
            raw_value = veml7700_read_als(i2c_fd);
            if (raw_value == -1) {
                fprintf(stderr, "Error reading ALS data. Retrying...\n");
                retries++;
                usleep(RETRY_DELAY_MS * 1000); // Sleep for 100ms
            }
        }

        if (raw_value != -1) {
            // Convert to lux
            float lux = veml7700_convert_to_lux(raw_value);

            // Map to brightness
            int brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Print lux and brightness
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read ALS data after %d retries. Skipping.\n", NUM_RETRIES);
        }

        usleep(200000); // Sleep for 200ms
    }

    return 0;
}

