    terminate = 1;
}

// Self-test function
int self_test(void)
{
    int low_count = 0;
    struct timespec start, now;
    double elapsed;

    clock_gettime(CLOCK_MONOTONIC, &start);

    printf("Starting self-test...\n");

    // Blink LED twice
    gpiod_line_set_value(led_line, 1);
    usleep(500000); // 500ms
    gpiod_line_set_value(led_line, 0);
    usleep(500000); // 500ms

    // Read flame sensor multiple times
    for (int i = 0; i < SELF_TEST_READINGS; i++) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
            fprintf(stderr, "Error reading flame sensor during self-test.\n");
            return ERROR_GPIO_READ_FAILED;
        }
        if (value == 0) {
            low_count++;
        }
        usleep(SELF_TEST_INTERVAL_MS * 1000); // Convert ms to us
    }

    clock_gettime(CLOCK_MONOTONIC, &now);
    elapsed = (now.tv_sec - start.tv_sec) + (now.tv_nsec - start.tv_nsec) / 1000000000.0;

    printf("Self-test complete. Time elapsed: %.2f seconds\n", elapsed);

    if (low_count != SELF_TEST_READINGS) {
        fprintf(stderr, "Self-test failed: Flame sensor consistently read LOW %d times out of %d readings.\n", low_count, SELF_TEST_READINGS);
        return ERROR_SELF_TEST_FAILED;
    }

    printf("Self-test passed.\n");
    return 0;
}

int main(void)
{
    int flame_detected = 0;
    int flame_value;
    struct timespec start_time, current_time;
    double elapsed_time;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!flame_sensor_line || !buzzer_line || !led_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO lines
    if (gpiod_line_request(flame_sensor_line, "flame_sensor") != 0) {
        cleanup();
        return 1;
    }
    if (gpiod_line_request(buzzer_line, "buzzer") != 0) {
        cleanup();
        return 1;
    }
    if (gpiod_line_request(led_line, "led") != 0) {
        cleanup();
        return 1;
    }

    // Perform self-test
    if (self_test() != 0) {
        error_pattern();
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        flame_value = gpiod_line_get_value(flame_sensor_line);
        if (flame_value < 0) {
            fprintf(stderr, "Error reading flame sensor value.\n");
            cleanup();
            return 1;
        }

        if (flame_value == 0) { // Flame detected (LOW signal)
            if (!flame_detected) {
                log_event("Flame detected");
                flame_detected = 1;
                gpiod_line_set_value(buzzer_line, 1);
                gpiod_line_set_value(led_line, 1);
                clock_gettime(CLOCK_MONOTONIC, &start_time);
            }
        } else { // No flame (HIGH signal)
            if (flame_detected) {
                log_event("Flame gone");
                flame_detected = 0;
                gpiod_line_set_value(buzzer_line, 0);
                gpiod_line_set_value(led_line, 0);
            }
        }

        if (flame_detected) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

            if (elapsed_time >= SELF_TEST_TIMEOUT_S) {
                log_event("Timeout waiting for flame to return to HIGH");
                flame_detected = 0;
                gpiod_line_set_value(buzzer_line, 0);
                gpiod_line_set_value(led_line, 0);
            }
        }

        usleep(50000); // 50ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

