#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio17/value"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIRECTION_PATH "/sys/class/gpio/gpio17/direction"
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_bh1750(uint16_t *raw_value);
float convert_to_lux(uint16_t raw_value);
void update_circular_buffer(float lux_value);
float calculate_average_lux();
void control_led(float average_lux);
void cleanup();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Send continuous high-resolution mode command
    uint8_t mode = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &mode, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    // Export GPIO
    int export_fd = open(GPIO_EXPORT_PATH, O_WRONLY);
    if (export_fd < 0) {
        perror("Error opening GPIO export file");
        return -1;
    }
    if (write(export_fd, "17", 2) != 2) {
        perror("Error writing to GPIO export file");
        close(export_fd);
        return -1;
    }
    close(export_fd);

    // Set direction to output
    int direction_fd = open(GPIO_DIRECTION_PATH, O_WRONLY);
    if (direction_fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }
    if (write(direction_fd, "out", 3) != 3) {
        perror("Error writing to GPIO direction file");
        close(direction_fd);
        return -1;
    }
    close(direction_fd);

    // Open GPIO value file for writing
    gpio_fd = open(GPIO_PATH, O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    return 0;
}

// Function to read raw data from BH1750
