#define BLINK_INTERVAL_MS 500

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *data_line, *clock_line, *latch_line;
int running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    running = 0;
}

// Function to set the state of a GPIO line
int set_gpio_line(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Function to shift out a byte to the 74HC595
int shift_out(unsigned char data)
{
    for (int i = 0; i < 8; i++) {
        // Set data pin
        if (set_gpio_line(data_line, (data >> (7 - i)) & 1) < 0) return -1;

        // Clock high
        if (set_gpio_line(clock_line, 1) < 0) return -1;
        usleep(1); // Small delay

        // Clock low
        if (set_gpio_line(clock_line, 0) < 0) return -1;
        usleep(1); // Small delay
    }
    return 0;
}

// Function to display a digit on the 74HC595
int display_digit(int digit)
{
    // Define segment patterns for common cathode display
    unsigned char segment_patterns[10] = {
        0b00111111, // 0
        0b00000110, // 1
        0b01011011, // 2
        0b01001111, // 3
        0b01100110, // 4
        0b01101101, // 5
        0b01111101, // 6
        0b00000111, // 7
        0b01111111, // 8
        0b01101111  // 9
    };

    // Get the segment pattern for the digit
    unsigned char pattern = segment_patterns[digit];

    // Shift out the pattern
    if (shift_out(pattern) < 0) return -1;

    // Latch the data
    if (set_gpio_line(latch_line, 1) < 0) return -1;
    usleep(1); // Small delay
    if (set_gpio_line(latch_line, 0) < 0) return -1;
    usleep(1); // Small delay

    return 0;
}

