    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(data_line, "segment_display", 0) < 0) {
        perror("Error requesting data line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(clock_line, "segment_display", 0) < 0) {
        perror("Error requesting clock line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(latch_line, "segment_display", 0) < 0) {
        perror("Error requesting latch line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Display the digit
        if (display_digit(DISPLAY_DIGIT) < 0) {
            fprintf(stderr, "Error displaying digit, exiting.\n");
            break;
        }

        // Blink the display
        if (set_gpio_line(latch_line, 1) < 0) return -1;
        usleep(BLINK_INTERVAL_MS * 1000); // On
        if (set_gpio_line(latch_line, 0) < 0) return -1;
