#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int ret;
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request LED line as output with initial value 0 (low)
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    config.consumer = "blink_button";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    ret = gpiod_line_request(led_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting LED line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with pull-up resistor
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    config.consumer = "blink_button";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    ret = gpiod_line_request(button_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting button line");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Blink LED in a loop until button is pressed
    while (1) {
        // Set LED to HIGH
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Error setting LED value");
            break;
        }
        sleep(1);

        // Set LED to LOW
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Error setting LED value");
            break;
        }
        sleep(1);

        // Wait for button press with timeout
        ret = gpiod_line_event_wait(button_line, NULL, 1000000); // Timeout of 1 second (1000000 microseconds)
        if (ret < 0) {
            perror("Error waiting for button event");
            break;
        } else if (ret > 0) {
            // Button pressed, stop blinking and turn off LED
            printf("Button pressed! Stopping blinking and turning off LED.\n");
            gpiod_line_set_value(led_line, 0);
            break;
        }
    }

    // Release GPIO lines and close GPIO chip before exiting
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

