#include <pigpio.h>

#define LED_GPIO 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int result;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO5 as an output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("Blinking LED on GPIO%d. Press Ctrl+C to exit.\n", LED_GPIO);

    while (program_running) {
        // Turn LED on
        gpioWrite(LED_GPIO, 1);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(750000); // 750 ms

        // Turn LED off
        gpioWrite(LED_GPIO, 0);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(750000); // 750 ms
    }

    // Cleanly turn off the LED
    gpioWrite(LED_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

