#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <stdbool.h>

#define GPIO_CHIP "gpiochip0"
#define LED_GPIO 24
#define BUTTON_GPIO 22
#define BLINK_ON_MS 500
#define BLINK_OFF_MS 500

// Global variables for signal handling
static volatile bool running = true;
static int gpio_fd = -1;

// Function prototypes
int gpio_export(int gpio);
int gpio_unexport(int gpio);
int gpio_set_direction(int gpio, const char *direction);
int gpio_read(int gpio);
int gpio_write(int gpio, int value);
void blink_led(int gpio, int on_ms, int off_ms);
void signal_handler(int sig);

// Helper function to handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s (errno: %d)\n", message, errno);
}

// Export GPIO pin
int gpio_export(int gpio) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        handle_error("Failed to open /sys/class/gpio/export");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (bytes_written < 0 || bytes_written >= sizeof(buffer)) {
        handle_error("Failed to format GPIO number");
        close(fd);
        return -1;
    }

    if (write(fd, buffer, bytes_written) < 0) {
        handle_error("Failed to write to /sys/class/gpio/export");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Unexport GPIO pin
int gpio_unexport(int gpio) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        handle_error("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (bytes_written < 0 || bytes_written >= sizeof(buffer)) {
        handle_error("Failed to format GPIO number");
        close(fd);
        return -1;
    }

    if (write(fd, buffer, bytes_written) < 0) {
        handle_error("Failed to write to /sys/class/gpio/unexport");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Set GPIO direction (in or out)
int gpio_set_direction(int gpio, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        handle_error("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        handle_error("Failed to write to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Read GPIO value
int gpio_read(int gpio) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd == -1) {
        handle_error("Failed to open GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        handle_error("Failed to read GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Write GPIO value
int gpio_write(int gpio, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        handle_error("Failed to open GPIO value file");
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) < 0) {
        handle_error("Failed to write to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Blink the LED
void blink_led(int gpio, int on_ms, int off_ms) {
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = on_ms * 1000000;
    off_time.tv_sec = 0;
    off_time.tv_nsec = off_ms * 1000000;

    if (gpio_write(gpio, 1) == -1) {
        fprintf(stderr, "Failed to turn LED on\n");
        return;
    }
    nanosleep(&on_time, NULL);

    if (gpio_write(gpio, 0) == -1) {
        fprintf(stderr, "Failed to turn LED off\n");
        return;
    }
    nanosleep(&off_time, NULL);
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    running = false;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    int button_state = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(LED_GPIO) == -1) {
        fprintf(stderr, "Failed to export LED GPIO %d\n", LED_GPIO);
        return 1;
    }
    if (gpio_export(BUTTON_GPIO) == -1) {
        fprintf(stderr, "Failed to export button GPIO %d\n", BUTTON_GPIO);
        gpio_unexport(LED_GPIO);
        return 1;
    }

    // Set GPIO directions
    if (gpio_set_direction(LED_GPIO, "out") == -1) {
        fprintf(stderr, "Failed to set LED GPIO direction\n");
        gpio_unexport(LED_GPIO);
        gpio_unexport(BUTTON_GPIO);
        return 1;
    }
    if (gpio_set_direction(BUTTON_GPIO, "in") == -1) {
        fprintf(stderr, "Failed to set button GPIO direction\n");
        gpio_unexport(LED_GPIO);
        gpio_unexport(BUTTON_GPIO);
        return 1;
    }

    // Main loop
    while (running) {
        int new_button_state = gpio_read(BUTTON_GPIO);
        if (new_button_state == -1) {
            fprintf(stderr, "Failed to read button state\n");
            break;
        }

        if (new_button_state != button_state) {
            button_state = new_button_state;

            if (button_state == 0) { // Button pressed
                while (button_state == 0 && running) {
                    blink_led(LED_GPIO, BLINK_ON_MS, BLINK_OFF_MS);
                    new_button_state = gpio_read(BUTTON_GPIO);
                    if (new_button_state == -1) {
                        fprintf(stderr, "Failed to read button state in blink loop\n");
                        break;
                    }
                    button_state = new_button_state;
                }
                if (gpio_write(LED_GPIO, 0) == -1) {
                    fprintf(stderr, "Failed to turn LED off after button release\n");
                }
            } else { // Button released
                if (gpio_write(LED_GPIO, 0) == -1) {
                    fprintf(stderr, "Failed to turn LED off after button release\n");
                }
            }
        }
        usleep(10000); // Check every 10ms
    }

    // Cleanup
    gpio_unexport(LED_GPIO);
    gpio_unexport(BUTTON_GPIO);

    return 0;
}

