#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define PWM period (10 ms)
#define PWM_PERIOD_NS 10000000

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle)
{
    struct timespec on_time, off_time;
    long on_ns, off_ns;

    // Calculate on and off times based on duty cycle
    on_ns = (long)((float)duty_cycle / 100.0 * PWM_PERIOD_NS);
    off_ns = PWM_PERIOD_NS - on_ns;

    on_time.tv_sec = 0;
    on_time.tv_nsec = on_ns;
    off_time.tv_sec = 0;
    off_time.tv_nsec = off_ns;

    // Set GPIO high
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO high");
        exit(1);
    }
    if (nanosleep(&on_time, NULL) < 0) {
        perror("nanosleep");
        exit(1);
    }

    // Set GPIO low
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO low");
        exit(1);
    }
    if (nanosleep(&off_time, NULL) < 0) {
        perror("nanosleep");
        exit(1);
    }
}

int main()
{
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("Error requesting red GPIO as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("Error requesting green GPIO as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("Error requesting blue GPIO as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Generate random RGB values
        int red_value = rand() % 101;
        int green_value = rand() % 101;
        int blue_value = rand() % 101;

        // Set PWM duty cycles
        set_pwm_duty_cycle(red_line, red_value);
        set_pwm_duty_cycle(green_line, green_value);
        set_pwm_duty_cycle(blue_line, blue_value);

        // Wait 100 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
