#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_LSB_REG 0x66
#define RED_MSB_REG 0x67
#define GREEN_LSB_REG 0x68
#define GREEN_MSB_REG 0x69
#define BLUE_LSB_REG 0x6A
#define BLUE_MSB_REG 0x6B
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als(uint16_t *als);
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
int set_led_brightness(uint16_t als);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize the ADPD188BI sensor
int initialize_sensor() {
    int result;
    result = i2cWriteByteData(i2c_handle, MODE_REG, 0x01); // Normal mode
    if (result != 0) {
        fprintf(stderr, "Error writing to MODE register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ALS data from the sensor
int read_als(uint16_t *als) {
    int result;
    uint8_t lsb, msb;

    result = i2cReadByteData(i2c_handle, ALS_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS LSB: %d\n", result);
        return -1;
    }
    lsb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, ALS_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS MSB: %d\n", result);
        return -1;
    }
    msb = (uint8_t)result;

    *als = ((uint16_t)msb << 8) | lsb;
    return 0;
}

// Read RGB data from the sensor
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int result;
    uint8_t red_lsb, red_msb, green_lsb, green_msb, blue_lsb, blue_msb;

    result = i2cReadByteData(i2c_handle, RED_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading RED LSB: %d\n", result);
        return -1;
    }
    red_lsb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, RED_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading RED MSB: %d\n", result);
        return -1;
    }
    red_msb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, GREEN_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading GREEN LSB: %d\n", result);
        return -1;
    }
    green_lsb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, GREEN_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading GREEN MSB: %d\n", result);
        return -1;
    }
    green_msb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, BLUE_LSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading BLUE LSB: %d\n", result);
        return -1;
    }
    blue_lsb = (uint8_t)result;

    result = i2cReadByteData(i2c_handle, BLUE_MSB_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading BLUE MSB: %d\n", result);
        return -1;
    }
    blue_msb = (uint8_t)result;

    *red = ((uint16_t)red_msb << 8) | red_lsb;
    *green = ((uint16_t)green_msb << 8) | green_lsb;
    *blue = ((uint16_t)blue_msb << 8) | blue_lsb;

    return 0;
}

// Log data to CSV file
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Set LED brightness using PWM
int set_led_brightness(uint16_t als) {
    int duty_cycle = (int)(((float)als / 65535.0) * 255.0);
    if (duty_cycle > 255) {
        duty_cycle = 255;
    }
    gpioPWM(LED_GPIO, duty_cycle);
    return 0;
}

int main() {
    uint16_t als, red, green, blue;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,R,G,B\n");
    }
    fflush(log_file);

    // Set GPIO18 as output for PWM
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LED_GPIO, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_als(&als);
        if (result != 0) {
            fprintf(stderr, "Error reading ALS data, retrying...\n");
            gpioDelay(100); // Wait 100 ms before retrying
            continue;
        }

        result = read_rgb(&red, &green, &blue);
        if (result != 0) {
            fprintf(stderr, "Error reading RGB data, retrying...\n");
            gpioDelay(100); // Wait 100 ms before retrying
            continue;
        }

        // Log data
