#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define FXOS8700CQ_ADDR 0x1F
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0xC7
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define STANDBY_MODE 0x00
#define ACTIVE_MODE 0x01
#define ODR_200HZ 0x01
#define SENSITIVITY 4096.0f
#define G_TO_MS2 9.81f
#define IMPACT_THRESHOLD 19.62f
#define SAMPLE_INTERVAL_MS 50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the FXOS8700CQ sensor
int initialize_sensor() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Place sensor in standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, STANDBY_MODE) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby mode): %d\n", i2c_handle);
        return -1;
    }

    // Configure XYZ_DATA_CFG for ±2g mode
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG (2g mode): %d\n", i2c_handle);
        return -1;
    }

    // Activate sensor with active mode and 200 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, ACTIVE_MODE | ODR_200HZ) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active mode): %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Reads acceleration data from the sensor
int read_sensor_data(float *x, float *y, float *z) {
    char buffer[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    // Combine MSB and LSB, shift right by 2, and convert to g
    int16_t raw_x = (int16_t)((buffer[0] << 6) | (buffer[1] >> 2));
    int16_t raw_y = (int16_t)((buffer[2] << 6) | (buffer[3] >> 2));
    int16_t raw_z = (int16_t)((buffer[4] << 6) | (buffer[5] >> 2));

    *x = (float)raw_x / SENSITIVITY * G_TO_MS2;
    *y = (float)raw_y / SENSITIVITY * G_TO_MS2;
    *z = (float)raw_z / SENSITIVITY * G_TO_MS2;

    return 0;
}

// Calculates the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Logs impact data to a file
int log_impact(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                if (log_impact(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "Error logging impact\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

