#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDRESS 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0xD3
#define SENSITIVITY 0.00875
#define CALIBRATION_SAMPLES 100
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_PERIOD_MS 50
#define SAMPLE_RATE_HZ 20

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Structure to hold gyroscope offsets
typedef struct {
    float x;
    float y;
    float z;
} gyro_offsets_t;

// Function prototypes
int i2c_open(const char *bus, int address);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int gyro_init(int fd);
gyro_data_t read_gyro_data(int fd);
gyro_offsets_t calibrate_gyro(int fd);
float convert_to_dps(int16_t raw_value, gyro_offsets_t offsets);
void log_data(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int sig);
void cleanup();

// I2C functions
int i2c_open(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C");
        return -1;
    }

    return 0;
}

int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C");
        return -1;
    }

    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for block read");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading block from I2C");
        return -1;
    }

    return 0;
}

// Gyroscope functions
int gyro_init(int fd) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled, 100 Hz ODR)
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4 (250 dps full-scale, continuous update)
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t raw_data[6];

    if (i2c_read_block(fd, OUT_X_L, raw_data, 6) < 0) {
