#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define DEVID_REG 0x00
#define DATAX0_REG 0x32
#define LED_GPIO 17
#define ACCEL_SCALE 0.0039 // 3.9 mg/LSB for +/- 2g range
#define ACCEL_THRESHOLD 2.0 // Acceleration threshold in g

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int verify_device_id();
int read_acceleration(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void control_led(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data
typedef struct {
    float x;
    float y;
    float z;
} AccelerationData;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify the ADXL345 device ID
int verify_device_id() {
    int devid = i2cReadByteData(i2c_handle, DEVID_REG);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID: 0x%02X\n", devid);
        return -1;
    }
    return 0;
}

// Function to read acceleration data
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DATAX0_REG, raw_data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", bytes_read);
        return -1;
    }

    // Combine high and low bytes, convert to g units
    int16_t x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    *x = (float)x_raw * ACCEL_SCALE;
    *y = (float)y_raw * ACCEL_SCALE;
    *z = (float)z_raw * ACCEL_SCALE;

    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the LED based on acceleration
void control_led(float x, float y, float z) {
    if (fabs(x) > ACCEL_THRESHOLD || fabs(y) > ACCEL_THRESHOLD || fabs(z) > ACCEL_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    AccelerationData accel_data;
    while (!terminate) {
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            log_data(accel_data.x, accel_data.y, accel_data.z);
            control_led(accel_data.x, accel_data.y, accel_data.z);
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }
        gpioDelay(100000); // 100 ms delay (10 Hz)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

