#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// Sensor addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// Accelerometer registers
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// Magnetometer registers
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Scaling factors
#define ACCEL_SCALE 0.000061 // +/- 2g, 16-bit
#define MAG_SCALE 0.00014 // +/- 1.3 gauss, 16-bit

// Global variables
int i2c_handle_accel;
int i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_accelerometer();
int init_magnetometer();
int read_accelerometer(float *x, float *y, float *z);
int read_magnetometer(float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float mag_x, float mag_y);
int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize accelerometer
int init_accelerometer() {
    int status = i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27); // 50 Hz, all axes enabled
    if (status != 0) {
        fprintf(stderr, "Error initializing accelerometer: %d\n", status);
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    int status = i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00); // Continuous conversion mode
    if (status != 0) {
        fprintf(stderr, "Error initializing magnetometer: %d\n", status);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6); // Auto-increment
    if (status != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;

    return 0;
}

// Read magnetometer data
int read_magnetometer(float *x, float *y, float *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", status);
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | buffer[5]);

    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float mag_x, float mag_y) {
    float heading = atan2(mag_y, mag_x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to file
int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_accelerometer() != 0) {
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    if (init_magnetometer() != 0) {
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accelerometer(&accel_x, &accel_y, &accel_z) == 0 &&
            read_magnetometer(&mag_x, &mag_y, &mag_z) == 0) {

            // Calculate heading
            heading = calculate_heading(accel_x, accel_y, mag_x, mag_y);

            // Log data
            log_data(heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

