#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses and control register value
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define CONTROL_REG 0x00
#define DATA_REG 0x01

// Define sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 10

// Define I2C bus
#define I2C_BUS 1

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize a sensor
int init_sensor(int i2c_handle) {
    // Write the control register to enable continuous measurement
    if (i2cWriteByteData(i2c_handle, CONTROL_REG, 0x80) != 0) {
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }
    return 0;
}

// Function to read audio data from a sensor
int16_t read_sensor_data(int i2c_handle) {
    int16_t data;
    // Read 2 bytes from the data register
    data = i2cReadWordData(i2c_handle, DATA_REG);
    if (data < 0) {
        fprintf(stderr, "Error reading data from sensor\n");
        return 0; // Return 0 on error
    }
    return data;
}

// Function to calculate TDOA
double calculate_tdoa(int16_t sample1, int16_t sample2) {
    return (double)(sample1 - sample2);
}

// Function to log data to a file
void log_data(FILE *fp, struct timespec ts, int16_t sensor1, int16_t sensor2, double tdoa) {
    fprintf(fp, "%ld,%ld,%d,%d,%.2f\n", ts.tv_sec, ts.tv_nsec, sensor1, sensor2, tdoa);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2\n");
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Initialize both sensors
    if (init_sensor(i2c_handle1) != 0 || init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        struct timespec ts;
        int16_t sensor1_data, sensor2_data;
        double tdoa;

        // Read data from both sensors
        sensor1_data = read_sensor_data(i2c_handle1);
        sensor2_data = read_sensor_data(i2c_handle2);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp\n");
            continue; // Skip to the next iteration
        }

        // Calculate TDOA
        tdoa = calculate_tdoa(sensor1_data, sensor2_data);

        // Log data
        log_data(log_file, ts, sensor1_data, sensor2_data, tdoa);

        // Sleep for the sampling interval
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // The following lines will never be reached due to the infinite loop
    // However, they are included for completeness and to avoid compiler warnings
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

