#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0b11000000000 // CPOL=1, CPHA=1, aux SPI off

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Function Prototypes
int spi_read_register(int handle, unsigned char reg_addr, int *data);
int spi_write_register(int handle, unsigned char reg_addr, int data);
void cleanup(int signum);

// Signal Handler
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, exiting...\n");
}

// SPI Read Register Function
int spi_read_register(int handle, unsigned char reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer
    tx_buf[0] = (reg_addr << 1) | 0x00; // MSB=0 for read
    tx_buf[1] = 0x00; // Dummy byte

    // Perform the SPI transfer
    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result < 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return result;
    }

    // Combine the received bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, unsigned char reg_addr, int data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer
    tx_buf[0] = (reg_addr << 1) | 0x01; // MSB=1 for write
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data

    // Perform the SPI transfer
    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result < 0) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return result;
