#include <time.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_INTERVAL_MS 100

// ADIS16448 Registers
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Scale Factors
#define GYRO_SCALE 0.02
#define ACCEL_SCALE 0.00025

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(const char *device, int mode, int speed);
int spi_transfer(int fd, uint8_t reg, uint16_t *data);
int gpio_init(const char *chip, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device, int mode, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t reg, uint16_t *data) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    // Construct the transmit buffer
    tx_buf[0] = reg | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;       // Dummy byte
    tx_buf[2] = 0x00;       // Dummy byte

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = ((uint16_t)rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// GPIO Initialization
int gpio_init(const char *chip, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "adis16448_cs", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
        struct timespec ts;

        // Read gyroscope data
        if (spi_transfer(spi_fd, XGYRO_OUT, &gyro_x) < 0 ||
            spi_transfer(spi_fd, YGYRO_OUT, &gyro_y) < 0 ||
            spi_transfer(spi_fd, ZGYRO_OUT, &gyro_z) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            cleanup();
            return 1;
        }

        // Read accelerometer data
        if (spi_transfer(spi_fd, XACCL_OUT, &accel_x) < 0 ||
            spi_transfer(spi_fd, YACCL_OUT, &accel_y) < 0 ||
            spi_transfer(spi_fd, ZACCL_OUT, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            cleanup();
            return 1;
        }

        // Convert to physical units
        float gyro_x_dps = gyro_x * GYRO_SCALE;
        float gyro_y_dps = gyro_y * GYRO_SCALE;
        float gyro_z_dps = gyro_z * GYRO_SCALE;
        float accel_x_g = accel_x * ACCEL_SCALE;
        float accel_y_g = accel_y * ACCEL_SCALE;
        float accel_z_g = accel_z * ACCEL_SCALE;

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            cleanup();
            return 1;
        }

        // Log data
        printf("%ld.%09ld, Gyro X: %.3f dps, Gyro Y: %.3f dps, Gyro Z: %.3f dps, Accel X: %.6f g, Accel Y: %.6f g, Accel Z: %.6f g\n",
               ts.tv_sec, ts.tv_nsec, gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);

        // Delay
        struct timespec delay = {0, SAMPLE_INTERVAL_MS * 1000000L}; // 100 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

