#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a single byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            perror("I2C read failed");
            retries--;
            usleep(1000); // Wait 1ms before retrying
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0;
        } else {
            perror("I2C write failed");
            retries--;
            usleep(1000); // Wait 1ms before retrying
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to initialize the MPU-6886
int init_mpu6886(int fd) {
    // Check WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i != 0x86) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x86\n", who_am_i);
        return -1;
    }

    // Wake up the sensor
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6886\n");
        return -1;
    }

    // Configure accelerometer range to +-2g
    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range to +-250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_i2c_block_data(fd, ACCEL_XOUT_H, 14, buffer);
        if (result == 14) {
            *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
            *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
            *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
            *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
            *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
            *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);
            return 0;
        } else {
            perror("I2C block read failed");
            retries--;
            usleep(1000); // Wait 1ms before retrying
        }
    }
    fprintf(stderr, "I2C block read failed after multiple retries.\n");
    return -1; // Indicate failure
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6886
    if (init_mpu6886(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU-6886 initialized successfully.\n");

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(50000); // 50ms delay
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program terminated.\n");
    return 0;
}

