#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define ACCEL_THRESHOLD 2.0f // 2g
#define ACCEL_SCALE 0.000244f // 2g/4096 counts
#define IMPACT_LOG_FILE "impact_log.txt"

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_acceleration(int fd, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int detect_impact(float magnitude);
int log_impact(void);
void cleanup(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        perror("I2C read error");
        return -1;
    }
    return result;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

// Read acceleration data
int read_acceleration(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    int x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    x_msb = i2c_read_reg(fd, OUT_X_MSB);
    x_lsb = i2c_read_reg(fd, OUT_X_MSB + 1);
    y_msb = i2c_read_reg(fd, OUT_X_MSB + 2);
    y_lsb = i2c_read_reg(fd, OUT_X_MSB + 3);
    z_msb = i2c_read_reg(fd, OUT_X_MSB + 4);
    z_lsb = i2c_read_reg(fd, OUT_X_MSB + 5);

    if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0 || z_msb < 0 || z_lsb < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((x_msb << 8) | x_lsb) >> 4;
    raw_y = (int16_t)((y_msb << 8) | y_lsb) >> 4;
    raw_z = (int16_t)((z_msb << 8) | z_lsb) >> 4;

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;

    return 0;
}

// Calculate magnitude of acceleration
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Detect impact
int detect_impact(float magnitude) {
    return (magnitude > ACCEL_THRESHOLD);
}

// Log impact
int log_impact(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Impact detected\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
}

// Cleanup function
void cleanup(int signal) {
    printf("Cleaning up...\n");

    // Close I2C bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Release GPIO line
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }

    // Close GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    float x, y, z, magnitude;
    int impact_detected;

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C bus
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor ID
    int who_am_i = i2c_read_reg(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        close(i2c_fd);
        return 1;
    }

    // Configure accelerometer (active mode, 800 Hz ODR)
    if (i2c_write_reg(i2c_fd, CTRL_REG1, 0x01) < 0) {
        close(i2c_fd);
