    printf("Cleaning up...\n");

    // Close I2C bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Release GPIO line
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }

    // Close GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

