#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define TMAG5273_ADDR 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define LOG_FILE "magnetic_field_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *device);
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize I2C interface
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", TMAG5273_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data from TMAG5273
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int ret;

    // Read X, Y, and Z registers (6 bytes)
    ret = read(fd, buffer, 6);
    if (ret != 6) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Convert bytes to 16-bit little-endian values
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Log data to CSV file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    int16_t x, y, z;
    struct timespec sleep_time;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_PERIOD_US * 1000; // Convert microseconds to nanoseconds

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &x, &y, &z) == 0) {
            // Log data
            if (log_data(log_file, x, y, z) != 0) {
                fprintf(stderr, "Error logging data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, but continuing...\n");
        }

        // Sleep for the specified sample period
        if (nanosleep(&sleep_time, NULL) != 0) {
            if (errno == EINTR) {
                fprintf(stderr, "Sleep interrupted by signal\n");
            } else {
                fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
            }
        }
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

