#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define FREEFALL_THRESHOLD 300 // milli-g
#define FREEFALL_DURATION 100  // milliseconds
#define LOG_FILE "freefall_log.csv"

// ADXL345 Registers
#define POWER_CTL 0x2D
#define INT_ENABLE 0x2E
#define INT_MAP 0x2F
#define THRESH_FF 0x0A
#define TIME_FF 0x20
#define DATAX0 0x32
#define INT_SOURCE 0x30

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_gpio(const char *chip, int pin);
int write_register(int fd, uint8_t reg, uint8_t value);
int read_register(int fd, uint8_t reg, uint8_t *value);
int read_block(int fd, uint8_t reg, uint8_t *data, int len);
int init_adxl345(int fd);
int detect_freefall(int fd, int gpio_fd);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize GPIO
int init_gpio(const char *chip, int pin) {
    struct gpiod_chip *chip_ = gpiod_chip_open_by_name(chip);
    if (!chip_) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_ = gpiod_chip_get_line(chip_, pin);
    if (!line_) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_);
        return -1;
    }

    if (gpiod_line_request_falling_edge_events(line_, "freefall_detector") < 0) {
        perror("Error requesting GPIO line for falling edge events");
        gpiod_chip_close(chip_);
        gpiod_line_release(line_);
        return -1;
    }

    return gpiod_line_get_fd(line_);
}

// Function to write a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Function to read a register
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Function to read a block of registers
int read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for block read");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading block from I2C device");
        return -1;
    }

    return 0;
}

// Function to initialize the ADXL345
int init_adxl345(int fd) {
    uint8_t devid;

    // Verify device ID
    if (read_register(fd, 0x00, &devid) < 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }

    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Put the ADXL345 into standby mode
    if (write_register(fd, POWER_CTL, 0x00) < 0) {
