        return -1;
    }

    // Set freefall threshold
    if (write_register(fd, THRESH_FF, FREEFALL_THRESHOLD) < 0) {
        fprintf(stderr, "Error setting freefall threshold\n");
        return -1;
    }

    // Set freefall time
    if (write_register(fd, TIME_FF, FREEFALL_DURATION) < 0) {
        fprintf(stderr, "Error setting freefall time\n");
        return -1;
    }

