    if (write_register(fd, INT_MAP, 0x00) < 0) {
        fprintf(stderr, "Error mapping freefall interrupt to INT1\n");
        return -1;
    }

    // Start measurement in measurement mode
    if (write_register(fd, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error starting measurement mode\n");
        return -1;
    }

    return 0;
}

// Function to detect freefall
int detect_freefall(int fd, int gpio_fd) {
    uint8_t int_source;
    uint8_t data[6];
    struct timespec ts;
    struct tm tm;
    char timestamp[30];
    accelerometer_data_t acc_data;

    // Read INT_SOURCE register
    if (read_register(fd, INT_SOURCE, &int_source) < 0) {
        fprintf(stderr, "Error reading INT_SOURCE register\n");
        return -1;
    }

    // Check if freefall interrupt is active
    if (int_source & 0x40) {
