        if (read_block(fd, DATAX0, data, 6) < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            return -1;
        }

        // Convert data to signed 16-bit integers
        acc_data.x = (int16_t)((data[1] << 8) | data[0]);
        acc_data.y = (int16_t)((data[3] << 8) | data[2]);
        acc_data.z = (int16_t)((data[5] << 8) | data[4]);

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        localtime_r(&ts.tv_sec, &tm);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

        // Log data to file
        if (log_data(log_file, acc_data.x, acc_data.y, acc_data.z) < 0) {
