    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    // Flush the buffer to ensure data is written to disk
    fflush(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup() {
    // Disable interrupts
    if (i2c_fd != -1) {
        write_register(i2c_fd, POWER_CTL, 0x00); // Standby mode
        close(i2c_fd);
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
