    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, ADXL345_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    int gpio_fd = gpiod_line_get_fd(gpio_line);
    if (gpio_fd < 0) {
        perror("Error getting GPIO file descriptor");
        cleanup();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Main loop
    struct timespec ts;
    fd_set rfds;
    int ret;

    while (!terminate) {
        FD_ZERO(&rfds);
        FD_SET(gpio_fd, &rfds);

        ts.tv_sec = 0;
        ts.tv_nsec = 100 * 1000 * 1000; // 100ms

        ret = select(gpio_fd + 1, &rfds, NULL, NULL, &ts);

        if (ret == -1) {
            perror("select()");
            break;
        } else if (ret) {
            // Interrupt occurred, detect freefall
            if (detect_freefall(i2c_fd, gpio_fd) < 0) {
                fprintf(stderr, "Freefall detection failed\n");
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

