#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28
#define WHO_AM_I 0x0F

// Sensor ranges
#define ACCEL_RANGE 2.0f  // +-2g
#define GYRO_RANGE 250.0f // +-250 dps

// ODR
#define ODR 104.0f // Hz

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f // 0.2g
#define IMPACT_THRESHOLD 2.5f   // 2.5g

// Fall detection window
#define FALL_WINDOW 1.0f // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Enum for fall detection state
enum {
    IDLE,
    FREEFALL,
    IMPACT
} fall_state = IDLE;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
sensor_data_t process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 104 Hz, +-2g
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 104 Hz, +-250 dps
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read raw accelerometer and gyroscope data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[12];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

// Process raw data and convert to g and dps
sensor_data_t process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    sensor_data_t data;

    // Accelerometer: 16-bit signed integer, 16g range, 2g resolution
    data.accel_x = (float)accel_x / 16384.0f * ACCEL_RANGE;
    data.accel_y = (float)accel_y / 16384.0f * ACCEL_RANGE;
    data.accel_z = (float)accel_z / 16384.0f * ACCEL_RANGE;

    // Gyroscope: 16-bit signed integer, 250 dps range, 8250 dps resolution
    data.gyro_x = (float)gyro_x / 32768.0f * GYRO_RANGE;
    data.gyro_y = (float)gyro_y / 32768.0f * GYRO_RANGE;
    data.gyro_z = (float)gyro_z / 32768.0f * GYRO_RANGE;

    return data;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file);
}

// Fall detection state machine
void fall_detection(sensor_data_t data) {
    static time_t start_time = 0;
    time_t current_time = time(NULL);
    float accel_magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    switch (fall_state) {
        case IDLE:
            if (accel_magnitude < FREEFALL_THRESHOLD) {
                start_time = current_time;
                fall_state = FREEFALL;
