#define X_GYRO_OUT 0x14

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    PI_SPI_MODE3

// Scale Factor
#define SCALE_FACTOR 0.0305 // deg/sec/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, int16_t data);
int initialize_adis16266(int handle);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of register address for read operation
    tx_buf[0] = (reg_addr | 0x80) & 0xFF;
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg_addr, int16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of register address for write operation
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data & 0xFF; // LSB

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Initialize ADIS16266 Function
int initialize_adis16266(int handle) {
    int16_t who_am_i;

    // Verify WHO_AM_I register
    if (spi_read_register(handle, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "WHO_AM_I register returned 0x%04X, expected 0x3F5A\n", who_am_i);
        return -1;
    }

    printf("ADIS16266 initialized successfully. WHO_AM_I: 0x%04X\n", who_am_i);
    return 0;
}

int main() {
    int status;
    int16_t gyro_data;
    double angular_rate;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADIS16266
    if (initialize_adis16266(spi_handle) != 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,AngularRate(deg/sec)\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (spi_read_register(spi_handle, X_GYRO_OUT, &gyro_data) == 0) {
            // Scale the data
            angular_rate = gyro_data * SCALE_FACTOR;

            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the data
            fprintf(log_file, "%s,%.4f\n", timestamp, angular_rate);
            fflush(log_file); // Ensure data is written to file immediately

            printf("%s, Angular Rate: %.4f deg/sec\n", timestamp, angular_rate);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Close SPI and log file
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

