#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SENSITIVITY 8.75 // mdps/LSB
#define SAMPLE_INTERVAL_NS 10000000 // 10 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_value);
int log_data(long long timestamp, float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int initialize_gyro() {
    int retries = 3;
    int status;

    // Verify WHO_AM_I register
    while (retries > 0) {
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
            gpioDelay(100000); // 100 ms delay
            retries--;
            continue;
        }
        if (who_am_i != WHO_AM_I_VALUE) {
            fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
            gpioDelay(100000); // 100 ms delay
            retries--;
            continue;
        }
        break;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to verify WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 for normal mode and enable all axes
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure CTRL_REG4 for +-250 dps full-scale range
    status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %d\n", status);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

