#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"

static volatile int terminate_flag = 0;
static FILE *log_file = NULL;

// Function to handle SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    terminate_flag = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    return 0;
}

// Function to open the log file
int open_log_file()
{
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL)
    {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

// Function to read the flame sensor
int read_flame_sensor()
{
    int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
    if (sensor_value < 0)
    {
        fprintf(stderr, "Error reading sensor value\n");
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to log the event to the file
void log_event(int flame_detected)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s - Flame detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
        fflush(log_file);
    }
    else
    {
        fprintf(stderr, "Log file not open, cannot log event\n");
    }
}

// Function to print the alarm message
void print_alarm_message()
{
    printf("FLAME DETECTED!\n");
}

// Function to cleanup resources before exiting
void cleanup()
{
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioTerminate();
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    // Open the log file
    if (open_log_file() != 0)
    {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate_flag)
    {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) // Flame detected (LOW)
        {
            log_event(1);
            print_alarm_message();
        }
        else if (sensor_value > 0) // No flame (HIGH)
        {
            log_event(0);
        }
        else
        {
            fprintf(stderr, "Error reading sensor, skipping this iteration\n");
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

