#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x53
#define X_LSB_REG 0x28
#define X_MSB_REG 0x29
#define Y_LSB_REG 0x2A
#define Y_MSB_REG 0x2B
#define Z_LSB_REG 0x2C
#define Z_MSB_REG 0x2D

#define SAMPLE_INTERVAL_MS 100

// Global variables for signal handling and file I/O
static volatile int keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
sensor_data_t read_sensor_data(int fd);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(FILE* fp, const char* timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function with error handling
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write function with error handling
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data;
    int x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;

    x_lsb = i2c_read_reg(fd, X_LSB_REG);
    x_msb = i2c_read_reg(fd, X_MSB_REG);
    y_lsb = i2c_read_reg(fd, Y_LSB_REG);
    y_msb = i2c_read_reg(fd, Y_MSB_REG);
    z_lsb = i2c_read_reg(fd, Z_LSB_REG);
    z_msb = i2c_read_reg(fd, Z_MSB_REG);

    if (x_lsb < 0 || x_msb < 0 || y_lsb < 0 || y_msb < 0 || z_lsb < 0 || z_msb < 0) {
        data.x = 0; // Set to 0 to avoid garbage values
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((x_msb << 8) | x_lsb);
    data.y = (int16_t)((y_msb << 8) | y_lsb);
    data.z = (int16_t)((z_msb << 8) | z_lsb);

    return data;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", &timeinfo);
    return timestamp_str;
}

// Function to log data to CSV file
int log_data(FILE* fp, const char* timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int main() {
    char timestamp[32];
    sensor_data_t sensor_data;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (keep_running) {
        // Read sensor data
        sensor_data = read_sensor_data(i2c_fd);

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(log_file, timestamp, sensor_data.x, sensor_data.y, sensor_data.z) != 0) {
            fprintf(stderr, "Error logging data, skipping sample.\n");
        }

        // Sleep for 100ms
        usleep(SAMPLE_INTERVAL_MS * 1000); // usleep takes microseconds
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

