// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(struct gpiod_line *line);
int log_data(int sensor1_state, int sensor2_state);
void handle_conveyor_halt();
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO pins
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(chip);
        return -1;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("Error getting GPIO line 27");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return -1;
    }

    if (gpiod_line_request_input(line1, "conveyor_monitor") < 0) {
        perror("Error requesting GPIO line 17 as input");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return -1;
    }

    if (gpiod_line_request_input(line2, "conveyor_monitor") < 0) {
        perror("Error requesting GPIO line 27 as input");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO line value");
        return -1; // Indicate error
    }
    return value;
}

// Log data to file
int log_data(int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%ld.%03ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000000, sensor1_state, sensor2_state);
    fclose(log_file);

    return 0;
}

// Handle conveyor halt
void handle_conveyor_halt() {
    printf("Conveyor halted!\n");
}

// Cleanup resources
void cleanup() {
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Conveyor belt monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int sensor1_state = read_sensor(line1);
        int sensor2_state = read_sensor(line2);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor values. Continuing.\n");
        } else {
            if (log_data(sensor1_state, sensor2_state) < 0) {
                fprintf(stderr, "Error logging data. Continuing.\n");
            }

            if (sensor1_state == 1 && sensor2_state == 1) {
                handle_conveyor_halt();
            }
        }

        usleep(50000); // 50 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Conveyor belt monitor stopped.\n");
    return 0;
}

