        fprintf(stderr, "Error setting CTRL_REG1 to standby mode: %s\n", strerror(errno));
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2c_write_reg(fd, CTRL_REG1, 0x02) < 0) {
        fprintf(stderr, "Error setting CTRL_REG1 to active mode and 100 Hz: %s\n", strerror(errno));
        return -1;
    }

    printf("MMA8452Q sensor initialized successfully.\n");
    return 0;
}

// Read accelerometer function
void read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read_block(fd, OUT_X_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        *x = *y = *z = 0; // Set to 0 to avoid using uninitialized values
        return;
    }

    *x = (int16_t)((data[0] << 8) | data[1]) >> 4;
    *y = (int16_t)((data[2] << 8) | data[3]) >> 4;
    *z = (int16_t)((data[4] << 8) | data[5]) >> 4;
}

// Calculate tilt angle function
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 2048.0f * SENSITIVITY_2G; // Convert to g
    float y_g = (float)y / 2048.0f * SENSITIVITY_2G;
    float z_g = (float)z / 2048.0f * SENSITIVITY_2G;

    float angle = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0f / PI;
    return angle;
}

// Log fall function
void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, MMA8452Q_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        i2c_close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        i2c_close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float tilt_angle;

    // Main loop
    while (!terminate) {
        read_accelerometer(i2c_fd, &x, &y, &z);
        tilt_angle = calculate_tilt_angle(x, y, z);

        if (fabs(tilt_angle) > FALL_THRESHOLD) {
            log_fall(x, y, z);
        }

        usleep(10000); // 10 ms
    }

    // Cleanup
    i2c_close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

