#include <time.h>
#include <errno.h>
#include <string.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG3 0x22
#define WHO_AM_I 0x0F
#define OUT_X_L 0x28

// Calibration values (replace with your actual calibration data)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detector threshold (in milliGauss)
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int init_i2c(int addr);
int init_lis3mdl(int fd);
int read_mag_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_mgauss(int16_t raw_data, float scale);
void apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void check_metal_detector(float x, float y, float z);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    stop_flag = 1;
}

// Initialize I2C interface
int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize LIS3MDL sensor
int init_lis3mdl(int fd) {
    uint8_t who_am_i;
    uint8_t ctrl_reg1 = 0x70; // Continuous conversion, 80 Hz ODR, high-performance
    uint8_t ctrl_reg4 = 0x0C; // +-4 gauss
    uint8_t ctrl_reg3 = 0x00; // Continuous-conversion mode

    // Verify WHO_AM_I register
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0x3D) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1
    uint8_t buf[2];
    buf[0] = CTRL_REG1;
    buf[1] = ctrl_reg1;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    // Configure CTRL_REG4
    buf[0] = CTRL_REG4;
    buf[1] = ctrl_reg4;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to CTRL_REG4");
        return -1;
    }

    // Configure CTRL_REG3
    buf[0] = CTRL_REG3;
    buf[1] = ctrl_reg3;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to CTRL_REG3");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_mag_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    uint8_t reg = OUT_X_L | 0x80; // Enable auto-increment

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to register address for reading");
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        perror("Error reading magnetometer data");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Convert raw data to milliGauss
float convert_to_mgauss(int16_t raw_data, float scale) {
    return (float)raw_data * scale * 0.146;
}

// Apply calibration offsets and scales
void apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x, float *y, float *z) {
    *x = (float)raw_x * X_SCALE + X_OFFSET;
    *y = (float)raw_y * Y_SCALE + Y_OFFSET;
    *z = (float)raw_z * Z_SCALE + Z_OFFSET;
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file);
}

// Check for metal detection
void check_metal_detector(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.2f mgauss\n", magnitude);
    }
}

int main() {
    int16_t raw_x, raw_y, raw_z;
    float x, y, z;
    int retries = 3;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(LIS3MDL_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed, exiting...\n");
        return 1;
    }

    // Initialize LIS3MDL
    if (init_lis3mdl(i2c_fd) < 0) {
        fprintf(stderr, "LIS3MDL initialization failed, exiting...\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        // Read magnetometer data with retries
        if (read_mag_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Apply calibration
            apply_calibration(raw_x, raw_y, raw_z, &x, &y, &z);

            // Log data
            log_data(x, y, z);

            // Check for metal detection
            check_metal_detector(x, y, z);

            // Delay for 100 ms (10 Hz sampling rate)
            usleep(100000); // 100 ms
        } else {
            fprintf(stderr, "Failed to read magnetometer data, retrying...\n");
            // Attempt to re-initialize I2C
            close(i2c_fd);
            i2c_fd = init_i2c(LIS3MDL_ADDR);
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed, exiting...\n");
                stop_flag = 1; // Exit loop if re-initialization fails
            } else {
                if (init_lis3mdl(i2c_fd) < 0) {
                    fprintf(stderr, "LIS3MDL re-initialization failed, exiting...\n");
                    stop_flag = 1; // Exit loop if re-initialization fails
                }
            }
        }
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

