#define ADXL354_PARTID    0x01
#define ADXL354_XDATA_REG 0x08
#define ADXL354_YDATA_REG 0x0B
#define ADXL354_ZDATA_REG 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// ADXL354B Sensitivity
#define ADXL354_SENSITIVITY 0.0000039 // 3.9 microg/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int adxl354_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len);
int adxl354_write_register(int handle, uint8_t reg_addr, uint8_t data);
int adxl354_init(int handle);
int adxl354_read_acceleration(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Function to read a register from the ADXL354B
int adxl354_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read

    int result = spiXfer(handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to write a register in the ADXL354B
int adxl354_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    int result = spiWrite(handle, tx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to initialize the ADXL354B
int adxl354_init(int handle) {
    uint8_t part_id;
    int retries = 3;

    // Reset the device
    while (retries > 0) {
        if (adxl354_write_register(handle, ADXL354_RESET_REG, 0x52) == 0) {
            break;
        }
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // Wait for reset to complete

    // Verify Part ID
    if (adxl354_read_register(handle, ADXL354_PARTID, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read Part ID\n");
        return -1;
    }
    if (part_id != 0x1D) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Set measurement mode (clear RUN bit)
    uint8_t power_ctl;
    if (adxl354_read_register(handle, ADXL354_POWER_CTL, &power_ctl, 1) != 0) {
        fprintf(stderr, "Failed to read POWER_CTL\n");
        return -1;
    }
    power_ctl &= ~(1 << 0); // Clear RUN bit
    if (adxl354_write_register(handle, ADXL354_POWER_CTL, power_ctl) != 0) {
        fprintf(stderr, "Failed to write POWER_CTL\n");
        return -1;
    }

    // Wait for STABLE bit to set (polling)
    uint8_t status;
    retries = 100; // Wait 100ms for status to stabilize
    while (retries > 0) {
        if (adxl354_read_register(handle, ADXL354_STATUS, &status, 1) == 0) {
            if (status & (1 << 0)) {
                break;
            }
        }
        gpioDelay(1000); // 1 ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Timeout waiting for STABLE bit\n");
        return -1;
    }

    // Set RUN bit to start measurement
    power_ctl |= (1 << 0); // Set RUN bit
    if (adxl354_write_register(handle, ADXL354_POWER_CTL, power_ctl) != 0) {
        fprintf(stderr, "Failed to write POWER_CTL\n");
        return -1;
    }

    return 0;
}

