#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// ADIS16266 Register Addresses
#define MSC_CTRL_REG 0x24
#define X_RATE_OUT 0x04
#define Y_RATE_OUT 0x06
#define Z_RATE_OUT 0x08

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_CLOCK_SPEED 1000000 // 1 MHz

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8

// Scale Factor
#define SCALE_FACTOR 0.02 // deg/sec/LSB

// Global Variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int spi_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
int adis16266_init(void);
int read_adis16266_register(uint8_t reg_addr, int16_t *data);
void convert_raw_to_angular_rate(int16_t raw_data, float *angular_rate);
void log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization Function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure clock speed
    uint32_t speed = SPI_CLOCK_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting clock speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization Function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "adis16266_cs", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// ADIS16266 Initialization Function
int adis16266_init(void) {
    // Enable data ready mode
    uint8_t data[2];
    data[0] = MSC_CTRL_REG | 0x80; // Set MSB to 1 for write
    data[1] = 0x03; // Enable data ready mode

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)data,
        .len = 2,
        .speed_hz = SPI_CLOCK_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error writing to MSC_CTRL register");
        return -1;
    }

    return 0;
}

// Read ADIS16266 Register Function
int read_adis16266_register(uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set MSB to 1 for read
    tx_buf[1] = 0x00; // Dummy byte for reading

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_CLOCK_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error reading register");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Convert Raw Data to Angular Rate Function
void convert_raw_to_angular_rate(int16_t raw_data, float *angular_rate) {
    *angular_rate = raw_data * SCALE_FACTOR;
}

// Log Data Function
void log_data(float x_rate, float y_rate, float z_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", timestamp, x_rate, y_rate, z_rate);
}

// Signal Handler Function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
        terminate = 1;
    }
}

// Cleanup Function
void cleanup(void) {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Deactivate CS
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize ADIS16266
    if (adis16266_init() < 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return 1;
    }

    int16_t x_raw, y_raw, z_raw;
    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        // Read X, Y, and Z angular rates
        if (read_adis16266_register(X_RATE_OUT, &x_raw) < 0) {
            fprintf(stderr, "Error reading X rate\n");
        } else if (read_adis16266_register(Y_RATE_OUT, &y_raw) < 0) {
            fprintf(stderr, "Error reading Y rate\n");
        } else if (read_adis16266_register(Z_RATE_OUT, &z_raw) < 0) {
            fprintf(stderr, "Error reading Z rate\n");
        } else {
            // Convert raw data to angular rates
            convert_raw_to_angular_rate(x_raw, &x_rate);
            convert_raw_to_angular_rate(y_raw, &y_rate);
            convert_raw_to_angular_rate(z_raw, &z_rate);

            // Log the data
            log_data(x_rate, y_rate, z_rate);
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

