    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error writing to MSC_CTRL register");
        return -1;
    }

    return 0;
}

// Read ADIS16266 Register Function
int read_adis16266_register(uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set MSB to 1 for read
    tx_buf[1] = 0x00; // Dummy byte for reading

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_CLOCK_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error reading register");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Convert Raw Data to Angular Rate Function
void convert_raw_to_angular_rate(int16_t raw_data, float *angular_rate) {
    *angular_rate = raw_data * SCALE_FACTOR;
}

// Log Data Function
void log_data(float x_rate, float y_rate, float z_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", timestamp, x_rate, y_rate, z_rate);
}

// Signal Handler Function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
        terminate = 1;
    }
}

// Cleanup Function
void cleanup(void) {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Deactivate CS
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize ADIS16266
    if (adis16266_init() < 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return 1;
    }

    int16_t x_raw, y_raw, z_raw;
    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        // Read X, Y, and Z angular rates
        if (read_adis16266_register(X_RATE_OUT, &x_raw) < 0) {
            fprintf(stderr, "Error reading X rate\n");
        } else if (read_adis16266_register(Y_RATE_OUT, &y_raw) < 0) {
            fprintf(stderr, "Error reading Y rate\n");
        } else if (read_adis16266_register(Z_RATE_OUT, &z_raw) < 0) {
            fprintf(stderr, "Error reading Z rate\n");
        } else {
            // Convert raw data to angular rates
            convert_raw_to_angular_rate(x_raw, &x_rate);
            convert_raw_to_angular_rate(y_raw, &y_rate);
            convert_raw_to_angular_rate(z_raw, &z_rate);

            // Log the data
            log_data(x_rate, y_rate, z_rate);
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

