// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Sensitivity values
#define GYRO_SENSITIVITY 8.75  // mdps/LSB
#define ACCEL_SENSITIVITY 0.061 // g/LSB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    int status = i2cWriteByteData(i2c_handle, CTRL1_XL, 0x42); // +-2g, 104 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL: %d\n", status);
        return -1;
    }

    // Configure gyroscope
    status = i2cWriteByteData(i2c_handle, CTRL2_G, 0x42); // +-250 dps, 104 Hz
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL2_G: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    char buffer[12];
    int status = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    // Extract raw values
    int16_t raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t raw_accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to physical units
    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY / 1000.0;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY / 1000.0;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY / 1000.0;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY / 1000.0;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY / 1000.0;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY / 1000.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps, Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

