#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_S 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    int i;
    time_t start_time;
    time_t current_time;
    double elapsed_time;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop
    start_time = time(NULL);
    while (program_running) {
        high_count = 0;
        for (i = 0; i < WINDOW_DURATION_S * 1000 / SAMPLE_INTERVAL_MS; i++) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
        }

        current_time = time(NULL);
        elapsed_time = difftime(current_time, start_time);

        if (high_count > threshold) {
            printf("ALERT: High-reading count exceeded threshold (%d) in the last 5 seconds.\n", high_count);
        } else {
            printf("Status: High-reading count = %d, Elapsed time = %.2f seconds\n", high_count, elapsed_time);
        }

        gpioDelay(1000000); // 1-second pause
        start_time = time(NULL);
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

