#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "access_log.txt"

// Define code length
#define CODE_LENGTH 6

// Global variables
static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *door_a_line, *door_b_line;
static FILE *log_file;

// Function prototypes
int generate_random_code(char *code);
int validate_code(const char *code);
int unlock_door(int door_number);
int lock_door(int door_number);
int log_access(const char *code);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to generate a random 6-digit code
int generate_random_code(char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code buffer is NULL in generate_random_code\n");
        return -1;
    }

    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random number between 100000 and 999999
    int random_number = (rand() % (999999 - 100000 + 1)) + 100000;

    // Convert the number to a string
    sprintf(code, "%06d", random_number);

    return 0;
}

// Function to validate the user input code
int validate_code(const char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code is NULL in validate_code\n");
        return -1;
    }

    // Check if the code is exactly 6 digits long
    if (strlen(code) != CODE_LENGTH) {
        fprintf(stderr, "Error: Code is not 6 digits long\n");
        return -1;
    }

    // Check if all characters are digits
    for (int i = 0; i < CODE_LENGTH; i++) {
        if (code[i] < '0' || code[i] > '9') {
            fprintf(stderr, "Error: Code contains non-digit characters\n");
            return -1;
        }
    }

    return 0;
}

// Function to unlock a door
int unlock_door(int door_number) {
    struct gpiod_line *line;

    if (door_number == 1) {
        line = door_a_line;
    } else if (door_number == 2) {
        line = door_b_line;
    } else {
        fprintf(stderr, "Error: Invalid door number in unlock_door\n");
        return -1;
    }

    if (!line) {
        fprintf(stderr, "Error: Line for door %d is NULL in unlock_door\n", door_number);
        return -1;
    }

    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set value for door %d (ret=%d)\n", door_number, ret);
        return -1;
    }

    return 0;
}

// Function to lock a door
int lock_door(int door_number) {
    struct gpiod_line *line;

    if (door_number == 1) {
        line = door_a_line;
    } else if (door_number == 2) {
        line = door_b_line;
    } else {
        fprintf(stderr, "Error: Invalid door number in lock_door\n");
        return -1;
    }

    if (!line) {
        fprintf(stderr, "Error: Line for door %d is NULL in lock_door\n", door_number);
        return -1;
    }

    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set value for door %d (ret=%d)\n", door_number, ret);
        return -1;
    }

    return 0;
}

// Function to log access attempts
int log_access(const char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Code is NULL in log_access\n");
        return -1;
    }

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is NULL in log_access\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%s\n", timestamp, code);
    fflush(log_file); // Ensure data is written to the file immediately

    return 0;
}

int main() {
    char code[CODE_LENGTH + 1];
    char user_input[CODE_LENGTH + 1];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s\n", GPIOCHIP);
        return 1;
    }

    // Get GPIO lines for door A and door B
    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error: Failed to get line for door A (pin %d)\n", DOOR_A_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error: Failed to get line for door B (pin %d)\n", DOOR_B_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "door_access";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(door_a_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request line for door A (ret=%d)\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(door_b_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request line for door B (ret=%d)\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        gpiod_chip_close(chip);
        return 1;
    }

    // Generate initial random code
    if (generate_random_code(code) != 0) {
        fprintf(stderr, "Error: Failed to generate initial code\n");
        fclose(log_file);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Initial code: %s\n", code);

    // Main loop
    while (running) {
        printf("Enter code: ");
