#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define HIGH_RES_MODE_2 0x21
#define LOG_FILE "light_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Function to configure the BH1750FVI sensor
int config_sensor() {
    unsigned char config_cmd = HIGH_RES_MODE_2;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read raw data from the sensor
int read_sensor_data(unsigned char *data) {
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to convert raw data to lux
float convert_to_lux(unsigned char *data) {
    unsigned int raw_value = (data[0] << 8) | data[1];
    return (float)raw_value / 1.2;
}

// Function to log the data to a file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fclose(log_file);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C bus
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure the sensor
    if (config_sensor() < 0) {
        close(i2c_fd);
        return 1;
    }

    unsigned char sensor_data[2];
    float lux_value;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(sensor_data) < 0) {
            close(i2c_fd);
            return 1;
        }

        // Convert to lux
        lux_value = convert_to_lux(sensor_data);

        // Log the data
        if (log_data(lux_value) < 0) {
            close(i2c_fd);
            return 1;
        }

        printf("Lux: %.2f\n", lux_value);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

