#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define SERVER_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_S 5
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int init_mpr121();
int read_touch_data(unsigned short *data);
float map_touch_to_frequency(unsigned short touch_value);
void play_tone(float frequency);
void stop_tone();
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signum);

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_GPIO, 1000); // 1 kHz
    gpioSetPWMrange(PWM_GPIO, 1000); // Range of 0-1000

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);

    // Accept connections in a loop
    while (1) {
        struct sockaddr_in client_address;
        int addrlen = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for new connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(new_socket);

        close(new_socket);
    }

    return 0;
}

int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Failed to write ECR register\n");
        return 1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrode sensitivity and release thresholds
    if (i2cWriteByteData(i2c_handle, 0x41, 0x0C) < 0) return 1; // Set Electrode 0 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x42, 0x0C) < 0) return 1; // Set Electrode 1 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x43, 0x0C) < 0) return 1; // Set Electrode 2 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x44, 0x0C) < 0) return 1; // Set Electrode 3 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x45, 0x0C) < 0) return 1; // Set Electrode 4 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x46, 0x0C) < 0) return 1; // Set Electrode 5 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x47, 0x0C) < 0) return 1; // Set Electrode 6 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x48, 0x0C) < 0) return 1; // Set Electrode 7 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x49, 0x0C) < 0) return 1; // Set Electrode 8 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x4A, 0x0C) < 0) return 1; // Set Electrode 9 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x4B, 0x0C) < 0) return 1; // Set Electrode 10 sensitivity
    if (i2cWriteByteData(i2c_handle, 0x4C, 0x0C) < 0) return 1; // Set Electrode 11 sensitivity

    if (i2cWriteByteData(i2c_handle, 0x4D, 0x00) < 0) return 1; // Set Electrode 0 release threshold
    if (i2cWriteByteData(i2c_handle, 0x4E, 0x00) < 0) return 1; // Set Electrode 1 release threshold
    if (i2cWriteByteData(i2c_handle, 0x4F, 0x00) < 0) return 1; // Set Electrode 2 release threshold
    if (i2cWriteByteData(i2c_handle, 0x50, 0x00) < 0) return 1; // Set Electrode 3 release threshold
    if (i2cWriteByteData(i2c_handle, 0x51, 0x00) < 0) return 1; // Set Electrode 4 release threshold
    if (i2cWriteByteData(i2c_handle, 0x52, 0x00) < 0) return 1; // Set Electrode 5 release threshold
    if (i2cWriteByteData(i2c_handle, 0x53, 0x00) < 0) return 1; // Set Electrode 6 release threshold
    if (i2cWriteByteData(i2c_handle, 0x54, 0x00) < 0) return 1; // Set Electrode 7 release threshold
    if (i2cWriteByteData(i2c_handle, 0x55, 0x00) < 0) return 1; // Set Electrode 8 release threshold
    if (i2cWriteByteData(i2c_handle, 0x56, 0x00) < 0) return 1; // Set Electrode 9 release threshold
    if (i2cWriteByteData(i2c_handle, 0x57, 0x00) < 0) return 1; // Set Electrode 10 release threshold
    if (i2cWriteByteData(i2c_handle, 0x58, 0x00) < 0) return 1; // Set Electrode 11 release threshold

    // Configure filter
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x10) < 0) return 1; // Set filter configuration
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x01) < 0) return 1; // Set filter configuration

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Failed to write ECR register\n");
        return 1;
    }

    return 0;
}

int read_touch_data(unsigned short *data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Failed to read touch data\n");
        return 1;
    }

    *data = (buf[1] << 8) | buf[0];
    return 0;
}

float map_touch_to_frequency(unsigned short touch_value) {
    // Find the maximum touch value
    unsigned short max_touch = 0;
    for (int i = 0; i < 12; i++) {
        if (touch_value & (1 << i)) {
            max_touch = (touch_value >> i) & 0x03FF; // Extract the value of the electrode
            break;
        }
    }

    // Map the maximum touch value to a frequency between 220 and 880 Hz
    float frequency = 220.0 + (float)max_touch / 1023.0 * (880.0 - 220.0);
    return frequency;
}

void play_tone(float frequency) {
    // Calculate the PWM duty cycle based on the frequency
    int duty_cycle = (int)(500.0 / frequency); // Adjust 500.0 as needed
    if (duty_cycle > 1000) duty_cycle = 1000; //Clamp to max range
    if (duty_cycle < 0) duty_cycle = 0;

    gpioPWM(PWM_GPIO, duty_cycle);
}

void stop_tone() {
    gpioPWM(PWM_GPIO, 0);
}

void log_frequency(float frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %.2f Hz\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
