        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_GPIO, 1000); // 1 kHz
    gpioSetPWMrange(PWM_GPIO, 1000); // Range of 0-1000

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
