#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define GPIO_PIN 17
#define PWM_FREQUENCY 1000 // Hz
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)
#define SAMPLE_PERIOD_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(int bus, int addr);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int gpio_init(int pin);
int gpio_set_pwm(struct gpiod_line *line, int duty_cycle);
int log_message(const char *message);
void signal_handler(int sig);

// I2C initialization function
int i2c_init(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C block read function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// I2C byte write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "lsm303_led", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// GPIO PWM control function
int gpio_set_pwm(struct gpiod_line *line, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Duty cycle out of range (0-100)\n");
        return -1;
    }

    // Calculate the on-time based on the duty cycle
    long on_time_ns = (long)duty_cycle * PWM_PERIOD_NS / 100;

    // Set the line high for the on-time
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    struct timespec on_time = {0, on_time_ns};
    nanosleep(&on_time, NULL);

    // Set the line low for the remaining time
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    struct timespec off_time = {0, PWM_PERIOD_NS - on_time_ns};
    nanosleep(&off_time, NULL);

    return 0;
}

// Logging function
int log_message(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not initialized\n");
        return -1;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[256];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld: %s\n", tmbuf, tv.tv_usec, message);

    if (fprintf(log_file, "%s", buf) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize logging
    log_file = fopen("lsm303_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, LSM303_ADDR);
    if (i2c_fd < 0) {
        log_message("I2C initialization failed");
        fclose(log_file);
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        log_message("GPIO chip open failed");
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        log_message("GPIO line get failed");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "lsm303_led", 0) < 0) {
        log_message("GPIO line request failed");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Configure magnetometer
    if (i2c_write_byte(i2c_fd, CTRL_REG1_M, 0x18) < 0) {
        log_message("Magnetometer configuration failed");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        int16_t x, y, z;
        float magnitude;
        int duty_cycle;

        // Read magnetometer data
        if (i2c_read_block(i2c_fd, OUT_X_L_M, data, 6) < 0) {
            log_message("I2C read error");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert data to signed 16-bit integers
        x = (int16_t)((data[1] << 8) | data[0]);
        y = (int16_t)((data[3] << 8) | data[2]);
        z = (int16_t)((data[5] << 8) | data[4]);

        // Calculate magnitude of Z-axis
        magnitude = sqrt(z * z);

        // Calculate duty cycle (0-100)
        duty_cycle = (int)((magnitude / 1000.0) * 100.0); // Assuming max magnitude of 1000
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        // Set PWM duty cycle
        if (gpio_set_pwm(gpio_line, duty_cycle) < 0) {
            log_message("GPIO PWM set failed");
        }

        // Log data
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "X: %d, Y: %d, Z: %d, Magnitude: %.2f, Duty Cycle: %d", x, y, z, magnitude, duty_cycle);
        log_message(log_buffer);

        // Sleep for the sample period
        usleep(SAMPLE_PERIOD_MS * 1000); // Convert ms to us
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpiod_line_set_value(gpio_line, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

