#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Configuration values
#define HMC5883L_CONFIG_A_VALUE 0x70 // 8-average, 15 Hz, normal measurement
#define HMC5883L_CONFIG_B_VALUE 0x20 // Gain = 1.3 Gauss
#define HMC5883L_MODE_CONTINUOUS 0x00 // Continuous measurement mode

// Hard iron offset averaging window size
#define OFFSET_WINDOW_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold hard iron offsets
typedef struct {
    float x;
    float y;
    float z;
} HardIronOffsets;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int init_hmc5883l() {
    // Configure register A
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, HMC5883L_CONFIG_A_VALUE) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }

    // Configure register B
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, HMC5883L_CONFIG_B_VALUE) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, HMC5883L_MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate running average of hard iron offsets
HardIronOffsets calculate_running_average(HardIronOffsets current_offsets, HardIronOffsets new_offsets, int window_size, int sample_count) {
    HardIronOffsets averaged_offsets;

    if (sample_count < window_size) {
        averaged_offsets.x = (current_offsets.x * sample_count + new_offsets.x) / (sample_count + 1);
        averaged_offsets.y = (current_offsets.y * sample_count + new_offsets.y) / (sample_count + 1);
        averaged_offsets.z = (current_offsets.z * sample_count + new_offsets.z) / (sample_count + 1);
    } else {
        averaged_offsets.x = (current_offsets.x * (window_size - 1) + new_offsets.x) / window_size;
        averaged_offsets.y = (current_offsets.y * (window_size - 1) + new_offsets.y) / window_size;
        averaged_offsets.z = (current_offsets.z * (window_size - 1) + new_offsets.z) / window_size;
    }

    return averaged_offsets;
}

// Function to apply hard iron offsets
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, HardIronOffsets offsets, float *corrected_x, float *corrected_y, float *corrected_z) {
    *corrected_x = (float)x - offsets.x;
    *corrected_y = (float)y - offsets.y;
    *corrected_z = (float)z - offsets.z;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Hard iron offset variables
    HardIronOffsets hard_iron_offsets = {0.0, 0.0, 0.0};
    HardIronOffsets running_average_offsets = {0.0, 0.0, 0.0};
    int offset_sample_count = 0;

    // Main loop
    while (!terminate) {
        int16_t x, y, z;

        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calculate hard iron offsets
            HardIronOffsets current_offsets = {(float)x, (float)y, (float)z};
            running_average_offsets = calculate_running_average(running_average_offsets, current_offsets, OFFSET_WINDOW_SIZE, offset_sample_count);
            offset_sample_count++;

            // Apply hard iron offsets
            float corrected_x, corrected_y, corrected_z;
            apply_hard_iron_offsets(x, y, z, running_average_offsets, &corrected_x, &corrected_y, &corrected_z);

            // Print offset-corrected values
            printf("X: %.2f, Y: %.2f, Z: %.2f\n", corrected_x, corrected_y, corrected_z);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

