// LSM303D I2C address (SA0 high)
#define LSM303D_ADDR 0x1D

// LSM303D Registers
#define WHO_AM_I   0x0F
#define CTRL_REG1  0x20
#define CTRL_REG4  0x23
#define INT1_CFG   0x30
#define INT1_SRC   0x31
#define OUT_X_L_A  0x28

// GPIO pin for interrupt
#define GPIO_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int16_t x, y, z;
} sample_t;

static sample_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function prototypes
int init_i2c(int addr);
int init_gpio(int pin);
int read_lsm303d(int16_t *x, int16_t *y, int16_t *z);
void store_sample(int16_t x, int16_t y, int16_t z);
void dump_buffer();
void signal_handler(int sig);

// I2C initialization function
int init_i2c(int addr) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int init_gpio(int pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(gpio_line, "lsm303d_mon") < 0) {
        perror("Error requesting GPIO line for rising edge events");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// LSM303D data acquisition function
int read_lsm303d(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L_A | 0x80, (char *)buffer, 6);
    if (ret < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Circular buffer store function
void store_sample(int16_t x, int16_t y, int16_t z) {
    circular_buffer[buffer_index].x = x;
    circular_buffer[buffer_index].y = y;
    circular_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Circular buffer dump function
void dump_buffer() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s: ", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE;
        printf("X:%6d Y:%6d Z:%6d ", circular_buffer[index].x, circular_buffer[index].y, circular_buffer[index].z);
    }
    printf("\n");
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

