#define DELAY_NS 500000000

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *solenoid1_line, *solenoid2_line;

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Set both solenoid lines to LOW
    if (solenoid1_line) {
        gpiod_line_set_value(solenoid1_line, 0);
    }
    if (solenoid2_line) {
        gpiod_line_set_value(solenoid2_line, 0);
    }

    // Release GPIO lines
    if (solenoid1_line) {
        gpiod_line_release(solenoid1_line);
    }
    if (solenoid2_line) {
        gpiod_line_release(solenoid2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for solenoid 1
    solenoid1_line = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!solenoid1_line) {
        perror("Error getting solenoid 1 line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for solenoid 2
    solenoid2_line = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!solenoid2_line) {
        perror("Error getting solenoid 2 line");
        gpiod_chip_close(chip);
        gpiod_line_release(solenoid1_line);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(solenoid1_line, "solenoid1", 0) < 0) {
        perror("Error requesting solenoid 1 line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        return 1;
    }

    if (gpiod_line_request_output(solenoid2_line, "solenoid2", 0) < 0) {
        perror("Error requesting solenoid 2 line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        return 1;
    }

    // Main loop
    while (1) {
        // Energize solenoid 1
        if (gpiod_line_set_value(solenoid1_line, 1) < 0) {
            perror("Error setting solenoid 1 line to HIGH");
            signal_handler(SIGTERM); // Simulate a signal to clean up
        }

        // Wait for 500 ms
        struct timespec delay = {0, DELAY_NS};
        nanosleep(&delay, NULL);

        // De-energize solenoid 1
        if (gpiod_line_set_value(solenoid1_line, 0) < 0) {
            perror("Error setting solenoid 1 line to LOW");
            signal_handler(SIGTERM); // Simulate a signal to clean up
        }

        // Energize solenoid 2
        if (gpiod_line_set_value(solenoid2_line, 1) < 0) {
            perror("Error setting solenoid 2 line to HIGH");
            signal_handler(SIGTERM); // Simulate a signal to clean up
        }

        // Wait for 500 ms
        nanosleep(&delay, NULL);

        // De-energize solenoid 2
        if (gpiod_line_set_value(solenoid2_line, 0) < 0) {
            perror("Error setting solenoid 2 line to LOW");
            signal_handler(SIGTERM); // Simulate a signal to clean up
        }
    }

    return 0;
}

