#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <termios.h>
#include <fcntl.h>
#include <errno.h>

// Define GPIO pins
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define UART ports
#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define timeout duration (in seconds)
#define TIMEOUT 5

// Define expected code
#define EXPECTED_CODE "123456"

// Global variables
int primary_fd = -1;
int secondary_fd = -1;

// Function prototypes
int setup_uart(const char *port);
int read_code(int fd, char *buffer, int buffer_size);
int validate_code(const char *code, const char *expected_code);
void unlock_doors(void);
void lock_doors(void);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    lock_doors(); // Ensure doors are locked on exit

    if (primary_fd != -1) {
        close(primary_fd);
    }
    if (secondary_fd != -1) {
        close(secondary_fd);
    }

    gpioTerminate();
    exit(0);
}

// Setup UART port
int setup_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = 5;             // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, B9600) != 0 || cfsetispeed(&tty, B9600) != 0) {
        fprintf(stderr, "Error from cfsetospeed/cfsetispeed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read code from UART port with timeout
int read_code(int fd, char *buffer, int buffer_size) {
    fd_set readfds;
    struct timeval timeout;
    int retval;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT;
    timeout.tv_usec = 0;

    retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error from select: %s\n", strerror(errno));
        return -1;
    } else if (retval) {
        // Data is available, read it
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            return 0; // Success
        } else if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        } else {
            // No data read, but select indicated it was ready
            return -1; // Indicate timeout
        }
    } else {
        // Timeout occurred
        return -1;
    }
}

// Validate code against expected code using constant-time comparison
int validate_code(const char *code, const char *expected_code) {
    return strncmp(code, expected_code, 6) == 0;
}

// Unlock doors
void unlock_doors(void) {
    gpioWrite(LOCK1_GPIO, 1);
    gpioWrite(LOCK2_GPIO, 1);
    printf("Doors unlocked\n");
}

// Lock doors
void lock_doors(void) {
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    printf("Doors locked\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Initialize locks to locked state
    lock_doors();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up UART ports
    primary_fd = setup_uart(PRIMARY_UART);
    if (primary_fd == -1) {
        gpioTerminate();
        return 1;
    }

    secondary_fd = setup_uart(SECONDARY_UART);
    if (secondary_fd == -1) {
        close(primary_fd);
        gpioTerminate();
        return 1;
    }

    char primary_code[7] = {0}; // Buffer for primary code
    char secondary_code[7] = {0}; // Buffer for secondary code

    // Main loop
    while (1) {
        // Read codes from both ports
        int primary_result = read_code(primary_fd, primary_code, sizeof(primary_code));
        int secondary_result = read_code(secondary_fd, secondary_code, sizeof(secondary_code));

        // Check for errors or timeouts
        if (primary_result == -1) {
