        }

        if (secondary_result == 0 && validate_code(secondary_code, EXPECTED_CODE)) {
            printf("Secondary code received: %s\n", secondary_code);
        }

        // Check if both codes are valid and match
        if (primary_result == 0 && secondary_result == 0 &&
