#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_DURATION_MS 1000
#define FAILSAFE_TIMEOUT_MS 10000
#define POLL_INTERVAL_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_pir_sensor(void);
int control_relay(int state);
void cleanup(int signal);

// Signal handler
void signal_handler(int signal)
{
    syslog(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

// Initialize GPIO lines
int initialize_gpio(void)
{
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    // Get PIR sensor line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request PIR sensor line as input
    ret = gpiod_line_request(pir_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request PIR sensor line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request relay line as output
    ret = gpiod_line_request(relay_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Initialize relay to LOW
    ret = gpiod_line_set_value(relay_line, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay to LOW");
        gpiod_chip_close(chip);
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Read PIR sensor value
int read_pir_sensor(void)
{
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Control relay state
int control_relay(int state)
{
    int ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay state");
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup(int signal)
{
    syslog(LOG_INFO, "Cleaning up GPIO resources...");

    // Set relay to LOW
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
    }

    // Release GPIO lines
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    syslog(LOG_INFO, "GPIO resources released");
    closelog();
    exit(0);
}

int main(void)
{
    int pir_value;
    int relay_state = 0; // 0 = off, 1 = on
    time_t last_high_time;
    time_t current_time;
    double time_diff;

    // Initialize syslog
    openlog("motion_strike", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        pir_value = read_pir_sensor();
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor, exiting");
            cleanup(0);
            return 1;
        }

        if (pir_value == 1) {
            // Motion detected
            if (relay_state == 0) {
                syslog(LOG_INFO, "Motion detected, activating relay");
                if (control_relay(1) < 0) {
                    syslog(LOG_ERR, "Failed to activate relay, exiting");
                    cleanup(0);
                    return 1;
                }
                relay_state = 1;
                last_high_time = time(NULL);
            } else {
                // Check failsafe timeout
                current_time = time(NULL);
                time_diff = difftime(current_time, last_high_time);

                if (time_diff * 1000 > FAILSAFE_TIMEOUT_MS) {
                    syslog(LOG_WARNING, "Potential malfunction: PIR sensor remains HIGH for %.2f seconds", time_diff);
                    cleanup(0);
                    return 1;
                }
            }
        } else {
            // No motion
            if (relay_state == 1) {
                syslog(LOG_INFO, "No motion detected, deactivating relay");
                if (control_relay(0) < 0) {
                    syslog(LOG_ERR, "Failed to deactivate relay, exiting");
                    cleanup(0);
                    return 1;
                }
                relay_state = 0;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000); // Sleep for POLL_INTERVAL_MS milliseconds
    }

    // Cleanup and exit
    cleanup(0);
    return 0;
}

