#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the timer interval (60 seconds)
#define TIMER_INTERVAL 60

// Define the relay activation time (5 minutes = 300 seconds)
#define RELAY_ACTIVATION_TIME 300

// Define the pause time between relay activations (1 minute = 60 seconds)
#define PAUSE_TIME 60

// Define the number of relays
#define NUM_RELAYS 4

// Define the number of states in the state machine
#define NUM_STATES 3

// Define the state machine states
enum {
    RELAY_ACTIVATION,
    PAUSE,
    RELAY_DEACTIVATION
};

// Define the relay pins
int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

// Define the relay activation times
int relay_activation_times[NUM_RELAYS] = {RELAY_ACTIVATION_TIME, RELAY_ACTIVATION_TIME, RELAY_ACTIVATION_TIME, RELAY_ACTIVATION_TIME};

// Define the pause times
int pause_times[NUM_RELAYS] = {PAUSE_TIME, PAUSE_TIME, PAUSE_TIME, PAUSE_TIME};

// Define the current state of the state machine
int current_state = RELAY_ACTIVATION;

// Define the current relay index
int current_relay_index = 0;

// Define the timer number
int timer_number = 0;

// Define a volatile sig_atomic_t flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void timer_callback();
void signal_handler(int signal);
void log_relay_state(int pin, int state);

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set all relay pins as output and initialize to HIGH (OFF)
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioWrite(relay_pins[i], PI_HIGH); // Initialize to OFF
    }

    return 0;
}

// Function to activate a relay
void activate_relay(int pin) {
    gpioWrite(pin, PI_LOW); // Set GPIO to LOW to activate the relay
    log_relay_state(pin, 1); // Log the relay activation
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    gpioWrite(pin, PI_HIGH); // Set GPIO to HIGH to deactivate the relay
    log_relay_state(pin, 0); // Log the relay deactivation
}

// Function to log relay state changes to syslog
void log_relay_state(int pin, int state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (state == 1) {
        syslog(LOG_INFO, "%s: Relay on GPIO %d activated", buf, pin);
    } else {
        syslog(LOG_INFO, "%s: Relay on GPIO %d deactivated", buf, pin);
    }
}

// Timer callback function
void timer_callback() {
    if (program_running) {
        switch (current_state) {
            case RELAY_ACTIVATION:
                activate_relay(relay_pins[current_relay_index]);
                current_state = PAUSE;
                break;
            case PAUSE:
                gpioDelay(pause_times[current_relay_index] * 1000); // Delay for the pause time
                current_state = RELAY_DEACTIVATION;
                break;
            case RELAY_DEACTIVATION:
                deactivate_relay(relay_pins[current_relay_index]);
                current_state = RELAY_ACTIVATION;
                break;
        }

        // Increment the relay index and wrap around if necessary
        current_relay_index = (current_relay_index + 1) % NUM_RELAYS;
    }
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;

    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        deactivate_relay(relay_pins[i]);
    }

    // Release GPIO resources
    gpioTerminate();

    // Close syslog
    closelog();

    exit(0);
}

int main() {
    // Open syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Set up the timer callback function
    if (gpioSetTimerFuncEx(timer_number, TIMER_INTERVAL * 1000, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Irrigation system started");

    // Keep the program running until a signal is received
    while (program_running) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

