}

// Add data to circular buffer
void add_to_buffer(float x, float y, float z) {
    accel_buffer[buffer_index] = x;
    accel_buffer[buffer_index + 1] = y;
    accel_buffer[buffer_index + 2] = z;
    buffer_index = (buffer_index + 3) % (BUFFER_SIZE * 3);
}

// Get latest data from buffer
accel_data_t get_latest_data() {
    accel_data_t data;
    data.x = accel_buffer[buffer_index];
    data.y = accel_buffer[buffer_index + 1];
    data.z = accel_buffer[buffer_index + 2];
    return data;
}

// Create sysfs entry
int create_sysfs_entry(const char *path) {
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open sysfs entry: %s", strerror(errno));
        return -1;
    }
    return fd;
}

// Remove sysfs entry
int remove_sysfs_entry(const char *path) {
    if (unlink(path) < 0) {
        syslog(LOG_ERR, "Failed to unlink sysfs entry: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Timer handler
void timer_handler(union sigval sv) {
    accel_data_t accel_data = read_accel_data(i2c_fd);
    add_to_buffer(accel_data.x, accel_data.y, accel_data.z);

    // Update sysfs entry
    accel_data_t latest_data = get_latest_data();
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%.3f %.3f %.3f", latest_data.x, latest_data.y, latest_data.z);

    int fd = create_sysfs_entry(SYSFS_PATH);
    if (fd >= 0) {
        if (ftruncate(fd, strlen(buffer)) < 0) {
            syslog(LOG_ERR, "Failed to truncate sysfs file: %s", strerror(errno));
        } else {
            lseek(fd, 0, SEEK_SET);
            if (write(fd, buffer, strlen(buffer)) < 0) {
                syslog(LOG_ERR, "Failed to write to sysfs file: %s", strerror(errno));
            }
        }
        close(fd);
    }
}

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Create timer
int create_timer(int fd, int interval_ms) {
    struct sigevent sev;
    struct itimerspec its;

    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGUSR1;
    sev.sigev_value.sival_ptr = &timer_fd;

    if (timer_create(CLOCK_REALTIME, &sev, &timer_fd) < 0) {
        syslog(LOG_ERR, "Failed to create timer: %s", strerror(errno));
        return -1;
    }

    its.it_value.tv_sec = interval_ms / 1000;
    its.it_value.tv_nsec = (interval_ms % 1000) * 1000000;
    its.it_interval.tv_sec = interval_ms / 1000;
    its.it_interval.tv_nsec = (interval_ms % 1000) * 1000000;

    if (timer_settime(timer_fd, 0, &its, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set timer: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Create epoll event
int create_epoll_event(int fd, int events) {
    struct epoll_event ev;
    ev.data.fd = fd;
    ev.events = events;
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, fd, &ev) < 0) {
        syslog(LOG_ERR, "Failed to add epoll event: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Create shared memory
int create_shared_memory(const char *name, size_t size) {
    shm_fd = shm_open(name, O_CREAT | O_RDWR, 0666);
    if (shm_fd < 0) {
        syslog(LOG_ERR, "Failed to create shared memory: %s", strerror(errno));
        return -1;
    }

    if (ftruncate(shm_fd, size) < 0) {
        syslog(LOG_ERR, "Failed to truncate shared memory: %s", strerror(errno));
        return -1;
    }

    accel_buffer = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (accel_buffer == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map shared memory: %s", strerror(errno));
        return -1;
    }

    return shm_fd;
}

// Open shared memory
int open_shared_memory(const char *name, size_t size) {
    shm_fd = shm_open(name, O_RDWR, 0666);
    if (shm_fd < 0) {
        syslog(LOG_ERR, "Failed to open shared memory: %s", strerror(errno));
        return -1;
    }

    accel_buffer = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (accel_buffer == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map shared memory: %s", strerror(errno));
        return -1;
    }

    return shm_fd;
}

// Close shared memory
void close_shared_memory(int fd) {
    if (munmap(accel_buffer, BUFFER_SIZE * 3 * sizeof(float)) < 0) {
        syslog(LOG_ERR, "Failed to unmap shared memory: %s", strerror(errno));
    }
    if (close(fd) < 0) {
        syslog(LOG_ERR, "Failed to close shared memory: %s", strerror(errno));
    }
}

// Unlink shared memory
void unlink_shared_memory(const char *name) {
    if (shm_unlink(name) < 0) {
        syslog(LOG_ERR, "Failed to unlink shared memory: %s", strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    int opt;
    const char *i2c_device_default = "/dev/i2c-1";

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                i2c_device = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-d i2c_device]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("mpu6050_accel", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        goto cleanup;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        goto cleanup;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) < 0) {
        goto cleanup;
    }

    // Create shared memory
    if (create_shared_memory("mpu6050_accel", BUFFER_SIZE * 3 * sizeof(float)) < 0) {
        goto cleanup;
    }

    // Create epoll instance
    epoll_fd = epoll_create1(0);
    if (epoll_fd < 0) {
        syslog(LOG_ERR, "Failed to create epoll instance: %s", strerror(errno));
        goto cleanup;
    }

    // Create timer
    if (create_timer(i2c_fd, 10) < 0) {
        goto cleanup;
    }

    // Create epoll event for timer
    if (create_epoll_event(timer_fd, EPOLLIN) < 0) {
        goto cleanup;
    }

    // Main loop
    struct epoll_event events[1];
    while (running) {
        int nfds = epoll_wait(epoll_fd, events, 1, -1);
        if (nfds < 0) {
            if (errno == EINTR) {
                break; // Interrupted by signal
            }
            syslog(LOG_ERR, "Epoll wait failed: %s", strerror(errno));
            break;
        }

        if (events[0].events & EPOLLIN) {
            // Timer event
            timer_handler(events[0].data);
        }
    }

    // Cleanup
cleanup:
    syslog(LOG_INFO, "Cleaning up...");

    // Remove sysfs entry
    remove_sysfs_entry(SYSFS_PATH);

    // Close I2C device
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Close timer
    if (timer_fd >= 0) {
        timer_delete(timer_fd);
    }

    // Close epoll
    if (epoll_fd >= 0) {
        close(epoll_fd);
    }

    // Unmap and close shared memory
    if (accel_buffer != MAP_FAILED && accel_buffer != NULL) {
        close_shared_memory(shm_fd);
        unlink_shared_memory("mpu6050_accel");
    }

    // Close syslog
    closelog();

    return 0;
}

