// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the prime numbers for the intervals
#define PRIME1 2
#define PRIME2 3
#define PRIME3 5
#define PRIME4 7

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void toggle_relay(struct gpiod_line *line);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO lines for the relays
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(relay1_line, "lighting_system", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(relay2_line, "lighting_system", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(relay3_line, "lighting_system", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(relay4_line, "lighting_system", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio() {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to toggle the state of a relay
void toggle_relay(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO line value");
        return;
    }
    int new_value = !value;
    if (gpiod_line_set_value(line, new_value) < 0) {
        perror("Error setting GPIO line value");
    }
}

int main() {
    struct timespec start_time, current_time;
    double elapsed_time;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current time
        if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
            perror("Error getting start time");
            cleanup_gpio();
            return 1;
        }

        // Toggle relays based on prime number intervals
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            perror("Error getting current time");
            cleanup_gpio();
            return 1;
        }

        elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        if (elapsed_time >= PRIME1) {
            toggle_relay(relay1_line);
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                perror("Error getting start time");
                cleanup_gpio();
                return 1;
            }
        }

        if (elapsed_time >= PRIME2) {
            toggle_relay(relay2_line);
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                perror("Error getting start time");
                cleanup_gpio();
                return 1;
            }
        }

        if (elapsed_time >= PRIME3) {
            toggle_relay(relay3_line);
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                perror("Error getting start time");
                cleanup_gpio();
                return 1;
            }
        }

        if (elapsed_time >= PRIME4) {
            toggle_relay(relay4_line);
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                perror("Error getting start time");
                cleanup_gpio();
                return 1;
            }
        }

        // Sleep for a short interval to avoid busy-waiting
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10000000; // 10 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

