#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 3

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 500

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void log_alarm_event();
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int relay_active;
} ProgramState;

ProgramState state = {0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected && !state.relay_active) {
            activate_relay();
            log_alarm_event();
            state.relay_active = 1; // Set relay active flag
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        } else if (!sound_detected) {
            state.relay_active = 0; // Reset relay active flag
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay for ALARM_DURATION seconds
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn relay on
    printf("Alarm triggered!\n");
    gpioDelay(ALARM_DURATION * 1000000); // Wait for ALARM_DURATION seconds
    gpioWrite(RELAY_PIN, 0); // Turn relay off
    printf("Alarm deactivated.\n");
}

// Log alarm event to file
void log_alarm_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Alarm triggered\n", timestamp);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
}

