#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43

// Circular buffer size
#define BUFFER_SIZE 100

// Gyroscope sensitivity
#define GYRO_SENSITIVITY 131.0f

// Threshold for angular velocity magnitude
#define ANGULAR_VELOCITY_THRESHOLD 50.0f

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t gyro_buffer;

// Function prototypes
int i2c_init(const char *device);
int mpu6050_init(int fd);
int read_gyro_data(int fd, float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z);
float calculate_magnitude(float x, float y, float z);
void handle_threshold_exceeded(float magnitude);
void signal_handler(int signal);
void cleanup();

// I2C initialization function
int i2c_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU-6050
    uint8_t data[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        return -1;
    }

    // Verify the WHO_AM_I register
    uint8_t who_am_i_reg = WHO_AM_I;
    if (write(fd, &who_am_i_reg, 1) != 1) {
        perror("Error writing to WHO_AM_I register");
        return -1;
    }

    uint8_t who_am_i_value;
    if (read(fd, &who_am_i_value, 1) != 1) {
        perror("Error reading WHO_AM_I value");
        return -1;
    }

    if (who_am_i_value != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02x, expected 0x68\n", who_am_i_value);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t gyro_reg = GYRO_XOUT_H;
    uint8_t buffer[6];

    if (write(fd, &gyro_reg, 1) != 1) {
        perror("Error writing to GYRO_XOUT_H register");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t gyro_x = (buffer[0] << 8) | buffer[1];
    int16_t gyro_y = (buffer[2] << 8) | buffer[3];
    int16_t gyro_z = (buffer[4] << 8) | buffer[5];

    // Convert to degrees per second
    *x = (float)gyro_x / GYRO_SENSITIVITY;
    *y = (float)gyro_y / GYRO_SENSITIVITY;
    *z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the magnitude of the angular velocity vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to handle threshold exceeded event
void handle_threshold_exceeded(float magnitude) {
    printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Main loop
    float x, y, z, magnitude;
    struct timespec sleep_time = {0, 10000000}; // 10ms

    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, x, y, z);

            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check if threshold is exceeded
            if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
                handle_threshold_exceeded(magnitude);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        // Sleep for 10ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

