#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define READ_COMMAND {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}
#define READ_COMMAND_LENGTH 9
#define RESPONSE_LENGTH 9
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define SLEEP_INTERVAL 5 // seconds

int uart_handle;
FILE *log_file;
FILE *error_log_file;

// Function prototypes
int init_pigpio();
int open_uart(const char *device, int baud_rate);
int read_sensor_data(int uart_handle, unsigned char *response);
int validate_checksum(const unsigned char *response);
int extract_co2_ppm(const unsigned char *response);
int log_data(FILE *log_file, long long timestamp, int co2_ppm, int error_flag);
int print_json(long long timestamp, int co2_ppm, int error_flag);
void signal_handler(int signal);
int close_resources();

int main() {
    unsigned char response[RESPONSE_LENGTH];
    int co2_ppm;
    long long timestamp;
    int error_flag = 0;

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open UART
    uart_handle = open_uart(UART_DEVICE, BAUD_RATE);
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART. Exiting.\n");
        close_resources();
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        close_resources();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file. Exiting.\n");
        close_resources();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(uart_handle, response) == 0) {
            // Validate checksum
            if (validate_checksum(response) == 0) {
                // Extract CO2 concentration
                co2_ppm = extract_co2_ppm(response);

                // Get timestamp
                timestamp = time(NULL) * 1000000LL; // Microseconds

                // Log data
                if (log_data(log_file, timestamp, co2_ppm, error_flag) != 0) {
                    fprintf(stderr, "Failed to log data.\n");
                }

                // Print JSON
                if (print_json(timestamp, co2_ppm, error_flag) != 0) {
                    fprintf(stderr, "Failed to print JSON.\n");
                }

                fflush(log_file);
            } else {
                fprintf(stderr, "Checksum validation failed.\n");
                error_flag = 1;
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
            error_flag = 1;
        }

        sleep(SLEEP_INTERVAL);
    }

    return 0;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int open_uart(const char *device, int baud_rate) {
    int handle = serOpen(device, baud_rate, 0); // 0 for default flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", device);
        return -1;
    }
    return handle;
}

int read_sensor_data(int uart_handle, unsigned char *response) {
    unsigned char command[] = READ_COMMAND;
    int bytes_written, bytes_read;

    bytes_written = serWrite(uart_handle, command, READ_COMMAND_LENGTH);
    if (bytes_written != READ_COMMAND_LENGTH) {
        fprintf(stderr, "Failed to write command. Wrote %d bytes, expected %d\n", bytes_written, READ_COMMAND_LENGTH);
        return -1;
    }

    gpioDelay(100); // Wait for sensor to respond

    bytes_read = serRead(uart_handle, response, RESPONSE_LENGTH);
    if (bytes_read != RESPONSE_LENGTH) {
        fprintf(stderr, "Failed to read response. Read %d bytes, expected %d\n", bytes_read, RESPONSE_LENGTH);
        return -1;
    }

    return 0;
}

int validate_checksum(const unsigned char *response) {
    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = 0xFF - checksum + 1;

    if (checksum != response[8]) {
        fprintf(stderr, "Checksum mismatch: calculated %02X, received %02X\n", checksum, response[8]);
        return -1;
    }

    return 0;
}

int extract_co2_ppm(const unsigned char *response) {
    return (response[2] << 8) | response[3];
}

int log_data(FILE *log_file, long long timestamp, int co2_ppm, int error_flag) {
    fprintf(log_file, "{\"timestamp\": %lld, \"co2_ppm\": %d, \"error\": %d}\n", timestamp, co2_ppm, error_flag);
    return 0;
}

int print_json(long long timestamp, int co2_ppm, int error_flag) {
    printf("{\"timestamp\": %lld, \"co2_ppm\": %d, \"error\": %d}\n", timestamp, co2_ppm, error_flag);
    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    close_resources();
    exit(0);
}

int close_resources() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
    return 0;
}

