    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

int open_uart(const char *device, int baud_rate) {
    int handle = serOpen(device, baud_rate, 0); // 0 for default flags
    if (handle < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", device);
        return -1;
    }
    return handle;
}

int read_sensor_data(int uart_handle, unsigned char *response) {
    unsigned char command[] = READ_COMMAND;
    int bytes_written, bytes_read;

    bytes_written = serWrite(uart_handle, command, READ_COMMAND_LENGTH);
    if (bytes_written != READ_COMMAND_LENGTH) {
        fprintf(stderr, "Failed to write command. Wrote %d bytes, expected %d\n", bytes_written, READ_COMMAND_LENGTH);
        return -1;
    }

    gpioDelay(100); // Wait for sensor to respond

    bytes_read = serRead(uart_handle, response, RESPONSE_LENGTH);
    if (bytes_read != RESPONSE_LENGTH) {
        fprintf(stderr, "Failed to read response. Read %d bytes, expected %d\n", bytes_read, RESPONSE_LENGTH);
        return -1;
    }

    return 0;
}

int validate_checksum(const unsigned char *response) {
    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = 0xFF - checksum + 1;

    if (checksum != response[8]) {
        fprintf(stderr, "Checksum mismatch: calculated %02X, received %02X\n", checksum, response[8]);
        return -1;
    }

    return 0;
}

int extract_co2_ppm(const unsigned char *response) {
    return (response[2] << 8) | response[3];
}

int log_data(FILE *log_file, long long timestamp, int co2_ppm, int error_flag) {
    fprintf(log_file, "{\"timestamp\": %lld, \"co2_ppm\": %d, \"error\": %d}\n", timestamp, co2_ppm, error_flag);
    return 0;
}

int print_json(long long timestamp, int co2_ppm, int error_flag) {
    printf("{\"timestamp\": %lld, \"co2_ppm\": %d, \"error\": %d}\n", timestamp, co2_ppm, error_flag);
    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    close_resources();
    exit(0);
}

int close_resources() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
    return 0;
}

