#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A_REG 0x00
#define CONFIG_B_REG 0x01
#define MODE_REG 0x02
#define DATA_START_REG 0x03
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define GPIO_PIN 17

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_hmc5883l();
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
void control_gpio(float heading);
void add_to_buffer(CircularBuffer *cb, float value);
float get_latest_heading(CircularBuffer *cb);
void signal_handler(int signal);

// Circular buffer functions
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

float get_latest_heading(CircularBuffer *cb) {
    if (cb->count > 0) {
        int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        return cb->buffer[index];
    } else {
        return 0.0; // Or some other default value
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// HMC5883L initialization function
int init_hmc5883l() {
    // Configure register A
    if (i2cWriteByteData(i2c_handle, CONFIG_A_REG, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A_REG\n");
        return -1;
    }

    // Configure register B
    if (i2cWriteByteData(i2c_handle, CONFIG_B_REG, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B_REG\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE_REG\n");
        return -1;
    }

    return 0;
}

// Function to read data from HMC5883L
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, DATA_START_REG, buffer, 6) != 6) {
        fprintf(stderr, "Error reading data from HMC5883L\n");
        return -1;
    }

    // Combine MSB and LSB for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate heading
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to control GPIO
void control_gpio(float heading) {
    float diff = fabs(heading - TARGET_HEADING);
    if (diff > 180) {
        diff = 360 - diff;
    }

    if (diff > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // High
    } else {
        gpioWrite(GPIO_PIN, 0); // Low
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer heading_buffer;
    init_circular_buffer(&heading_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    float heading;
    while (!terminate) {
        // Read data from HMC5883L
        if (read_hmc5883l_data(&x, &y, &z) == 0) {
            // Compensate for hard-iron distortion
            x -= 100;
            y -= -50;

            // Calculate heading
            heading = calculate_heading(x, y);

            // Add to circular buffer
            add_to_buffer(&heading_buffer, heading);

            // Control GPIO
            control_gpio(heading);

            // Print heading (for debugging)
            printf("Heading: %.2f\n", heading);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Sleep for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

