#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and address for BH1750 sensor
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds for relays
#define LUX_THRESHOLD_RED 50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE 300

// Define log file name
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int initialize_logging();
int read_bh1750(float *lux);
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold relay states
typedef struct {
    int red;
    int green;
    int blue;
} RelayStates;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_RELAY_PIN, PI_OUTPUT);

    return 0;
}

// Function to initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Failed to configure BH1750: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to initialize logging
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char buffer[2];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read data from BH1750: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to control relays based on lux value
void control_relays(float lux) {
    int red_state = 0;
    int green_state = 0;
    int blue_state = 0;

    if (lux < LUX_THRESHOLD_RED) {
        red_state = 1;
    }
    if (lux >= LUX_THRESHOLD_GREEN) {
        green_state = 1;
    }
    if (lux >= LUX_THRESHOLD_BLUE) {
        blue_state = 1;
    }

    gpioWrite(RED_RELAY_PIN, red_state);
    gpioWrite(GREEN_RELAY_PIN, green_state);
    gpioWrite(BLUE_RELAY_PIN, blue_state);
}

// Function to log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    // Turn off all relays
    gpioWrite(RED_RELAY_PIN, 0);
    gpioWrite(GREEN_RELAY_PIN, 0);
    gpioWrite(BLUE_RELAY_PIN, 0);

    // Close I2C device
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    RelayStates relay_states;

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Control relays
            control_relays(lux);

            // Get relay states
            relay_states.red = gpioRead(RED_RELAY_PIN);
            relay_states.green = gpioRead(GREEN_RELAY_PIN);
            relay_states.blue = gpioRead(BLUE_RELAY_PIN);

            // Log data
            log_data(lux, relay_states.red, relay_states.green, relay_states.blue);
        } else {
            fprintf(stderr, "Failed to read lux value. Logging error.\n");
            log_data(-1.0, -1, -1, -1); // Log error value
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

