    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    RelayStates relay_states;

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Control relays
            control_relays(lux);

            // Get relay states
            relay_states.red = gpioRead(RED_RELAY_PIN);
            relay_states.green = gpioRead(GREEN_RELAY_PIN);
            relay_states.blue = gpioRead(BLUE_RELAY_PIN);

            // Log data
            log_data(lux, relay_states.red, relay_states.green, relay_states.blue);
        } else {
            fprintf(stderr, "Failed to read lux value. Logging error.\n");
            log_data(-1.0, -1, -1, -1); // Log error value
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

