#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_GPIO 18
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define SERVO_CENTER_PULSE_WIDTH (SERVO_MIN_PULSE_WIDTH + SERVO_RANGE / 2)
#define SERVO_PWM_FREQUENCY 50 // Hz
#define SERVO_PWM_RANGE 20000   // us
#define SERVO_PWM_CLOCK 19200000 // Hz
#define SERVO_PWM_DUTY_CYCLE_OFFSET 1000
#define SERVO_PWM_DUTY_CYCLE_RANGE 1000
#define SERVO_PWM_DUTY_CYCLE_CENTER 1500

#define LOG_FILE "solar_tracker.log"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// MPU6050 Registers
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_GYRO_CONFIG 0x1B

// Global variables
static int i2c_fd = -1;
static int pwm_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_pwm(int gpio, int frequency, int range, int clock);
int read_mpu6050(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int fd, float angle);
int log_data(FILE *fp, float pitch, float roll, int servo_position);
int send_data_to_server(float pitch, float roll, int servo_position);
void signal_handler(int sig);

// Helper function for exponential backoff
void delay_ms(int ms)
{
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000;
    nanosleep(&ts, NULL);
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize PWM
int init_pwm(int gpio, int frequency, int range, int clock)
{
    int fd = gpioCfgClock(clock, PI_DEFAULT_CLK_PERIPHERAL, 0); // Configure clock
    if (fd < 0) {
        fprintf(stderr, "Error configuring PWM clock: %d\n", fd);
        return -1;
    }

    gpioSetMode(gpio, PI_OUTPUT); // Set GPIO mode to output

    // Set PWM range and frequency
    gpioSetPWMrange(gpio, range);
    gpioSetPWMfrequency(gpio, frequency);

    return gpio;
}

// Read data from MPU6050
int read_mpu6050(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    uint8_t buffer[14];
    int retries = 3;

    while (retries > 0) {
        // Read accelerometer and gyroscope data
        if (read(fd, buffer, 14) != 14) {
            perror("Error reading MPU6050 data");
            retries--;
            delay_ms(10 * (3 - retries)); // Exponential backoff
            continue;
        }

        *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
        *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
        *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
        *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
        *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
        *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read MPU6050 data after multiple retries.\n");
    return -1; // Failure
}

// Calculate pitch and roll angles
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll)
{
    float accel_x_f = (float)accel_x;
    float accel_y_f = (float)accel_y;
    float accel_z_f = (float)accel_z;

    *roll = atan2(accel_y_f, accel_z_f) * 180 / M_PI;
    *pitch = atan2(-accel_x_f, sqrt(accel_y_f * accel_y_f + accel_z_f * accel_z_f)) * 180 / M_PI;
}

// Set servo angle using PWM
int set_servo_angle(int fd, float angle)
{
    // Map angle (0-180) to pulse width (SERVO_MIN_PULSE_WIDTH - SERVO_MAX_PULSE_WIDTH)
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (angle / 180.0) * SERVO_RANGE);

    // Calculate duty cycle
    int duty_cycle = pulse_width - SERVO_PWM_DUTY_CYCLE_OFFSET;

    // Set PWM duty cycle
    gpioPWM(SERVO_GPIO, duty_cycle);

    return 0;
}

// Log data to file
int log_data(FILE *fp, float pitch, float roll, int servo_position)
{
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Send data to server
int send_data_to_server(float pitch, float roll, int servo_position)
{
    int sockfd;
    struct sockaddr_in servaddr;
    char message[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    snprintf(message, sizeof(message), "Pitch: %.2f, Roll: %.2f, Servo: %d", pitch, roll, servo_position);

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Signal handler
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received: %d. Cleaning up...\n", sig);
    terminate = 1;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize PWM
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Pigpio initialisation failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    pwm_fd = init_pwm(SERVO_GPIO, SERVO_PWM_FREQUENCY, SERVO_PWM_RANGE, SERVO_PWM_CLOCK);
    if (pwm_fd < 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // MPU6050 initialization sequence
    uint8_t init_data[2];

    // Wake up the MPU6050 (clear sleep bit)
    init_data[0] = MPU6050_REG_PWR_MGMT_1;
    init_data[1] = 0x00;
    if (write(i2c_fd, init_data, 2) != 2) {
        perror("Error writing to MPU6050 PWR_MGMT_1");
        fclose(log_file);
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Set accelerometer range to +/- 2g
    init_data[0] = MPU6050_REG_ACCEL_CONFIG;
    init_data[1] = 0x00; // +/- 2g
    if (write(i2c_fd, init_data, 2) != 2) {
        perror("Error writing to MPU6050 ACCEL_CONFIG");
        fclose(log_file);
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    // Set gyroscope range to +/- 250 deg/s
    init_data[0] = MPU6050_REG_GYRO_CONFIG;
    init_data[1] = 0x00; // +/- 250 deg/s
    if (write(i2c_fd, init_data, 2) != 2) {
        perror("Error writing to MPU6050 GYRO_CONFIG");
        fclose(log_file);
        gpioTerminate();
        close(i2c_fd);
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_position;

    while (!terminate) {
        // Read sensor data
        if (read_mpu6050(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            calculate_pitch_roll(accel_x, accel_y, accel_z, &pitch, &roll);

            // Set servo angle
            servo_position = (int)((pitch + 90.0) / 180.0 * SERVO_PWM_DUTY_CYCLE_RANGE + SERVO_PWM_DUTY_CYCLE_CENTER);
            if (servo_position < SERVO_PWM_DUTY_CYCLE_OFFSET) servo_position = SERVO_PWM_DUTY_CYCLE_OFFSET;
            if (servo_position > SERVO_PWM_DUTY_CYCLE_OFFSET + SERVO_PWM_DUTY_CYCLE_RANGE) servo_position = SERVO_PWM_DUTY_CYCLE_OFFSET + SERVO_PWM_DUTY_CYCLE_RANGE;
            set_servo_angle(pwm_fd, (float)(servo_position - SERVO_PWM_DUTY_CYCLE_CENTER) / SERVO_PWM_DUTY_CYCLE_RANGE * 180.0 - 90.0);

            // Log data
            log_data(log_file, pitch, roll, servo_position);

            // Send data to server
            send_data_to_server(pitch, roll, servo_position);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying I2C initialization.\n");
            close(i2c_fd);
            i2c_fd = init_i2c(I2C_BUS, MPU6050_ADDR);
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break;
            }
        }

        delay_ms(100); // Delay for 100ms
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();
    close(i2c_fd);

    return 0;
}

