#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Define the PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define the transition duration (30 minutes in seconds)
#define TRANSITION_DURATION 1800

// Structure to hold schedule entry data
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
FILE *schedule_file = NULL;
int running = 1;

// Function prototypes
int read_schedule(schedule_entry_t *schedule, int max_entries);
void apply_schedule(schedule_entry_t *schedule, int num_entries);
void fade_relay(int relay_number, int on_off);
void signal_handler(int signal);

// Function to read the schedule from the file
int read_schedule(schedule_entry_t *schedule, int max_entries) {
    char line[256];
    int i = 0;

    // Open the schedule file for reading
    schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        return 0; // Indicate failure
    }

    // Read the file line by line
    while (fgets(line, sizeof(line), schedule_file) != NULL && i < max_entries) {
        // Parse the line into the schedule entry
        if (sscanf(line, "%d:%d:%d,%d,%d", &schedule[i].hour, &schedule[i].minute, &schedule[i].second, &schedule[i].relay_number, &schedule[i].on_off) == 5) {
            // Validate the schedule entry
            if (schedule[i].hour >= 0 && schedule[i].hour < 24 &&
                schedule[i].minute >= 0 && schedule[i].minute < 60 &&
                schedule[i].second >= 0 && schedule[i].second < 60 &&
                schedule[i].relay_number >= 1 && schedule[i].relay_number <= 4 &&
                schedule[i].on_off == 0 || schedule[i].on_off == 1) {
                i++;
            } else {
                fprintf(stderr, "Invalid schedule entry: %s", line);
            }
        } else {
            fprintf(stderr, "Invalid format in schedule file: %s", line);
        }
    }

    // Close the file
    fclose(schedule_file);
    schedule_file = NULL;

    return i; // Return the number of valid entries read
}

// Function to apply the schedule to the relays
void apply_schedule(schedule_entry_t *schedule, int num_entries) {
    time_t current_time;
    struct tm *time_info;
    int i;

    // Get the current time
    time(&current_time);
    time_info = localtime(&current_time);

    // Iterate through the schedule entries
    for (i = 0; i < num_entries; i++) {
        // Check if the current time matches the schedule entry
        if (time_info->tm_hour == schedule[i].hour &&
            time_info->tm_min == schedule[i].minute &&
            time_info->tm_sec == schedule[i].second) {
            // Apply the schedule entry to the corresponding relay
            fade_relay(schedule[i].relay_number, schedule[i].on_off);
        }
    }
}

// Function to fade the relay brightness
void fade_relay(int relay_number, int on_off) {
    int gpio_pin;
    int i;
    int duty_cycle;
    int increment;

    // Determine the GPIO pin for the relay
    switch (relay_number) {
        case 1:
            gpio_pin = RELAY1_PIN;
            break;
        case 2:
            gpio_pin = RELAY2_PIN;
            break;
        case 3:
            gpio_pin = RELAY3_PIN;
            break;
        case 4:
            gpio_pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    // Set the GPIO pin as an output
    gpioSetMode(gpio_pin, PI_OUTPUT);

    // Set the PWM frequency
    gpioSetPWMfrequency(gpio_pin, PWM_FREQUENCY);

    // Determine the increment value for the duty cycle
    increment = (on_off == 1) ? 1 : -1;

    // Smoothly fade the relay brightness
    for (i = 0; i <= 100; i += increment) {
        duty_cycle = i;
        gpioPWM(gpio_pin, duty_cycle);
        gpioDelay(TRANSITION_DURATION / 100); // Delay for 1/100th of the transition duration
    }

    // Set the relay to the desired state (on or off)
    if (on_off == 1) {
        gpioPWM(gpio_pin, 100); // Set to 100% duty cycle for full brightness
    } else {
        gpioPWM(gpio_pin, 0);  // Set to 0% duty cycle for off
    }
}

// Signal handler function
void signal_handler(int signal) {
    int i;

    printf("Caught signal %d, cleaning up...\n", signal);

    // Turn off all relays
    for (i = 0; i < 4; i++) {
        int gpio_pin;
        switch (i + 1) {
            case 1:
                gpio_pin = RELAY1_PIN;
                break;
            case 2:
                gpio_pin = RELAY2_PIN;
                break;
            case 3:
                gpio_pin = RELAY3_PIN;
                break;
            case 4:
                gpio_pin = RELAY4_PIN;
                break;
        }
        gpioPWM(gpio_pin, 0); // Turn off the relay
    }

    // Release GPIO resources
    gpioTerminate();

    // Close the schedule file if it's open
    if (schedule_file != NULL) {
        fclose(schedule_file);
    }

    running = 0; // Set running to 0 to exit the main loop
    exit(0);
}

int main() {
    schedule_entry_t schedule[100]; // Assuming a maximum of 100 schedule entries
    int num_entries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read the schedule from the file
        num_entries = read_schedule(schedule, 100);

        // Apply the schedule to the relays
        apply_schedule(schedule, num_entries);

        // Wait for 1 second
        gpioDelay(1000); // Delay for 1 second (1000 milliseconds)
    }

    return 0;
}

