#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 30.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define TIMEOUT_US 50000       // 50ms timeout

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
double measureDistance();
double mapDistanceToFrequency(double distance);
void setBuzzerFrequency(double frequency);
void signalHandler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) // Rising edge
    {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that a rising edge has been received
    }
    else if (level == 0) // Falling edge
    {
        if (echo_received) {
            echo_end_tick = tick;
            echo_received = 0; // Reset the flag
        }
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microsecond trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
double measureDistance()
{
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    triggerSensor();

    // Wait for echo to be received or timeout
    int start_tick = gpioTick();
    while (!echo_received) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for echo.\n");
            return -1.0; // Indicate timeout error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Calculate pulse width
    int pulse_width = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    double distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;

    return distance;
}

// Function to map distance to frequency
double mapDistanceToFrequency(double distance)
{
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE)
    {
        distance = MIN_DISTANCE;
    }
    else if (distance > MAX_DISTANCE)
    {
        distance = MAX_DISTANCE;
    }

    // Linearly map distance to frequency
    double frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set the buzzer frequency using PWM
void setBuzzerFrequency(double frequency)
{
    // Calculate PWM range and duty cycle
    int range = 1000; // Adjust as needed
    int duty_cycle = (int)((frequency / MAX_FREQUENCY) * range);

    // Set PWM frequency
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);

    // Set PWM range
    gpioSetPWMrange(BUZZER_PIN, range);

    // Set PWM duty cycle
    gpioPWM(BUZZER_PIN, duty_cycle);
}

// Signal handler for Ctrl+C
void signalHandler(int signal)
{
    printf("Ctrl+C pressed. Exiting...\n");

    // Silence the buzzer
    gpioPWM(BUZZER_PIN, 0);

    // De-initialise pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (1)
    {
        // Measure distance
        double distance = measureDistance();

        if (distance > 0) // Check for valid distance reading
        {
            // Map distance to frequency
            double frequency = mapDistanceToFrequency(distance);

            // Set buzzer frequency
            setBuzzerFrequency(frequency);

            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        }
        else
        {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        }

        // Delay to control loop frequency
        gpioDelay(20); // 50 Hz loop
    }

    return 0;
}

