#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050
        if (write(i2c_fd, "\x00", 1) != 1) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        return 0; // Initialization successful
    }
    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    unsigned char buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }

    *gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_to_dps(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    *gyro_x_dps = (float)gyro_x_raw / GYRO_SCALE;
    *gyro_y_dps = (float)gyro_y_raw / GYRO_SCALE;
    *gyro_z_dps = (float)gyro_z_raw / GYRO_SCALE;
}

// Function to log data to a file
int log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, gyro_x_dps, gyro_y_dps, gyro_z_dps);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x_raw, &gyro_y_raw, &gyro_z_raw) == 0) {
            // Convert to degrees per second
            convert_to_dps(gyro_x_raw, gyro_y_raw, gyro_z_raw, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Log data
            if (log_data(gyro_x_dps, gyro_y_dps, gyro_z_dps) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying initialization.\n");
            init_mpu6050(); // Attempt to re-initialize
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

