#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody parameters
#define MELODY_LENGTH 10

// Define melody lookup table
const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523, 587, 659};

// Global variables
volatile int playback_active = 0;
volatile int stop_requested = 0;

// Function prototypes
void button_callback(int gpio, int level, uint32_t tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Callback function for button press
void button_callback(int gpio, int level, uint32_t tick, void *user_data)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == PI_LOW) // Button pressed (active low)
    {
        if (current_tick - last_tick > 50000) // Debounce: 50ms
        {
            last_tick = current_tick;

            if (playback_active)
            {
                stop_requested = 1; // Request melody stop
            }
            else
            {
                play_melody();
            }
        }
    }
}

// Function to play the melody
void play_melody()
{
    playback_active = 1;
    stop_requested = 0; // Reset stop request

    for (int i = 0; i < MELODY_LENGTH; i++)
    {
        if (stop_requested)
        {
            gpioHardwarePWM(BUZZER_PIN, 0, 500000); // Stop PWM
            playback_active = 0;
            return;
        }

        gpioHardwarePWM(BUZZER_PIN, 500000, melody[i]); // Play tone
        gpioDelay(100000); // Delay for tone duration (100ms)
    }

    playback_active = 0;
    gpioHardwarePWM(BUZZER_PIN, 0, 500000); // Stop PWM after melody
}

// Function to stop the melody
void stop_melody()
{
    gpioHardwarePWM(BUZZER_PIN, 0, 500000); // Stop PWM
    playback_active = 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody(); // Stop melody if playing
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable pull-up resistor on button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_callback, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        gpioDelay(10000); // Check every 10ms
    }

    return 0;
}

