#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Structure to hold the last WINDOW_SIZE events
typedef struct {
    int events[WINDOW_SIZE];
    int head;
} EventWindow;

// Function prototypes
int init_gpio(void);
int read_sensor(void);
char *get_iso8601_timestamp(void);
int log_event(const char *timestamp, int value);
void check_earthquake_alert(EventWindow *window, int value);
void signal_handler(int sig);
void cleanup(void);

// Initialize GPIO line
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Read the sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value\n");
        return -1;
    }
    return value;
}

// Get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log the event to the file
int log_event(const char *timestamp, int value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Check for earthquake alert based on the last WINDOW_SIZE events
void check_earthquake_alert(EventWindow *window, int value) {
    window->events[window->head] = value;
    window->head = (window->head + 1) % WINDOW_SIZE;

    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window->events[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            printf("EARTHQUAKE ALERT: %s\n", timestamp);
            free(timestamp);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize event window
    EventWindow window = {{0}, 0};

    // Main loop
    while (!terminate) {
        int value = read_sensor();
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value\n");
            break;
        }

        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            if (log_event(timestamp, value) < 0) {
                fprintf(stderr, "Error logging event\n");
            }
            free(timestamp);
        }

        check_earthquake_alert(&window, value);

        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = timeout_ms * 1000000; // Convert milliseconds to nanoseconds
        if (gpiod_line_event_wait(line, &ts) < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

