        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *z = (int16_t)((buffer[3] << 8) | buffer[2]);
    *y = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetometer X value
float calibrate_mag_x(int16_t raw_x) {
    return (float)raw_x - MAG_X_OFFSET;
}

// Calibrate magnetometer Y value
float calibrate_mag_y(int16_t raw_y) {
    return (float)raw_y - MAG_Y_OFFSET;
}

// Calibrate magnetometer Z value
float calibrate_mag_z(int16_t raw_z) {
    return (float)raw_z - MAG_Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

// Map heading to compass direction
const char *map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading >= 22.5 && heading < 67.5) return "NE";
    if (heading >= 67.5 && heading < 112.5) return "E";
    if (heading >= 112.5 && heading < 157.5) return "SE";
    if (heading >= 157.5 && heading < 202.5) return "S";
    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    return "NW";
}

// Log data to CSV file
int log_data_to_csv(FILE *fp, float x, float y, float z, float heading, const char *direction) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, x, y, z, heading, direction) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", I2C_DEVICE);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MAGNETOMETER_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address\n");
        close(i2c_fd);
        return 1;
    }

    // Configure magnetometer (Continuous conversion mode, 15 Hz ODR)
    if (i2c_write_reg(i2c_fd, MR_REG_M, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, CRA_REG_M, 0x14) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a+");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", CSV_FILE);
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    fseek(csv_file, 0, SEEK_END);

    // Main loop
    while (!terminate) {
        int16_t raw_x, raw_y, raw_z;
        float x, y, z, heading;
        const char *direction;

        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate magnetometer data
            x = calibrate_mag_x(raw_x);
            y = calibrate_mag_y(raw_y);
            z = calibrate_mag_z(raw_z);

            // Calculate heading
            heading = calculate_heading(x, y);

            // Map heading to direction
            direction = map_heading_to_direction(heading);

            // Log data to CSV file
            if (log_data_to_csv(csv_file, x, y, z, heading, direction) != 0) {
                fprintf(stderr, "Error logging data, skipping sample\n");
            }

            // Print data to console
            printf("Calibrated X: %.2f, Calibrated Y: %.2f, Calibrated Z: %.2f, Heading: %.2f, Direction: %s\n", x, y, z, heading, direction);
        } else {
            fprintf(stderr, "Error reading magnetometer data, skipping sample\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    if (csv_file != NULL) {
        fclose(csv_file);
    }

    return 0;
}

