#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17

static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write JSON object to relay_log.json
int write_json_to_file(const char* timestamp, const char* relay_state_str) {
    FILE *fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        perror("Error opening relay_log.json");
        return -1;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state_str);
    fclose(fp);
    return 0;
}

// Interrupt service routine (ISR) for touch sensor
void touch_isr(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();

    if (level == 0) { // Falling edge detected (touch released)
        if (current_time - last_touch_time > 200000) { // Debounce: 200ms
            relay_state = !relay_state; // Toggle relay state
            gpioWrite(RELAY_PIN, relay_state);

            char* timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                const char* relay_state_str = (relay_state == 1) ? "ON" : "OFF";
                if (write_json_to_file(timestamp, relay_state_str) != 0) {
                    fprintf(stderr, "Error writing to log file.\n");
                }
                free(timestamp);
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }

            last_touch_time = current_time;
        }
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF

    char* timestamp = get_iso8601_timestamp();
    if (timestamp != NULL) {
        write_json_to_file(timestamp, "OFF");
        free(timestamp);
    } else {
        fprintf(stderr, "Error getting timestamp for final log entry.\n");
    }

    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on touch pin
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Set up interrupt service routine for touch sensor
    if (gpioSetISRFuncEx(TOUCH_PIN, FALLING_EDGE, 0, touch_isr, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Relay control program running. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

