#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio();
int read_soil_moisture();
int activate_relay(int relay_number, int duration_seconds);
int log_event(int relay_number, int moisture_level);
void cleanup();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Setup GPIO lines
int setup_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIOCHIP);
        return -1;
    }

    // Get the lines for the relays
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        cleanup();
        return -1;
    }

    // Request the lines as outputs with an initial value of 1 (inactive)
    ret = gpiod_line_request_output(relay1_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for relay 1: %d\n", ret);
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(relay2_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for relay 2: %d\n", ret);
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(relay3_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for relay 3: %d\n", ret);
        cleanup();
        return -1;
    }

    ret = gpiod_line_request_output(relay4_line, "irrigation", 1);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for relay 4: %d\n", ret);
        cleanup();
        return -1;
    }

    return 0;
}

// Read soil moisture value
int read_soil_moisture() {
    return rand() % 101; // Returns a value between 0 and 100
}

// Activate a relay for a specified duration
int activate_relay(int relay_number, int duration_seconds) {
    struct gpiod_line *line;
    int ret;

    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return -1;
    }

    // Set the line value to 0 to activate the relay (active-low)
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value for relay %d: %d\n", relay_number, ret);
        return -1;
    }

    // Wait for the specified duration
    sleep(duration_seconds);

    // Set the line value back to 1 to deactivate the relay
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value for relay %d: %d\n", relay_number, ret);
        return -1;
    }

    return 0;
}

// Log an event to the log file
int log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    // Write the log entry
    fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);

    // Flush the log file
    fflush(log_file);

    // Close the log file
    fclose(log_file);

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    int ret;

    // Deactivate all relays
    if (relay1_line) {
        ret = gpiod_line_set_value(relay1_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating relay 1: %d\n", ret);
        }
    }
    if (relay2_line) {
        ret = gpiod_line_set_value(relay2_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating relay 2: %d\n", ret);
        }
    }
    if (relay3_line) {
        ret = gpiod_line_set_value(relay3_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating relay 3: %d\n", ret);
        }
    }
    if (relay4_line) {
        ret = gpiod_line_set_value(relay4_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating relay 4: %d\n", ret);
        }
    }

    // Release the lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Close the chip
    if (chip) gpiod_chip_close(chip);

    // Close the log file
    if (log_file) fclose(log_file);
}

int main() {
    int moisture_level;

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handling for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read soil moisture
        moisture_level = read_soil_moisture();

        // Check if moisture is below threshold
        if (moisture_level < 30) {
            // Activate relays sequentially
            if (activate_relay(1, 5) < 0) break;
            sleep(1);
            if (activate_relay(2, 5) < 0) break;
            sleep(1);
            if (activate_relay(3, 5) < 0) break;
            sleep(1);
            if (activate_relay(4, 5) < 0) break;
        }

        // Log the event
        if (log_event(0, moisture_level) < 0) {
            fprintf(stderr, "Logging failed\n");
        }

        // Wait for 10 seconds
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

