    fflush(log_file);

    // Close the log file
    fclose(log_file);

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    int ret;

    // Deactivate all relays
    if (relay1_line) {
        ret = gpiod_line_set_value(relay1_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating relay 1: %d\n", ret);
        }
    }
    if (relay2_line) {
        ret = gpiod_line_set_value(relay2_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating relay 2: %d\n", ret);
        }
    }
    if (relay3_line) {
        ret = gpiod_line_set_value(relay3_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating relay 3: %d\n", ret);
        }
    }
    if (relay4_line) {
        ret = gpiod_line_set_value(relay4_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating relay 4: %d\n", ret);
        }
    }

    // Release the lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Close the chip
    if (chip) gpiod_chip_close(chip);

    // Close the log file
    if (log_file) fclose(log_file);
}

int main() {
    int moisture_level;

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handling for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read soil moisture
        moisture_level = read_soil_moisture();

        // Check if moisture is below threshold
        if (moisture_level < 30) {
            // Activate relays sequentially
            if (activate_relay(1, 5) < 0) break;
            sleep(1);
            if (activate_relay(2, 5) < 0) break;
            sleep(1);
            if (activate_relay(3, 5) < 0) break;
            sleep(1);
            if (activate_relay(4, 5) < 0) break;
        }

        // Log the event
        if (log_event(0, moisture_level) < 0) {
            fprintf(stderr, "Logging failed\n");
        }

        // Wait for 10 seconds
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

