#define MOISTURE_THRESHOLD_HIGH 50

// Define servo pulse widths
#define VALVE_CLOSED 500
#define VALVE_OPEN 1500
#define NOZZLE_ANGLE_0 500
#define NOZZLE_ANGLE_45 1000
#define NOZZLE_ANGLE_90 1500
#define NOZZLE_ANGLE_135 2000
#define NOZZLE_ANGLE_180 2500

// Define watering cycle parameters
#define WATERING_DURATION 5 // seconds
#define STEP_DELAY 2 // seconds

// Global volatile signal flag
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, terminating...");
    terminate = 1;
}

// Function to set servo pulse width with retry
int set_servo_pulse(int gpio, int pulse_width)
{
    int retries = 3;
    int result;

    while (retries > 0) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse width (GPIO %d, pulse width %d): %d. Retrying...\n", gpio, pulse_width, result);
            gpioDelay(100); // 100 ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to set servo pulse width (GPIO %d, pulse width %d) after multiple retries.\n", gpio, pulse_width);
    return -1; // Failure
}

