    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(NOZZLE_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read moisture sensor
        int moisture_level = read_moisture_sensor();
        printf("Moisture level: %d\n", moisture_level);

        // Check moisture level and control watering
        if (moisture_level < MOISTURE_THRESHOLD_LOW) {
            // Open valve
            if (set_servo_pulse(VALVE_GPIO, VALVE_OPEN) != 0) {
                fprintf(stderr, "Failed to open valve.\n");
                continue; // Continue to the next iteration
            }

            // Sweep nozzle
            int nozzle_angles[] = {NOZZLE_ANGLE_0, NOZZLE_ANGLE_45, NOZZLE_ANGLE_90, NOZZLE_ANGLE_135, NOZZLE_ANGLE_180};
            int num_angles = sizeof(nozzle_angles) / sizeof(nozzle_angles[0]);

