                if (set_servo_pulse(NOZZLE_GPIO, nozzle_angles[i]) != 0) {
                    fprintf(stderr, "Failed to set nozzle angle to %d.\n", nozzle_angles[i]);
                    continue; // Continue to the next angle
                }
                gpioDelay(STEP_DELAY * 1000); // Delay for watering duration
            }

