            gpioDelay(WATERING_DURATION * 1000);

            // Close valve
            if (set_servo_pulse(VALVE_GPIO, VALVE_CLOSED) != 0) {
                fprintf(stderr, "Failed to close valve.\n");
            }
        } else if (moisture_level > MOISTURE_THRESHOLD_HIGH) {
            printf("Moisture level above threshold, skipping watering.\n");
        } else {
            printf("Moisture level within acceptable range, no watering needed.\n");
        }

        // Wait before next cycle
        gpioDelay(5000); // 5 seconds
    }

    // Stop servos and terminate pigpio
    set_servo_pulse(VALVE_GPIO, 0);
    set_servo_pulse(NOZZLE_GPIO, 0);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

