#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor
#define GYRO_SCALE_FACTOR 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Sampling rate (Hz)
#define SAMPLING_RATE 10

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050
        if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        return 0; // Initialization successful
    }
    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    uint8_t buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (read(i2c_fd, buffer, 6) != 6) {
            fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert raw data to degrees per second
        data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
        data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
        data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read gyro data after multiple retries.\n");
    return -1; // Failure
}

// Function to log data to a file
int log_data(struct timespec ts, gyro_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    // Convert raw data to degrees per second
    double x_dps = (double)data.x / GYRO_SCALE_FACTOR;
    double y_dps = (double)data.y / GYRO_SCALE_FACTOR;
    double z_dps = (double)data.z / GYRO_SCALE_FACTOR;

    fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec, x_dps, y_dps, z_dps);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    struct timespec ts;
    gyro_data_t gyro_data;
    while (!terminate) {
        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            break;
        }

        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Log data
            if (log_data(ts, gyro_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data.\n");
        }

        // Sleep for 100ms (10 Hz sampling rate)
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

