#define IN2 17
#define IN3 27
#define IN4 22

// Define GPIO pins for the buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define the number of steps for a quarter turn
#define STEPS_PER_QUARTER_TURN 512

// Define the inter-step delay in milliseconds
#define DELAY_MS 3

// Define the debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 200

// Define the locking duration in seconds
#define LOCKING_DURATION_SEC 5

// Define the unlocking duration in seconds
#define UNLOCKING_DURATION_SEC 5

// Define the locking and unlocking durations in milliseconds
#define LOCKING_DURATION_MS (LOCKING_DURATION_SEC * 1000)
#define UNLOCKING_DURATION_MS (UNLOCKING_DURATION_SEC * 1000)

// Define the locking and unlocking steps
#define LOCKING_STEPS (STEPS_PER_QUARTER_TURN / 4)
#define UNLOCKING_STEPS (STEPS_PER_QUARTER_TURN / 4)

// Define the locking and unlocking directions
#define LOCKING_DIRECTION 1 // Clockwise
#define UNLOCKING_DIRECTION -1 // Counter-clockwise

// Define the locking and unlocking delays
#define LOCKING_DELAY_MS (LOCKING_DURATION_MS / STEPS_PER_QUARTER_TURN)
#define UNLOCKING_DELAY_MS (UNLOCKING_DURATION_MS / STEPS_PER_QUARTER_TURN)

// Define the locking and unlocking steps
#define LOCKING_STEPS_PER_DELAY (LOCKING_DURATION_MS / LOCKING_DELAY_MS)
#define UNLOCKING_STEPS_PER_DELAY (UNLOCKING_DURATION_MS / UNLOCKING_DELAY_MS)

