#define LOCKING_STEPS_PER_SEC (STEPS_PER_QUARTER_TURN / 4 / LOCKING_DURATION_SEC)
#define UNLOCKING_STEPS_PER_SEC (STEPS_PER_QUARTER_TURN / 4 / UNLOCKING_DURATION_SEC)

