#define UNLOCKING_STEPS_PER_MS (UNLOCKING_STEPS_PER_SEC / 1000.0)

// Define the locking and unlocking steps
#define LOCKING_STEPS_PER_DELAY (LOCKING_DURATION_MS / LOCKING_DELAY_MS)
#define UNLOCKING_STEPS_PER_DELAY (UNLOCKING_DURATION_MS / UNLOCKING_DELAY_MS)

// Define the locking and unlocking steps
#define LOCKING_STEPS_PER_DELAY (LOCKING_DURATION_MS / LOCKING_DELAY_MS)
#define UNLOCKING_STEPS_PER_DELAY (UNLOCKING_DURATION_MS / UNLOCKING_DELAY_MS)

