#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TIMEOUT_DURATION 50 // milliseconds
#define MIN_GUARD_TIME 60 // milliseconds

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;
static struct timespec last_measurement_time;

// Function prototypes
int init_gpio();
int trigger_sensor();
int read_echo();
double calculate_distance(long long duration_us);
int log_distance(double distance);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO lines
int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "ultrasonic_sensor", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "ultrasonic_sensor") < 0) {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
int trigger_sensor() {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return -1;
    }
    usleep(TRIGGER_PULSE_DURATION);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
        return -1;
    }
    return 0;
}

// Read the echo pulse width
int read_echo() {
    struct timespec start, end;
    int timeout = 0;

    // Wait for rising edge
    while (gpiod_line_get_value(echo_line) == 0 && !timeout) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        timeout = 1;
    }

    if (timeout) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }

    // Wait for falling edge
    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1 && !timeout) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        timeout = 1;
    }

    if (timeout) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }

    // Calculate pulse width in microseconds
