#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm
#define POLL_INTERVAL 100 // ms

// VL53L1X register addresses
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_RANGING_MODE 0x0080
#define VL53L1X_REG_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Set ranging mode to continuous
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X set ranging mode failed\n");
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(uint16_t *distance) {
    int status;
    uint8_t data[2];

    // Check interrupt status
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X read interrupt status failed\n");
        return -1;
    }

    if (!(status & 0x04)) {
        // No data ready
        return -1;
    }

    // Read distance data
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error: VL53L1X read distance failed\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Relay control function
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // Activate relay (open door)
    } else {
        gpioWrite(GPIO_RELAY, 0); // Deactivate relay (close door)
    }
}

int main() {
    uint16_t distance;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        result = vl53l1x_read_distance(&distance);
        if (result == 0) {
            printf("Distance: %d mm\n", distance);
            control_relay(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(POLL_INTERVAL);
    }

    // Cleanup
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

