#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

// Define watering cycle duration (seconds)
#define WATERING_DURATION 5

// Define watering cycle interval (seconds)
#define WATERING_INTERVAL 86400

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void activate_relay(int gpio_pin);
void deactivate_relay(int gpio_pin);
void log_watering_cycle(int gpio_pin);
void cleanup(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int i;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Configure GPIO lines as outputs
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int pins[] = {GPIO17, GPIO18, GPIO27, GPIO22};

    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            cleanup();
            return -1;
        }

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line");
            cleanup();
            return -1;
        }

        // Set initial state to HIGH (inactive)
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            perror("Error setting GPIO line value");
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Activate a relay (set GPIO line LOW)
void activate_relay(int gpio_pin) {
    int i;
    for (i = 0; i < 4; i++) {
        if (lines[i]->num == gpio_pin) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("Error activating relay");
            }
            break;
        }
    }
}

// Deactivate a relay (set GPIO line HIGH)
void deactivate_relay(int gpio_pin) {
    int i;
    for (i = 0; i < 4; i++) {
        if (lines[i]->num == gpio_pin) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("Error deactivating relay");
            }
            break;
        }
    }
}

// Log watering cycle start time
void log_watering_cycle(int gpio_pin) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    // Write log entry
    fprintf(fp, "%s - Relay on GPIO%d activated\n", timestamp, gpio_pin);

    // Close log file
    fclose(fp);
}

// Cleanup GPIO lines and close chip
void cleanup(void) {
    int i;

    // Deactivate all relays
    for (i = 0; i < 4; i++) {
        deactivate_relay(lines[i]->num);
    }

    // Release GPIO lines
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int i;
    time_t start_time, current_time;
    int gpio_pins[] = {GPIO17, GPIO18, GPIO27, GPIO22};

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        time(&start_time);

        for (i = 0; i < 4; i++) {
            // Activate relay
            activate_relay(gpio_pins[i]);

            // Log watering cycle
            log_watering_cycle(gpio_pins[i]);

            // Wait for watering duration
            sleep(WATERING_DURATION);

            // Deactivate relay
            deactivate_relay(gpio_pins[i]);

            // Wait for the next watering cycle
            sleep(WATERING_INTERVAL - WATERING_DURATION);
        }

        // Check if the watering cycle has been completed for 24 hours
        time(&current_time);
        if (difftime(current_time, start_time) >= WATERING_INTERVAL) {
            time(&start_time); // Reset the start time
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    return 0;
}

