#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define the PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define the sunrise duration (in seconds)
#define SUNRISE_DURATION 1800 // 30 minutes

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_relay_state(int gpio, int state);
void set_pwm_duty_cycle(int gpio, int duty_cycle);
void simulate_sunrise();
void log_event(const char *message);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received termination signal. Cleaning up and exiting...");
        cleanup();
        exit(0);
    }
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    // Set initial PWM duty cycle to 0 (relay off)
    gpioPWM(RELAY1_GPIO, 0);
    gpioPWM(RELAY2_GPIO, 0);
    gpioPWM(RELAY3_GPIO, 0);
    gpioPWM(RELAY4_GPIO, 0);

    log_event("GPIO initialisation successful");
    return 0;
}

// Function to set the state of a relay (1 for ON, 0 for OFF)
void set_relay_state(int gpio, int state) {
    gpioPWM(gpio, state ? 255 : 0); // Set PWM duty cycle to 255 for ON, 0 for OFF
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to simulate the sunrise effect
void simulate_sunrise() {
    time_t start_time = time(NULL);
    int current_duty_cycle = 0;

    while (program_running && (time(NULL) - start_time) < SUNRISE_DURATION) {
        // Increment the duty cycle
        current_duty_cycle = (current_duty_cycle + 1) % 256;

        // Set the PWM duty cycle for all relays
        set_pwm_duty_cycle(RELAY1_GPIO, current_duty_cycle);
        set_pwm_duty_cycle(RELAY2_GPIO, current_duty_cycle);
        set_pwm_duty_cycle(RELAY3_GPIO, current_duty_cycle);
        set_pwm_duty_cycle(RELAY4_GPIO, current_duty_cycle);

        // Log the current duty cycle
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Sunrise: Duty cycle set to %d", current_duty_cycle);
        log_event(log_message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function takes milliseconds
    }

    if (!program_running) {
        log_event("Sunrise simulation interrupted by signal.");
    } else {
        log_event("Sunrise simulation complete.");
    }
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to clean up GPIO resources before exiting
void cleanup() {
    // Turn off all relays
    set_relay_state(RELAY1_GPIO, 0);
    set_relay_state(RELAY2_GPIO, 0);
    set_relay_state(RELAY3_GPIO, 0);
    set_relay_state(RELAY4_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    log_event("GPIO resources released");
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Simulate the sunrise effect
    simulate_sunrise();

    // Clean up GPIO resources before exiting
    cleanup();

    return 0;
}

