    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Simulate the sunrise effect
    simulate_sunrise();

    // Clean up GPIO resources before exiting
    cleanup();

    return 0;
}

