#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define WHO_AM_I 0x75

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to store gyroscope data and timestamp
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    float x, y, z;
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(x, y, z);

            // Check threshold and control LED
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        // Delay for 50 ms (20 Hz sampling rate)
        gpioDelay(50000); // 50000 microseconds = 50 milliseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor ID
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%x\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0) < 0) {
        fprintf(stderr, "Failed to write to SMPLRT_DIV register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Set gyroscope full-scale range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Failed to write to GYRO_CONFIG register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read gyro data: %d\n", result);
        return -1;
    }

    // Convert to signed 16-bit values
    int16_t x_raw = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y_raw = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z_raw = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees/second (assuming sensitivity of 131 LSB/deg/s)
    *x = (float)x_raw / 131.0f;
    *y = (float)y_raw / 131.0f;
    *z = (float)z_raw / 131.0f;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    gyro_buffer[buffer_index].timestamp = ts;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check threshold and control LED
void check_threshold(float x, float y, float z) {
    float abs_x = fabs(x);
    float abs_y = fabs(y);
    float abs_z = fabs(z);

    if (abs_x > 250.0f || abs_y > 250.0f || abs_z > 250.0f) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

