#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define GYRO_SENSITIVITY 131.0f // degrees/sec per LSB for ±250 dps
#define GYRO_X_REG 0x43
#define GYRO_Y_REG 0x44
#define GYRO_Z_REG 0x45
#define GYRO_DATA_LENGTH 6
#define LOG_FILE "gyro_log.txt"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_NS 10000000 // 10 ms

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gyro_read_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_data);
int log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
int gpio_init(void);
void gpio_cleanup(void);
void spi_cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure max speed Hz
    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting max speed Hz: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Gyroscope data reading function
int gyro_read_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[GYRO_DATA_LENGTH] = {GYRO_X_REG, 0, 0, GYRO_Y_REG, 0, 0, GYRO_Z_REG, 0, 0};
    uint8_t rx_buf[GYRO_DATA_LENGTH];

    if (spi_transfer(tx_buf, rx_buf, GYRO_DATA_LENGTH) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    *y = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
    *z = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);

    return 0;
}

// Data conversion to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SENSITIVITY;
}

// Logging function
int log_data(float x_rate, float y_rate, float z_rate) {
    struct timespec ts;
    char timestamp[30];

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "gyro_logger", 0) != 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
void gpio_cleanup(void) {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 1); // Set high
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// SPI cleanup function
void spi_cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        spi_cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpio_cleanup();
        spi_cleanup();
        return 1;
    }

    int16_t raw_x, raw_y, raw_z;
    float x_rate, y_rate, z_rate;
    int retry;

    fprintf(stderr, "Starting gyroscope data logging...\n");

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (gyro_read_data(&raw_x, &raw_y, &raw_z) == 0) {
                x_rate = convert_to_dps(raw_x);
                y_rate = convert_to_dps(raw_y);
                z_rate = convert_to_dps(raw_z);

                if (log_data(x_rate, y_rate, z_rate) != 0) {
                    fprintf(stderr, "Error logging data, retrying...\n");
                } else {
                    break; // Exit retry loop on success
                }
            } else {
                fprintf(stderr, "Gyro read failed, retrying...\n");
            }
            retry++;
            usleep(10000); // Wait 10ms before retrying
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Gyro read failed after %d retries. Skipping.\n", RETRY_COUNT);
        }

        usleep(SAMPLE_INTERVAL_NS); // Sample every 10 ms
    }

    // Cleanup
    fprintf(stderr, "Cleaning up resources...\n");
    fclose(log_file);
    gpio_cleanup();
    spi_cleanup();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

