#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0
#define CS_GPIO 8
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define GYRO_SENSITIVITY 131.0f
#define GYRO_RANGE 200.0f
#define LED_ON_TIME_MS 500

// MPU-6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Data Structure for Gyroscope Readings
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular Buffer
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init();
int spi_transfer(uint8_t *data, int len);
int mpu6050_init();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void print_buffer();
void signal_handler(int sig);
void cleanup();

// SPI Initialisation
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(uint8_t *data, int len) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "mpu6050_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(cs_line, &config, 0) < 0) {
        perror("Error requesting CS line");
        return -1;
    }

    if (write(spi_fd, data, len) != len) {
        perror("Error writing to SPI device");
        gpiod_line_release(cs_line);
        return -1;
    }

    gpiod_line_release(cs_line);
    return 0;
}

// MPU-6050 Initialisation
int mpu6050_init() {
    uint8_t data[2];

    // Wake up the MPU-6050 (clear sleep bit)
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (spi_transfer(data, 2) < 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        return -1;
    }

    return 0;
}

// Read Gyroscope Data
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t data[7];
    int16_t raw_x, raw_y, raw_z;

    // Read X, Y, and Z axis data
    data[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes, auto-increment
    memset(data + 1, 0, 6); // Dummy data for reading 6 bytes

    if (spi_transfer(data, 7) < 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((data[1] << 8) | data[2]);
    raw_y = (int16_t)((data[3] << 8) | data[4]);
    raw_z = (int16_t)((data[5] << 8) | data[6]);

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add Data to Circular Buffer
void add_to_buffer(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    gyro_buffer.buffer[gyro_buffer.head].timestamp = ts;
    gyro_buffer.buffer[gyro_buffer.head].x = x;
    gyro_buffer.buffer[gyro_buffer.head].y = y;
    gyro_buffer.buffer[gyro_buffer.head].z = z;

    gyro_buffer.head = (gyro_buffer.head + 1) % BUFFER_SIZE;
    if (gyro_buffer.count < BUFFER_SIZE) {
        gyro_buffer.count++;
    }
}

// Print Circular Buffer
void print_buffer() {
    int i, index;
    for (i = 0; i < gyro_buffer.count; i++) {
        index = (gyro_buffer.head - gyro_buffer.count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n",
               gyro_buffer.buffer[index].timestamp.tv_sec,
               gyro_buffer.buffer[index].timestamp.tv_nsec,
               gyro_buffer.buffer[index].x,
               gyro_buffer.buffer[index].y,
               gyro_buffer.buffer[index].z);
    }
}

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        terminate = 1;
    }
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");

    // Disable LED
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize Circular Buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_GPIO);
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);

    if (!cs_line || !led_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init() < 0) {
        cleanup();
        return 1;
    }

    float x, y, z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10ms

    printf("Monitoring gyroscope data...\n");

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to buffer
            add_to_buffer(x, y, z);

            // Check for anomalies
            if (fabs(x) > GYRO_RANGE || fabs(y) > GYRO_RANGE || fabs(z) > GYRO_RANGE) {
                // Blink LED
                gpiod_line_set_value(led_line, 1);
                nanosleep(&(struct timespec){0, LED_ON_TIME_MS * 1000000}, NULL);
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Print buffer before exiting
    print_buffer();

    // Cleanup and exit
    cleanup();
    return 0;
}

