#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
int control_led(struct gpiod_line *line, uint16_t proximity);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register select) failed");
            retries--;
            usleep(10000); // 10 ms delay
            continue;
        }
        if (read(fd, data, len) != len) {
            perror("I2C read failed");
            retries--;
            usleep(10000); // 10 ms delay
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    int retries = 3;
    while (retries > 0) {
        if (write(fd, buf, 2) != 2) {
            perror("I2C write failed");
            retries--;
            usleep(10000); // 10 ms delay
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// Read sensor data
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t ambient_data[2];
    uint8_t proximity_data[2];

    if (i2c_read_reg(fd, AMBIENT_LIGHT_REG, ambient_data, 2) != 0) {
        fprintf(stderr, "Failed to read ambient light data.\n");
        return -1;
    }
    if (i2c_read_reg(fd, PROXIMITY_REG, proximity_data, 2) != 0) {
        fprintf(stderr, "Failed to read proximity data.\n");
        return -1;
    }

    *ambient_light = (uint16_t)((ambient_data[1] << 8) | ambient_data[0]);
    *proximity = (uint16_t)((proximity_data[1] << 8) | proximity_data[0]);

    return 0;
}

// Log data to file
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Control LED based on proximity
int control_led(struct gpiod_line *line, uint16_t proximity) {
    int ret = gpiod_line_set_value(line, (proximity > 100) ? 1 : 0);
    if (ret < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "biometric_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    uint16_t ambient_light, proximity;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // 100 ms

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            control_led(gpio_line, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

