#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define alert duration in seconds
#define ALERT_DURATION 2

// Define seismic event duration in milliseconds
#define SEISMIC_EVENT_DURATION 500

// Global variables
FILE *log_file = NULL;
volatile int sensor1_state = 1; // Initialize to HIGH (no tilt)
volatile int sensor2_state = 1;
volatile unsigned long last_event_time = 0;

// Function prototypes
int initialize_gpio();
void log_event(const char *message);
void sensor_callback(int gpio, int level, unsigned int tick, void *user_data);
void trigger_alert();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int pin;
    volatile int *state;
} sensor_data_t;

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, unsigned int tick, void *user_data) {
    sensor_callback(gpio, level, tick, user_data);
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, unsigned int tick, void *user_data) {
    sensor_callback(gpio, level, tick, user_data);
}

// Generic sensor callback function
void sensor_callback(int gpio, int level, unsigned int tick, void *user_data) {
    sensor_data_t *sensor_data = (sensor_data_t *)user_data;
    *(sensor_data->state) = level;

    if (level == 1) { // Rising edge
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        if (*(sensor_data->state) == 1) {
            if (sensor1_state == 1 && sensor2_state == 1) {
                unsigned long current_time = gpioTick();
                if (current_time - last_event_time > (SEISMIC_EVENT_DURATION * 1000)) {
                    trigger_alert();
                    last_event_time = current_time;
                }
            }
        }
    }
}

// Function to trigger the alert
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
    log_event("Seismic event detected!");
    gpioDelay(ALERT_DURATION * 1000000); // Wait for alert duration
    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to log events to a file
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, message);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable callbacks
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);

    // Set alert pin LOW
    gpioWrite(ALERT_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up sensor data
    sensor_data_t sensor1_data = {SENSOR_1_PIN, &sensor1_state};
    sensor_data_t sensor2_data = {SENSOR_2_PIN, &sensor2_state};

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor1_callback, &sensor1_data) != 0) {
        fprintf(stderr, "Error registering callback for sensor 1\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor2_callback, &sensor2_data) != 0) {
        fprintf(stderr, "Error registering callback for sensor 2\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100000); // Check every 0.1 seconds
    }

    return 0;
}

