#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdbool.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define GYRO_SENSITIVITY 200.0 // LSB/deg/s
#define RATE_XL_REG 0x02
#define RATE_XH_REG 0x03
#define LED_GPIO 17
#define ANGULAR_VELOCITY_THRESHOLD 20.0 // deg/s
#define BUFFER_CAPACITY 100

// Data structure for circular buffer
typedef struct {
    struct timespec timestamp;
    double angular_rate;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_CAPACITY];
int buffer_index = 0;
int buffer_size = 0;

// Global variables
int spi_handle;
bool running = true;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len);
double convert_to_degrees_per_second(int16_t raw_data);
void add_to_buffer(struct timespec timestamp, double angular_rate);
gyro_data_t get_from_buffer(int index);
void control_led(bool on);
void signal_handler(int signal);

// Function to read a register from the ADXRS290 via SPI
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];

    tx_buf[0] = reg_addr | 0x80; // Set MSB to 1 for read

    int result = spiXfer(handle, tx_buf, rx_buf, len + 1);
    if (result != (len + 1)) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Function to convert raw gyro data to degrees per second
double convert_to_degrees_per_second(int16_t raw_data) {
    return (double)raw_data / GYRO_SENSITIVITY;
}

// Function to add data to the circular buffer
void add_to_buffer(struct timespec timestamp, double angular_rate) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].angular_rate = angular_rate;

    buffer_index = (buffer_index + 1) % BUFFER_CAPACITY;
    if (buffer_size < BUFFER_CAPACITY) {
        buffer_size++;
    }
}

// Function to get data from the circular buffer
gyro_data_t get_from_buffer(int index) {
    return gyro_buffer[index];
}

// Function to control the LED
void control_led(bool on) {
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read gyro data
        uint8_t data[2];
        if (spi_read_register(spi_handle, RATE_XL_REG, data, 2) == 0) {
            // Combine bytes
            int16_t raw_data = (data[1] << 8) | data[0];

            // Convert to degrees per second
            double angular_rate = convert_to_degrees_per_second(raw_data);

            // Get timestamp
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);

            // Add to buffer
            add_to_buffer(ts, angular_rate);

            // Control LED based on threshold
            if (fabs(angular_rate) > ANGULAR_VELOCITY_THRESHOLD) {
                control_led(true);
            } else {
                control_led(false);
            }

            // Print data (optional)
            printf("Timestamp: %ld.%09ld, Angular Rate: %.2f deg/s\n", ts.tv_sec, ts.tv_nsec, angular_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    control_led(false);
    gpioTerminate();

    printf("Exited cleanly.\n");
    return 0;
}

