// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define the maximum duration (3600 seconds)
#define MAX_DURATION 3600

// Global variable to store the fade duration
int fade_duration = 0;

// Function prototypes
int validate_duration(int duration);
void fade_lamp(int gpio, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all lamps
    gpioPWM(LAMP1_GPIO, 0);
    gpioPWM(LAMP2_GPIO, 0);
    gpioPWM(LAMP3_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to validate the fade duration
int validate_duration(int duration) {
    if (duration < 1 || duration > MAX_DURATION) {
        fprintf(stderr, "Error: Duration must be between 1 and %d seconds.\n", MAX_DURATION);
        return 0; // Indicate invalid duration
    }
    return 1; // Indicate valid duration
}

// Function to fade a lamp
void fade_lamp(int gpio, int duration) {
    int i;
    int duty_cycle;
    int delay_ms = (1000000 / PWM_FREQUENCY) / 256; // Calculate delay for 100Hz frequency

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration);

    // Fade from 100% to 0% duty cycle
    for (i = 0; i <= 255; i++) {
        duty_cycle = i;
        gpioPWM(gpio, duty_cycle);
        usleep(delay_ms); // Delay for PWM frequency
    }

    printf("Lamp on GPIO %d faded to 0%% duty cycle.\n", gpio);
}

int main(int argc, char *argv[]) {
    // Check for the correct number of command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Convert the command-line argument to an integer
    fade_duration = atoi(argv[1]);

    // Validate the fade duration
    if (!validate_duration(fade_duration)) {
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade each lamp sequentially
    fade_lamp(LAMP1_GPIO, fade_duration);
    fade_lamp(LAMP2_GPIO, fade_duration);
    fade_lamp(LAMP3_GPIO, fade_duration);

    printf("Smart sunset simulator complete.\n");

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

