#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define RED_RELAY_PIN 17
#define YELLOW_RELAY_PIN 22
#define GREEN_RELAY_PIN 23
#define BLUE_RELAY_PIN 24

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *red_line, *yellow_line, *green_line, *blue_line;

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Close GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (yellow_line) {
        gpiod_line_release(yellow_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret;
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    yellow_line = gpiod_chip_get_line(chip, YELLOW_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);

    if (!red_line || !yellow_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(red_line, "traffic_light", 0) < 0) {
        perror("Error requesting red GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(yellow_line, "traffic_light", 0) < 0) {
        perror("Error requesting yellow GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(green_line, "traffic_light", 0) < 0) {
        perror("Error requesting green GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(blue_line, "traffic_light", 0) < 0) {
        perror("Error requesting blue GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Traffic light sequence
    while (1) {
        // Red state
        printf("Red\n");
        if (set_gpio_state(red_line, 0) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(yellow_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(green_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(blue_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        sleep(10);

        // Red + Yellow state
        printf("Red + Yellow\n");
        if (set_gpio_state(red_line, 0) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(yellow_line, 0) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(green_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(blue_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        sleep(2);

        // Green state
        printf("Green\n");
        if (set_gpio_state(red_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(yellow_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(green_line, 0) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(blue_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        sleep(10);

        // Yellow state
        printf("Yellow\n");
        if (set_gpio_state(red_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(yellow_line, 0) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(green_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        if (set_gpio_state(blue_line, 1) < 0) {
            signal_handler(SIGTERM);
        }
        sleep(3);
    }

    return 0;
}

