#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_DELAY_MS 100
#define READ_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_status(unsigned short *touch_status);
void control_relay(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, cleaning up...");
}

// Initialize MPR121
int init_mpr121() {
    // Reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Error: MPR121 reset failed");
        return -1;
    }
    gpioDelay(1000); // Wait for reset

    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_message("Error: MPR121 stop mode failed");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("Error: MPR121 enable electrode 0 failed");
        return -1;
    }

    // Set touch threshold
    if (i2cWriteByteData(i2c_handle, 0x41, TOUCH_THRESHOLD) < 0) {
        log_message("Error: MPR121 set touch threshold failed");
        return -1;
    }

    // Set release threshold
    if (i2cWriteByteData(i2c_handle, 0x42, RELEASE_THRESHOLD) < 0) {
        log_message("Error: MPR121 set release threshold failed");
        return -1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x21) < 0) {
        log_message("Error: MPR121 set debounce failed");
        return -1;
    }

    // Set charge time
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0D) < 0) {
        log_message("Error: MPR121 set charge time failed");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0D) < 0) {
        log_message("Error: MPR121 run mode failed");
        return -1;
    }

    log_message("MPR121 initialized successfully");
    return 0;
}

// Read touch status from MPR121
int read_touch_status(unsigned short *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("Error: MPR121 read touch status failed");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    char message[50];
    snprintf(message, sizeof(message), "Relay set to %s", state ? "ON" : "OFF");
    log_message(message);
}

// Log messages to file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
