void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, cleaning up...");
}

// Initialize MPR121
int init_mpr121() {
    // Reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Error: MPR121 reset failed");
        return -1;
    }
    gpioDelay(1000); // Wait for reset

    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_message("Error: MPR121 stop mode failed");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("Error: MPR121 enable electrode 0 failed");
        return -1;
    }

    // Set touch threshold
    if (i2cWriteByteData(i2c_handle, 0x41, TOUCH_THRESHOLD) < 0) {
        log_message("Error: MPR121 set touch threshold failed");
        return -1;
    }

    // Set release threshold
    if (i2cWriteByteData(i2c_handle, 0x42, RELEASE_THRESHOLD) < 0) {
        log_message("Error: MPR121 set release threshold failed");
        return -1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x21) < 0) {
        log_message("Error: MPR121 set debounce failed");
        return -1;
    }

    // Set charge time
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0D) < 0) {
        log_message("Error: MPR121 set charge time failed");
        return -1;
    }

    // Run mode
