void activate_alarm();
void deactivate_alarm();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int i, readings[DEBOUNCE_READS];
    int high_count = 0;

    for (i = 0; i < DEBOUNCE_READS; i++) {
        readings[i] = gpioRead(FLAME_SENSOR_PIN);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }

    for (i = 0; i < DEBOUNCE_READS; i++) {
        if (readings[i] == 1) {
            high_count++;
        }
    }

    return (high_count == DEBOUNCE_READS) ? 1 : 0; // Return 1 if flame detected, 0 otherwise
}

// Function to activate the alarm (buzzer and LED)
