    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_flame_sensor()) {
            activate_alarm();
            log_event("Flame Detected");
            while (read_flame_sensor() && running) {
                gpioDelay(100000); // Check every 100ms if flame is still present
            }
            deactivate_alarm();
        }
        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

