#define SOLENOID_2_PIN 27

// Define dispense duration in milliseconds
#define DISPENSE_DURATION_MS 1000

// Define dispense interval in seconds
#define DISPENSE_INTERVAL_S 5

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void dispense();
void log_dispense(int solenoid1_state, int solenoid2_state, int duration_ms);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Cleaning up and exiting.\n");
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Ensure solenoids are initially off
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    return 0;
}

// Dispense the liquid
void dispense() {
    // Activate solenoid 1 for half the duration
    gpioWrite(SOLENOID_1_PIN, 1);
    gpioDelay(DISPENSE_DURATION_MS * 1000 / 2); // Delay in microseconds

    // Activate solenoid 2 for the remaining half of the duration
    gpioWrite(SOLENOID_2_PIN, 1);
    gpioDelay(DISPENSE_DURATION_MS * 1000 / 2); // Delay in microseconds

    // Deactivate both solenoids
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
}

