#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N Enable Pins
#define ENABLE_A 24
#define ENABLE_B 25

// PID Constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle Distance Threshold
#define OBSTACLE_DISTANCE 20.0

// Global Variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// PID Controller Variables
float integral = 0.0;
float previous_error = 0.0;

// Function Prototypes
int initialize_gpio();
float simulate_tilt_error();
float simulate_distance();
void set_motor_speed(char motor, int speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);

    gpioWrite(ENABLE_A, PI_HIGH);
    gpioWrite(ENABLE_B, PI_HIGH);

    return 0;
}

// Function to simulate tilt error (random float between -10.0 and 10.0)
float simulate_tilt_error() {
    return (float)(rand() % 21 - 10); // Generates a random float between -10.0 and 10.0
}

// Function to simulate distance (random float between 2.0 and 400.0)
float simulate_distance() {
    return (float)(rand() % 399 + 2); // Generates a random float between 2.0 and 400.0
}

// Function to set motor speed (forward or backward)
void set_motor_speed(char motor, int speed) {
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    int forward_pin, backward_pin;

    if (motor == 'A') {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
    } else if (motor == 'B') {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
    } else {
        fprintf(stderr, "Invalid motor character: %c\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(forward_pin, PI_HIGH);
        gpioWrite(backward_pin, PI_LOW);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, PI_LOW);
        gpioWrite(backward_pin, PI_HIGH);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, PI_LOW);
        gpioWrite(backward_pin, PI_LOW);
    }
}

// Function to stop both motors
void stop_motors() {
    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
}

