#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define RELAY_PIN 17
#define SENSOR_PIN 4

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to toggle the relay state
void toggle_relay()
{
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to state: %d\n", relay_state);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Light Switch running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        // Read sensor value
        int sensor_value = gpioRead(SENSOR_PIN);

        // Check for touch
        if (sensor_value == 1)
        {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds

            // Re-read sensor value after debounce
            sensor_value = gpioRead(SENSOR_PIN);

            // Check if touch is still detected
            if (sensor_value == 1)
            {
                toggle_relay();
            }
        }

        gpioDelay(1000); // Check every 1 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

