#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA parameters
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16
#define PERIOD_SIZE 1024

// Define ALSA device name
#define ALSA_DEVICE "default"

// Define ALSA availability macro
#ifdef ALSA_AVAILABLE
#define ALSA_ENABLED 1
#else
#define ALSA_ENABLED 0
#endif

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle;
static float sensitivity = 1.0f;

// Function prototypes
void signal_handler(int signal);
int initialize_alsa(snd_pcm_t **pcm_handle);
int read_audio_data(snd_pcm_t *pcm_handle, int16_t *buffer, int buffer_size);
float calculate_rms(const int16_t *buffer, int buffer_size);
void map_rms_to_rgb(float rms, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void cleanup(snd_pcm_t *pcm_handle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    running = 0;
}

// Initialize ALSA audio capture
int initialize_alsa(snd_pcm_t **pcm_handle) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening ALSA device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size_near(*pcm_handle, hw_params, &PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Read audio data from ALSA
int read_audio_data(snd_pcm_t *pcm_handle, int16_t *buffer, int buffer_size) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, buffer_size / NUM_CHANNELS)) != buffer_size / NUM_CHANNELS) {
        fprintf(stderr, "Error reading audio data: %s\n", snd_strerror(err));
        if (err == -EPIPE) {
            fprintf(stderr, "EPIPE: Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "ESTRPIPE: Suspend occurred\n");
            snd_pcm_resume(pcm_handle);
        } else {
            return -1; // Other error
        }
    }
    return 0;
}

// Calculate RMS amplitude
float calculate_rms(const int16_t *buffer, int buffer_size) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    double mean_square = sum_of_squares / buffer_size;
    return sqrt(mean_square);
}

// Map RMS amplitude to RGB PWM values
void map_rms_to_rgb(float rms, int *red, int *green, int *blue) {
    // Non-linear mapping for cool colors for low amplitude, warm colors for high amplitude
    float normalized_rms = rms / 32767.0f; // Normalize to 16-bit range
    float hue = normalized_rms * 0.5f; // Map to 0-0.5 range

    // Cool colors (blue)
    if (hue < 0.33f) {
        *red = 0;
        *green = (int)(hue / 0.33f * 255.0f);
        *blue = 255;
    }
    // Warm colors (red)
    else if (hue < 0.66f) {
        *red = 255;
        *green = (int)(((hue - 0.33f) / 0.33f) * 255.0f);
        *blue = 0;
    }
    // Warm colors (green)
    else {
        *red = 0;
        *green = 255;
        *blue = (int)(((hue - 0.66f) / 0.34f) * 255.0f);
    }
}

// Set LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Cleanup resources
void cleanup(snd_pcm_t *pcm_handle) {
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        sensitivity = strtof(argv[1], &endptr);
        if (*endptr != '\0' || sensitivity <= 0) {
            fprintf(stderr, "Invalid sensitivity value: %s\n", argv[1]);
            return 1;
        }
        printf("Sensitivity: %f\n", sensitivity);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize ALSA
    int16_t *audio_buffer = NULL;
    int buffer_size = PERIOD_SIZE * NUM_CHANNELS * (SAMPLE_SIZE / 8); // Bytes

    if (ALSA_ENABLED) {
        if (initialize_alsa(&pcm_handle) != 0) {
            fprintf(stderr, "ALSA initialization failed\n");
            gpioTerminate();
            return 1;
        }
        audio_buffer = (int16_t *)malloc(buffer_size);
        if (!audio_buffer) {
            fprintf(stderr, "Failed to allocate audio buffer\n");
            cleanup(pcm_handle);
            return 1;
        }
    } else {
        // Simulate ALSA with a sine wave
        audio_buffer = (int16_t *)malloc(buffer_size);
        if (!audio_buffer) {
            fprintf(stderr, "Failed to allocate audio buffer for simulation\n");
            gpioTerminate();
            return 1;
        }
        for (int i = 0; i < PERIOD_SIZE; i++) {
            float t = (float)i / SAMPLE_RATE;
            audio_buffer[i] = (int16_t)(32767.0f * sin(2.0f * M_PI * 440.0f * t)); // 440 Hz sine wave
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int red, green, blue;

        if (ALSA_ENABLED) {
            if (read_audio_data(pcm_handle, audio_buffer, buffer_size) != 0) {
                fprintf(stderr, "Error reading audio data, exiting...\n");
                break;
            }
            float rms = calculate_rms(audio_buffer, buffer_size);
            map_rms_to_rgb(rms, &red, &green, &blue);
        } else {
            // Simulate ALSA with a sine wave
            float rms = 0.0f;
            for (int i = 0; i < PERIOD_SIZE; i++) {
                float t = (float)i / SAMPLE_RATE;
                rms += (float)audio_buffer[i] * audio_buffer[i];
            }
            rms = sqrt(rms / PERIOD_SIZE);
            map_rms_to_rgb(rms, &red, &green, &blue);
        }

        // Apply sensitivity scaling
        red = (int)(red * sensitivity);
        green = (int)(green * sensitivity);
        blue = (int)(blue * sensitivity);

        // Clamp values to 0-255 range
        if (red < 0) red = 0;
        if (red > 255) red = 255;
        if (green < 0) green = 0;
        if (green > 255) green = 255;
        if (blue < 0) blue = 0;
        if (blue > 255) blue = 255;

        set_led_color(red, green, blue);

        usleep(10000); // 10 ms delay
    }

    // Cleanup resources
    free(audio_buffer);
    cleanup(pcm_handle);

    return 0;
}

