#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TCS34725_ADDR 0x29
#define POWER_ON_REG 0x80
#define ENABLE_REG 0x80
#define INTEGRATION_TIME_REG 0x81
#define CLEAR_LOW_REG 0x14
#define CLEAR_HIGH_REG 0x15
#define RED_LOW_REG 0x16
#define RED_HIGH_REG 0x17
#define GREEN_LOW_REG 0x18
#define GREEN_HIGH_REG 0x19
#define BLUE_LOW_REG 0x1A
#define BLUE_HIGH_REG 0x1B

#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint32_t timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize the TCS34725 sensor
int init_sensor() {
    // Power on the sensor
    if (i2cWriteByteData(i2c_handle, POWER_ON_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to power-on register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(3); // Wait for power-on

    // Enable RGBC
    if (i2cWriteByteData(i2c_handle, ENABLE_REG, 0x03) < 0) {
        fprintf(stderr, "Error writing to enable register: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, INTEGRATION_TIME_REG, 0xD5) < 0) {
        fprintf(stderr, "Error writing to integration time register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];

    if (i2cReadI2CBlockData(i2c_handle, CLEAR_LOW_REG, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        *clear = 0; *red = 0; *green = 0; *blue = 0;
        return -1;
    }

    *clear = (uint16_t)buffer[1] << 8 | buffer[0];
    *red = (uint16_t)buffer[3] << 8 | buffer[2];
    *green = (uint16_t)buffer[5] << 8 | buffer[4];
    *blue = (uint16_t)buffer[7] << 8 | buffer[6];

    return 0;
}

// Log data to CSV file
int log_data(uint32_t timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    if (fp == NULL) {
        fprintf(stderr, "File pointer is NULL\n");
        return -1;
    }

    fprintf(fp, "%u,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
    }
    fflush(fp);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t clear, red, green, blue;
    uint32_t timestamp;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
            // Get Unix epoch timestamp
            timestamp = time(NULL);

            // Log data
            if (log_data(timestamp, clear, red, green, blue) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, setting values to 0\n");
            timestamp = time(NULL);
            clear = 0; red = 0; green = 0; blue = 0;
            log_data(timestamp, clear, red, green, blue);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

