    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO lines for the relays
    sunrise_line = gpiod_chip_get_line(chip, SUNRISE_PIN);
    daytime_line = gpiod_chip_get_line(chip, DAYTIME_PIN);
    sunset_line = gpiod_chip_get_line(chip, SUNSET_PIN);
    nighttime_line = gpiod_chip_get_line(chip, NIGHTTIME_PIN);

    if (!sunrise_line || !daytime_line || !sunset_line || !nighttime_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request the GPIO lines as output
    ret = gpiod_line_request_output(sunrise_line, "sunrise", 0);
    if (ret < 0) {
        perror("Error requesting sunrise line as output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(daytime_line, "daytime", 0);
    if (ret < 0) {
        perror("Error requesting daytime line as output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(sunset_line, "sunset", 0);
    if (ret < 0) {
        perror("Error requesting sunset line as output");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(nighttime_line, "nighttime", 0);
    if (ret < 0) {
        perror("Error requesting nighttime line as output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines and close the chip
void cleanup_gpio(void) {
    if (sunrise_line) {
        gpiod_line_set_value(sunrise_line, 0);
        gpiod_line_release(sunrise_line);
    }
    if (daytime_line) {
        gpiod_line_set_value(daytime_line, 0);
        gpiod_line_release(daytime_line);
    }
    if (sunset_line) {
        gpiod_line_set_value(sunset_line, 0);
        gpiod_line_release(sunset_line);
    }
    if (nighttime_line) {
        gpiod_line_set_value(nighttime_line, 0);
        gpiod_line_release(nighttime_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to set the state of a relay (active-low)
void set_relay_state(int pin, int state) {
    struct gpiod_line *line = NULL;

    if (pin == SUNRISE_PIN) {
        line = sunrise_line;
    } else if (pin == DAYTIME_PIN) {
        line = daytime_line;
    } else if (pin == SUNSET_PIN) {
        line = sunset_line;
    } else if (pin == NIGHTTIME_PIN) {
        line = nighttime_line;
    } else {
        fprintf(stderr, "Invalid pin number: %d\n", pin);
        return;
    }

    if (line) {
        gpiod_line_set_value(line, !state); // Active-low
    } else {
        fprintf(stderr, "Line not initialized for pin %d\n", pin);
    }
}

// Function to simulate sunrise
void simulate_sunrise(void) {
    int i;
    for (i = 0; i < PWM_STEPS && !terminate; i++) {
        set_relay_state(SUNRISE_PIN, 1);
        usleep(1000000 / PWM_STEPS); // 1 second period
        set_relay_state(SUNRISE_PIN, 0);
        usleep(1000000 / PWM_STEPS); // 1 second period
    }
}

// Function to simulate daytime
void simulate_daytime(void) {
    set_relay_state(DAYTIME_PIN, 1);
    sleep(6 * 60 * 60); // 6 hours
    set_relay_state(DAYTIME_PIN, 0);
}

// Function to simulate sunset
void simulate_sunset(void) {
    int i;
    for (i = 0; i < PWM_STEPS && !terminate; i++) {
        set_relay_state(SUNSET_PIN, 1);
        usleep(1000000 / PWM_STEPS); // 1 second period
        set_relay_state(SUNSET_PIN, 0);
        usleep(1000000 / PWM_STEPS); // 1 second period
    }
}

// Function to simulate nighttime
void simulate_nighttime(void) {
    set_relay_state(NIGHTTIME_PIN, 0);
    sleep(14 * 60 * 60); // 14.4 hours
}

int main(void) {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Sunrise/Sunset Lighting Simulator started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        simulate_sunrise();
        simulate_daytime();
        simulate_sunset();
        simulate_nighttime();
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

