#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define DEBOUNCE_MS 200

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to generate a timestamp string
char* generate_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // YYYYMMDD_HHMMSS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y%m%d_%H%M%S", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
void log_message(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", generate_timestamp(), message);
        fflush(log_file); // Ensure the message is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to generate the video filename
char* generate_video_filename() {
    char *timestamp = generate_timestamp();
    char *filename = (char*)malloc(strlen(VIDEO_DIR) + strlen(timestamp) + 5); // VIDEO_DIR + timestamp + .h264 + \0
    sprintf(filename, "%s%s.h264", VIDEO_DIR, timestamp);
    free(timestamp);
    return filename;
}

