    if (status == -1) {
        log_message("Error executing raspivid command.");
        return -1;
    }
    return 0;
}

// Function to handle motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) { // Obstacle detected (LOW signal)
        if (current_tick - last_tick > DEBOUNCE_MS * 1000) { // Debounce
            char *filename = generate_video_filename();
            if (filename != NULL) {
                log_message("Motion detected, recording video.");
                if (record_video(filename) == 0) {
                    char log_message_buffer[256];
                    sprintf(log_message_buffer, "Motion detected, video recorded: %s", filename);
                    log_message(log_message_buffer);
                } else {
                    log_message("Error recording video.");
                }
                free(filename);
            } else {
                log_message("Error generating video filename.");
            }
            last_tick = current_tick;
        }
    }
}

