        gpioTerminate();
        return 1;
    }

    log_message("System started.");

    // Set GPIO mode and register callback
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetAlertFunc(GPIO_PIN, motion_detected_callback);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    log_message("System exiting.");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

