#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define SENSITIVITY_SCALE 131.0
#define SAMPLE_RATE_HZ 100
#define SAMPLE_INTERVAL_MS (1000 / SAMPLE_RATE_HZ)
#define MAX_RETRIES 3
#define LOG_FILE "gyro_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
double convert_to_degps(int16_t raw_value);
int log_data(double x_degps, double y_degps, double z_degps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPU-6050 sensor
int initialize_sensor() {
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        // Wake up the sensor
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error: Failed to wake up MPU-6050 (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Set sample rate divider
        status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07); // 125 Hz
        if (status != 0) {
            fprintf(stderr, "Error: Failed to set sample rate divider (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(1000);
            continue;
        }

        // Set gyroscope full-scale range
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00); // ±250°/s
        if (status != 0) {
            fprintf(stderr, "Error: Failed to set gyroscope full-scale range (attempt %d): %d\n", retries + 1, status);
            retries++;
            gpioDelay(1000);
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to initialize MPU-6050 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error: Failed to read gyroscope data: %d\n", status);
        return -1; // Indicate failure
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0; // Indicate success
}

// Function to convert raw gyroscope data to degrees per second
double convert_to_degps(int16_t raw_value) {
    return (double)raw_value / SENSITIVITY_SCALE;
}

// Function to log data to a CSV file
int log_data(double x_degps, double y_degps, double z_degps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%ld,%.3f,%.3f,%.3f\n", timestamp_ms, x_degps, y_degps, z_degps);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int status;
    int16_t raw_x, raw_y, raw_z;
    double x_degps, y_degps, z_degps;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_degps = convert_to_degps(raw_x);
            y_degps = convert_to_degps(raw_y);
            z_degps = convert_to_degps(raw_z);

            // Log the data
            if (log_data(x_degps, y_degps, z_degps) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Attempting to re-initialize.\n");
            initialize_sensor(); // Attempt to re-initialize the sensor
        }

        // Delay for the sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

