#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdbool.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10  // microseconds
#define MAX_PULSE_WIDTH 23200      // microseconds (4 meters)
#define TIMEOUT_DURATION 100       // milliseconds
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile bool echo_received = false;
static FILE *log_file = NULL;
static volatile bool running = true;

// Mutex for protecting shared variables
static int mutex = PI_MUTEX_INIT;

// Function prototypes
void trigger_pulse(int gpio, int level, uint32_t tick);
void echo_pulse(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Interrupt handler for TRIG pin
void trigger_pulse(int gpio, int level, uint32_t tick)
{
    if (level == 1) // Rising edge
    {
        gpioWrite(TRIG_PIN, 0); // Send trigger pulse
        gpioDelay(TRIGGER_PULSE_DURATION);
    }
}

// Interrupt handler for ECHO pin
void echo_pulse(int gpio, int level, uint32_t tick)
{
    if (level == 1) // Rising edge
    {
        gpioLock(mutex);
        start_tick = tick;
        echo_received = false; // Reset flag
        gpioUnlock(mutex);
    }
    else if (level == 0) // Falling edge
    {
        gpioLock(mutex);
        end_tick = tick;
        echo_received = true; // Set flag
        gpioUnlock(mutex);
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width)
{
    // Speed of sound in air (approx. 343 m/s)
    // Distance = (Time * Speed of Sound) / 2
    // Time = Distance * 2 / Speed of Sound
    // pulse_width is in microseconds
    return (double)pulse_width * 0.0343 / 2.0;
}

// Function to log distance to file
void log_distance(double distance)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (log_file != NULL)
    {
        fprintf(log_file, "%ld,%.2f\n", ts.tv_nsec, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;

    // Disable interrupts
    gpioSetAlertFuncEx(TRIG_PIN, NULL, NULL);
