#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor 1 (X-axis) GPIO pins
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Motor 2 (Y-axis) GPIO pins
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Stepper motor parameters
#define STEPS_PER_REVOLUTION 2048.0
#define STEP_DELAY_US 1000  // 1000 microseconds = 1 millisecond
#define STEP_DELAY_NS (STEP_DELAY_US * 1000) // Convert microseconds to nanoseconds

// Square dimensions (in mm)
#define SQUARE_SIDE_MM 50.0

// Conversion factor (steps per mm)
#define STEPS_PER_MM 10.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Stopping motors and exiting...\n");
}

// Function to set the GPIO pins for a given step sequence
void set_step_sequence(int motor_num, int step) {
    int in1, in2, in3, in4;

    if (motor_num == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor_num == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
        return;
    }

    switch (step) {
        case 0:
            gpioWrite(in1, 0);
            gpioWrite(in2, 0);
            gpioWrite(in3, 0);
            gpioWrite(in4, 1);
            break;
        case 1:
            gpioWrite(in1, 0);
            gpioWrite(in2, 0);
            gpioWrite(in3, 1);
            gpioWrite(in4, 1);
            break;
        case 2:
            gpioWrite(in1, 0);
            gpioWrite(in2, 0);
            gpioWrite(in3, 1);
            gpioWrite(in4, 0);
            break;
        case 3:
            gpioWrite(in1, 0);
            gpioWrite(in2, 1);
            gpioWrite(in3, 1);
            gpioWrite(in4, 0);
            break;
        case 4:
            gpioWrite(in1, 0);
            gpioWrite(in2, 1);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 5:
            gpioWrite(in1, 1);
            gpioWrite(in2, 1);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 6:
            gpioWrite(in1, 1);
            gpioWrite(in2, 0);
            gpioWrite(in3, 0);
            gpioWrite(in4, 0);
            break;
        case 7:
            gpioWrite(in1, 1);
            gpioWrite(in2, 0);
            gpioWrite(in3, 0);
            gpioWrite(in4, 1);
            break;
        default:
            fprintf(stderr, "Error: Invalid step number: %d\n", step);
            break;
    }
}

// Function to move a stepper motor a specified number of steps
void move_motor(int motor_num, int steps) {
    int i;
    int num_steps = abs(steps); // Ensure steps is positive

    for (i = 0; i < num_steps; i++) {
        // Determine the step sequence based on the direction of movement
        int step_sequence = (steps > 0) ? (i % 8) : (7 - (i % 8));

        set_step_sequence(motor_num, step_sequence);

        // Delay for the specified step delay
        gpioDelay(STEP_DELAY_NS);
    }
}

// Function to draw a square
void draw_square(int side_length_mm) {
    int steps = (int)(side_length_mm * STEPS_PER_MM);

    // Move X-axis (Motor 1)
    move_motor(1, steps);

    // Move Y-axis (Motor 2)
    move_motor(2, steps);

    // Move X-axis (Motor 1) back
    move_motor(1, -steps);

    // Move Y-axis (Motor 2) back
    move_motor(2, -steps);
}

