#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>

// Default I2C address
#define DEFAULT_I2C_ADDRESS 0x18

// Default acceleration threshold
#define DEFAULT_THRESHOLD 2.0f

// Log file path
#define LOG_FILE "/var/log/high_acceleration.log"

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int handle);
int read_acceleration(int handle, float *x, float *y, float *z);
int log_event(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Structure to hold acceleration data
typedef struct {
    float x;
    float y;
    float z;
} AccelerationData;

// Function to initialize I2C
int initialize_i2c(int address) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the LIS3DH sensor
int configure_sensor(int handle) {
    // Configure CTRL_REG1: 100 Hz, Enable all axes
    if (i2cWriteByteData(handle, 0x20, 0x57) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: High resolution, ±2g range
    if (i2cWriteByteData(handle, 0x23, 0x88) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, 0x28, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        *x = 0.0f; *y = 0.0f; *z = 0.0f;
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]) >> 4;
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]) >> 4;
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]) >> 4;

    *x = (float)raw_x * 0.0009765625f;
    *y = (float)raw_y * 0.0009765625f;
    *z = (float)raw_z * 0.0009765625f;

    return 0;
}

// Function to log an event to a file
int log_event(float x, float y, float z) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.6f, Y: %.6f, Z: %.6f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
    return 0;
}

// Function to shutdown the system
void shutdown_system() {
    printf("Shutting down...\n");
    system("sudo shutdown -h now");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    float x, y, z;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) < 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Check for high acceleration
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                printf("High acceleration detected!\n");
                log_event(x, y, z);
                shutdown_system();
            }
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    return 0;
}

