// Define no line detection threshold
#define NO_LINE_DETECT_THRESHOLD 1

// Define alert threshold
#define ALERT_THRESHOLD 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

// Structure to hold circular buffer data
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *left_line, *center_line, *right_line, *alert_line;
static circular_buffer_t sensor_buffer;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
sensor_data_t read_sensors();
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int check_alert_condition(circular_buffer_t *buffer);
void trigger_alert();
void cleanup();
void signal_handler(int sig);

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left_line || !center_line || !right_line || !alert_line) {
        perror("Error getting GPIO line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(left_line, "line_follower", 0) < 0) {
        perror("Error requesting left line as output");
        cleanup();
        return -1;
    }
    if (gpiod_line_request_output(center_line, "line_follower", 0) < 0) {
        perror("Error requesting center line as output");
        cleanup();
        return -1;
    }
    if (gpiod_line_request_output(right_line, "line_follower", 0) < 0) {
        perror("Error requesting right line as output");
        cleanup();
        return -1;
    }
    if (gpiod_line_request_output(alert_line, "line_follower", 0) < 0) {
        perror("Error requesting alert line as output");
        cleanup();
        return -1;
    }

    return 0;
}

// Read sensor values
sensor_data_t read_sensors() {
    sensor_data_t data;
    int left_val, center_val, right_val;

    left_val = gpiod_line_get_value(left_line);
    center_val = gpiod_line_get_value(center_line);
    right_val = gpiod_line_get_value(right_line);

    if (left_val < 0 || center_val < 0 || right_val < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        data.left = -1; // Indicate error
        data.center = -1;
        data.right = -1;
        return data;
    }

    data.left = left_val;
    data.center = center_val;
    data.right = right_val;

    return data;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Check alert condition
int check_alert_condition(circular_buffer_t *buffer) {
    if (buffer->count < BUFFER_SIZE) return 0; // Not enough data

    int no_line_count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer->data[i].center == NO_LINE_DETECT_THRESHOLD) {
            no_line_count++;
        }
    }

    return (no_line_count >= ALERT_THRESHOLD);
}

// Trigger alert (turn on LED)
void trigger_alert() {
    if (gpiod_line_set_value(alert_line, 1) < 0) {
        perror("Error setting alert line value");
    }
    sleep(ALERT_DURATION);
    if (gpiod_line_set_value(alert_line, 0) < 0) {
        perror("Error setting alert line value");
    }
}

// Cleanup GPIO resources
void cleanup() {
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (alert_line) gpiod_line_release(alert_line);
    if (chip) gpiod_chip_close(chip);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", sig);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize circular buffer
    sensor_buffer.head = 0;
    sensor_buffer.count = 0;

    // Main loop
    while (!terminate) {
        // Read sensors
        sensor_data_t sensor_data = read_sensors();

        // Add data to buffer
        add_to_buffer(&sensor_buffer, sensor_data);

        // Check alert condition
        if (check_alert_condition(&sensor_buffer)) {
            trigger_alert();
        }

        // Line following logic
        if (sensor_data.center == LINE_DETECT_THRESHOLD) {
            // Move forward
            printf("Moving forward\n");
        } else if (sensor_data.left == LINE_DETECT_THRESHOLD) {
            // Turn left
            printf("Turning left\n");
        } else if (sensor_data.right == LINE_DETECT_THRESHOLD) {
            // Turn right
            printf("Turning right\n");
        } else {
            // Stop
            printf("Stopping\n");
        }

        // Log sensor data
        printf("Left: %d, Center: %d, Right: %d\n", sensor_data.left, sensor_data.center, sensor_data.right);

        // Delay
        usleep(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

