#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD_MT 5.0
#define FIELD_THRESHOLD_MT_X100 (int)(FIELD_THRESHOLD_MT * 100)
#define SAMPLE_INTERVAL_MS 100
#define TIMEOUT_MS 500
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_relay();
int read_sensor_data(int *raw_data);
float convert_to_mt(int raw_data);
int check_threshold(float field_mt);
int control_relay(int state);
int log_event(const char *event_type, const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    int raw_data;
    float field_mt;
    int relay_state;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize relay
    if (init_relay() != 0) {
        fprintf(stderr, "Failed to initialize relay. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.raw_data) != 0) {
            log_event("ERROR", "Failed to read sensor data");
            gpioDelay(SAMPLE_INTERVAL_MS);
            continue;
        }

        // Convert to milliTesla
        sensor_data.field_mt = convert_to_mt(sensor_data.raw_data);

        // Check threshold
        int threshold_exceeded = check_threshold(sensor_data.field_mt);

        // Control relay
        int new_relay_state = (threshold_exceeded) ? 1 : 0;
        if (sensor_data.relay_state != new_relay_state) {
            if (control_relay(new_relay_state) != 0) {
                log_event("ERROR", "Failed to control relay");
            } else {
                sensor_data.relay_state = new_relay_state;
                char message[100];
                snprintf(message, sizeof(message), "Relay state changed to %d", new_relay_state);
                log_event("RELAY_STATE", message);
            }
        }

        // Log data
        char message[100];
        snprintf(message, sizeof(message), "Field: %.2f mT, Relay: %d", sensor_data.field_mt, sensor_data.relay_state);
        log_event("SENSOR_READING", message);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize relay GPIO
int init_relay() {
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially off
    return 0;
}

// Read sensor data
int read_sensor_data(int *raw_data) {
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        // Start conversion
        status = i2cWriteByteData(i2c_handle, 0xC1, 0x01);
        if (status < 0) {
            log_event("ERROR", "Failed to write to I2C device");
            retries++;
            gpioDelay(10); // Small delay before retry
            continue;
        }

        // Wait for conversion to complete (polling register 0xC1)
        int timeout_count = 0;
        while (1) {
            status = i2cReadByteData(i2c_handle, 0xC1);
            if (status < 0) {
                log_event("ERROR", "Failed to read from I2C device");
                retries++;
                gpioDelay(10);
                break;
            }
            if (status == 0) {
                break; // Conversion complete
            }
            gpioDelay(10); // Small delay
            timeout_count++;
            if (timeout_count > TIMEOUT_MS / 10) {
                log_event("ERROR", "Timeout waiting for conversion");
                retries++;
                break;
            }
        }

        if (retries < MAX_RETRIES) {
            // Read raw data
            status = i2cReadByteData(i2c_handle, 0xC0);
            if (status < 0) {
                log_event("ERROR", "Failed to read from I2C device");
                retries++;
                gpioDelay(10);
                continue;
            }
            int lsb = status;

            status = i2cReadByteData(i2c_handle, 0xC0);
            if (status < 0) {
                log_event("ERROR", "Failed to read from I2C device");
                retries++;
                gpioDelay(10);
                continue;
            }
            int msb = status;

            *raw_data = (msb << 8) | lsb;
            return 0; // Success
        }
    }

    log_event("ERROR", "Max retries reached. Failed to read sensor data.");
    return 1; // Failure
}

// Convert raw data to milliTesla
float convert_to_mt(int raw_data) {
    return (float)raw_data * 25.0 / 1000.0;
}

// Check if field exceeds threshold
int check_threshold(float field_mt) {
    return (int)(field_mt * 100) > FIELD_THRESHOLD_MT_X100;
}

// Control relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log event to file
int log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s [%s] %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

