#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int setup_socket();
int accept_connection(int server_fd);
void handle_client(int client_fd);
void process_command(char *command, int client_fd);
void control_relay(int state);
void log_event(const char *event);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    printf("Signal received, shutting down...\n");
}

// Setup socket function
int setup_socket() {
    int server_fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_event("Error: Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        log_event("Error: Setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Error: Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        log_event("Error: Listen failed");
        close(server_fd);
        return -1;
    }

    return server_fd;
}

// Accept connection function
int accept_connection(int server_fd) {
    int new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        log_event("Error: Accept failed");
        return -1;
    }

    return new_socket;
}

// Handle client function
void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t valread;

    valread = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        log_event("Error: Receive failed");
        close(client_fd);
        return;
    }
    buffer[valread] = '\0'; // Null-terminate the received data

    // Process the command
    process_command(buffer, client_fd);

    close(client_fd);
}

// Process command function
void process_command(char *command, int client_fd) {
    char *token;
    char *rest = command;
    char *saveptr;

    // Remove leading whitespace
    while (isspace((unsigned char)*rest)) rest++;

    // Tokenize the command
    token = strtok_r(rest, " \t\n", &saveptr);

    if (token != NULL) {
        // Convert to uppercase
        for (int i = 0; token[i]; i++) {
            token[i] = toupper(token[i]);
        }

        if (strcmp(token, "ON") == 0) {
            control_relay(1);
            log_event("Relay ON");
        } else if (strcmp(token, "OFF") == 0) {
            control_relay(0);
            log_event("Relay OFF");
        } else {
            log_event("Invalid command");
            const char *error_message = "Invalid command\n";
            send(client_fd, error_message, strlen(error_message), 0);
        }
    } else {
        log_event("Empty command");
        const char *error_message = "Empty command\n";
        send(client_fd, error_message, strlen(error_message), 0);
    }
}

// Control relay function
void control_relay(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Log event function
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure the log is written immediately
}

