#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define SCALE_FACTOR 1.0 / 1500.0
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int start_measurement(int handle);
int read_flow(int handle, int *raw_flow);
float convert_to_ml_min(int raw_flow);
int validate_crc(uint8_t data[], int len, uint8_t crc);
void control_relay(float flow1, float flow2);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len, uint8_t crc, uint8_t polynomial)
{
    for (int i = 0; i < len; i++)
    {
        crc ^= data[i];
        for (int j = 0; j < 8; j++)
        {
            if (crc & 0x80)
            {
                crc = (crc << 1) ^ polynomial;
            }
            else
            {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C initialization function
int initialize_i2c(int bus, int addr)
{
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0)
    {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Start measurement command function
int start_measurement(int handle)
{
    char buf[2] = {0x36, 0x08};
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0)
    {
        fprintf(stderr, "Error writing start measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read flow data function
int read_flow(int handle, int *raw_flow)
{
    char buf[3];
    int result = i2cReadDevice(handle, buf, 3);
    if (result != 3)
    {
        fprintf(stderr, "Error reading flow data: %d\n", result);
        return -1;
    }

    uint8_t data[2] = {buf[0], buf[1]};
    uint8_t crc = buf[2];

    if (!validate_crc(data, 2, crc))
    {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    *raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// CRC validation function
int validate_crc(uint8_t data[], int len, uint8_t crc)
{
    return crc8(data, len, 0xFF, 0x31) == crc;
}

// Convert raw data to ml/min function
float convert_to_ml_min(int raw_flow)
{
    return (float)raw_flow * SCALE_FACTOR;
}

// Relay control function
void control_relay(float flow1, float flow2)
{
    if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD)
    {
        gpioWrite(RELAY_GPIO, 1); // Energize relay
    }
    else
    {
        gpioWrite(RELAY_GPIO, 0); // De-energize relay
    }
}

// Logging function
void log_flow_data(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL)
    {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", s, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

// Signal handler function
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup()
{
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle1 >= 0)
    {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0)
    {
        i2cClose(i2c_handle2);
    }
    gpioWrite(RELAY_GPIO, 0); // De-energize relay
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to off

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0)
    {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0)
    {
        cleanup();
        return 1;
    }

    // Start measurement
    if (start_measurement(i2c_handle1) != 0 || start_measurement(i2c_handle2) != 0)
    {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int raw_flow1, raw_flow2;
    float flow1, flow2;

    while (!terminate)
    {
        // Read flow data
        if (read_flow(i2c_handle1, &raw_flow1) == 0 && read_flow(i2c_handle2, &raw_flow2) == 0)
        {
            // Convert to ml/min
            flow1 = convert_to_ml_min(raw_flow1);
            flow2 = convert_to_ml_min(raw_flow2);

            // Control relay
            control_relay(flow1, flow2);

            // Log data
            log_flow_data(flow1, flow2);
        }
        else
        {
            fprintf(stderr, "Error reading flow data, skipping cycle\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

