int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = gpioRead(RAIN_SENSOR_PIN);
    if (rain_detected < 0) {
        syslog(LOG_ERR, "Error reading rain sensor: %d", rain_detected);
        return -1; // Indicate error
    }
    return rain_detected;
}

// Function to close the window
void close_window() {
    syslog(LOG_INFO, "Closing window...");

    // Set motor direction (forward)
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_WARNING, "Error writing to MOTOR_IN1_PIN");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_WARNING, "Error writing to MOTOR_IN2_PIN");
    }

    // Enable motor
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        syslog(LOG_WARNING, "Error writing to MOTOR_ENA_PIN");
    }

    // Wait for motor run time
    usleep(MOTOR_RUN_TIME_S * 1000000); // Convert seconds to microseconds

    // Stop motor
    stop_motor();

    syslog(LOG_INFO, "Window closed.");
}

// Function to stop the motor
void stop_motor() {
    syslog(LOG_INFO, "Stopping motor...");

    // Disable motor
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_WARNING, "Error writing to MOTOR_ENA_PIN");
    }

    // Set all motor control pins to LOW
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_WARNING, "Error writing to MOTOR_IN1_PIN");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_WARNING, "Error writing to MOTOR_IN2_PIN");
    }

    syslog(LOG_INFO, "Motor stopped.");
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_USER, LOG_USER);
    syslog(LOG_INFO, "Starting rain-actuated window controller...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up resistor on rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int rain_status = read_rain_sensor();
        if (rain_status < 0) {
            // Error reading sensor, exit loop
            break;
        }

        if (rain_status == 0) { // Dry
            rain_count++;
            if (rain_count >= RAIN_THRESHOLD) {
                close_window();
                rain_count = 0; // Reset counter after closing
            }
        } else { // Wet
            rain_count = 0; // Reset counter if rain starts
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 200 ms
    }

    // Cleanup
    stop_motor();
    gpioTerminate();
    closelog();

    syslog(LOG_INFO, "Rain-actuated window controller stopped.");
    return 0;
}

