        fprintf(stderr, "Error setting servo pulse width to %d\n", pulse_width);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read button states
        int lock_button_pressed = (read_button(LOCK_BUTTON_PIN) == 0); // Active low
        int unlock_button_pressed = (read_button(UNLOCK_BUTTON_PIN) == 0); // Active low

        // Debounce and set servo position
        if (lock_button_pressed && current_servo_state != 0) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            if (read_button(LOCK_BUTTON_PIN) == 0) { // Re-check after debounce
                printf("Locking door...\n");
                if (set_servo_position(LOCK_PULSE_WIDTH) != 0) {
                    fprintf(stderr, "Error locking door\n");
                }
                current_servo_state = 0;
            }
        } else if (unlock_button_pressed && current_servo_state != 1) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            if (read_button(UNLOCK_BUTTON_PIN) == 0) { // Re-check after debounce
                printf("Unlocking door...\n");
                if (set_servo_position(UNLOCK_PULSE_WIDTH) != 0) {
                    fprintf(stderr, "Error unlocking door\n");
                }
                current_servo_state = 1;
            }
        }

        gpioDelay(1000); // Small delay to avoid busy-waiting
    }

    return 0; // This line will not be reached due to the infinite loop
}

