// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_floodlight();
int deactivate_floodlight();
int log_event(const char *event_type, const char *timestamp);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, cleaning up...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to activate the floodlight
int activate_floodlight() {
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error activating floodlight\n");
        return 1;
    }
    return 0;
}

// Function to deactivate the floodlight
int deactivate_floodlight() {
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error deactivating floodlight\n");
        return 1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Security Light running...\n");

    while (!terminate) {
        if (read_pir_sensor() == 1) {
            printf("Motion detected!\n");

            // Get timestamp
            char* timestamp = get_iso8601_timestamp();
            if (timestamp == NULL) {
                fclose(log_file);
                gpioTerminate();
                return 1;
            }

            // Activate floodlight
            if (activate_floodlight() != 0) {
                free(timestamp);
                fclose(log_file);
                gpioTerminate();
                return 1;
            }

            // Log event
            if (log_event("Motion Detected", timestamp) != 0) {
                free(timestamp);
                deactivate_floodlight();
                fclose(log_file);
                gpioTerminate();
                return 1;
            }
            free(timestamp);

            // Wait for 60 seconds
            gpioDelay(60000000); // 60 seconds in microseconds

            // Deactivate floodlight
            timestamp = get_iso8601_timestamp();
            if (timestamp == NULL) {
                fclose(log_file);
                gpioTerminate();
                return 1;
            }
            if (deactivate_floodlight() != 0) {
                free(timestamp);
                fclose(log_file);
                gpioTerminate();
                return 1;
            }

            // Log deactivation event
            if (log_event("Floodlight Deactivated", timestamp) != 0) {
                free(timestamp);
                fclose(log_file);
                gpioTerminate();
                return 1;
            }
            free(timestamp);
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_floodlight();
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

