#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_MS 200
#define LOG_FILE "relay_control.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio_pin);
void log_event(const char *message);
void signal_handler(int signal);

// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_ECR 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D


// Function to initialize the MPR121
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        log_event("Error: MPR121 soft reset failed");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_MHD_R, 0x01) < 0) {
        log_event("Error: MPR121 MHD_R config failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHD_R, 0x01) < 0) {
        log_event("Error: MPR121 NHD_R config failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCL_R, 0x00) < 0) {
        log_event("Error: MPR121 NCL_R config failed");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDL_R, 0x00) < 0) {
        log_event("Error: MPR121 FDL_R config failed");
        return -1;
    }

    // Configure debounce
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x0F) < 0) {
        log_event("Error: MPR121 ECR config failed");
        return -1;
    }

    // Configure electrode config to enable 12 electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        log_event("Error: MPR121 electrode config failed");
        return -1;
    }

    log_event("MPR121 initialized successfully");
    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(int i2c_handle) {
    int touch_status_l, touch_status_h;

    touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        log_event("Error: MPR121 read LSB failed");
        return -1;
    }

    touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        log_event("Error: MPR121 read MSB failed");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to toggle the relay
void toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
    log_event(current_state ? "Relay OFF" : "Relay ON");
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Received signal, shutting down...");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
