#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <stdarg.h>
#include <errno.h>
#include <gpiod.h>
#include <pthread.h>
#include <math.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define TCP_PORT 5000
#define PWM_FREQUENCY 50 // Hz
#define LOG_FILE "security.log"

// Global variables
static int server_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio();
int setup_socket();
void *handle_client(void *socket_desc);
void *pwm_thread(void *arg);
void log_message(int priority, const char *format, ...);
void cleanup();
void signal_handler(int signum);

// Servo control functions
int set_servo_angle(int angle);
int map_angle_to_pulse_width(int angle);

// PIR sensor functions
int read_pir_sensor();

// Thread-safe logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    vsyslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// GPIO setup function
int setup_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", GPIO_CHIP);
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo GPIO line: %d", SERVO_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR GPIO line: %d", PIR_GPIO);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR GPIO line for input");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Socket setup function
int setup_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed");
        close(server_fd);
        return -1;
    }
    log_message(LOG_INFO, "Listening on port %d", TCP_PORT);
    return 0;
}

// Client handling function
void *handle_client(void *socket_desc) {
    int client_socket = *(int *)socket_desc;
    char buffer[1024] = {0};
    int valread;

    while ((valread = recv(client_socket, buffer, 1024, 0)) > 0) {
        buffer[valread] = '\0';
        log_message(LOG_INFO, "Received: %s", buffer);

        if (strncmp(buffer, "SERVO ", 6) == 0) {
            int angle = atoi(buffer + 6);
            if (angle >= 0 && angle <= 180) {
                set_servo_angle(angle);
                log_message(LOG_INFO, "Set servo angle to: %d", angle);
            } else {
                log_message(LOG_ERR, "Invalid servo angle: %d", angle);
                send(client_socket, "Invalid servo angle\n", strlen("Invalid servo angle\n"), 0);
            }
        } else if (strcmp(buffer, "PIR\n") == 0) {
            int pir_value = read_pir_sensor();
            char response[16];
            snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
            send(client_socket, response, strlen(response), 0);
            log_message(LOG_INFO, "Sent PIR sensor value: %d", pir_value);
        } else {
            log_message(LOG_ERR, "Unknown command: %s", buffer);
            send(client_socket, "Unknown command\n", strlen("Unknown command\n"), 0);
        }
    }

    if (valread == 0) {
        log_message(LOG_INFO, "Client disconnected");
    } else if (valread < 0) {
        log_message(LOG_ERR, "Recv failed");
    }

    close(client_socket);
    free(socket_desc);
    pthread_exit(NULL);
}

// PWM thread function
void *pwm_thread(void *arg) {
    int pulse_width_us;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 2000000 / PWM_FREQUENCY; // Calculate sleep time for 50 Hz

    while (!terminate) {
        for (int angle = 0; angle <= 180; angle++) {
            pulse_width_us = map_angle_to_pulse_width(angle);

            // Set servo pulse width
            if (gpiod_line_set_value(servo_line, 1) < 0) {
                log_message(LOG_ERR, "Failed to set servo line high");
                pthread_exit(NULL);
            }
            nanosleep(&(struct timespec){0, pulse_width_us * 1000}, NULL);

            if (gpiod_line_set_value(servo_line, 0) < 0) {
                log_message(LOG_ERR, "Failed to set servo line low");
                pthread_exit(NULL);
            }
            nanosleep(&(struct timespec){0, (1000000 - pulse_width_us) * 1000}, NULL);

            if (terminate) break;
        }
    }

    pthread_exit(NULL);
}

// Servo control functions
int set_servo_angle(int angle) {
    int pulse_width_us = map_angle_to_pulse_width(angle);
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message(LOG_ERR, "Failed to set servo line high");
        return -1;
    }
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = pulse_width_us * 1000;
    nanosleep(&sleep_time, NULL);

    if (gpiod_line_set_value(servo_line, 0) < 0) {
        log_message(LOG_ERR, "Failed to set servo line low");
        return -1;
    }
    sleep_time.tv_nsec = (1000000 - pulse_width_us) * 1000;
    nanosleep(&sleep_time, NULL);

    return 0;
}

int map_angle_to_pulse_width(int angle) {
    // Map angle (0-180) to pulse width (1000-2000 us)
    return (int)(1000 + (float)angle / 180.0 * 1000.0);
}

// PIR sensor functions
int read_pir_sensor() {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message(LOG_INFO, "Received signal %d, terminating...", signum);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");

    // Close socket
    if (server_fd != -1) {
        close(server_fd);
    }

    // Release GPIO lines
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    log_message(LOG_INFO, "Cleanup complete. Exiting.");
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        log_message(LOG_ERR, "GPIO setup failed");
        cleanup();
        return 1;
    }

    // Initialize socket
    if (setup_socket() != 0) {
        log_message(LOG_ERR, "Socket setup failed");
        cleanup();
        return 1;
    }

    // Create PWM thread
    pthread_t pwm_thread_id;
    if (pthread_create(&pwm_thread_id, NULL, pwm_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PWM thread");
        cleanup();
        return 1;
    }

    // Accept incoming connections
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int new_socket;

    while (!terminate) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            if (terminate) break; // Exit loop if terminated by signal
            log_message(LOG_ERR, "Accept failed");
            continue; // Continue listening
        }

        log_message(LOG_INFO, "Connection accepted");

        // Create a new thread for each client
        pthread_t client_thread_id;
        int *new_sock = malloc(sizeof(int));
        *new_sock = new_socket;

        if (pthread_create(&client_thread_id, NULL, handle_client, (void *)new_sock) < 0) {
            log_message(LOG_ERR, "Could not create thread");
            free(new_sock);
            close(new_socket);
        }
    }

    // Wait for PWM thread to finish
    pthread_join(pwm_thread_id, NULL);

    // Cleanup and exit
    cleanup();

    return 0;
}

