#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int dout_pin;
    int sck_pin;
    int solenoid_pin;
    float threshold;
    float scale;
    int duration;
    int tare_samples;
    int readings_per_measurement;
} Config;

// Global variables
static volatile int running = 1;
static Config config;
static int solenoid_state = 0; // 0 = unlocked, 1 = locked

// Function prototypes
int read_hx711(int dout_pin, int sck_pin);
float calculate_weight(int raw_value, float scale, int tare_offset);
void control_solenoid(int solenoid_pin, int state, int duration);
void tare_load_cell(int dout_pin, int sck_pin, int tare_samples, int *tare_offset);
void signal_handler(int signal);
void load_configuration(const char *filename, Config *config);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Load configuration from file
void load_configuration(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open configuration file: %s", filename);
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "dout_pin") == 0) {
                config->dout_pin = atoi(value);
            } else if (strcmp(key, "sck_pin") == 0) {
                config->sck_pin = atoi(value);
            } else if (strcmp(key, "solenoid_pin") == 0) {
                config->solenoid_pin = atoi(value);
            } else if (strcmp(key, "threshold") == 0) {
                config->threshold = atof(value);
            } else if (strcmp(key, "scale") == 0) {
                config->scale = atof(value);
            } else if (strcmp(key, "duration") == 0) {
                config->duration = atoi(value);
            } else if (strcmp(key, "tare_samples") == 0) {
                config->tare_samples = atoi(value);
            } else if (strcmp(key, "readings_per_measurement") == 0) {
                config->readings_per_measurement = atoi(value);
            }
        }
    }

    fclose(fp);
}

// Read HX711 value
int read_hx711(int dout_pin, int sck_pin) {
    int data = 0;
    int timeout = 0;

    gpioSetMode(dout_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    // Wait for DOUT to go low
    while (gpioRead(dout_pin) == 1 && timeout < 1000) {
        gpioDelay(1); // 1 ms delay
        timeout++;
    }

    if (timeout >= 1000) {
        syslog(LOG_ERR, "Timeout waiting for DOUT to go low");
        return -1; // Indicate error
    }

    // Read 24 bits
    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(dout_pin)) {
            data++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // Small delay
    }

    // Select channel A and gain 128
    gpioWrite(sck_pin, 1);
    gpioDelay(1); // Small delay
    gpioWrite(sck_pin, 0);
    gpioDelay(1); // Small delay

    // Two's complement conversion (if needed, HX711 is already signed)
    //if (data & 0x800000) {
    //    data |= 0xFF000000;
    //}

    return data;
}

// Calculate weight
float calculate_weight(int raw_value, float scale, int tare_offset) {
    return (float)(raw_value - tare_offset) / scale;
}

// Control solenoid
void control_solenoid(int solenoid_pin, int state, int duration) {
    gpioWrite(solenoid_pin, state);
    gpioDelay(duration);
    gpioWrite(solenoid_pin, 0); // Ensure solenoid is off after duration
}

// Tare load cell
void tare_load_cell(int dout_pin, int sck_pin, int tare_samples, int *tare_offset) {
    long sum = 0;
    for (int i = 0; i < tare_samples; i++) {
        int raw_value = read_hx711(dout_pin, sck_pin);
        if (raw_value == -1) {
            syslog(LOG_ERR, "Error reading during tare, skipping sample");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    *tare_offset = sum / tare_samples;
    syslog(LOG_INFO, "Tare offset: %d", *tare_offset);
}

int main(int argc, char *argv[]) {
    // Default configuration
    config.dout_pin = 23;
    config.sck_pin = 24;
    config.solenoid_pin = 25;
    config.threshold = 1000.0;
    config.scale = 100.0;
    config.duration = 200;
    config.tare_samples = 10;
    config.readings_per_measurement = 5;

    // Override with command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            config.threshold = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            config.scale = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            config.duration = atoi(argv[i + 1]);
            i++;
        }
    }

    // Load configuration from file
    load_configuration("config.txt", &config);

    // Initialize syslog
    openlog("load_cell_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.dout_pin, PI_INPUT);
    gpioSetMode(config.sck_pin, PI_OUTPUT);
    gpioSetMode(config.solenoid_pin, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    int tare_offset = 0;
    tare_load_cell(config.dout_pin, config.sck_pin, config.tare_samples, &tare_offset);

    // Main loop
    while (running) {
        float total_weight = 0.0;
        for (int i = 0; i < config.readings_per_measurement; i++) {
            int raw_value = read_hx711(config.dout_pin, config.sck_pin);
            if (raw_value == -1) {
                syslog(LOG_ERR, "Error reading HX711, skipping measurement");
                continue; // Skip to the next iteration
            }
            total_weight += calculate_weight(raw_value, config.scale, tare_offset);
            gpioDelay(10); // Small delay between readings
        }
        float average_weight = total_weight / config.readings_per_measurement;

        syslog(LOG_INFO, "Average weight: %.2f grams", average_weight);

        // Check threshold and control solenoid
        if (average_weight > config.threshold && solenoid_state == 0) {
            syslog(LOG_INFO, "Weight exceeds threshold, locking solenoid");
            control_solenoid(config.solenoid_pin, 1, config.duration);
            solenoid_state = 1;
        } else if (average_weight < config.threshold && solenoid_state == 1) {
            syslog(LOG_INFO, "Weight below threshold, unlocking solenoid");
            control_solenoid(config.solenoid_pin, 0, config.duration);
            solenoid_state = 0;
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup
    gpioWrite(config.solenoid_pin, 0); // Ensure solenoid is off
    gpioTerminate();
    closelog();

    return 0;
}

