#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

// Function to set the relay state
int set_relay_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        log_message(LOG_ERR, "Failed to write to GPIO");
        return -1;
    }
    return 0;
}

// Callback function for when the MQTT client connects to the broker
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT connected to broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to subscribe to topic");
            running = 0; // Stop the loop if subscription fails
        }
    } else {
        log_message(LOG_ERR, "MQTT connection error");
        running = 0; // Stop the loop on connection error
    }
}

// Callback function for when the MQTT client disconnects from the broker
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    log_message(LOG_INFO, "MQTT disconnected from broker");
    running = 0; // Stop the loop on disconnection
}

// Callback function for when a message is received
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            log_message(LOG_INFO, "Received ON command");
            set_relay_state(1); // Turn relay ON
        } else if (strcmp(payload, "OFF") == 0) {
            log_message(LOG_INFO, "Received OFF command");
            set_relay_state(0); // Turn relay OFF
        } else {
            log_message(LOG_ERR, "Invalid command received");
        }
    } else {
        log_message(LOG_ERR, "Empty message received");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    log_message(LOG_INFO, "Signal received, stopping...");
    running = 0; // Stop the loop
}

int main() {
    openlog("mqtt_relay", LOG_USER, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    set_relay_state(0);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create MQTT client instance");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to the MQTT broker
    int connect_result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (connect_result != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to run the MQTT client
    while (running) {
        int loop_result = mosquitto_loop(mosq, -1, 1); // -1 means blocking, 1 max messages to process
        if (loop_result != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "MQTT loop error");
            running = 0; // Stop the loop on error
        }

        if (!running) {
            // Clean up resources before exiting
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
            gpioTerminate();
            closelog();
            return 0;
        }

        // Reconnect if disconnected
        if (!mosquitto_is_connected(mosq)) {
            log_message(LOG_INFO, "Attempting to reconnect...");
            sleep(5); // Wait before reconnecting
            connect_result = mosquitto_reconnect(mosq);
            if (connect_result != MOSQ_ERR_SUCCESS) {
                log_message(LOG_ERR, "Failed to reconnect to MQTT broker");
                running = 0; // Stop the loop if reconnection fails
            }
        }
    }

    // Clean up resources before exiting
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

