#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoders
#define ENCODER_A_A 4
#define ENCODER_A_B 5
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PI Controller Parameters
#define Kp 0.5
#define Ki 0.05

// PWM Frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Target RPM
#define TARGET_RPM 50.0

// Encoder Stall Threshold (seconds)
#define ENCODER_STALL_THRESHOLD 2.0

// Global Variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int encoder_a_stall = 0;
volatile int encoder_b_stall = 0;

pthread_mutex_t encoder_a_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder_b_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void *encoder_a_isr(void *arg);
void *encoder_b_isr(void *arg);
void *control_loop(void *arg);
void signal_handler(int signal);

// Motor Control Functions
void set_motor_direction(int motor, int direction);
void set_motor_pwm(int motor, int pwm_value);

// PI Controller Functions
double calculate_rpm(int encoder_count, double elapsed_time);
double calculate_control_output(double rpm_error, double *integral, double elapsed_time);

// Encoder Stall Detection
void check_encoder_stall(int encoder, int *stall_flag, pthread_mutex_t *mutex);

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_PWM, 255);
    gpioSetPWMrange(MOTOR_B_PWM, 255);

    // Set PWM duty cycle to 0 initially
    set_motor_pwm(0, 0);
    set_motor_pwm(1, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create threads
    pthread_t encoder_a_thread, encoder_b_thread, control_thread;

    if (pthread_create(&encoder_a_thread, NULL, encoder_a_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to create encoder A thread\n");
        gpioTerminate();
        return 1;
    }

    if (pthread_create(&encoder_b_thread, NULL, encoder_b_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to create encoder B thread\n");
        gpioTerminate();
        return 1;
    }

    if (pthread_create(&control_thread, NULL, control_loop, NULL) != 0)
    {
        fprintf(stderr, "Failed to create control thread\n");
        gpioTerminate();
        return 1;
    }

    // Wait for threads to finish (never happens in this example, but good practice)
    pthread_join(encoder_a_thread, NULL);
    pthread_join(encoder_b_thread, NULL);
    pthread_join(control_thread, NULL);

    // Cleanup (should not reach here normally due to signal handler)
    gpioTerminate();
    return 0;
}

void *encoder_a_isr(void *arg)
{
    int last_state_a = gpioRead(ENCODER_A_A);
    int last_state_b = gpioRead(ENCODER_A_B);

    while (1)
    {
        int current_state_a = gpioRead(ENCODER_A_A);
        int current_state_b = gpioRead(ENCODER_A_B);

        if (current_state_a != last_state_a)
        {
            if (current_state_a != current_state_b)
            {
                pthread_mutex_lock(&encoder_a_mutex);
                encoder_a_count++;
                pthread_mutex_unlock(&encoder_a_mutex);
            }
            else
            {
                pthread_mutex_lock(&encoder_a_mutex);
                encoder_a_count--;
                pthread_mutex_unlock(&encoder_a_mutex);
            }
            last_state_a = current_state_a;
            last_state_b = current_state_b;
        }
