#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYSTERESIS_DELAY 5 // seconds
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int initialize_relay();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize relay GPIO
int initialize_relay() {
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially off
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd = 0x10; // High Resolution Mode 2
    char data[2];
    int result;

    result = i2cWriteByte(i2c_handle, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(180000); // Wait 180 ms

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relay state
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate();
}

int main() {
    float lux;
    int relay_state = 0; // 0 = off, 1 = on
    time_t last_lux_read_time = 0;
    time_t last_relay_change_time = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize_pigpio() != 0) {
        return 1;
    }

    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    if (initialize_relay() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Smart Chicken Coop Lighting System started\n");

    while (!terminate) {
        time_t current_time = time(NULL);

        // Read lux value every 5 seconds
        if (difftime(current_time, last_lux_read_time) >= 5) {
            if (read_bh1750(&lux) == 0) {
                printf("Lux: %.2f\n", lux);
                log_data(lux, relay_state);
                last_lux_read_time = current_time;

                // Control relay based on lux value
                if (lux < LUX_THRESHOLD_DUSK && relay_state == 0 && difftime(current_time, last_relay_change_time) >= HYSTERESIS_DELAY) {
                    control_relay(1);
                    relay_state = 1;
                    log_data(lux, relay_state);
                    last_relay_change_time = current_time;
                } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1 && difftime(current_time, last_relay_change_time) >= HYSTERESIS_DELAY) {
                    control_relay(0);
                    relay_state = 0;
                    log_data(lux, relay_state);
                    last_relay_change_time = current_time;
                }
            } else {
                fprintf(stderr, "Error reading BH1750 sensor\n");
                log_data(-1, relay_state); // Log error
            }
        }

        gpioDelay(1000); // Check every 1 second
    }

    cleanup();
    return 0;
}

