#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int relay_state = 0; // 0 = OFF, 1 = ON
    int touch_state = 0;
    int last_touch_state = 0;
    struct timespec delay = {0, 50000000}; // 50 ms

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 1 && last_touch_state == 0) {
            // Touch detected, debounce and toggle relay
            nanosleep(&delay, NULL);
            if (gpioRead(TOUCH_PIN) == 1) {
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);

                // Log relay state change
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char buf[80];
                strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
                printf("%s Relay is now %s\n", buf, relay_state ? "ON" : "OFF");
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10000); // 10 ms delay
    }

    // Turn off relay before exiting
    gpioWrite(RELAY_PIN, 0);

    // Release pigpio resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

