#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define PULSES_PER_LITER 450.0
#define PULSE_DEBOUNCE_TIME_US 1000000 // 1 second
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define SOLENOID_OPEN_STATE 1
#define SOLENOID_CLOSED_STATE 0

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;
int solenoid_state = SOLENOID_OPEN_STATE; // Initially open

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    // Debounce the interrupt
    gpioDelay(PULSE_DEBOUNCE_TIME_US);

    // Increment the pulse count
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulses) {
    return (pulses / PULSES_PER_LITER) * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == SOLENOID_OPEN_STATE) {
        gpioWrite(SOLENOID_PIN, SOLENOID_CLOSED_STATE);
        solenoid_state = SOLENOID_CLOSED_STATE;
        log_data(lpm, solenoid_state);
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == SOLENOID_CLOSED_STATE) {
        gpioWrite(SOLENOID_PIN, SOLENOID_OPEN_STATE);
        solenoid_state = SOLENOID_OPEN_STATE;
        log_data(lpm, solenoid_state);
    }
}

// Function to log data to a file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state == SOLENOID_OPEN_STATE ? "Open" : "Closed");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the solenoid valve
    gpioWrite(SOLENOID_PIN, SOLENOID_OPEN_STATE);
    solenoid_state = SOLENOID_OPEN_STATE;
    log_data(0.0, solenoid_state); // Log the state change

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set FLOW_SENSOR_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SOLENOID_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Sample the pulse count
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset the pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        double lpm = calculate_lpm(current_pulse_count);

        // Control the solenoid valve
        control_solenoid(lpm);

        // Log the data
        log_data(lpm, solenoid_state);

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

