#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>
#include <errno.h>

// Configuration defaults
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_HX711_TIMEOUT_MS 100

// GPIO pins
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

// Servo limits
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Global variables
static volatile int running = 1;
static int socket_fd = -1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[INET_ADDRSTRLEN] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int hx711_timeout_ms = DEFAULT_HX711_TIMEOUT_MS;

// Function prototypes
int read_config(const char *filename);
int init_gpio();
long read_hx711();
double calibrate_weight(long raw_value);
int set_servo_pulse_width(int pulse_width);
int dispense(double target_weight);
int send_data(int socket_fd, double actual_weight);
int log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
int create_socket(const char *server_ip, int server_port);
int accept_connection(int socket_fd);
double receive_target_weight(int socket_fd);

// Function to read configuration from file
int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
                server_ip[INET_ADDRSTRLEN - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            } else if (strcmp(key, "hx711_timeout_ms") == 0) {
                hx711_timeout_ms = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(SERVO_PIN, 50); // Set PWM frequency to 50 Hz
    gpioSetPWMrange(SERVO_PIN, 20000); // Set PWM range to 20000 for 1000-2000 us range

    return 0;
}

// Function to read data from HX711 using bit-banging
long read_hx711() {
    long value = 0;
    int i;

    gpioWrite(HX711_SCK_PIN, 0);

    // Wait for DATA pin to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > hx711_timeout_ms) {
            fprintf(stderr, "HX711 timeout waiting for data\n");
            return -1; // Timeout error
        }
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // 1 us clock pulse
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // 1 us clock pulse
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1); // 1 us clock pulse
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1); // 1 us clock pulse

    // Two's complement conversion if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Function to calibrate raw HX711 reading to grams
double calibrate_weight(long raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to set servo pulse width using pigpio
int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return -1;
    }

    gpioPWM(SERVO_PIN, pulse_width); // Set PWM duty cycle
    return 0;
}

// Function to dispense a weight
int dispense(double target_weight) {
    // Map target weight to servo pulse width
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (target_weight / 100.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    if (set_servo_pulse_width(pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width\n");
        return -1;
    }

    gpioDelay(1000); // Wait for 1 second

    long raw_value = read_hx711();
    if (raw_value < 0) {
        fprintf(stderr, "Failed to read HX711 value\n");
        return -1;
    }

    double actual_weight = calibrate_weight(raw_value);

    if (send_data(socket_fd, actual_weight) != 0) {
        fprintf(stderr, "Failed to send data to server\n");
        return -1;
    }

    return 0;
}

// Function to send data to the server
int send_data(int socket_fd, double actual_weight) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%.2f", actual_weight);

    if (send(socket_fd, buffer, strlen(buffer), 0) < 0) {
        perror("Error sending data to server");
        return -1;
    }

    return 0;
}

// Function to log events to a JSON file
int log_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root = json_object();
    json_t *timestamp = json_object();
    json_t *target = json_real(target_weight);
    json_t *actual = json_real(actual_weight);
    json_t *error = json_string(error_message);

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    json_object_set_new(timestamp, "timestamp", json_string(timestamp_str));
    json_object_set_new(root, "timestamp", timestamp);
    json_object_set_new(root, "target_weight", target);
    json_object_set_new(root, "actual_weight", actual);
