// Function to read configuration from file
int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, INET_ADDRSTRLEN - 1);
                server_ip[INET_ADDRSTRLEN - 1] = '\0';
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            } else if (strcmp(key, "hx711_timeout_ms") == 0) {
                hx711_timeout_ms = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(SERVO_PIN, 50); // Set PWM frequency to 50 Hz
    gpioSetPWMrange(SERVO_PIN, 20000); // Set PWM range to 20000 for 1000-2000 us range

    return 0;
}

// Function to read data from HX711 using bit-banging
long read_hx711() {
    long value = 0;
    int i;

    gpioWrite(HX711_SCK_PIN, 0);

    // Wait for DATA pin to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > hx711_timeout_ms) {
            fprintf(stderr, "HX711 timeout waiting for data\n");
            return -1; // Timeout error
        }
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // 1 us clock pulse
        value = value << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // 1 us clock pulse
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1); // 1 us clock pulse
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1); // 1 us clock pulse

    // Two's complement conversion if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Function to calibrate raw HX711 reading to grams
double calibrate_weight(long raw_value) {
    return (double)raw_value / calibration_factor;
