// Function to set servo pulse width using pigpio
int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return -1;
    }

    gpioPWM(SERVO_PIN, pulse_width); // Set PWM duty cycle
    return 0;
}

// Function to dispense a weight
int dispense(double target_weight) {
    // Map target weight to servo pulse width
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (target_weight / 100.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    if (set_servo_pulse_width(pulse_width) != 0) {
