    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Read the touch sensor with debouncing
int read_touch_sensor() {
    int touch_detected = 0;
    int stable_count = 0;
    int current_state;

    for (int i = 0; i < (debounce_time * 10); ++i) { // Debounce loop
        current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state == 1) {
            stable_count++;
        }
        gpioDelay(debounce_time / 10); // Delay for debounce_time / 1000 seconds
    }

    if (stable_count == debounce_time * 10) {
        touch_detected = 1;
    }

    return touch_detected;
}

// Toggle the relay state
int toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    int new_state = !current_state;

    if (gpioWrite(RELAY_PIN, new_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_PIN);
        return 1;
    }

    return 0;
}

