        if (argc > 2) {
            debounce_time = atoi(argv[2]);
            if (debounce_time <= 0) {
                fprintf(stderr, "Invalid debounce time. Using default value.\n");
                debounce_time = DEFAULT_DEBOUNCE_TIME;
            }
        } else {
            fprintf(stderr, "Missing debounce time value.\n");
            debounce_time = DEFAULT_DEBOUNCE_TIME;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Relay control started. Debounce time: %d ms. Press Ctrl+C to exit.\n", debounce_time);

    // Main loop
    while (running) {
        if (read_touch_sensor()) {
            if (toggle_relay() == 0) {
