#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "motor_rpm.log"
#define DEBOUNCE_DELAY_NS 2000000 // 2 ms

// Global variables for signal handling
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold program state
typedef struct {
    struct timespec last_pulse_time;
    int pulse_count;
} program_state_t;

program_state_t state = {0};

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
int read_sensor(struct gpiod_line *line);
double calculate_rpm(int pulse_count);
int log_rpm(double rpm);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nSignal received, exiting gracefully...\n");
}

// Initialize GPIO line
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(*chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motor_rpm_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(*line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input\n", GPIO_PIN);
        gpiod_chip_close(*chip);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// Read sensor value with debouncing
int read_sensor(struct gpiod_line *line) {
    struct timespec now, diff;
    clock_gettime(CLOCK_MONOTONIC, &now);

    // Calculate time difference from the last pulse
    diff.tv_sec = now.tv_sec - state.last_pulse_time.tv_sec;
    diff.tv_nsec = now.tv_nsec - state.last_pulse_time.tv_nsec;
    if (diff.tv_nsec < 0) {
        diff.tv_sec--;
        diff.tv_nsec += 1000000000;
    }

    // Check if enough time has passed since the last pulse
    if (diff.tv_sec == 0 && diff.tv_nsec < DEBOUNCE_DELAY_NS) {
        return 0; // Debounced, ignore the pulse
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value\n");
        return 0; // Return 0 to avoid counting an invalid pulse
    }

    if (value == 1) {
        state.pulse_count++;
        state.last_pulse_time = now;
        return 1; // Pulse detected
    }

    return 0; // No pulse detected
}

// Calculate RPM
double calculate_rpm(int pulse_count) {
    return (double)pulse_count / 5.0 * 60.0;
}

// Log RPM to file
int log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_fp, "%s,%.2f\n", timestamp, rpm);
    fflush(log_fp);

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line) < 0) {
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor(line)) {
            // Pulse detected, calculate RPM
            double rpm = calculate_rpm(state.pulse_count);
            printf("RPM: %.2f\n", rpm);

            // Log RPM
            log_rpm(rpm);
        }

        // Sleep for 1 second
        struct timespec sleep_time;
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_fp);

    return 0;
}

