#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Failsafe time in seconds
#define FAILSAFE_TIME 10

// Global volatile flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Function to read the touch sensor
int read_touch_sensor()
{
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
    if (sensor_value < 0)
    {
        fprintf(stderr, "Error reading GPIO%d\n", TOUCH_SENSOR_PIN);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to toggle the relay state
void toggle_relay(int current_state)
{
    gpioWrite(RELAY_PIN, !current_state);
}

// Function to implement failsafe mechanism
void failsafe_check(int sensor_value)
{
    static time_t last_touch_time = 0;
    time_t current_time = time(NULL);

    if (sensor_value == 1)
    {
        if (last_touch_time == 0)
        {
            last_touch_time = current_time;
        }
        else if (difftime(current_time, last_touch_time) >= FAILSAFE_TIME)
        {
            fprintf(stderr, "Failsafe triggered: Relay forced OFF\n");
            gpioWrite(RELAY_PIN, 0); // Force relay OFF
            last_touch_time = 0;       // Reset failsafe timer
        }
    }
    else
    {
        last_touch_time = 0; // Reset failsafe timer when sensor is released
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    int relay_state = 0; // 0 = OFF, 1 = ON
    int last_sensor_value = 0;

    // Main loop
    while (!terminate)
    {
        int sensor_value = read_touch_sensor();
        if (sensor_value < 0)
        {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        failsafe_check(sensor_value);

        if (sensor_value == 1 && last_sensor_value == 0) // Rising edge
        {
            toggle_relay(relay_state);
            relay_state = !relay_state;
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        last_sensor_value = sensor_value;
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
    }

    // Cleanup
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully\n");
    return 0;
}

