#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18  // BCM GPIO 18, hardware PWM 0
#define VALVE_DIR_PIN 23  // BCM GPIO 23
#define FLOW_SENSOR_PIN 24 // BCM GPIO 24

// Define constants
#define FLOW_SENSOR_CALIBRATION 450.0 // Pulses per liter
#define PULSES_PER_LITER 450.0
#define PULSE_WIDTH_US 1000 // 1 ms pulse width for YF-S201
#define SAMPLE_INTERVAL_MS 100
#define PWM_FREQUENCY 1000 // 1 kHz

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulses);
int control_valve(double flow_rate, double target_flow_rate, int *pwm_duty_cycle);
int log_data(double flow_rate, int pwm_duty_cycle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetMode(VALVE_DIR_PIN, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);

    // Enable pull-up resistor on the flow sensor pin
    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP);

    // Register interrupt handler for rising edge detection
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR\n");
        gpioTerminate();
        return 1;
    }

    // Enable the valve
    gpioWrite(VALVE_DIR_PIN, 1); // Assuming active-high control

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Disable the valve
    gpioWrite(VALVE_DIR_PIN, 0);

    // Set PWM duty cycle to 0
    gpioPWM(VALVE_PWM_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Calculate flow rate in L/min
