#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 100000
#define SPI_FLAGS 0

// Define authentication constants
#define VALID_TAG_1 0x01
#define VALID_TAG_2 0x02
#define VALID_TAG_3 0x03
#define VALID_TAG_4 0x04
#define VALID_TAG_5 0x05
#define VALID_TAG_6 0x06
#define VALID_TAG_7 0x07
#define VALID_TAG_8 0x08
#define VALID_TAG_9 0x09
#define VALID_TAG_10 0x0A

#define VALID_TAG_COUNT 10

const unsigned char valid_tags[VALID_TAG_COUNT] = {
    VALID_TAG_1, VALID_TAG_2, VALID_TAG_3, VALID_TAG_4, VALID_TAG_5,
    VALID_TAG_6, VALID_TAG_7, VALID_TAG_8, VALID_TAG_9, VALID_TAG_10
};

#define BUTTON_DEBOUNCE_MS 50

// Define lock activation time (seconds)
#define LOCK_ACTIVATION_SECONDS 5

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid_tag();
int validate_tag(unsigned char *tag);
int check_button_press();
void activate_locks();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read RFID tag via SPI
int read_rfid_tag() {
    unsigned char rx_buffer[10];
    int result;

    result = spiXfer(spi_handle, NULL, rx_buffer, 10);
    if (result != 0) {
        log_event("SPI read failed");
        return -1; // Indicate failure
    }

    // Check for all-zero response (no tag)
    int all_zeros = 1;
    for (int i = 0; i < 10; i++) {
        if (rx_buffer[i] != 0) {
            all_zeros = 0;
            break;
        }
    }

    if (all_zeros) {
        log_event("No RFID tag detected");
        return -1; // Indicate no tag
    }

    return 0; // Indicate success
}

// Function to validate the RFID tag
int validate_tag(unsigned char *tag) {
    for (int i = 0; i < VALID_TAG_COUNT; i++) {
        if (memcmp(tag, &valid_tags[i], 10) == 0) {
            return 0; // Valid tag
        }
    }
    return -1; // Invalid tag
}

// Function to check for button press with debouncing
int check_button_press() {
    int button_state = gpioRead(BUTTON_PIN);
    if (button_state == 0) { // Button is pressed (active low)
        gpioDelay(BUTTON_DEBOUNCE_MS * 1000); // Debounce
        if (gpioRead(BUTTON_PIN) == 0) {
            return 0; // Valid button press
        }
    }
    return -1; // Button press not confirmed
}

// Function to activate the locks
void activate_locks() {
    gpioWrite(LOCK_1_PIN, 0); // Engage lock 1
    gpioWrite(LOCK_2_PIN, 0); // Engage lock 2
    gpioDelay(LOCK_ACTIVATION_SECONDS * 1000000); // Wait for activation time
    gpioWrite(LOCK_1_PIN, 1); // Disengage lock 1
    gpioWrite(LOCK_2_PIN, 1); // Disengage lock 2
}

// Function to log events to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    log_event("Received signal, shutting down...");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        log_event("SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started");

    // Main loop
    while (!terminate) {
        unsigned char rfid_tag[10];
        int rfid_result;
        int button_result;
        int tag_valid;

        // Read RFID tag
        rfid_result = read_rfid_tag();
        if (rfid_result == 0) {
            // Read tag data (dummy read, tag is already read via spiXfer)
            rfid_tag[0] = 0x01; // Example tag data
            rfid_tag[1] = 0x02;
            rfid_tag[2] = 0x03;
            rfid_tag[3] = 0x04;
            rfid_tag[4] = 0x05;
            rfid_tag[5] = 0x06;
            rfid_tag[6] = 0x07;
            rfid_tag[7] = 0x08;
            rfid_tag[8] = 0x09;
            rfid_tag[9] = 0x0A;

            // Validate tag
            tag_valid = validate_tag(rfid_tag);
            if (tag_valid == 0) {
                // Check button press
                button_result = check_button_press();
                if (button_result == 0) {
                    // Authentication successful
                    log_event("Authentication successful");
                    activate_locks();
                } else {
                    // Button press failed
                    log_event("Button press failed");
                }
            } else {
                // Invalid tag
                log_event("Invalid RFID tag");
            }
        } else if (rfid_result == -1) {
            // No tag present
            // Check button press
            button_result = check_button_press();
            if (button_result == 0) {
                // Authentication attempt with no tag
                log_event("Authentication attempt with no tag");
            } else {
                // Button press failed
                log_event("Button press failed with no tag");
            }
        } else {
            // RFID read failure
            log_event("RFID read failure");
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

