#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <math.h>
#include <gpiod.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PULSES_PER_REVOLUTION 600.0
#define SAMPLE_TIME_MS 100
#define PWM_FREQUENCY 100 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPM
#define TARGET_RPM 60.0

// Global variables
static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *motor1_ena, *motor1_in1, *motor1_in2, *motor2_enb, *motor2_in3, *motor2_in4;
static struct gpiod_line *encoder1_a, *encoder1_b, *encoder2_a, *encoder2_b;
static FILE *log_file;
static pthread_mutex_t encoder1_mutex, encoder2_mutex;
static long encoder1_count, encoder2_count;
static double last_encoder1_time, last_encoder2_time;

// Function prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
void set_motor_speed(int motor, int speed);
double calculate_pid(double setpoint, double actual_value, double *integral, double *previous_error);
void log_data(double motor1_rpm, double motor2_rpm, double pid1, double pid2, double pid_output);
void signal_handler(int signal);

// Encoder 1 thread function
void *encoder1_thread(void *arg) {
    struct gpiod_line_event event;
    int ret;

    while (running) {
        ret = gpiod_line_event_wait(encoder1_a, NULL);
        if (ret < 0) {
            perror("gpiod_line_event_wait (Encoder 1 A)");
            break;
        }

        ret = gpiod_line_event_read(encoder1_a, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read (Encoder 1 A)");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int b_value = gpiod_line_get_value(encoder1_b);
            if (b_value < 0) {
                perror("gpiod_line_get_value (Encoder 1 B)");
                break;
            }

            pthread_mutex_lock(&encoder1_mutex);
            if (b_value == 0) {
                encoder1_count++;
            } else {
                encoder1_count--;
            }
            pthread_mutex_unlock(&encoder1_mutex);
        }
    }

    pthread_exit(NULL);
}

// Encoder 2 thread function
