    double error = setpoint - actual_value;
    *integral += error * SAMPLE_TIME_MS / 1000.0;
    double derivative = (error - *previous_error) * 1000.0 / SAMPLE_TIME_MS;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
