        gpiod_chip_close(chip);
        pthread_mutex_destroy(&encoder1_mutex);
        pthread_mutex_destroy(&encoder2_mutex);
        fclose(log_file);
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        perror("pthread_create (encoder2_thread)");
        gpiod_chip_close(chip);
        pthread_mutex_destroy(&encoder1_mutex);
        pthread_mutex_destroy(&encoder2_mutex);
        fclose(log_file);
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (running) {
        // Read encoder counts
        pthread_mutex_lock(&encoder1_mutex);
        long current_encoder1_count = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        long current_encoder2_count = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate time difference
        double current_time = time(NULL);
        encoder1_time_diff = current_time - last_encoder1_time;
        encoder2_time_diff = current_time - last_encoder2_time;

        // Calculate RPM
        if (encoder1_time_diff > 0) {
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_rate = (double)current_encoder1_count / encoder1_time_diff * 60.0 / PULSES_PER_REVOLUTION;
            pthread_mutex_unlock(&encoder1_mutex);
        } else {
            encoder1_rate = 0;
        }

        if (encoder2_time_diff > 0) {
            pthread_mutex_lock(&encoder2_mutex);
            encoder2_rate = (double)current_encoder2_count / encoder2_time_diff * 60.0 / PULSES_PER_REVOLUTION;
            pthread_mutex_unlock(&encoder2_mutex);
        } else {
            encoder2_rate = 0;
        }

        // Calculate PID outputs
        pid1 = calculate_pid(TARGET_RPM, encoder1_rate, &integral1, &previous_error1);
        pid2 = calculate_pid(TARGET_RPM, encoder2_rate, &integral2, &previous_error2);

        // Calculate PID output
        pid_output = (pid1 + pid2) / 2.0;

        // Limit PID output to +/- 100
        if (pid_output > 100) {
            pid_output = 100;
        } else if (pid_output < -100) {
            pid_output = -100;
        }

        // Set motor speeds
        set_motor_speed(1, (int)pid_output);
        set_motor_speed(2, (int)pid_output);

        // Log data
        log_data(encoder1_rate, encoder2_rate, pid1, pid2, pid_output);

        // Update last time
        last_encoder1_time = current_time;
        last_encoder2_time = current_time;

        // Sleep for sample time
        usleep(SAMPLE_TIME_MS * 1000);
    }

    // Join threads
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    gpiod_line_release(motor1_ena);
    gpiod_line_release(motor1_in1);
    gpiod_line_release(motor1_in2);
    gpiod_line_release(motor2_enb);
    gpiod_line_release(motor2_in3);
    gpiod_line_release(motor2_in4);
    gpiod_line_release(encoder1_a);
    gpiod_line_release(encoder1_b);
    gpiod_line_release(encoder2_a);
    gpiod_line_release(encoder2_b);

    gpiod_chip_close(chip);
    fclose(log_file);
    pthread_mutex_destroy(&encoder1_mutex);
    pthread_mutex_destroy(&encoder2_mutex);

    return 0;
}

