#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_relay_state(int state);
void signal_handler(int signal);

// MPR121 Initialization Sequence
int mpr121_init(int i2c_handle) {
    // Soft Reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft Reset failed\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Configure Filtering
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x06) < 0) {
        fprintf(stderr, "Error: Filter Configuration failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x06) < 0) {
        fprintf(stderr, "Error: Filter Configuration failed\n");
        return -1;
    }

    // Set Touch and Release Thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch Threshold
            fprintf(stderr, "Error: Touch Threshold configuration failed for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release Threshold
            fprintf(stderr, "Error: Release Threshold configuration failed for electrode %d\n", i);
            return -1;
        }
    }

    // Enable Run Mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x8F) < 0) {
        fprintf(stderr, "Error: Run Mode configuration failed\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int i2c_handle) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return ((buf[1] << 8) | buf[0]);
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log relay state to file
void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d Relay: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, state ? "ON" : "OFF");
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    int last_relay_state = 0; // Track the last relay state

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        int any_touched = (touch_status > 0);

        if (any_touched) {
            if (last_relay_state == 0) {
                control_relay(RELAY_GPIO, 1);
                log_relay_state(1);
                last_relay_state = 1;
            }
        } else {
            if (last_relay_state == 1) {
                control_relay(RELAY_GPIO, 0);
                log_relay_state(0);
                last_relay_state = 0;
            }
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    control_relay(RELAY_GPIO, 0); // Turn off relay on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

