#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *valve1_line, *valve2_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int open_valve(int gpio_pin);
int close_valve(int gpio_pin);
int log_event(const char *valve_name, const char *event_type);
void schedule();
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Error getting valve 1 line");
        gpiod_chip_close(chip);
        return -1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Error getting valve 2 line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(valve1_line, "valve1", 0) < 0) {
        perror("Error requesting valve 1 output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, "valve2", 0) < 0) {
        perror("Error requesting valve 2 output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Open a valve
int open_valve(int gpio_pin) {
    int ret;
    if (gpio_pin == VALVE1_GPIO) {
        ret = gpiod_line_set_value(valve1_line, 1);
        if (ret < 0) {
            perror("Error setting valve 1 value");
            return -1;
        }
        log_event("Valve 1", "OPEN");
    } else if (gpio_pin == VALVE2_GPIO) {
        ret = gpiod_line_set_value(valve2_line, 1);
        if (ret < 0) {
            perror("Error setting valve 2 value");
            return -1;
        }
        log_event("Valve 2", "OPEN");
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Close a valve
int close_valve(int gpio_pin) {
    int ret;
    if (gpio_pin == VALVE1_GPIO) {
        ret = gpiod_line_set_value(valve1_line, 0);
        if (ret < 0) {
            perror("Error setting valve 1 value");
            return -1;
        }
        log_event("Valve 1", "CLOSE");
    } else if (gpio_pin == VALVE2_GPIO) {
        ret = gpiod_line_set_value(valve2_line, 0);
        if (ret < 0) {
            perror("Error setting valve 2 value");
            return -1;
        }
        log_event("Valve 2", "CLOSE");
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Log an event to the log file
int log_event(const char *valve_name, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s - %s - %s\n", timestamp, valve_name, event_type);
    fclose(log_file);

    return 0;
}

// Execute the water distribution schedule
void schedule() {
    // Valve 1: 500ms ON, 5s OFF
    if (open_valve(VALVE1_GPIO) < 0) {
        fprintf(stderr, "Error opening Valve 1\n");
    }
    usleep(500000); // 500ms
    if (close_valve(VALVE1_GPIO) < 0) {
        fprintf(stderr, "Error closing Valve 1\n");
    }
    sleep(5);

    // Valve 2: 1000ms ON, 10s OFF
    if (open_valve(VALVE2_GPIO) < 0) {
        fprintf(stderr, "Error opening Valve 2\n");
    }
    usleep(1000000); // 1000ms
    if (close_valve(VALVE2_GPIO) < 0) {
        fprintf(stderr, "Error closing Valve 2\n");
    }
    sleep(10);
}

// Cleanup GPIO resources
void cleanup() {
    printf("Cleaning up GPIO resources...\n");
    if (valve1_line) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        gpiod_line_release(valve2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        schedule();
    }

    // Cleanup and exit
    cleanup();
    printf("Water distribution system stopped.\n");
    return 0;
}

