    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Water distribution system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        schedule();
    }

    // Cleanup and exit
    cleanup();
    printf("Water distribution system stopped.\n");
    return 0;
}

