// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
int mpr121_write_register(uint8_t reg, uint8_t value);
int mpr121_read_register(uint8_t reg, uint8_t *value);
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// MPR121 initialization function
int mpr121_init() {
    // Stop mode
    if (mpr121_write_register(0x80, 0x63) != 0) return -1;
    gpioDelay(10000); // 10ms

    // Configure touch and release thresholds
    for (int i = 0x41; i <= 0x5A; i++) {
        if (mpr121_write_register(i, 0x0A) != 0) return -1; // Release threshold
        if (mpr121_write_register(i + 0x0C, 0x10) != 0) return -1; // Touch threshold
    }

    // Configure filter and charge time
    if (mpr121_write_register(0x5C, 0x20) != 0) return -1; // Filter and charge time

    // Configure electrode current
    if (mpr121_write_register(0x5B, 0x01) != 0) return -1; // Electrode current

    // Enter run mode
    if (mpr121_write_register(0x80, 0x10) != 0) return -1;
    gpioDelay(10000); // 10ms

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(uint16_t *touch_status) {
    uint8_t data[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    *touch_status = (data[1] << 8) | data[0];
    return 0;
}

// MPR121 write register function
int mpr121_write_register(uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteI2CBlockData(i2c_handle, reg, buf + 1, 1) != 1) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// MPR121 read register function
int mpr121_read_register(uint8_t reg, uint8_t *value) {
    if (i2cWriteI2CBlockData(i2c_handle, reg, NULL, 0) != 0) {
        fprintf(stderr, "Error setting register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, reg, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Toggle relay function
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                toggle_relay();
                printf("Touch detected, relay toggled. Touch status: 0x%04X\n", touch_status);
            }
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

