#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define unlock duration (in milliseconds)
#define UNLOCK_DURATION 500

// Define rate limiting interval (in seconds)
#define RATE_LIMIT_INTERVAL 2

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor(int gpio_pin);
int unlock_door(int gpio_pin, int duration_ms);
int log_event(const char *event_type, int gpio_pin);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    time_t last_unlock_time;
} sensor_data_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read PIR sensor value
int read_pir_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Unlock the door for a specified duration
int unlock_door(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Activate relay
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Deactivate relay
    return 0;
}

// Log an event to the log file
int log_event(const char *event_type, int gpio_pin) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - GPIO %d - %s\n", buf, gpio_pin, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensor data
    sensor_data_t sensor1_data = {PIR_SENSOR_1, 0};
    sensor_data_t sensor2_data = {PIR_SENSOR_2, 0};

    // Main loop
    while (program_running) {
        // Read PIR sensors
        int sensor1_value = read_pir_sensor(PIR_SENSOR_1);
        int sensor2_value = read_pir_sensor(PIR_SENSOR_2);

        // Check for motion detection on sensor 1
        if (sensor1_value == 1) {
            time_t now = time(NULL);
            if (difftime(now, sensor1_data.last_unlock_time) >= RATE_LIMIT_INTERVAL) {
                printf("Motion detected on sensor 1 (GPIO %d)\n", PIR_SENSOR_1);
                log_event("Motion Detected", PIR_SENSOR_1);
                unlock_door(RELAY_PIN, UNLOCK_DURATION);
                log_event("Door Unlocked", RELAY_PIN);
                sensor1_data.last_unlock_time = now;
            } else {
                printf("Rate-limited: Motion detected on sensor 1 (GPIO %d)\n", PIR_SENSOR_1);
                log_event("Rate-Limited", PIR_SENSOR_1);
            }
        }

        // Check for motion detection on sensor 2
        if (sensor2_value == 1) {
            time_t now = time(NULL);
            if (difftime(now, sensor2_data.last_unlock_time) >= RATE_LIMIT_INTERVAL) {
                printf("Motion detected on sensor 2 (GPIO %d)\n", PIR_SENSOR_2);
                log_event("Motion Detected", PIR_SENSOR_2);
                unlock_door(RELAY_PIN, UNLOCK_DURATION);
                log_event("Door Unlocked", RELAY_PIN);
                sensor2_data.last_unlock_time = now;
            } else {
                printf("Rate-limited: Motion detected on sensor 2 (GPIO %d)\n", PIR_SENSOR_2);
                log_event("Rate-Limited", PIR_SENSOR_2);
            }
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

