#define MIN_STEPS 5
#define MAX_STEPS 15

// Global variable to signal program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold motor and duration data for a single step
typedef struct {
    int motor;
    int duty_cycle;
    int duration;
} StepData;

// Function to generate a random integer within a given range
int random_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate a randomized haptic feedback pattern
void generate_pattern(StepData *pattern, int *num_steps) {
    *num_steps = random_int(MIN_STEPS, MAX_STEPS);
    for (int i = 0; i < *num_steps; i++) {
        pattern[i].motor = random_int(0, 1); // 0 for MOTOR1, 1 for MOTOR2
        pattern[i].duty_cycle = random_int(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        pattern[i].duration = random_int(MIN_DURATION, MAX_DURATION);
    }
}

// Function to play a single step of the haptic feedback pattern
void play_step(int motor_pin, int duty_cycle, int duration_ms) {
    gpioPWM(motor_pin, duty_cycle);
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    // Set PWM frequency for both motors
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop to generate and play haptic feedback patterns
    while (program_running) {
        // Generate a new haptic feedback pattern
        StepData pattern[MAX_STEPS];
        int num_steps;
        generate_pattern(pattern, &num_steps);

        // Play the pattern
        for (int i = 0; i < num_steps; i++) {
            int motor_pin = (pattern[i].motor == 0) ? MOTOR1_PIN : MOTOR2_PIN;
            play_step(motor_pin, pattern[i].duty_cycle, pattern[i].duration);
        }

        // Small delay before generating the next pattern
        gpioDelay(1000000); // 1 second delay
    }

    // Stop both motors before exiting
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

