#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Define log file name
#define LOG_FILE "weight_log.txt"

// Define weight threshold (in kg)
#define WEIGHT_THRESHOLD 10.0

// Define timeout duration (in seconds)
#define TIMEOUT_DURATION 0.5

// Global variables
double scale_factor = 1.0;
double offset = 0.0;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(double weight);
void log_weight(double weight);
void calibrate_offset();
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout_counter = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_DURATION * 1000000) {
        gpioDelay(1); // Delay 1 microsecond
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_DURATION * 1000000) {
        fprintf(stderr, "Timeout reading HX711\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high duration
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low duration
    }

    // Pulse the clock pin 1 more time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid (lock)
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid (unlock)
    }
}

// Function to log weight data
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to calibrate the offset
void calibrate_offset() {
    double sum = 0.0;
    int num_readings = 100;

    printf("Calibrating offset...\n");
    for (int i = 0; i < num_readings; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711 during offset calibration, skipping.\n");
            continue; // Skip this reading
        }
        sum += raw_value;
        gpioDelay(50); // Small delay between readings
    }
    offset = sum / num_readings;
    printf("Offset calibrated: %.2f\n", offset);
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found, using default values.\n");
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Invalid calibration data format, using default values.\n");
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return;
    }

    fprintf(fp, "%.2f %.2f", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved to %s\n", CALIBRATION_FILE);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration_data();

    // Calibrate offset if needed
    calibrate_offset();

    // Save calibration data
    save_calibration_data();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_weight(raw_value);
            control_solenoid(weight);
            log_weight(weight);
            printf("Weight: %.2f kg\n", weight);
        } else {
            fprintf(stderr, "Error reading HX711, skipping.\n");
        }

        gpioDelay(500); // Delay 500 ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid on exit
    fclose(log_file);
    gpioTerminate();

    printf("Weight monitoring stopped.\n");

    return 0;
}

