#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL_MS 50
#define RAIN_THRESHOLD 3
#define MOTOR_FREQUENCY 1000 // Hz
#define MOTOR_DUTY_CYCLE 150 // 0-255
#define MOTOR_RUN_TIME_SEC 5
#define CHECK_INTERVAL_SEC 60
#define WINDOW_CLOSE_DELAY_SEC 60

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received SIGINT or SIGTERM. Stopping motor and exiting.");
        stop_motor();
        running = 0;
        if (pigpio_initialized) {
            gpioTerminate();
        }
        closelog();
        exit(0);
    }
}

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }
    return (low_count >= RAIN_THRESHOLD) ? 0 : 1; // 0: rain detected, 1: dry
}

// Function to close the window
void close_window() {
    log_event("Closing window.");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, MOTOR_DUTY_CYCLE);
    gpioDelay(MOTOR_RUN_TIME_SEC * 1000000); // Convert seconds to microseconds
    stop_motor();
    log_event("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }
    pigpio_initialized = 1;

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control system started.");

    // Main loop
    while (running) {
        if (read_rain_sensor() == 0) { // Rain detected
            close_window();
            gpioDelay(WINDOW_CLOSE_DELAY_SEC * 1000000); // Wait before checking again
        } else {
            gpioDelay(CHECK_INTERVAL_SEC * 1000000); // Check every CHECK_INTERVAL_SEC seconds
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

