    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Two's complement conversion if negative
    if (count & 0x800000) {
        count |= 0xFF000000;
    }

