#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define weight threshold
#define WEIGHT_THRESHOLD 5.0

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Define log file name
#define LOG_FILE "security.log"

// Global variables
static volatile int running = 1;
static double calibration_factor = 0.0;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value, double calibration_factor);
void control_solenoid(int state);
void log_event(double weight);
void calibrate_load_cell();
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1 microsecond
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 25th time to set the HX711 for the next reading
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Clock high delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Clock low delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

// Function to control the solenoid
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Function to log events to a file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calibrate the load cell
void calibrate_load_cell() {
    double known_weight;
    int raw_value;
    char buffer[256];

    printf("Place a known weight on the load cell and enter its value in kilograms: ");
    if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
        fprintf(stderr, "Error reading input.\n");
        return;
    }

    if (sscanf(buffer, "%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input. Please enter a number.\n");
        return;
    }

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error reading raw value from HX711 during calibration.\n");
        return;
    }

    calibration_factor = (double)raw_value / known_weight;

    FILE *calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return;
    }

    fprintf(calibration_file, "%.6f", calibration_factor);
    fclose(calibration_file);

    printf("Calibration complete. Calibration factor: %.6f\n", calibration_factor);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    control_solenoid(0); // Unlock the solenoid
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Calibrate the load cell
    calibrate_load_cell();

    // Read calibration factor from file
    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error opening calibration file for reading.\n");
        fclose(log_file);
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from file.\n");
        fclose(calibration_file);
        fclose(log_file);
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    fclose(calibration_file);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value, calibration_factor);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded! Locking solenoid.\n");
                control_solenoid(1); // Lock the solenoid
                log_event(weight);
                gpioDelay(5000); // Keep locked for 5 seconds
                control_solenoid(0); // Unlock the solenoid
                printf("Solenoid unlocked.\n");
            }
        } else {
            fprintf(stderr, "Error reading from HX711.\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0); // Unlock the solenoid
    fclose(log_file);
    gpioTerminate(); // Terminate pigpio

    return 0;
}

