#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_GPIO 16
#define RELAY_GPIO 20

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL;
struct gpiod_line *relay_line = NULL;

// Global variable for relay state
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio(void);
int read_sensor(void);
int toggle_relay(void);
int log_event(int new_relay_state);
void cleanup_gpio(int signal);

// Signal handler for graceful shutdown
void cleanup_gpio(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Error getting sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request sensor line as input
    ret = gpiod_line_request(sensor_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        perror("Error requesting sensor line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error getting relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request relay line as output
    ret = gpiod_line_request(relay_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting relay line as output");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set initial relay state to OFF
    ret = gpiod_line_set_value(relay_line, 0);
    if (ret < 0) {
        perror("Error setting initial relay state");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return -1;
    }
    relay_state = 0;

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value;

    value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }

    return value;
}

// Toggle relay state
int toggle_relay(void) {
    int ret;

    relay_state = !relay_state;
    ret = gpiod_line_set_value(relay_line, relay_state);
    if (ret < 0) {
        perror("Error setting relay state");
        return -1;
    }

    return relay_state;
}

