        perror("Error requesting PIR sensor line as input");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "motion_detector", 0) < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_line_release(pir_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return -1;
    }

