#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// Configuration file path
#define CONFIG_FILE "watering.conf"

// GPIO chip and line names
#define GPIOCHIP "gpiochip0"
#define GPIO_LINE_NAME "valve"

// Default watering duration (seconds)
#define DEFAULT_DURATION 60

// Maximum watering duration (seconds)
#define MAX_DURATION 3600

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_watering_duration(const char *filename, int *duration);
int initialize_gpio(const char *chipname, const char *linename);
int set_valve_state(int state);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        fprintf(stdout, "Signal received, turning valve off and exiting.\n");
    }
}

// Function to read watering duration from configuration file
int read_watering_duration(const char *filename, int *duration) {
    FILE *fp;
    char line_buffer[256];
    char *token;
    int duration_value;

    fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening configuration file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    // Read the first line from the file
    if (fgets(line_buffer, sizeof(line_buffer), fp) == NULL) {
        fprintf(stderr, "Error reading from configuration file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    // Tokenize the line to extract the duration value
    token = strtok(line_buffer, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid format in configuration file %s\n", filename);
        fclose(fp);
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid format in configuration file %s\n", filename);
        fclose(fp);
        return -1;
    }

    duration_value = atoi(token);

    // Validate the duration value
    if (duration_value <= 0 || duration_value > MAX_DURATION) {
        fprintf(stderr, "Error: Invalid watering duration in configuration file %s: %d\n", filename, duration_value);
        fclose(fp);
        return -1;
    }

    *duration = duration_value;
    fclose(fp);
    return 0;
}

// Function to initialize GPIO line
int initialize_gpio(const char *chipname, const char *linename) {
    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chipname, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, 18); // GPIO18
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %s: %s\n", linename, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, linename, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %s as output: %s\n", linename, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set valve state
int set_valve_state(int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup function to release resources
void cleanup(void) {
    if (line) {
        set_valve_state(0); // Ensure valve is off
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int watering_duration = DEFAULT_DURATION;
    struct timespec sleep_duration;

    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Read watering duration from configuration file
    if (read_watering_duration(CONFIG_FILE, &watering_duration) != 0) {
        fprintf(stderr, "Error reading watering duration, using default duration: %d seconds\n", DEFAULT_DURATION);
    }

    // Initialize GPIO
    if (initialize_gpio(GPIOCHIP, GPIO_LINE_NAME) != 0) {
        fprintf(stderr, "Error initializing GPIO, exiting.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Turn valve on
        if (set_valve_state(1) != 0) {
            fprintf(stderr, "Error turning valve on, exiting.\n");
            break;
        }
        fprintf(stdout, "Valve ON for %d seconds\n", watering_duration);

        // Wait for the specified duration
        sleep_duration.tv_sec = watering_duration;
        sleep_duration.tv_nsec = 0;
        if (nanosleep(&sleep_duration, NULL) != 0) {
            if (errno == EINTR) {
                fprintf(stdout, "Sleep interrupted by signal.\n");
            } else {
                fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
                break;
            }
        }

        // Turn valve off
        if (set_valve_state(0) != 0) {
            fprintf(stderr, "Error turning valve off, exiting.\n");
            break;
        }
        fprintf(stdout, "Valve OFF\n");

        // Wait for a short period before the next cycle
        sleep_duration.tv_sec = 5; // Wait 5 seconds
        sleep_duration.tv_nsec = 0;
        if (nanosleep(&sleep_duration, NULL) != 0) {
            if (errno == EINTR) {
                fprintf(stdout, "Sleep interrupted by signal.\n");
            } else {
                fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
                break;
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

