#include <string.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

#define LEFT_MOTOR_PWM 22
#define LEFT_MOTOR_DIR 23
#define RIGHT_MOTOR_PWM 24
#define RIGHT_MOTOR_DIR 25

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED 128

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensors(int *left, int *middle, int *right);
void control_motors(int left_sensor, int middle_sensor, int right_sensor);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and exiting.\n");
        running = 0;

        // Stop motors
        gpioPWM(LEFT_MOTOR_PWM, 0);
        gpioPWM(RIGHT_MOTOR_PWM, 0);

        // Close log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        // Terminate pigpio
        gpioTerminate();

        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, PWM_FREQUENCY);

    return 0;
}

// Read sensor values
int read_sensors(int *left, int *middle, int *right) {
    *left = gpioRead(LEFT_SENSOR);
    *middle = gpioRead(MIDDLE_SENSOR);
    *right = gpioRead(RIGHT_SENSOR);

    return 0;
}

// Control motors based on sensor readings
void control_motors(int left_sensor, int middle_sensor, int right_sensor) {
    int left_speed = BASE_SPEED;
    int right_speed = BASE_SPEED;

    if (middle_sensor == 0) {
        // Go straight
        gpioWrite(LEFT_MOTOR_DIR, 1); // Forward
        gpioWrite(RIGHT_MOTOR_DIR, 1); // Forward
        gpioPWM(LEFT_MOTOR_PWM, left_speed);
        gpioPWM(RIGHT_MOTOR_PWM, right_speed);
    } else {
        if (left_sensor == 0) {
            // Turn right
            gpioWrite(LEFT_MOTOR_DIR, 1); // Forward
            gpioWrite(RIGHT_MOTOR_DIR, 0); // Backward
            gpioPWM(LEFT_MOTOR_PWM, left_speed);
            gpioPWM(RIGHT_MOTOR_PWM, TURN_SPEED);
        } else if (right_sensor == 0) {
            // Turn left
            gpioWrite(LEFT_MOTOR_DIR, 0); // Backward
            gpioWrite(RIGHT_MOTOR_DIR, 1); // Forward
            gpioPWM(LEFT_MOTOR_PWM, TURN_SPEED);
            gpioPWM(RIGHT_MOTOR_PWM, right_speed);
