    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(LEFT_MOTOR_PWM, 0);
    gpioPWM(RIGHT_MOTOR_PWM, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

