#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MEASUREMENT_DELAY_MS 180
#define LUX_THRESHOLD 150.0
#define RELAY_GPIO 23
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the relay (GPIO23)
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    printf("Starting light sensor monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1); // Turn on relay
                relay_state = 1;
                log_data(lux, relay_state);
                printf("Relay turned ON\n");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0); // Turn off relay
                relay_state = 0;
                log_data(lux, relay_state);
                printf("Relay turned OFF\n");
            }
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
            log_data(-1.0, -1); // Log error
        }

        gpioDelay(1000000); // Delay 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Ensure relay is off on exit
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

