#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

// Define servo pulse widths (microseconds)
#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handling
volatile int program_running = 1;

// Function prototypes
int initialize_gpio();
int read_button(int gpio_pin);
int debounce_button(int gpio_pin);
int set_servo_position(int gpio_pin, int pulse_width);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, cleaning up and exiting...\n");
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Enable pull-up resistors (external or internal, depending on wiring)
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Read button state with debouncing
int read_button(int gpio_pin) {
    int button_state = gpioRead(gpio_pin);
    if (button_state == 0) { // Button is pressed (active-low)
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        if (gpioRead(gpio_pin) == 0) { // Re-check after debounce
            return 1; // Button is still pressed
        }
    }
    return 0; // Button is not pressed
}

// Set servo position with pulse width constraint
int set_servo_position(int gpio_pin, int pulse_width) {
    if (pulse_width < 500) {
        pulse_width = 500;
    } else if (pulse_width > 2500) {
        pulse_width = 2500;
    }

    gpioPWM(gpio_pin, pulse_width);
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioPWM(SERVO_PIN, 0); // Stop PWM signal
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (read_button(LOCK_BUTTON_PIN)) {
            printf("Lock button pressed. Setting servo to locked position.\n");
            set_servo_position(SERVO_PIN, LOCKED_PULSE_WIDTH);
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Check unlock button
        if (read_button(UNLOCK_BUTTON_PIN)) {
            printf("Unlock button pressed. Setting servo to unlocked position.\n");
            set_servo_position(SERVO_PIN, UNLOCKED_PULSE_WIDTH);
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(1000); // Small delay to prevent busy-waiting
    }

    return 0;
}

