#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse durations in milliseconds
#define MOTOR1_PULSE_DURATION 200
#define MOTOR2_PULSE_DURATION 300

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *motor1_line = NULL;
struct gpiod_line *motor2_line = NULL;

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable motors
    if (motor1_line) {
        gpiod_line_set_value(motor1_line, 0);
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_set_value(motor2_line, 0);
        gpiod_line_release(motor2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for motors
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_GPIO);
    if (!motor1_line) {
        perror("Error getting GPIO line for motor 1");
        gpiod_chip_close(chip);
        return 1;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_GPIO);
    if (!motor2_line) {
        perror("Error getting GPIO line for motor 2");
        gpiod_chip_close(chip);
        gpiod_line_release(motor1_line);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(motor1_line, "motor1", 0) < 0) {
        perror("Error requesting GPIO line for motor 1 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(motor1_line);
        gpiod_line_release(motor2_line);
        return 1;
    }

    if (gpiod_line_request_output(motor2_line, "motor2", 0) < 0) {
        perror("Error requesting GPIO line for motor 2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(motor1_line);
        gpiod_line_release(motor2_line);
        return 1;
    }

    // Main loop
    while (1) {
        // Pulse motor 1
        if (gpiod_line_set_value(motor1_line, 1) < 0) {
            perror("Error setting motor 1 value");
            signal_handler(SIGTERM); // Simulate signal to cleanup
        }
        usleep(MOTOR1_PULSE_DURATION * 1000); // Convert ms to us
        if (gpiod_line_set_value(motor1_line, 0) < 0) {
            perror("Error setting motor 1 value");
            signal_handler(SIGTERM); // Simulate signal to cleanup
        }

        // Pulse motor 2
        if (gpiod_line_set_value(motor2_line, 1) < 0) {
            perror("Error setting motor 2 value");
            signal_handler(SIGTERM); // Simulate signal to cleanup
        }
        usleep(MOTOR2_PULSE_DURATION * 1000); // Convert ms to us
        if (gpiod_line_set_value(motor2_line, 0) < 0) {
            perror("Error setting motor 2 value");
            signal_handler(SIGTERM); // Simulate signal to cleanup
        }
    }

    // Cleanup (should not reach here due to signal handler)
    gpiod_line_release(motor1_line);
    gpiod_line_release(motor2_line);
    gpiod_chip_close(chip);

    return 0;
}

