#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <zmq.h>

#define SOUND_SENSOR_MODE "sound_sensor"
#define ALARM_NODE_MODE "alarm_node"
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define ALARM_LED_GPIO 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define POLLING_INTERVAL_MS 10

// Global variables for cleanup
static int running = 1;
static int gpio_initialized = 0;
static void *zmq_context = NULL;
static void *zmq_publisher = NULL;
static void *zmq_subscriber = NULL;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int publish_alarm(int sound_detected);
int subscribe_alarm();
void activate_alarm();
void signal_handler(int signal);
void cleanup();

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: %s or %s\n", SOUND_SENSOR_MODE, ALARM_NODE_MODE);
        return 1;
    }

    const char *mode = argv[1];

    if (strcmp(mode, SOUND_SENSOR_MODE) != 0 && strcmp(mode, ALARM_NODE_MODE) != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        fprintf(stderr, "  mode: %s or %s\n", SOUND_SENSOR_MODE, ALARM_NODE_MODE);
        return 1;
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }
    gpio_initialized = 1;

    // Initialize ZeroMQ context
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        fprintf(stderr, "Failed to create ZeroMQ context. Exiting.\n");
        cleanup();
        return 1;
    }

    if (strcmp(mode, SOUND_SENSOR_MODE) == 0) {
        // Sound sensor mode
        while (running) {
            int sound_detected = read_sound_sensor();
            if (sound_detected) {
                publish_alarm(1);
            }
            gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
        }
    } else if (strcmp(mode, ALARM_NODE_MODE) == 0) {
        // Alarm node mode
        if (subscribe_alarm() != 0) {
            fprintf(stderr, "Failed to subscribe to alarm. Exiting.\n");
            cleanup();
            return 1;
        }

        while (running) {
            // In alarm node mode, we don't need to read the sound sensor.
            // The alarm is activated based on the received ZeroMQ message.
            gpioDelay(POLLING_INTERVAL_MS * 1000); // Keep the loop running
        }
    }

    cleanup();
    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_LED_GPIO, 0); // Ensure LED is off initially
    return 0;
}

int read_sound_sensor() {
    // Read the sound sensor's digital output.
    // The sensor's output is active-low, so a logic 0 indicates sound detection.
    int sensor_value = gpioRead(17); // Assuming GPIO17 is connected to the sensor
    return (sensor_value == 0) ? 1 : 0;
}

int publish_alarm(int sound_detected) {
    // Create a ZeroMQ publisher socket
    zmq_publisher = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_publisher) {
        fprintf(stderr, "Failed to create ZeroMQ publisher socket\n");
        return 1;
    }

    // Bind the socket to the endpoint
    int rc = zmq_bind(zmq_publisher, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ publisher socket: %s\n", zmq_strerror(zmq_errno()));
        zmq_close(zmq_publisher);
        return 1;
    }

    // Get current timestamp
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long long timestamp_ms = (long long)(tv.tv_sec) * 1000 + (long long)(tv.tv_usec) / 1000;

    // Create the message
    char message[100];
    snprintf(message, sizeof(message), "%lld", timestamp_ms);

    // Send the message
    zmq_msg_t zmq_message;
    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    rc = zmq_msg_send(&zmq_message, zmq_publisher, 0);
    zmq_msg_close(&zmq_message);

    if (rc == -1) {
        fprintf(stderr, "Failed to send message: %s\n", zmq_strerror(zmq_errno()));
        return 1;
    }

    printf("Published alarm: %s\n", message);
    return 0;
}

int subscribe_alarm() {
    // Create a ZeroMQ subscriber socket
    zmq_subscriber = zmq_socket(zmq_context, ZMQ_SUB);
    if (!zmq_subscriber) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
        return 1;
    }

    // Connect the socket to the endpoint
    int rc = zmq_connect(zmq_subscriber, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to connect ZeroMQ subscriber socket: %s\n", zmq_strerror(zmq_errno()));
        zmq_close(zmq_subscriber);
        return 1;
    }

    // Subscribe to the SOUND_ALERTS topic
    rc = zmq_setsockopt(zmq_subscriber, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC));
    if (rc != 0) {
        fprintf(stderr, "Failed to set ZeroMQ subscribe option: %s\n", zmq_strerror(zmq_errno()));
        zmq_close(zmq_subscriber);
        return 1;
    }

    printf("Subscribed to topic: %s\n", SOUND_ALERTS_TOPIC);
    return 0;
}

void activate_alarm() {
    printf("Activating alarm!\n");
    gpioWrite(ALARM_LED_GPIO, 1); // Turn on the LED
    gpioDelay(1000000);           // Wait for 1 second (1000000 microseconds)
    gpioWrite(ALARM_LED_GPIO, 0); // Turn off the LED
    printf("Alarm deactivated.\n");
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

void cleanup() {
    printf("Cleaning up resources...\n");

    if (zmq_publisher) {
        zmq_close(zmq_publisher);
    }
    if (zmq_subscriber) {
        zmq_close(zmq_subscriber);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    if (gpio_initialized) {
        gpioWrite(ALARM_LED_GPIO, 0); // Ensure LED is off
        gpioTerminate();
    }
}

