#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <unistd.h>

// Configuration
#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100
#define NEC_TIMEOUT_US 100000 // 100ms

// NEC Protocol Timings (in microseconds)
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560

// Global variables
static volatile int running = 1;
static volatile unsigned int pulse_buffer[PULSE_BUFFER_SIZE];
static volatile int pulse_index = 0;
static struct mosquitto *mosq = NULL;

// Function prototypes
void signal_handler(int sig);
int init_gpio();
int init_mqtt();
void cleanup();
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(unsigned int *pulses, int pulse_count, unsigned int *address, unsigned int *command);
int validate_checksum(unsigned int address, unsigned int command);
int publish_mqtt(unsigned int address, unsigned int command);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    running = 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    if (gpioSetAlertFuncEx(IR_GPIO, FALLING_EDGE, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set alert function");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize MQTT
int init_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to start MQTT loop: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");

    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }

    gpioTerminate();
    closelog();
}

// IR callback function
void ir_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t pulse_width;

    if (level == FALLING_EDGE) {
        pulse_width = tick - last_tick;
        last_tick = tick;

        if (pulse_index < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_index++] = pulse_width;
        } else {
            syslog(LOG_WARNING, "Pulse buffer overflow!");
            pulse_index = 0; // Reset buffer
        }
    }
}

// Decode NEC IR signal
int decode_nec(unsigned int *pulses, int pulse_count, unsigned int *address, unsigned int *command) {
    if (pulse_count < 68) {
        syslog(LOG_WARNING, "Too few pulses received (%d), cannot decode NEC", pulse_count);
        return -1;
    }

    // Validate header
    if (pulses[0] < NEC_HEADER_MARK * 0.8 || pulses[0] > NEC_HEADER_MARK * 1.2 ||
        pulses[1] < NEC_HEADER_SPACE * 0.8 || pulses[1] > NEC_HEADER_SPACE * 1.2) {
        syslog(LOG_WARNING, "Invalid NEC header");
        return -1;
    }

    *address = 0;
    *command = 0;

    // Decode address and command
    for (int i = 2; i < 34; i++) {
        *address <<= 1;
        if (pulses[2 * i] > NEC_BIT_MARK * 0.8 && pulses[2 * i] < NEC_BIT_MARK * 1.2) {
            if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8 && pulses[2 * i + 1] < NEC_ONE_SPACE * 1.2) {
                *address |= 1;
            } else if (pulses[2 * i + 1] > NEC_ZERO_SPACE * 0.8 && pulses[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
                *address |= 0;
            } else {
                syslog(LOG_WARNING, "Invalid bit mark or space");
                return -1;
            }
        } else {
            syslog(LOG_WARNING, "Invalid bit mark");
            return -1;
        }
    }

    for (int i = 34; i < 58; i++) {
        *command <<= 1;
        if (pulses[2 * i] > NEC_BIT_MARK * 0.8 && pulses[2 * i] < NEC_BIT_MARK * 1.2) {
            if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8 && pulses[2 * i + 1] < NEC_ONE_SPACE * 1.2) {
                *command |= 1;
            } else if (pulses[2 * i + 1] > NEC_ZERO_SPACE * 0.8 && pulses[2 * i + 1] < NEC_ZERO_SPACE * 1.2) {
                *command |= 0;
            } else {
                syslog(LOG_WARNING, "Invalid bit mark or space");
                return -1;
            }
        } else {
            syslog(LOG_WARNING, "Invalid bit mark");
            return -1;
        }
    }

    return 0;
}

// Validate NEC checksum
int validate_checksum(unsigned int address, unsigned int command) {
    unsigned int inverted_command = ~command;
    unsigned int checksum = (address & 0xFF) ^ (inverted_command & 0xFF);

    if (checksum != 0) {
        syslog(LOG_WARNING, "Checksum mismatch: 0x%02X != 0x%02X", checksum, 0xFF);
        return -1;
    }

    return 0;
}

// Publish to MQTT broker
int publish_mqtt(unsigned int address, unsigned int command) {
    char json_payload[100];
    snprintf(json_payload, sizeof(json_payload), "{\"address\": %u, \"command\": %u}", address, command);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(json_payload), json_payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(rc));
        return -1;
    }

    syslog(LOG_INFO, "Published: %s", json_payload);
    return 0;
}

int main() {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        syslog(LOG_ERR, "MQTT initialization failed, exiting");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        if (pulse_index > 67) { // Minimum number of pulses to decode
            unsigned int address, command;
            if (decode_nec(pulse_buffer, pulse_index, &address, &command) == 0) {
                if (validate_checksum(address, command) == 0) {
                    if (publish_mqtt(address, command) != 0) {
                        syslog(LOG_ERR, "Failed to publish MQTT message");
                    }
                } else {
                    syslog(LOG_WARNING, "Checksum validation failed");
                }
            } else {
                syslog(LOG_WARNING, "NEC decoding failed");
            }
            pulse_index = 0; // Reset pulse buffer
        }
        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup resources
    cleanup();

    syslog(LOG_INFO, "Exiting...");
    return 0;
}

