#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define MAX_SENSORS 4

// Sensor addresses
const int sensor_addresses[MAX_SENSORS] = {0x23, 0x24, 0x25, 0x26};

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int i2c_fds[MAX_SENSORS];

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read light level from a BH1750 sensor
float read_bh1750(int fd) {
    uint8_t cmd = 0x20; // One-Time High-Resolution Mode
    uint8_t data[2];
    int ret;

    // Write the command
    ret = write(fd, &cmd, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return NAN;
    }

    // Wait for conversion (180ms)
    usleep(180000);

    // Read the data
    ret = read(fd, data, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return NAN;
    }

    // Convert to lux
    uint16_t raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to format sensor data into a string
void format_sensor_data(float lux_values[], int num_sensors, char *buffer, size_t buffer_size) {
    size_t offset = 0;
    for (int i = 0; i < num_sensors; i++) {
        offset += snprintf(buffer + offset, buffer_size - offset, "%d,%.1f;", i + 1, lux_values[i]);
        if (offset >= buffer_size) {
            fprintf(stderr, "Buffer overflow!\n");
            break;
        }
    }
    // Remove trailing semicolon
    if (offset > 0) {
        buffer[offset - 1] = '\0';
    }
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1; // Time-to-live for multicast packets

    // Create socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting TTL: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    float lux_values[MAX_SENSORS];
    char data_buffer[256]; // Buffer for formatted sensor data
    int num_sensors = sizeof(sensor_addresses) / sizeof(sensor_addresses[0]);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C devices
    for (int i = 0; i < num_sensors; i++) {
        i2c_fds[i] = open(I2C_BUS, O_RDWR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Error opening I2C device %d: %s\n", i, strerror(errno));
            // Set NaN for failed sensor
            lux_values[i] = NAN;
            continue;
        }

        // Set slave address
        if (ioctl(i2c_fds[i], I2C_SLAVE, sensor_addresses[i]) < 0) {
            fprintf(stderr, "Error setting I2C slave address for sensor %d: %s\n", i, strerror(errno));
            close(i2c_fds[i]);
            lux_values[i] = NAN;
            continue;
        }
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        for (int i = 0; i < num_sensors; i++) {
            if (i2c_fds[i] >= 0) {
                lux_values[i] = read_bh1750(i2c_fds[i]);
                if (lux_values[i] != lux_values[i]) {
                    fprintf(stderr, "Error reading sensor %d, setting to NaN\n", i);
                    lux_values[i] = NAN;
                }
                close(i2c_fds[i]);
                i2c_fds[i] = -1; // Mark as closed
            } else {
                lux_values[i] = NAN; // Already NaN, just to be safe
            }
        }

        // Format sensor data
        format_sensor_data(lux_values, num_sensors, data_buffer, sizeof(data_buffer));

        // Send UDP multicast
        if (send_udp_multicast(data_buffer) != 0) {
            fprintf(stderr, "Error sending UDP multicast\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C devices
    for (int i = 0; i < num_sensors; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

