// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fflush(log_fp);
        fclose(log_fp);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int read_i2c(int fd, unsigned char *data, int len) {
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = read(fd, data, len);
        if (bytes_read == len) {
            return 0; // Success
        } else if (bytes_read < 0) {
            perror("Error reading from I2C");
            retries--;
            usleep(100000); // 100ms delay
        } else {
            fprintf(stderr, "Short read from I2C (%d bytes, expected %d)\n", bytes_read, len);
            retries--;
            usleep(100000); // 100ms delay
        }
    }

    fprintf(stderr, "Failed to read from I2C after multiple retries.\n");
    return -1; // Failure
}

// Function to write data to the I2C device
int write_i2c(int fd, unsigned char *data, int len) {
    int retries = 3;
    int bytes_written;

    while (retries > 0) {
        bytes_written = write(fd, data, len);
        if (bytes_written == len) {
            return 0; // Success
        } else if (bytes_written < 0) {
            perror("Error writing to I2C");
            retries--;
            usleep(100000); // 100ms delay
        } else {
            fprintf(stderr, "Short write to I2C (%d bytes, expected %d)\n", bytes_written, len);
            retries--;
            usleep(100000); // 100ms delay
        }
    }

    fprintf(stderr, "Failed to write to I2C after multiple retries.\n");
    return -1; // Failure
}

// Function to read raw airflow data from the sensor
int read_airflow(int fd, unsigned char *data) {
    unsigned char cmd[1] = {0x00}; // Start measurement command (example)
    if (write_i2c(fd, cmd, 1) != 0) {
        fprintf(stderr, "Error writing start command to sensor.\n");
        return -1;
    }

    usleep(1000); // Wait for measurement (adjust as needed)

    if (read_i2c(fd, data, 2) != 0) {
        fprintf(stderr, "Error reading airflow data from sensor.\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to SLPM
float convert_to_slpm(unsigned char *data) {
    unsigned int raw_value = ((unsigned int)data[0] << 8) | data[1];
    return (float)(raw_value - 3277) * 0.1;
}

// Function to log the airflow data to a file
int log_airflow(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_fp, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fflush(log_fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (set_i2c_slave(i2c_fd, AWM7300V_ADDR) != 0) {
        close(i2c_fd);
        return 1;
    }

    unsigned char data[2];
    float flow_rate;

    // Main loop
    while (1) {
        if (read_airflow(i2c_fd, data) == 0) {
            flow_rate = convert_to_slpm(data);
            if (log_airflow(flow_rate) != 0) {
                fprintf(stderr, "Error logging airflow data.\n");
            }
        } else {
            fprintf(stderr, "Error reading airflow data.\n");
        }

        sleep(1); // Sample every 1 second
    }

    return 0;
}

