#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Registers
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_F1_DATA 0x60
#define AS7341_F2_DATA 0x61
#define AS7341_F3_DATA 0x62
#define AS7341_F4_DATA 0x63
#define AS7341_F5_DATA 0x64
#define AS7341_F6_DATA 0x65
#define AS7341_F7_DATA 0x66
#define AS7341_F8_DATA 0x67
#define AS7341_CLEAR_DATA 0x68
#define AS7341_NIR_DATA 0x69

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int init_i2c(int addr);
int verify_sensor(int fd);
int power_on_sensor(int fd);
int configure_sensor(int fd);
int read_spectral_data(int fd, uint16_t *data);
float calculate_lux(uint16_t *data);
int log_data(float lux);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        stop_flag = 1;
    }
}

// Initialize I2C communication
int init_i2c(int addr) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Verify sensor ID
int verify_sensor(int fd) {
    uint8_t who_am_i;
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0x19) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I register verified successfully.\n");
    return 0;
}

// Power on the sensor
int power_on_sensor(int fd) {
    uint8_t enable_reg = 0x03; // PON bit set
    if (write(fd, &enable_reg, 1) != 1) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    printf("Sensor powered on.\n");
    return 0;
}

// Configure the sensor for spectral measurements
int configure_sensor(int fd) {
    uint8_t config_reg = 0x01; // SMUX = 1, Gain = 1
    if (write(fd, &config_reg, 1) != 1) {
        perror("Error writing to CFG6 register");
        return -1;
    }

    printf("Sensor configured for spectral measurements.\n");
    return 0;
}

// Read spectral data from the sensor
int read_spectral_data(int fd, uint16_t *data) {
    uint8_t buffer[10];
    if (read(fd, buffer, 10) != 10) {
        perror("Error reading spectral data");
        return -1;
    }

    data[0] = buffer[0] | (buffer[1] << 8); // F1
    data[1] = buffer[2] | (buffer[3] << 8); // F2
    data[2] = buffer[4] | (buffer[5] << 8); // F3
    data[3] = buffer[6] | (buffer[7] << 8); // F4
    data[4] = buffer[8] | (buffer[9] << 8); // F5
    data[5] = buffer[10] | (buffer[11] << 8); // F6
    data[6] = buffer[12] | (buffer[13] << 8); // F7
    data[7] = buffer[14] | (buffer[15] << 8); // F8
    data[8] = buffer[16] | (buffer[17] << 8); // Clear
    data[9] = buffer[18] | (buffer[19] << 8); // NIR

    return 0;
}

// Calculate lux approximation (simplified)
float calculate_lux(uint16_t *data) {
    // This is a very basic approximation.  A more accurate calculation
    // would require calibration data and a more complex formula.
    // This example just averages the F1-F8 values.
    float sum = 0.0;
    for (int i = 0; i < 8; i++) {
        sum += data[i];
    }
    return sum / 8.0;
}

// Log data to a CSV file
int log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c(AS7341_ADDR) < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Power on sensor
    if (power_on_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor power on failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor configuration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    uint16_t spectral_data[10];
    float lux;
    while (!stop_flag) {
        // Read spectral data
        if (read_spectral_data(i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Error reading spectral data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate lux
        lux = calculate_lux(spectral_data);

        // Log data
        if (log_data(lux) < 0) {
            fprintf(stderr, "Error logging data. Retrying.\n");
        }

        printf("Lux: %.2f\n", lux);

        sleep(5); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

