// Default values
#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"

// Sensor-specific constants
#define ACCEL_SCALE 0.000244f
#define ACCEL_RANGE 8.0f

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static FILE *error_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char filename[256] = DEFAULT_FILENAME;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t val);
int read_sensor_data(int fd, float *x_g, float *y_g, float *z_g);
void log_data(FILE *fp, float x_g, float y_g, float z_g);
void log_error(const char *message);
void signal_handler(int sig);
void cleanup();

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_i2c_block_data(fd, reg, len, buf);
        if (result == len) {
            return 0; // Success
        } else {
            log_error("I2C read failed, retrying...");
            usleep(10000); // 10 ms backoff
            retries--;
        }
    }

    log_error("I2C read failed after multiple retries.");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, val);
        if (result == 0) {
            return 0; // Success
        } else {
            log_error("I2C write failed, retrying...");
            usleep(10000); // 10 ms backoff
            retries--;
        }
    }

    log_error("I2C write failed after multiple retries.");
    return -1; // Failure
}

// Read sensor data and convert to g
int read_sensor_data(int fd, float *x_g, float *y_g, float *z_g) {
    uint8_t raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2c_read_bytes(fd, 0x28, raw_data, 6) != 0) {
        log_error("Failed to read sensor data.");
        return -1;
    }

    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    *x_g = (float)x_raw * ACCEL_SCALE;
    *y_g = (float)y_raw * ACCEL_SCALE;
    *z_g = (float)z_raw * ACCEL_SCALE;

    return 0;
}

// Log data to CSV file
void log_data(FILE *fp, float x_g, float y_g, float z_g) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
    fflush(fp); // Ensure data is written immediately
}

// Log error to error file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_file, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fflush(error_file);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function to close files and I2C
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = strtol(optarg, NULL, 0);
                break;
            case 'f':
                strncpy(filename, optarg, sizeof(filename) - 1);
                filename[sizeof(filename) - 1] = '\0'; // Ensure null termination
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        perror("Failed to open error log file");
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(filename, "a");
    if (csv_file == NULL) {
        log_error("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    float x_g, y_g, z_g;
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &x_g, &y_g, &z_g) == 0) {
            log_data(csv_file, x_g, y_g, z_g);
        } else {
            log_error("Failed to read sensor data in main loop.");
        }
        sleep(interval);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

