#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define POWER_ON 0x01
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

// Function to initialize the BH1750 sensor
int init_bh1750() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Send power-on command
    if (write(i2c_fd, &POWER_ON, 1) != 1) {
        perror("Error writing power-on command");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Send continuous high-resolution mode command
    if (write(i2c_fd, &CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Error writing continuous high-resolution mode command");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read raw light value from the BH1750 sensor
int read_raw_light(unsigned short *raw_value) {
    unsigned char buffer[2];

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading raw light value");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    char message[50];

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        return -1;
    }

    // Configure multicast address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Set TTL
    int ttl = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    // Format the message
    snprintf(message, sizeof(message), "%.2f", lux_value);

    // Send the message
    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        perror("Error sending UDP multicast");
        close(udp_socket);
        udp_socket = -1;
        return -1;
    }

    close(udp_socket);
    udp_socket = -1;
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the BH1750 sensor
    if (init_bh1750() < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Retrying in 1 second.\n");
        sleep(1);
        if (init_bh1750() < 0) {
            fprintf(stderr, "Failed to initialize BH1750 sensor after multiple retries. Exiting.\n");
            return 1;
        }
    }

    // Main loop
    while (1) {
        unsigned short raw_value;
        float lux_value;

        // Read raw light value
