    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the BH1750 sensor
    if (init_bh1750() < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Retrying in 1 second.\n");
        sleep(1);
        if (init_bh1750() < 0) {
            fprintf(stderr, "Failed to initialize BH1750 sensor after multiple retries. Exiting.\n");
            return 1;
        }
    }

    // Main loop
    while (1) {
        unsigned short raw_value;
        float lux_value;

        // Read raw light value
        if (read_raw_light(&raw_value) < 0) {
            fprintf(stderr, "Failed to read raw light value. Retrying in 1 second.\n");
            sleep(1);
            if (init_bh1750() < 0) {
                fprintf(stderr, "Failed to re-initialize BH1750 sensor after multiple retries. Exiting.\n");
                return 1;
            }
            continue;
        }

        // Convert to lux
        lux_value = convert_to_lux(raw_value);

        // Send over UDP multicast
        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Failed to send UDP multicast. Retrying in 1 second.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

