#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600

// Define magic word
#define MAGIC_WORD_SIZE 16
const unsigned char magic_word[MAGIC_WORD_SIZE] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09};

// Define TLV structure
typedef struct {
    unsigned short type;
    unsigned short length;
    unsigned char *value;
} tlv_t;

// Global variables
int uart_fd;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_uart();
int read_uart_data(unsigned char *buffer, int max_size);
int find_magic_word(const unsigned char *buffer, int buffer_size);
int validate_tlv(const tlv_t *tlv);
int extract_object_data(const tlv_t *tlv, float *range, float *velocity);
int write_to_csv(float range, float velocity);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize UART
int initialize_uart() {
    uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_fd < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_fd);
        return -1;
    }
    return 0;
}

// Read data from UART
int read_uart_data(unsigned char *buffer, int max_size) {
    int bytes_read = serRead(uart_fd, buffer, max_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Find magic word in buffer
int find_magic_word(const unsigned char *buffer, int buffer_size) {
    if (buffer_size < MAGIC_WORD_SIZE) return -1; // Not enough data

    for (int i = 0; i <= buffer_size - MAGIC_WORD_SIZE; ++i) {
        if (memcmp(buffer + i, magic_word, MAGIC_WORD_SIZE) == 0) {
            return i; // Magic word found
        }
    }
    return -1; // Magic word not found
}

// Validate TLV
int validate_tlv(const tlv_t *tlv) {
    // Basic validation: check length and type
    if (tlv->length > 1024) { // Limit the size of the TLV value
        fprintf(stderr, "Error: TLV length exceeds maximum allowed size.\n");
        return -1;
    }

    return 0;
}

// Extract object data
int extract_object_data(const tlv_t *tlv, float *range, float *velocity) {
    // Assuming range and velocity are floats in the TLV value
    if (tlv->length < 8) {
        fprintf(stderr, "Error: TLV value too short to contain range and velocity.\n");
        return -1;
    }

    memcpy(range, tlv->value, sizeof(float));
    memcpy(velocity, tlv->value + sizeof(float), sizeof(float));

    return 0;
}

// Write to CSV file
int write_to_csv(float range, float velocity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, range, velocity);
    fflush(csv_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (uart_fd >= 0) {
        serClose(uart_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,range_m,velocity_mps\n");
    }

    unsigned char buffer[4096]; // Buffer for UART data
    int buffer_index = 0;
    float range, velocity;

    fprintf(stderr, "Starting data acquisition...\n");

    while (!terminate) {
        int bytes_read = read_uart_data(buffer + buffer_index, sizeof(buffer) - buffer_index);
        if (bytes_read > 0) {
            buffer_index += bytes_read;

            // Find magic word in the buffer
            int magic_index = find_magic_word(buffer, buffer_index);

            if (magic_index >= 0) {
                // Process TLV data
                tlv_t tlv;
                tlv.type = (buffer[magic_index + 8] << 8) | buffer[magic_index + 9];
                tlv.length = (buffer[magic_index + 10] << 8) | buffer[magic_index + 11];
                tlv.value = (unsigned char *)(buffer + magic_index + 12);

                if (validate_tlv(&tlv) == 0) {
                    if (extract_object_data(&tlv, &range, &velocity) == 0) {
                        write_to_csv(range, velocity);
                    } else {
                        fprintf(stderr, "Error extracting object data.\n");
                    }
                } else {
                    fprintf(stderr, "Error validating TLV.\n");
                }

                // Remove processed data from buffer
                memmove(buffer, buffer + magic_index + MAGIC_WORD_SIZE + tlv.length, buffer_index - (magic_index + MAGIC_WORD_SIZE + tlv.length));
                buffer_index -= (magic_index + MAGIC_WORD_SIZE + tlv.length);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            gpioDelay(100); // Wait before retrying
        }

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

