        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VTIME] = 0; // Inter-byte timeout = 0.5 seconds
    tty.c_cc[VMIN] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }
}

int parse_data(const char *buffer, char *timestamp_str, char *range_str) {
    char *token;
    char *saveptr;
    int i = 0;

    token = strtok_r(buffer, ",", &saveptr);
    while (token != NULL && i < 2) {
        if (i == 0) {
            strncpy(timestamp_str, token, BUFFER_SIZE);
            timestamp_str[BUFFER_SIZE - 1] = '\0'; // Ensure null termination
        } else {
            strncpy(range_str, token, BUFFER_SIZE);
            range_str[BUFFER_SIZE - 1] = '\0'; // Ensure null termination
        }
        token = strtok_r(NULL, ",", &saveptr);
        i++;
    }

    if (i != 2) {
        fprintf(stderr, "Error: Invalid data format: %s\n", buffer);
        return -1;
    }

    return 0;
}

int validate_data(const char *timestamp_str, const char *range_str) {
    char *endptr;
    long timestamp = strtol(timestamp_str, &endptr, 10);

    if (*endptr != '\0' || timestamp < 0) {
        fprintf(stderr, "Error: Invalid timestamp: %s\n", timestamp_str);
        return -1;
    }

    double range = strtod(range_str, &endptr);

    if (*endptr != '\0' || range < 0) {
        fprintf(stderr, "Error: Invalid range: %s\n", range_str);
        return -1;
    }

    return 0;
}

void log_data(const char *timestamp_str, const char *range_str) {
    time_t rawtime = strtol(timestamp_str, NULL, 10);
    struct tm *info = localtime(&rawtime);
    char timestamp_str_iso8601[30];
    strftime(timestamp_str_iso8601, sizeof(timestamp_str_iso8601), "%Y-%m-%dT%H:%M:%SZ", info);

    printf("Timestamp: %s, Range: %s meters\n", timestamp_str_iso8601, range_str);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[BUFFER_SIZE];
    char timestamp_str[BUFFER_SIZE];
    char range_str[BUFFER_SIZE];
    int bytes_read;

    while (program_running) {
        bytes_read = read_uart(uart_fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            // Process complete lines
            char *line = strtok(buffer, "\n");
            while (line != NULL) {
                if (parse_data(line, timestamp_str, range_str) == 0 &&
                    validate_data(timestamp_str, range_str) == 0) {
                    log_data(timestamp_str, range_str);
                }
                line = strtok(NULL, "\n");
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "UART read error, exiting...\n");
            program_running = 0;
        }
    }

    if (uart_fd != -1) {
        close(uart_fd);
    }

    return EXIT_SUCCESS;
}

