// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define serial port device name
#define SERIAL_PORT "/dev/ttyAMA0"

// Define baud rate for serial communication
#define BAUD_RATE 115200

// Global variables
int serial_fd = -1; // File descriptor for the serial port

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left_state, int middle_state, int right_state);
int send_emergency_stop_message(int serial_fd);
void signal_handler(int signal);
int setup_serial(const char *port, int baud_rate);
void cleanup();

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log sensor data with a timestamp
void log_sensor_data(int left_state, int middle_state, int right_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left_state, middle_state, right_state);
}

// Function to send the emergency stop message over the serial port
int send_emergency_stop_message(int serial_fd) {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(serial_fd, message, strlen(message));

    if (bytes_written == -1) {
        fprintf(stderr, "Error writing to serial port: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to set up the serial port
int setup_serial(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening serial port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;             /* mask the character size bits */
    tty.c_cflag |= CS8;              /* 8-bit data */
    tty.c_cflag &= ~(PARENB | PARODD); /* no parity */
    tty.c_cflag &= ~CSTOPB;            /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;           /* no hardware flowcontrol */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;      /* read doesn't block */
    tty.c_cc[VTIME] = 5;     /* 0.5 seconds read timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to clean up resources before exiting
void cleanup() {
    if (serial_fd != -1) {
        close(serial_fd);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the serial port
    serial_fd = setup_serial(SERIAL_PORT, BAUD_RATE);
    if (serial_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor states
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int middle_state = read_sensor(MIDDLE_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        if (left_state != -1 && middle_state != -1 && right_state != -1) {
            log_sensor_data(left_state, middle_state, right_state);

            // Check for emergency stop condition
            if (left_state == 0 && middle_state == 0 && right_state == 0) {
                if (send_emergency_stop_message(serial_fd) != 0) {
                    fprintf(stderr, "Failed to send emergency stop message.\n");
                }
            }
        }

        // Delay for 100ms (10Hz loop)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

